import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import { useDispatch, useSelector } from 'react-redux';
import {
    Box,
    Card,
    CardContent,
    TextField,
    Button,
    Typography,
    InputAdornment,
    IconButton,
    CircularProgress,
    Divider,
    useTheme,
    Container,
    Paper,
    CardHeader,
    Alert,

} from '@mui/material';
import { Settings } from 'lucide-react';

import {
    Visibility,
    VisibilityOff,
    MedicalServices,
    Email,
    LockOutlined,
    WavingHand
} from '@mui/icons-material';
import { login } from '../../features/auth/authDeviceSlice';
import { useSnackbar } from 'notistack';

const Login = () => {
    const theme = useTheme();
    const navigate = useNavigate();
    const dispatch = useDispatch();
    const { enqueueSnackbar } = useSnackbar();
    const [showPassword, setShowPassword] = useState(false);
    const [credentials, setCredentials] = useState({
        email: '',
        password: ''
    });
    const [formTouched, setFormTouched] = useState(false);

    const { loading, error, token } = useSelector((state) => state.auth);

    useEffect(() => {
        if (token) {
            navigate('/device-portal/overview');
        }
    }, [token, navigate]);

    useEffect(() => {
        if (error) {
            enqueueSnackbar(error, {
                variant: 'error',
                anchorOrigin: {
                    vertical: 'top',
                    horizontal: 'right'
                }
            });
        }
    }, [error, enqueueSnackbar]);

    const handleSubmit = async (e) => {
        e.preventDefault();
        setFormTouched(true);
    
        console.log("Form submitted", credentials);
    
        if (!credentials.email || !credentials.password) {
            console.warn("Missing fields", credentials);
            enqueueSnackbar('Please fill in all fields', { variant: 'warning' });
            return;
        }
    
        try {
            console.log("Dispatching login action", credentials);
            const resultAction = await dispatch(login(credentials));
    
            if (login.fulfilled.match(resultAction)) {
                console.log("Login successful", resultAction);
                enqueueSnackbar('Welcome back!', {
                    variant: 'success',
                    icon: <WavingHand sx={{ mr: 1 }} />
                });
            } else {
                console.error("Login failed", resultAction);
            }
        } catch (err) {
            console.error("Error during login", err);
        }
    };
    

    const handleChange = (e) => {
        const { name, value } = e.target;
        setCredentials(prev => ({
            ...prev,
            [name]: value
        }));
    };

    const isValidEmail = (email) => {
        return /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email);
    };

    return (
        <Box
            sx={{
                minHeight: '100vh',
                background: 'linear-gradient(135deg, #1976d2 0%, #64b5f6 100%)',
                display: 'flex',
                alignItems: 'center',
                justifyContent: 'center',
                p: 4,
            }}
        >
            <Container maxWidth="sm">
                <Box
                    sx={{
                        display: 'flex',
                        flexDirection: 'column',
                        alignItems: 'center',
                        gap: 3,
                    }}
                >
                    {/* Logo/Icon Section */}
                    <Paper
                        elevation={4}
                        sx={{
                            width: 80,
                            height: 80,
                            borderRadius: '50%',
                            display: 'flex',
                            alignItems: 'center',
                            justifyContent: 'center',
                            backgroundColor: 'white',
                            transform: 'translateY(40px)',
                            zIndex: 2,
                        }}
                    >
                        <Settings size={40} color="#1976d2" />
                    </Paper>

                    {/* Main Card */}
                    <Card
                        sx={{
                            width: '100%',
                            borderRadius: 3,
                            boxShadow: '0 8px 32px rgba(0,0,0,0.1)',
                            background: 'rgba(255,255,255,0.95)',
                            backdropFilter: 'blur(10px)',
                        }}
                    >
                        <CardHeader
                            title={
                                <Box sx={{ textAlign: 'center', pt: 3 }}>
                                    <Typography
                                        variant="h4"
                                        sx={{
                                            fontWeight: 700,
                                            background: 'linear-gradient(45deg, #1976d2, #64b5f6)',
                                            backgroundClip: 'text',
                                            WebkitBackgroundClip: 'text',
                                            color: 'transparent',
                                        }}
                                    >
                                        Device Management
                                    </Typography>
                                    <Typography
                                        variant="body1"
                                        color="text.secondary"
                                        sx={{ mt: 1 }}
                                    >
                                        Enter your credentials to access the system
                                    </Typography>
                                </Box>
                            }
                        />
                        <CardContent sx={{ px: 4, pb: 4 }}>
                            <Box sx={{ display: 'flex', flexDirection: 'column', gap: 3 }}>
                                {error && (
                                    <Alert
                                        severity="error"
                                        sx={{
                                            borderRadius: 2,
                                            animation: 'slideIn 0.3s ease-out'
                                        }}
                                    >
                                        {error}
                                    </Alert>
                                )}


                                <form onSubmit={handleSubmit}>
                                    <TextField
                                        fullWidth
                                        id="email"
                                        name="email"
                                        label="Email Address"
                                        variant="outlined"
                                        margin="normal"
                                        value={credentials.email}
                                        onChange={handleChange}
                                        disabled={loading}
                                        error={formTouched && (!credentials.email || !isValidEmail(credentials.email))}
                                        helperText={formTouched && (!credentials.email
                                            ? 'Email is required'
                                            : !isValidEmail(credentials.email)
                                                ? 'Please enter a valid email'
                                                : ' ')}
                                        InputProps={{
                                            startAdornment: (
                                                <InputAdornment position="start">
                                                    <Email color="action" />
                                                </InputAdornment>
                                            ),
                                        }}
                                        sx={{
                                            '& .MuiOutlinedInput-root': {
                                                borderRadius: '12px',
                                            },
                                        }}
                                    />

                                    <TextField
                                        fullWidth
                                        id="password"
                                        name="password"
                                        label="Password"
                                        type={showPassword ? 'text' : 'password'}
                                        variant="outlined"
                                        margin="normal"
                                        value={credentials.password}
                                        onChange={handleChange}
                                        disabled={loading}
                                        error={formTouched && !credentials.password}
                                        helperText={formTouched && !credentials.password ? 'Password is required' : ' '}
                                        InputProps={{
                                            startAdornment: (
                                                <InputAdornment position="start">
                                                    <LockOutlined color="action" />
                                                </InputAdornment>
                                            ),
                                            endAdornment: (
                                                <InputAdornment position="end">
                                                    <IconButton
                                                        aria-label="toggle password visibility"
                                                        onClick={() => setShowPassword(!showPassword)}
                                                        onMouseDown={(e) => e.preventDefault()}
                                                        edge="end"
                                                    >
                                                        {showPassword ? <VisibilityOff /> : <Visibility />}
                                                    </IconButton>
                                                </InputAdornment>
                                            ),
                                        }}
                                        sx={{
                                            '& .MuiOutlinedInput-root': {
                                                borderRadius: '12px',
                                            },
                                        }}
                                    />

                                    <Button
                                        fullWidth
                                        type="submit"
                                        variant="contained"
                                        size="large"
                                        sx={{
                                            mt: 3,
                                            mb: 2,
                                            borderRadius: '12px',
                                            height: '48px',
                                            textTransform: 'none',
                                            fontSize: '1.1rem',
                                            background: `linear-gradient(45deg, ${theme.palette.primary.main}, ${theme.palette.secondary.main})`,
                                            boxShadow: '0 4px 10px rgba(0,0,0,0.1)',
                                            '&:hover': {
                                                background: `linear-gradient(45deg, ${theme.palette.primary.dark}, ${theme.palette.secondary.dark})`,
                                            },
                                        }}
                                        disabled={loading}
                                    >
                                        {loading ? (
                                            <CircularProgress size={24} color="inherit" />
                                        ) : (
                                            'Sign In'
                                        )}
                                    </Button>

                                    <Divider sx={{ my: 2 }} />

                                    <Typography
                                        variant="body2"
                                        color="text.secondary"
                                        align="center"
                                        sx={{
                                            cursor: 'pointer',
                                            transition: 'color 0.2s',
                                            '&:hover': {
                                                color: 'primary.main',
                                            },
                                        }}
                                    >
                                        Forgot your password? Contact your system administrator
                                    </Typography>
                                </form>
                            </Box>

                        </CardContent>
                    </Card>
                </Box>
            </Container>

            <style>
                {`
          @keyframes slideIn {
            from {
              opacity: 0;
              transform: translateY(-10px);
            }
            to {
              opacity: 1;
              transform: translateY(0);
            }
          }
        `}
            </style>
        </Box>
    );
};

export default Login;