
import { jsPDF } from 'jspdf';
import 'jspdf-autotable';

/**
 * Export devices data to PDF
 * @param {Array} devices - Array of device objects with their accessories
 * @returns {Promise<string>} - Success message
 */
const exportToPDF = async (devices, deviceService) => {
  try {
    // Create a new PDF document
    const doc = new jsPDF();
    
    // Add title
    doc.setFontSize(18);
    doc.text('Devices Report', 14, 22);
    doc.setFontSize(11);
    doc.text(`Generated on: ${new Date().toLocaleString()}`, 14, 30);
    
    // Prepare table data
    const tableData = devices.map(device => [
      device.deviceName,
      device.serialNumber,
      `${device.make} / ${device.model}`,
      device.roomNo,
      device.status,
      device.hasAMC ? 'Yes' : 'No',
      new Date(device.calibrationDate).toLocaleDateString()
    ]);
    
    // Add table
    doc.autoTable({
      startY: 40,
      head: [['Device Name', 'Serial No', 'Make/Model', 'Room', 'Status', 'AMC', 'Calibration Date']],
      body: tableData,
      headStyles: { fillColor: [25, 118, 210] },
      alternateRowStyles: { fillColor: [240, 240, 240] },
    });
    
    // Add accessories section in a separate table for each device
    let yPosition = doc.lastAutoTable.finalY + 20;
    
    devices.forEach((device, index) => {
      if (index > 0) {
        // Add page break if needed
        if (yPosition > 250) {
          doc.addPage();
          yPosition = 20;
        } else {
          yPosition += 15;
        }
      }
      
      // Add device name as header
      doc.setFontSize(12);
      doc.text(`Accessories for ${device.deviceName} (${device.serialNumber})`, 14, yPosition);
      
      if (device.accessories && device.accessories.length > 0) {
        // Prepare accessories table data
        const accessoriesData = device.accessories.map(acc => [
          acc.itemName,
          acc.supplier || 'N/A',
          acc.purchaseDate ? new Date(acc.purchaseDate).toLocaleDateString() : 'N/A',
          acc.isRight && acc.isLeft ? 'Right & Left' : acc.isRight ? 'Right' : acc.isLeft ? 'Left' : 'N/A',
          acc.status
        ]);
        
        // Add accessories table
        doc.autoTable({
          startY: yPosition + 5,
          head: [['Item Name', 'Supplier', 'Purchase Date', 'Position', 'Status']],
          body: accessoriesData,
          headStyles: { fillColor: [76, 175, 80] },
          alternateRowStyles: { fillColor: [240, 240, 240] },
          tableWidth: 'auto',
          margin: { left: 14 }
        });
        
        yPosition = doc.lastAutoTable.finalY + 10;
      } else {
        doc.setFontSize(10);
        doc.text('No accessories found for this device', 14, yPosition + 10);
        yPosition += 20;
      }
    });
    
    // Save the PDF
    doc.save(`devices_report_${new Date().toISOString().split('T')[0]}.pdf`);
    
    return 'Devices report exported to PDF successfully';
  } catch (error) {
    console.error('Error exporting devices to PDF:', error);
    throw new Error('Failed to export devices to PDF');
  }
};

export default exportToPDF;