import React, { useState, useEffect } from 'react';
import {
  Box,
  Card,
  TextField,
  Button,
  Typography,
  Stack,
  InputAdornment,
  IconButton,
  Tooltip,
  Dialog,
  DialogTitle,
  DialogContent,
  DialogActions,
  Alert,
  CircularProgress,
  Paper,
  Tabs,
  Tab,
  Autocomplete,
  FormControl,
  FormHelperText,
} from '@mui/material';
import {
  Search as SearchIcon,
  Phone as PhoneIcon,
  LocationOn as LocationIcon,
  Close as CloseIcon,
} from '@mui/icons-material';
import { useFormik } from 'formik';
import * as yup from 'yup';
import { useSnackbar } from 'notistack';
import { useSelector } from 'react-redux';
import { jwtDecode } from 'jwt-decode';
import api from '../../../api/axios';

// Validation schema for dispatch
const dispatchSchema = yup.object({
  csId: yup.string().required('CS User is required'),
  notes: yup.string(),
});

const SearchTab = ({ searchType, handleSearch, loading }) => {
  const [phoneNumber, setPhoneNumber] = useState('');
  const [name, setName] = useState('');
  const [caseId, setCaseId] = useState('');

  return (
    <Stack spacing={2} sx={{ mt: 2 }}>
      {searchType === 'patient' ? (
        <>
          <TextField
            fullWidth
            label="Search by Patient Name"
            value={name}
            onChange={(e) => {
              setName(e.target.value);
              setPhoneNumber('');
            }}
            InputProps={{
              startAdornment: (
                <InputAdornment position="start">
                  <SearchIcon />
                </InputAdornment>
              ),
              endAdornment: name && (
                <InputAdornment position="end">
                  <Button
                    variant="contained"
                    onClick={() => handleSearch('name', name)}
                    disabled={loading || name.length < 3}
                  >
                    Search
                  </Button>
                </InputAdornment>
              ),
            }}
          />
          <TextField
            fullWidth
            label="Search by Phone Number"
            value={phoneNumber}
            onChange={(e) => {
              setPhoneNumber(e.target.value.replace(/\D/g, '').slice(0, 10));
              setName('');
            }}
            InputProps={{
              startAdornment: (
                <InputAdornment position="start">
                  <PhoneIcon />
                </InputAdornment>
              ),
              endAdornment: phoneNumber && (
                <InputAdornment position="end">
                  <Button
                    variant="contained"
                    onClick={() => handleSearch('phone', phoneNumber)}
                    disabled={loading || phoneNumber.length !== 10}
                  >
                    Search
                  </Button>
                </InputAdornment>
              ),
            }}
          />
        </>
      ) : (
        <TextField
          fullWidth
          label="Search by Case ID"
          value={caseId}
          onChange={(e) => setCaseId(e.target.value)}
          InputProps={{
            startAdornment: (
              <InputAdornment position="start">
                <SearchIcon />
              </InputAdornment>
            ),
            endAdornment: caseId && (
              <InputAdornment position="end">
                <Button
                  variant="contained"
                  onClick={() => handleSearch('case', caseId)}
                  disabled={loading || !caseId}
                >
                  Search
                </Button>
              </InputAdornment>
            ),
          }}
        />
      )}
    </Stack>
  );
};

const DispatchFile = () => {
  const [files, setFiles] = useState([]);
  const [loading, setLoading] = useState(false);
  const [tabValue, setTabValue] = useState(0);
  const [searchType, setSearchType] = useState('patient');
  const [patientSearchResults, setPatientSearchResults] = useState([]);
  const [selectedPatient, setSelectedPatient] = useState(null);
  const [selectedFile, setSelectedFile] = useState(null);
  const [csUsers, setCsUsers] = useState([]);
  const [confirmDialog, setConfirmDialog] = useState(false);
  const [dispatchSuccess, setDispatchSuccess] = useState(false);

  const { enqueueSnackbar } = useSnackbar();
  const token = useSelector(state => state.auth.token);
  const userId = token ? jwtDecode(token).userId : null;

  // Formik for dispatch form
  const formik = useFormik({
    initialValues: {
      csId: '',
      notes: '',
    },
    validationSchema: dispatchSchema,
    onSubmit: async (values) => {
      try {
        const response = await api.post('/file-transfers/create', {
          userId,
          fileId: selectedFile._id,
          csId: values.csId,
          notes: {
            content: values.notes
          }
        });

        if (response.data.success) {
          setDispatchSuccess(true);
          enqueueSnackbar('File dispatched successfully', { variant: 'success' });
          resetForm();
        }
      } catch (error) {
        enqueueSnackbar(error.response?.data?.message || 'Error dispatching file', {
          variant: 'error'
        });
      }
    }
  });

  // Fetch CS users on component mount
  useEffect(() => {
    const fetchCsUsers = async () => {
      try {
        const response = await api.get('/users', {
          params: {
            level: 'cs',
            status: 'active'
          }
        });
        setCsUsers(response.data.data);
      } catch (error) {
        enqueueSnackbar('Error fetching CS users', { variant: 'error' });
      }
    };
    fetchCsUsers();
  }, [enqueueSnackbar]);

  const handleSearch = async (type, value) => {
    if (!value) return;
    
    setLoading(true);
    try {
      let response;
      
      if (type === 'phone') {
        response = await api.get(`/patients/search/phone?phoneNumber=${value}&userId=${userId}`);
      } 
      else if (type === 'name') {
        response = await api.get(`/patients/search/name?name=${value}&userId=${userId}`);
      } 
      else if (type === 'case') {
        response = await api.get(`/file-records/case/${value}?userId=${userId}`);
        if (response.data.success) {
          const file = response.data.data;
          setFiles([file]);
          setPatientSearchResults([]);
          return;
        }
      }

      if (response?.data.success) {
        if (type === 'case') {
          setFiles([response.data.data]);
          setPatientSearchResults([]);
        } else {
          setPatientSearchResults(response.data.data || []);
        }
      }
    } catch (error) {
      enqueueSnackbar(error.response?.data?.message || 'Error searching', { variant: 'error' });
      setFiles([]);
      setPatientSearchResults([]);
    } finally {
      setLoading(false);
    }
  };

  const handlePatientSelect = async (patient) => {
    setSelectedPatient(patient);
    setPatientSearchResults([]);
    setLoading(true);
    try {
      const response = await api.get(`/file-records/patient/${patient._id}?userId=${userId}`);
      if (response.data.success) {
        setFiles(response.data.data || []);
      }
    } catch (error) {
      enqueueSnackbar('Error fetching patient files', { variant: 'error' });
      setFiles([]);
    } finally {
      setLoading(false);
    }
  };

  const handleFileSelect = (file) => {
    setSelectedFile(file);
    formik.resetForm();
    setConfirmDialog(true);
  };

  const handleClearFilters = () => {
    setSelectedPatient(null);
    setPatientSearchResults([]);
    setFiles([]);
  };

  const resetForm = () => {
    setSelectedFile(null);
    setSelectedPatient(null);
    setFiles([]);
    setPatientSearchResults([]);
    formik.resetForm();
    setConfirmDialog(false);
    setDispatchSuccess(false);
  };

  return (
    <Box sx={{ p: 3 }}>
      <Typography variant="h4" gutterBottom>
        Dispatch File
      </Typography>

      {/* Search Section */}
      <Card sx={{ p: 3, mb: 3 }}>
        <Paper sx={{ borderBottom: 1, borderColor: 'divider' }}>
          <Tabs
            value={tabValue}
            onChange={(e, newValue) => {
              setTabValue(newValue);
              setSearchType(newValue === 0 ? 'patient' : 'case');
              handleClearFilters();
            }}
          >
            <Tab label="Search by Patient" />
            <Tab label="Search by Case ID" />
          </Tabs>
        </Paper>

        <SearchTab
          searchType={searchType}
          handleSearch={handleSearch}
          loading={loading}
        />

        {/* Patient Search Results */}
        {patientSearchResults.length > 0 && searchType === 'patient' && (
          <Box sx={{ mt: 2 }}>
            <Typography variant="subtitle2" gutterBottom>
              Search Results:
            </Typography>
            <Stack spacing={1}>
              {patientSearchResults.map((patient) => (
                <Card
                  key={patient._id}
                  sx={{
                    p: 2,
                    cursor: 'pointer',
                    '&:hover': { bgcolor: 'action.hover' },
                  }}
                  onClick={() => handlePatientSelect(patient)}
                >
                  <Stack direction="row" justifyContent="space-between" alignItems="center">
                    <Stack>
                      <Typography variant="subtitle1">{patient.patientName}</Typography>
                      <Typography variant="body2" color="text.secondary">
                        Phone: {patient.phoneNumber}
                      </Typography>
                    </Stack>
                    <Button size="small">Select</Button>
                  </Stack>
                </Card>
              ))}
            </Stack>
          </Box>
        )}

        {/* Selected Patient Display */}
        {selectedPatient && (
          <Alert
            severity="info"
            sx={{ mt: 2 }}
            action={
              <Button color="inherit" size="small" onClick={handleClearFilters}>
                Clear
              </Button>
            }
          >
            <Typography variant="body2">
              Selected Patient: {selectedPatient.patientName}
            </Typography>
          </Alert>
        )}
      </Card>

      {/* Files Display */}
      {files.length > 0 && (
        <Card sx={{ p: 3 }}>
          <Typography variant="h6" gutterBottom>
            Available Files
          </Typography>
          <Stack spacing={2}>
            {files.map((file) => (
              <Card
                key={file._id}
                sx={{
                  p: 2,
                  cursor: 'pointer',
                  '&:hover': { bgcolor: 'action.hover' },
                }}
              >
                <Stack direction="row" justifyContent="space-between" alignItems="center">
                  <Stack spacing={1}>
                    <Typography variant="subtitle1">
                      Case ID: {file.caseId}
                    </Typography>
                    <Stack direction="row" spacing={1} alignItems="center">
                      <LocationIcon color="primary" />
                      <Typography variant="body2">
                        Location: {file.rack?.rackId} - {file.subDivision}
                      </Typography>
                    </Stack>
                    <Typography variant="body2" color="text.secondary">
                      Status: {file.status}
                    </Typography>
                  </Stack>
                  <Button
                    variant="contained"
                    onClick={() => handleFileSelect(file)}
                    disabled={file.status !== 'active'}
                  >
                    Dispatch
                  </Button>
                </Stack>
              </Card>
            ))}
          </Stack>
        </Card>
      )}

      {/* Dispatch Dialog */}
      <Dialog
        open={confirmDialog}
        onClose={() => !loading && setConfirmDialog(false)}
        maxWidth="sm"
        fullWidth
      >
        <form onSubmit={formik.handleSubmit}>
          <DialogTitle>
            <Stack direction="row" alignItems="center" justifyContent="space-between">
              <Typography variant="h6">Dispatch File</Typography>
              <IconButton onClick={() => setConfirmDialog(false)}>
                <CloseIcon />
              </IconButton>
            </Stack>
          </DialogTitle>
          <DialogContent>
            {selectedFile && (
              <Stack spacing={3} sx={{ mt: 2 }}>
                <Alert severity="info">
                  <Stack spacing={1}>
                    <Typography variant="body2">
                      Case ID: {selectedFile.caseId}
                    </Typography>
                    <Typography variant="body2">
                      Location: {selectedFile.rack?.rackId} - {selectedFile.subDivision}
                    </Typography>
                    {selectedPatient && (
                      <Typography variant="body2">
                        Patient: {selectedPatient.patientName}
                      </Typography>
                    )}
                  </Stack>
                </Alert>

                <FormControl error={formik.touched.csId && Boolean(formik.errors.csId)}>
                  <Autocomplete
                    options={csUsers}
                    getOptionLabel={(option) => `${option.name} (${option.nishStaffId || 'No ID'})`}
                    value={csUsers.find(user => user._id === formik.values.csId) || null}
                    onChange={(_, newValue) => {
                      formik.setFieldValue('csId', newValue?._id || '');
                    }}
                    renderInput={(params) => (
                      <TextField
                        {...params}
                        label="Select CS User"
                        error={formik.touched.csId && Boolean(formik.errors.csId)}
                      />
                    )}
                    disabled={loading}
                  />
                  {formik.touched.csId && formik.errors.csId && (
                    <FormHelperText>{formik.errors.csId}</FormHelperText>
                  )}
                </FormControl>

                <TextField
                  fullWidth
                  multiline
                  rows={3}
                  name="notes"
                  label="Notes (Optional)"
                  value={formik.values.notes}
                  onChange={formik.handleChange}
                  error={formik.touched.notes && Boolean(formik.errors.notes)}
                  helperText={formik.touched.notes && formik.errors.notes}
                  disabled={loading}
                />
              </Stack>
            )}
          </DialogContent>
          <DialogActions>
            <Button
              onClick={() => setConfirmDialog(false)}
              disabled={loading || dispatchSuccess}
            >
              Cancel
            </Button>
            <Button
              type="submit"
              variant="contained"
              disabled={loading || dispatchSuccess}
            >
              {loading ? <CircularProgress size={24} /> : 'Dispatch File'}
            </Button>
          </DialogActions>
        </form>
      </Dialog>

      {/* Success Dialog */}
      <Dialog
        open={dispatchSuccess}
        maxWidth="sm"
        fullWidth
      >
        <DialogTitle>
          <Typography variant="h6">Success</Typography>
        </DialogTitle>
        <DialogContent>
          <Alert severity="success" sx={{ mt: 2 }}>
            File has been successfully dispatched to the selected CS user.
          </Alert>
        </DialogContent>
        <DialogActions>
          <Button
            variant="contained"
            onClick={resetForm}
          >
            Dispatch Another File
          </Button>
        </DialogActions>
      </Dialog>

      {/* Loading Overlay */}
      {loading && (
        <Box
          sx={{
            position: 'fixed',
            top: 0,
            left: 0,
            right: 0,
            bottom: 0,
            display: 'flex',
            alignItems: 'center',
            justifyContent: 'center',
            backgroundColor: 'rgba(0, 0, 0, 0.5)',
            zIndex: 9999,
          }}
        >
          <CircularProgress />
        </Box>
      )}
    </Box>
  );
};

export default DispatchFile;