import React, { useState, useEffect } from 'react';
import {
  Box,
  Card,
  TextField,
  Button,
  Typography,
  Stack,
  InputAdornment,
  IconButton,
  Dialog,
  DialogTitle,
  DialogContent,
  DialogActions,
  Alert,
  CircularProgress,
  FormControl,
  FormHelperText,
  Autocomplete,
  Paper,
  Tabs,
  Tab,
  Divider,
  Select,
  MenuItem,
  InputLabel,
} from '@mui/material';
import {
  Search as SearchIcon,
  Phone as PhoneIcon,
  Close as CloseIcon,
  CheckCircle as CheckCircleIcon,
} from '@mui/icons-material';
import { DataGrid } from '@mui/x-data-grid';
import { useFormik } from 'formik';
import * as yup from 'yup';
import { useSnackbar } from 'notistack';
import { useSelector } from 'react-redux';
import { jwtDecode } from 'jwt-decode';
import api from '../../../api/axios';

// Validation schema for return and location
const returnSchema = yup.object({
  csId: yup.string().required('Returning CS User is required'),
  notes: yup.string(),
  rackId: yup.string().required('Rack is required'),
  subDivision: yup.string().required('Subdivision is required'),
});

const SearchTab = ({ searchType, handleSearch, loading }) => {
  const [phoneNumber, setPhoneNumber] = useState('');
  const [name, setName] = useState('');
  const [caseId, setCaseId] = useState('');

  return (
    <Stack spacing={2} sx={{ mt: 2 }}>
      {searchType === 'patient' ? (
        <>
          <TextField
            fullWidth
            label="Search by Patient Name"
            value={name}
            onChange={(e) => {
              setName(e.target.value);
              setPhoneNumber('');
            }}
            InputProps={{
              startAdornment: (
                <InputAdornment position="start">
                  <SearchIcon />
                </InputAdornment>
              ),
              endAdornment: name && (
                <InputAdornment position="end">
                  <Button
                    variant="contained"
                    onClick={() => handleSearch('name', name)}
                    disabled={loading || name.length < 3}
                  >
                    Search
                  </Button>
                </InputAdornment>
              ),
            }}
          />
          <TextField
            fullWidth
            label="Search by Phone Number"
            value={phoneNumber}
            onChange={(e) => {
              setPhoneNumber(e.target.value.replace(/\\D/g, '').slice(0, 10));
              setName('');
            }}
            InputProps={{
              startAdornment: (
                <InputAdornment position="start">
                  <PhoneIcon />
                </InputAdornment>
              ),
              endAdornment: phoneNumber && (
                <InputAdornment position="end">
                  <Button
                    variant="contained"
                    onClick={() => handleSearch('phone', phoneNumber)}
                    disabled={loading || phoneNumber.length !== 10}
                  >
                    Search
                  </Button>
                </InputAdornment>
              ),
            }}
          />
        </>
      ) : (
        <TextField
          fullWidth
          label="Search by Case ID"
          value={caseId}
          onChange={(e) => setCaseId(e.target.value)}
          InputProps={{
            startAdornment: (
              <InputAdornment position="start">
                <SearchIcon />
              </InputAdornment>
            ),
            endAdornment: caseId && (
              <InputAdornment position="end">
                <Button
                  variant="contained"
                  onClick={() => handleSearch('case', caseId)}
                  disabled={loading || !caseId}
                >
                  Search
                </Button>
              </InputAdornment>
            ),
          }}
        />
      )}
    </Stack>
  );
};

const ReturnFile = () => {
  const [loading, setLoading] = useState(false);
  const [files, setFiles] = useState([]);
  const [selectedFile, setSelectedFile] = useState(null);
  const [confirmDialog, setConfirmDialog] = useState(false);
  const [locationDialog, setLocationDialog] = useState(false);
  const [returnSuccess, setReturnSuccess] = useState(false);
  const [csUsers, setCsUsers] = useState([]);
  const [tabValue, setTabValue] = useState(0);
  const [searchType, setSearchType] = useState('patient');
  const [patientSearchResults, setPatientSearchResults] = useState([]);
  const [selectedPatient, setSelectedPatient] = useState(null);
  const [racks, setRacks] = useState([]);
  const [subdivisions, setSubdivisions] = useState([]);
  const [selectedRack, setSelectedRack] = useState(null);

  const { enqueueSnackbar } = useSnackbar();
  const token = useSelector(state => state.auth.token);
  const userId = token ? jwtDecode(token).userId : null;

  const formik = useFormik({
    initialValues: {
      csId: '',
      notes: '',
      rackId: '',
      subDivision: '',
    },
    validationSchema: returnSchema,
    onSubmit: async (values) => {
      try {
        // First handle the file return
        const returnResponse = await api.post('/file-transfers/return', {
          userId,
          csId: values.csId,
          fileId: selectedFile.fileId,
          notes: values.notes ? { content: values.notes } : undefined,
        });

        if (returnResponse.data.success) {
          // Then update the file location
          const locationResponse = await api.put('/file-records/location', {
            userId,
            fileId: selectedFile.fileId,
            rackId: values.rackId,
            subDivision: values.subDivision,
          });

          if (locationResponse.data.success) {
            setReturnSuccess(true);
            enqueueSnackbar('File returned and location updated successfully', { variant: 'success' });
            fetchDispatchedFiles();
          }
        }
      } catch (error) {
        enqueueSnackbar(error.response?.data?.message || 'Error processing file return', {
          variant: 'error',
        });
      }
    },
  });

  useEffect(() => {
    const fetchInitialData = async () => {
      try {
        const [csResponse, rackResponse] = await Promise.all([
          api.get('/users', { params: { level: 'cs', status: 'active' } }),
          api.get('/racks/active')
        ]);

        setCsUsers(csResponse.data.data);
        setRacks(rackResponse.data.data);
      } catch (error) {
        enqueueSnackbar('Error fetching initial data', { variant: 'error' });
      }
    };

    fetchInitialData();
    fetchDispatchedFiles();
  }, [enqueueSnackbar]);

  useEffect(() => {
    const fetchSubdivisions = async () => {
      if (!formik.values.rackId) {
        setSubdivisions([]);
        return;
      }

      try {
        const selectedRack = racks.find(r => r._id === formik.values.rackId);
        if (!selectedRack) return;

        const response = await api.get(`/racks/subdivisions/${selectedRack.rackId}`);
        setSubdivisions(response.data.data);
      } catch (error) {
        enqueueSnackbar('Error fetching subdivisions', { variant: 'error' });
      }
    };

    fetchSubdivisions();
  }, [formik.values.rackId, racks]);

  const fetchDispatchedFiles = async () => {
    setLoading(true);
    try {
      const response = await api.get('/file-transfers/dispatched', {
        params: { userId }
      });
  
      if (response.data.success) {
        const processedFiles = response.data.data.map(file => ({
          ...file,
          caseId: file.caseId,
          patientName: file.patientName
        }));
        setFiles(processedFiles);
      }
    } catch (error) {
      enqueueSnackbar('Error fetching dispatched files', { variant: 'error' });
    } finally {
      setLoading(false);
    }
  };

  const handleSearch = async (type, value) => {
    if (!value || loading) return;
    
    setLoading(true);
    try {
      switch(type) {
        case 'case':
        const caseResponse = await api.get('/file-transfers/dispatched-by-case', {
          params: { 
            userId,
            caseId: value.trim()
          }
        });
        
        if (caseResponse.data.success) {
          
          const processedFiles = caseResponse.data.data
            .filter(file => file.fileId)
            .map(file => ({
              id: file._id,
              caseId: file.fileId.caseId,
              patientName: file.fileId.patient?.patientName || 'N/A',
              csUser: file.csId?.name || 'N/A',
              dispatchedAt: new Date(file.dispatchedAt).toLocaleDateString(),
              ...file
            }));

          setFiles(processedFiles);
          if (processedFiles.length === 0) {
            enqueueSnackbar('No dispatched file found with this Case ID', { variant: 'info' });
          }
        }
        setPatientSearchResults([]);
        break;
  
        case 'name':
          const nameResponse = await api.get('/patients/search/name', {
            params: { 
              name: value,
              userId 
            }
          });
          
          if (nameResponse.data.success) {
            setPatientSearchResults(nameResponse.data.data);
            setFiles([]);
          }
          break;
  
        case 'phone':
          const phoneResponse = await api.get('/patients/search/phone', {
            params: { 
              phoneNumber: value,
              userId 
            }
          });
          
          if (phoneResponse.data.success) {
            setPatientSearchResults(phoneResponse.data.data);
            setFiles([]);
          }
          break;
      }
    } catch (error) {
      enqueueSnackbar('Error searching', { variant: 'error' });
      setFiles([]);
      setPatientSearchResults([]);
    } finally {
      setLoading(false);
    }
  };
  
  const handlePatientSelect = async (patient) => {
    setSelectedPatient(patient);
    setPatientSearchResults([]);
    setLoading(true);
    
    try {
      const response = await api.get('/file-transfers/dispatched', {
        params: { 
          userId,
          patientId: patient._id
        }
      });
  
      if (response.data.success) {
        const processedFiles = response.data.data
          .filter(file => file.fileId)
          .map(file => ({
            id: file._id,
            caseId: file.fileId.caseId,
            patientName: patient.patientName,
            csUser: file.csId?.name || 'N/A',
            dispatchedAt: new Date(file.dispatchedAt).toLocaleDateString(),
            ...file
          }));
        
        setFiles(processedFiles);
        if (processedFiles.length === 0) {
          enqueueSnackbar('No dispatched files found for this patient', { variant: 'info' });
        }
      }
    } catch (error) {
      enqueueSnackbar('Error fetching patient files', { variant: 'error' });
      setFiles([]);
    } finally {
      setLoading(false);
    }
  };
  const handleFileSelect = (file) => {
    setSelectedFile(file);
    formik.resetForm();
    setConfirmDialog(true);
  };

  const handleClearFilters = () => {
    setSelectedPatient(null);
    setPatientSearchResults([]);
    fetchDispatchedFiles();
  };

  const handleConfirmDialogClose = () => {
    if (!loading) {
      setConfirmDialog(false);
      formik.resetForm();
    }
  };

  const resetForm = () => {
    setSelectedFile(null);
    setSelectedRack(null);
    formik.resetForm();
    setConfirmDialog(false);
    setLocationDialog(false);
    setReturnSuccess(false);
    setSelectedPatient(null);
    setPatientSearchResults([]);
    fetchDispatchedFiles();
  };

  const columns = [
    {
      field: 'caseId',
      headerName: 'Case ID',
      flex: 1,
      valueGetter: (params) => params.row.fileId?.caseId || params.row.caseId || 'N/A'
    },
    {
      field: 'patientName',
      headerName: 'Patient',
      flex: 1,
      valueGetter: (params) => params.row.fileId?.patient?.patientName || params.row.patientName || 'N/A'
    },
    {
      field: 'csName',
      headerName: 'CS User',
      flex: 1,
      valueGetter: (params) => params.row.csId?.name || 'N/A'
    },
    {
      field: 'dispatchedAt',
      headerName: 'Dispatched Date',
      flex: 1,
      valueGetter: (params) => new Date(params.row.dispatchedAt).toLocaleDateString()
    },
    {
      field: 'actions',
      headerName: 'Actions',
      flex: 1,
      renderCell: (params) => (
        <Button
          variant="contained"
          color="primary"
          size="small"
          onClick={() => handleFileSelect(params.row)}
        >
          Return
        </Button>
      ),
    }
  ];

  return (
    <Box sx={{ p: 3 }}>
      <Typography variant="h4" gutterBottom>
        Return File
      </Typography>

      <Card sx={{ p: 3, mb: 3 }}>
        <Paper sx={{ borderBottom: 1, borderColor: 'divider' }}>
          <Tabs
            value={tabValue}
            onChange={(e, newValue) => {
              setTabValue(newValue);
              setSearchType(newValue === 0 ? 'patient' : 'case');
              handleClearFilters();
            }}
          >
            <Tab label="Search by Patient" />
            <Tab label="Search by Case ID" />
          </Tabs>
        </Paper>
        <SearchTab
          searchType={searchType}
          handleSearch={handleSearch}
          loading={loading}
        />

        {patientSearchResults.length > 0 && searchType === 'patient' && (
          <Box sx={{ mt: 2 }}>
            <Typography variant="subtitle2" gutterBottom>
              Search Results:
            </Typography>
            <Stack spacing={1}>
              {patientSearchResults.map((patient) => (
                <Card
                  key={patient._id}
                  sx={{
                    p: 2,
                    cursor: 'pointer',
                    '&:hover': { bgcolor: 'action.hover' },
                  }}
                  onClick={() => handlePatientSelect(patient)}
                >
                  <Stack direction="row" justifyContent="space-between" alignItems="center">
                    <Stack>
                      <Typography variant="subtitle1">{patient.patientName}</Typography>
                      <Typography variant="body2" color="text.secondary">
                        Phone: {patient.phoneNumber}
                      </Typography>
                    </Stack>
                    <Button size="small">Select</Button>
                  </Stack>
                </Card>
              ))}
            </Stack>
          </Box>
        )}

        {selectedPatient && (
          <Alert
            severity="info"
            sx={{ mt: 2 }}
            action={
              <Button
                color="inherit"
                size="small"
                onClick={handleClearFilters}
              >
                Clear Filter
              </Button>
            }
          >
            <Typography variant="body2">
              Showing files for patient: {selectedPatient.patientName}
            </Typography>
          </Alert>
        )}
      </Card>

      <Card>
        <DataGrid
          rows={files}
          columns={columns}
          getRowId={(row) => row._id}
          autoHeight
          disableSelectionOnClick
          loading={loading}
          pageSize={10}
          components={{
            NoRowsOverlay: () => (
              <Stack height="100%" alignItems="center" justifyContent="center" py={3}>
                <Typography color="text.secondary">
                  {searchType === 'case' 
                    ? 'Enter a Case ID to search for dispatched files' 
                    : selectedPatient 
                      ? 'No dispatched files found for this patient'
                      : 'Search for a patient to view their dispatched files'
                  }
                </Typography>
              </Stack>
            ),
          }}
        />
      </Card>

      <Dialog
        open={confirmDialog}
        onClose={handleConfirmDialogClose}
        maxWidth="sm"
        fullWidth
      >
        <form onSubmit={formik.handleSubmit}>
          <DialogTitle>
            <Stack direction="row" alignItems="center" justifyContent="space-between">
              <Typography variant="h6">Return File</Typography>
              <IconButton onClick={handleConfirmDialogClose}>
                <CloseIcon />
              </IconButton>
            </Stack>
          </DialogTitle>
          <DialogContent>
            {selectedFile && (
              <Stack spacing={3} sx={{ mt: 2 }}>
                <Alert severity="info">
                  <Stack spacing={1}>
                    <Typography variant="body2">
                      Case ID: {selectedFile.caseId}
                    </Typography>
                    <Typography variant="body2">
                      Dispatched To: {selectedFile.csId?.name}
                    </Typography>
                    <Typography variant="body2">
                      Dispatched Date: {new Date(selectedFile.dispatchedAt).toLocaleDateString()}
                    </Typography>
                  </Stack>
                </Alert>

                <FormControl error={formik.touched.csId && Boolean(formik.errors.csId)}>
                  <Autocomplete
                    options={csUsers}
                    getOptionLabel={(option) => `${option.name} (${option.nishStaffId || 'No ID'})`}
                    value={csUsers.find(user => user._id === formik.values.csId) || null}
                    onChange={(_, newValue) => {
                      formik.setFieldValue('csId', newValue?._id || '');
                    }}
                    renderInput={(params) => (
                      <TextField
                        {...params}
                        label="Select Returning CS User"
                        error={formik.touched.csId && Boolean(formik.errors.csId)}
                      />
                    )}
                    disabled={loading}
                  />
                  {formik.touched.csId && formik.errors.csId && (
                    <FormHelperText>{formik.errors.csId}</FormHelperText>
                  )}
                </FormControl>

                <FormControl fullWidth error={formik.touched.rackId && Boolean(formik.errors.rackId)}>
                  <InputLabel>Rack</InputLabel>
                  <Select
                    value={formik.values.rackId}
                    label="Rack"
                    onChange={(e) => {
                      formik.setFieldValue('rackId', e.target.value);
                      formik.setFieldValue('subDivision', '');
                    }}
                    disabled={loading}
                  >
                    {racks.map((rack) => (
                      <MenuItem key={rack._id} value={rack._id}>
                        {rack.rackId}
                      </MenuItem>
                    ))}
                  </Select>
                  {formik.touched.rackId && formik.errors.rackId && (
                    <FormHelperText>{formik.errors.rackId}</FormHelperText>
                  )}
                </FormControl>

                <FormControl fullWidth error={formik.touched.subDivision && Boolean(formik.errors.subDivision)}>
                  <InputLabel>Subdivision</InputLabel>
                  <Select
                    value={formik.values.subDivision}
                    label="Subdivision"
                    onChange={(e) => formik.setFieldValue('subDivision', e.target.value)}
                    disabled={loading || !formik.values.rackId}
                  >
                    {subdivisions.map((sub) => (
                      <MenuItem key={sub} value={sub}>
                        {sub}
                      </MenuItem>
                    ))}
                  </Select>
                  {formik.touched.subDivision && formik.errors.subDivision && (
                    <FormHelperText>{formik.errors.subDivision}</FormHelperText>
                  )}
                </FormControl>

                <TextField
                  fullWidth
                  multiline
                  rows={3}
                  name="notes"
                  label="Notes (Optional)"
                  value={formik.values.notes}
                  onChange={formik.handleChange}
                  error={formik.touched.notes && Boolean(formik.errors.notes)}
                  helperText={formik.touched.notes && formik.errors.notes}
                  disabled={loading}
                />
              </Stack>
            )}
          </DialogContent>
          <DialogActions>
            <Button
              onClick={handleConfirmDialogClose}
              disabled={loading || returnSuccess}
            >
              Cancel
            </Button>
            <Button
              type="submit"
              variant="contained"
              disabled={loading || returnSuccess}
            >
              {loading ? <CircularProgress size={24} /> : 'Return File'}
            </Button>
          </DialogActions>
        </form>
      </Dialog>

      <Dialog
        open={returnSuccess}
        maxWidth="sm"
        fullWidth
      >
        <DialogTitle>
          <Stack direction="row" alignItems="center" spacing={1}>
            <CheckCircleIcon color="success" />
            <Typography variant="h6">Success</Typography>
          </Stack>
        </DialogTitle>
        <DialogContent>
          <Alert severity="success" sx={{ mt: 2 }}>
            File has been successfully returned and location updated.
          </Alert>
        </DialogContent>
        <DialogActions>
          <Button
            variant="contained"
            onClick={resetForm}
          >
            Return Another File
          </Button>
        </DialogActions>
      </Dialog>

      {loading && (
        <Box
          sx={{
            position: 'fixed',
            top: 0,
            left: 0,
            right: 0,
            bottom: 0,
            display: 'flex',
            alignItems: 'center',
            justifyContent: 'center',
            backgroundColor: 'rgba(0, 0, 0, 0.5)',
            zIndex: 9999,
          }}
        >
          <CircularProgress />
        </Box>
      )}
    </Box>
  );
};

export default ReturnFile;