import React, { useState, useEffect, useRef } from 'react';
import { 
  Box, 
  Typography, 
  Card, 
  Stack, 
  Button
} from '@mui/material';
import { 
  DataGrid, 
  GridToolbar 
} from '@mui/x-data-grid';
import { 
  Print as PrintIcon
} from '@mui/icons-material';
import { useSnackbar } from 'notistack';
import { useSelector } from 'react-redux';
import {jwtDecode }from 'jwt-decode';
import jsPDF from 'jspdf';
import 'jspdf-autotable';
import api from '../../../api/axios';
import moment from 'moment';

const GetDispatchedFiles = () => {
  const [files, setFiles] = useState([]);
  const [error, setError] = useState(null);
  const [loading, setLoading] = useState(false);
  const [pagination, setPagination] = useState({
    page: 0,
    pageSize: 10,
    total: 0
  });

  const { enqueueSnackbar } = useSnackbar();
  const token = useSelector(state => state.auth.token);
  const userId = token ? jwtDecode(token).userId : null;
  const pdfRef = useRef(null);

  const fetchDispatchedFiles = async () => {
    setLoading(true);
    setError(null);
    try {
      const params = {
        page: pagination.page + 1,
        limit: pagination.pageSize,
        userId
      };

      const response = await api.get('/file-transfers/dispatched', { params });
      setFiles(response.data.data);

      if (response.data.pagination) {
        setPagination(prev => ({
          ...prev,
          total: response.data.pagination.totalRecords
        }));
      }
    } catch (error) {
      setError('Error fetching dispatched files');
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchDispatchedFiles();
  }, [pagination.page, pagination.pageSize]);

  const generatePDF = () => {
    const doc = new jsPDF('landscape');

    doc.setFontSize(16);
    doc.text('NISH Medical Record Room - FMS', 148.5, 15, { align: 'center' });

    doc.setFontSize(12);
    doc.text(`Dispatched Files Report - ${moment().format('YYYY-MM-DD')}`, 148.5, 22, { align: 'center' });

    const columns = [
      { header: 'Case ID', dataKey: 'caseId' },
      { header: 'Patient Name', dataKey: 'patientName' },
      { header: 'CS User', dataKey: 'csId.name' },
      { header: 'MRRS User', dataKey: 'mrrsId.name' },
      { header: 'Dispatched Date', dataKey: 'dispatchedAt' }
    ];

    const formattedData = files.map(file => ({
      caseId: file.caseId,
      patientName: file.patientName,
      'csId.name': file.csId?.name || 'N/A',
      'mrrsId.name': file.mrrsId?.name || 'N/A',
      dispatchedAt: moment(file.dispatchedAt).format('YYYY-MM-DD')
    }));

    doc.autoTable({
      columns,
      body: formattedData,
      startY: 30,
      theme: 'striped',
      styles: { 
        fontSize: 9,
        cellPadding: 3 
      },
      headStyles: { 
        fillColor: [0, 51, 102],
        textColor: 255 
      },
      columnStyles: {
        dispatchedAt: {
          cellWidth: 30,
          halign: 'center'
        }
      }
    });

    doc.save(`Dispatched_Files_${moment().format('YYYYMMDD')}.pdf`);
  };

  const columns = [
    { 
      field: 'caseId', 
      headerName: 'Case ID', 
      flex: 1,
      minWidth: 120 
    },
    { 
      field: 'patientName', 
      headerName: 'Patient Name', 
      flex: 1,
      minWidth: 150 
    },
    { 
      field: 'csId.name', 
      headerName: 'CS User', 
      flex: 1,
      minWidth: 150,
      valueGetter: (params) => params.row.csId?.name || 'N/A'
    },
    { 
      field: 'mrrsId.name', 
      headerName: 'MRRS User', 
      flex: 1,
      minWidth: 150,
      valueGetter: (params) => params.row.mrrsId?.name || 'N/A'
    },
    { 
      field: 'dispatchedAt', 
      headerName: 'Dispatched Date', 
      flex: 1,
      minWidth: 120,
      valueGetter: (params) => moment(params.value).format('YYYY-MM-DD')
    }
  ];

  return (
    <Box sx={{ p: 3 }}>
      <Typography variant="h4" gutterBottom align="center">
        Dispatched Files Report
      </Typography>

      <Card sx={{ p: 3, mb: 3 }}>
        <Stack 
          direction="row" 
          spacing={2} 
          alignItems="center" 
          justifyContent="flex-end"
        >
          <Button
            variant="contained"
            startIcon={<PrintIcon />}
            onClick={generatePDF}
          >
            Print Report
          </Button>
        </Stack>
      </Card>

      {error && (
        <Typography variant="body1" color="error" sx={{ mb: 2 }}>
          {error}
        </Typography>
      )}

      <Card>
        <DataGrid
          ref={pdfRef}
          rows={files}
          columns={columns}
          getRowId={(row) => row._id}
          pagination
          paginationMode="server"
          rowCount={pagination.total}
          page={pagination.page}
          pageSize={pagination.pageSize}
          loading={loading}
          onPageChange={(newPage) => setPagination(prev => ({ ...prev, page: newPage }))}
          onPageSizeChange={(newPageSize) => 
            setPagination(prev => ({ ...prev, pageSize: newPageSize, page: 0 }))
          }
          components={{
            Toolbar: GridToolbar,
          }}
          componentsProps={{
            toolbar: {
              showQuickFilter: true,
              quickFilterProps: { debounceMs: 500 },
            },
          }}
          sx={{
            height: '70vh'
          }}
        />
      </Card>
    </Box>
  );
};

export default GetDispatchedFiles;
