import React, { useState, useEffect } from 'react';
import {
  Box,
  Card,
  IconButton,
  Tooltip,
  Dialog,
  DialogTitle,
  DialogContent,
  DialogActions,
  Button,
  TextField,
  Typography,
  Stack,
  Chip,
  Alert,
  CircularProgress,
} from '@mui/material';
import {
  DataGrid,
  GridToolbar,
} from '@mui/x-data-grid';
import {
  Edit as EditIcon,
  Add as AddIcon,
  Delete as DeleteIcon,
} from '@mui/icons-material';
import { useSnackbar } from 'notistack';
import * as yup from 'yup';
import { useFormik } from 'formik';
import api from '../../../api/axios';
import { useSelector } from 'react-redux';
import { jwtDecode } from 'jwt-decode';

// Validation schema for rack updates
const rackSchema = yup.object({
  rackId: yup.string()
    .required('Rack ID is required')
    .matches(/^[A-Za-z0-9-]+$/, 'Only alphanumeric characters and hyphens are allowed')
    .min(2, 'Rack ID must be at least 2 characters')
    .max(20, 'Rack ID must be at most 20 characters'),
  subDivision: yup.string()
    .matches(/^[A-Za-z0-9-]*$/, 'Only alphanumeric characters and hyphens are allowed')
});

const ManageRacks = () => {
  const [racks, setRacks] = useState([]);
  const [loading, setLoading] = useState(true);
  const [editDialog, setEditDialog] = useState(false);
  const [selectedRack, setSelectedRack] = useState(null);
  const [subDivisions, setSubDivisions] = useState([]);
  const [confirmDialog, setConfirmDialog] = useState({
    open: false,
    title: '',
    message: '',
    action: null,
  });

  const { enqueueSnackbar } = useSnackbar();
  const token = useSelector(state => state.auth.token);
  const adminId = token ? jwtDecode(token).userId : null;

  const formik = useFormik({
    initialValues: {
      rackId: '',
      subDivision: ''
    },
    validationSchema: rackSchema,
    onSubmit: async () => {
      if (subDivisions.length === 0) {
        enqueueSnackbar('At least one subdivision is required', { variant: 'error' });
        return;
      }
      handleConfirmUpdate();
    }
  });

  const columns = [
    {
      field: 'rackId',
      headerName: 'Rack ID',
      flex: 1,
      minWidth: 150,
    },
    {
      field: 'subDivision',
      headerName: 'Subdivisions',
      flex: 2,
      minWidth: 200,
      renderCell: (params) => (
        <Stack direction="row" spacing={1} flexWrap="wrap">
          {params.value.map((sub, index) => (
            <Chip key={index} label={sub} size="small" />
          ))}
        </Stack>
      )
    },
    {
      field: 'actions',
      headerName: 'Actions',
      width: 100,
      sortable: false,
      renderCell: (params) => (
        <Tooltip title="Edit Rack">
          <IconButton
            onClick={() => handleEdit(params.row)}
            color="primary"
            size="small"
          >
            <EditIcon />
          </IconButton>
        </Tooltip>
      ),
    }
  ];

  // Fetch racks data
  const fetchRacks = async () => {
    try {
      setLoading(true);
      const response = await api.get('/racks/active');
      setRacks(response.data.data);
    } catch (error) {
      enqueueSnackbar('Error fetching racks', { variant: 'error' });
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchRacks();
  }, []);

  const handleEdit = (rack) => {
    setSelectedRack(rack);
    formik.setValues({
      rackId: rack.rackId,
      subDivision: ''
    });
    setSubDivisions([...rack.subDivision]);
    setEditDialog(true);
  };

  const handleAddSubDivision = () => {
    if (!formik.values.subDivision) return;
    
    if (subDivisions.includes(formik.values.subDivision)) {
      enqueueSnackbar('Subdivision already exists', { variant: 'error' });
      return;
    }

    setSubDivisions([...subDivisions, formik.values.subDivision]);
    formik.setFieldValue('subDivision', '');
  };

  const handleDeleteSubDivision = (index) => {
    const newSubDivisions = subDivisions.filter((_, i) => i !== index);
    setSubDivisions(newSubDivisions);
  };

  const handleConfirmUpdate = () => {
    setConfirmDialog({
      open: true,
      title: 'Confirm Rack Update',
      message: `Are you sure you want to update this rack? This action cannot be undone.`,
      action: handleUpdate,
    });
  };

  const handleUpdate = async () => {
    setLoading(true);
    try {
      const response = await api.put('/racks', {
        adminId,
        rackId: selectedRack.rackId,
        newRackId: formik.values.rackId,
        subDivision: subDivisions,
      });

      if (response.data.success) {
        enqueueSnackbar('Rack updated successfully', { variant: 'success' });
        setEditDialog(false);
        setConfirmDialog({ ...confirmDialog, open: false });
        fetchRacks();
      }
    } catch (error) {
      enqueueSnackbar(error.response?.data?.message || 'Error updating rack', { 
        variant: 'error' 
      });
    } finally {
      setLoading(false);
    }
  };

  return (
    <Box sx={{ p: 3 }}>
      <Typography variant="h4" gutterBottom>
        Manage Racks
      </Typography>

      <Card>
        <DataGrid
          rows={racks}
          columns={columns}
          getRowId={(row) => row._id}
          loading={loading}
          autoHeight
          disableSelectionOnClick
          components={{
            Toolbar: GridToolbar,
          }}
          componentsProps={{
            toolbar: {
              showQuickFilter: true,
              quickFilterProps: { debounceMs: 500 },
            },
          }}
          sx={{
            '& .MuiDataGrid-toolbarContainer': {
              padding: 2,
              borderBottom: '1px solid',
              borderColor: 'divider',
            },
          }}
        />
      </Card>

      {/* Edit Dialog */}
      <Dialog
        open={editDialog}
        onClose={() => !loading && setEditDialog(false)}
        maxWidth="sm"
        fullWidth
      >
        <form onSubmit={formik.handleSubmit}>
          <DialogTitle>Edit Rack</DialogTitle>
          <DialogContent>
            <Stack spacing={3} sx={{ mt: 2 }}>
              <TextField
                fullWidth
                name="rackId"
                label="Rack ID"
                value={formik.values.rackId}
                onChange={formik.handleChange}
                error={formik.touched.rackId && Boolean(formik.errors.rackId)}
                helperText={formik.touched.rackId && formik.errors.rackId}
                disabled={loading}
              />

              <Stack direction="row" spacing={2}>
                <TextField
                  fullWidth
                  name="subDivision"
                  label="Add Subdivision"
                  value={formik.values.subDivision}
                  onChange={formik.handleChange}
                  error={formik.touched.subDivision && Boolean(formik.errors.subDivision)}
                  helperText={formik.touched.subDivision && formik.errors.subDivision}
                  disabled={loading}
                />
                <Button
                  variant="contained"
                  onClick={handleAddSubDivision}
                  disabled={!formik.values.subDivision || loading}
                  startIcon={<AddIcon />}
                >
                  Add
                </Button>
              </Stack>

              {subDivisions.length > 0 && (
                <Box>
                  <Typography variant="subtitle2" gutterBottom>
                    Subdivisions:
                  </Typography>
                  <Stack direction="row" flexWrap="wrap" gap={1}>
                    {subDivisions.map((sub, index) => (
                      <Chip
                        key={index}
                        label={sub}
                        onDelete={() => handleDeleteSubDivision(index)}
                        disabled={loading}
                      />
                    ))}
                  </Stack>
                </Box>
              )}

              <Alert severity="warning">
                Note: Editing a rack will affect all files currently assigned to this rack.
              </Alert>
            </Stack>
          </DialogContent>
          <DialogActions>
            <Button
              onClick={() => setEditDialog(false)}
              disabled={loading}
            >
              Cancel
            </Button>
            <Button
              type="submit"
              variant="contained"
              disabled={loading}
            >
              Update Rack
            </Button>
          </DialogActions>
        </form>
      </Dialog>

      {/* Confirmation Dialog */}
      <Dialog
        open={confirmDialog.open}
        onClose={() => !loading && setConfirmDialog({ ...confirmDialog, open: false })}
      >
        <DialogTitle>{confirmDialog.title}</DialogTitle>
        <DialogContent>
          <Stack spacing={2}>
            <Typography>{confirmDialog.message}</Typography>
            <Alert severity="info">
              <Typography variant="subtitle2">
                New Rack ID: {formik.values.rackId}
              </Typography>
              <Typography variant="subtitle2">
                New Subdivisions: {subDivisions.join(', ')}
              </Typography>
            </Alert>
          </Stack>
        </DialogContent>
        <DialogActions>
          <Button
            onClick={() => setConfirmDialog({ ...confirmDialog, open: false })}
            disabled={loading}
          >
            Cancel
          </Button>
          <Button
            onClick={confirmDialog.action}
            variant="contained"
            disabled={loading}
          >
            {loading ? <CircularProgress size={24} /> : 'Confirm'}
          </Button>
        </DialogActions>
      </Dialog>
    </Box>
  );
};

export default ManageRacks;