import React, { useState, useEffect } from 'react';
import {
  Box,
  Card,
  TextField,
  Button,
  Typography,
  Stack,
  InputAdornment,
  IconButton,
  Tooltip,
  Dialog,
  DialogTitle,
  DialogContent,
  Alert,
  CircularProgress,
  Divider,
  List,
  ListItem,
  ListItemText,
  Paper,
  Tabs,
  Tab,
} from '@mui/material';
import {
  Search as SearchIcon,
  Phone as PhoneIcon,
  LocationOn as LocationIcon,
  Person as PersonIcon,
  Close as CloseIcon,
} from '@mui/icons-material';
import { DataGrid, GridToolbar } from '@mui/x-data-grid';
import { useSnackbar } from 'notistack';
import { useSelector } from 'react-redux';
import { jwtDecode } from 'jwt-decode';
import api from '../../../api/axios';

const SearchTab = ({ searchType, handleSearch, loading }) => {
  const [phoneNumber, setPhoneNumber] = useState('');
  const [name, setName] = useState('');
  const [caseId, setCaseId] = useState('');

  return (
    <Stack spacing={2} sx={{ mt: 2 }}>
      {searchType === 'patient' ? (
        <>
          <TextField
            fullWidth
            label="Search by Patient Name"
            value={name}
            onChange={(e) => {
              setName(e.target.value);
              setPhoneNumber(''); // Clear phone when name is being entered
            }}
            InputProps={{
              startAdornment: (
                <InputAdornment position="start">
                  <SearchIcon />
                </InputAdornment>
              ),
              endAdornment: name && (
                <InputAdornment position="end">
                  <Button
                    variant="contained"
                    onClick={() => handleSearch('name', name)}
                    disabled={loading || name.length < 3}
                  >
                    Search
                  </Button>
                </InputAdornment>
              ),
            }}
          />
          <TextField
            fullWidth
            label="Search by Phone Number"
            value={phoneNumber}
            onChange={(e) => {
              setPhoneNumber(e.target.value.replace(/\D/g, '').slice(0, 10));
              setName(''); // Clear name when phone is being entered
            }}
            InputProps={{
              startAdornment: (
                <InputAdornment position="start">
                  <PhoneIcon />
                </InputAdornment>
              ),
              endAdornment: phoneNumber && (
                <InputAdornment position="end">
                  <Button
                    variant="contained"
                    onClick={() => handleSearch('phone', phoneNumber)}
                    disabled={loading || phoneNumber.length !== 10}
                  >
                    Search
                  </Button>
                </InputAdornment>
              ),
            }}
          />
        </>
      ) : (
        <TextField
          fullWidth
          label="Search by Case ID"
          value={caseId}
          onChange={(e) => setCaseId(e.target.value)}
          InputProps={{
            startAdornment: (
              <InputAdornment position="start">
                <SearchIcon />
              </InputAdornment>
            ),
            endAdornment: caseId && (
              <InputAdornment position="end">
                <Button
                  variant="contained"
                  onClick={() => handleSearch('case', caseId)}
                  disabled={loading || !caseId}
                >
                  Search
                </Button>
              </InputAdornment>
            ),
          }}
        />
      )}
    </Stack>
  );
};

const ManageFiles = () => {
  const [files, setFiles] = useState([]);
  const [loading, setLoading] = useState(false);
  const [tabValue, setTabValue] = useState(0);
  const [searchType, setSearchType] = useState('patient');
  const [patientSearchResults, setPatientSearchResults] = useState([]);
  const [selectedPatient, setSelectedPatient] = useState(null);
  const [selectedFile, setSelectedFile] = useState(null);
  const [locationHistoryDialog, setLocationHistoryDialog] = useState(false);
  const [patientDetailsDialog, setPatientDetailsDialog] = useState(false);
  const [locationHistory, setLocationHistory] = useState([]);
  const [pagination, setPagination] = useState({
    page: 0,
    pageSize: 10,
  });
  const [totalFiles, setTotalFiles] = useState(0);

  const { enqueueSnackbar } = useSnackbar();
  const token = useSelector(state => state.auth.token);
  const userId = token ? jwtDecode(token).userId : null;

  useEffect(() => {
    fetchAllFiles();
  }, [pagination.page, pagination.pageSize]);

  const fetchAllFiles = async () => {
    setLoading(true);
    try {
      const response = await api.get(`/file-records/all`, {
        params: {
          page: pagination.page + 1,
          limit: pagination.pageSize,
          userId
        }
      });
      
      if (response.data.success) {
        setFiles(response.data.data);
 
        setTotalFiles(response.data.pagination.totalRecords);
      }
    } catch (error) {
      enqueueSnackbar('Error fetching files', { variant: 'error' });
    } finally {
      setLoading(false);
    }
  };

  const handleSearch = async (type, value) => {
    if (!value) return;
    
    setLoading(true);
    try {
      let response;
      
      if (type === 'phone') {
        if (value.length !== 10) {
          enqueueSnackbar('Please enter a valid 10-digit phone number', { variant: 'warning' });
          return;
        }
        response = await api.get(`/patients/search/phone?phoneNumber=${value}&userId=${userId}`);
      } 
      else if (type === 'name') {
        if (value.length < 3) {
          enqueueSnackbar('Please enter at least 3 characters', { variant: 'warning' });
          return;
        }
        response = await api.get(`/patients/search/name?name=${value}&userId=${userId}`);
      } 
      else if (type === 'case') {
        response = await api.get(`/file-records/case/${value}?userId=${userId}`);
        if (response.data.success) {
          setFiles(Array.isArray(response.data.data) ? response.data.data : [response.data.data]);
          setTotalFiles(Array.isArray(response.data.data) ? response.data.data.length : 1);
          setPatientSearchResults([]);
          return;
        }
      }

      if (response?.data.success) {
        if (type === 'case') {
          setFiles(Array.isArray(response.data.data) ? response.data.data : [response.data.data]);
          setTotalFiles(Array.isArray(response.data.data) ? response.data.data.length : 1);
          setPatientSearchResults([]);
        } else {
          setPatientSearchResults(response.data.data || []);
          if (!response.data.data?.length) {
            enqueueSnackbar('No patients found', { variant: 'info' });
          }
        }
      }
    } catch (error) {
      console.error('Search error:', error);
      if (type === 'case') {
        enqueueSnackbar('File not found', { variant: 'info' });
        setFiles([]);
        setTotalFiles(0);
      } else {
        enqueueSnackbar(error.response?.data?.message || 'Error searching', { variant: 'error' });
      }
      setPatientSearchResults([]);
    } finally {
      setLoading(false);
    }
  };

  const handlePatientSelect = async (patient) => {
    setSelectedPatient(patient);
    setPatientSearchResults([]);
    setLoading(true);
    try {
      const response = await api.get(`/file-records/patient/${patient._id}?userId=${userId}`);
      if (response.data.success) {
        
        const patientFiles = response.data.data || [];
        setFiles(patientFiles);
        setTotalFiles(patientFiles.length);
      }
    } catch (error) {
      console.error('Patient files error:', error);
      enqueueSnackbar('Error fetching patient files', { variant: 'error' });
      setFiles([]);
      setTotalFiles(0);
    } finally {
      setLoading(false);
    }
  };
  const handleLocationHistory = async (file) => {
    setSelectedFile(file);
    setLoading(true);
    try {
      const response = await api.get(`/file-records/location-history/${file._id}`);
      if (response.data.success) {
        setLocationHistory(response.data.data);
      }
    } catch (error) {
      enqueueSnackbar('Error fetching location history', { variant: 'error' });
      setLocationHistory([]);
    } finally {
      setLoading(false);
      setLocationHistoryDialog(true);
    }
  };

  const handleClearFilters = () => {
    setSelectedPatient(null);
    setPatientSearchResults([]);
    fetchAllFiles();
  };

  const columns = [
    {
      field: 'caseId',
      headerName: 'Case ID',
      width: 150,
    },
    {
      field: 'patientName',
      headerName: 'Patient',
      width: 200,
      valueGetter: (params) => params.row.patientName || '',
    },
    {
      field: 'rack',
      headerName: 'Rack',
      width: 150,
      valueGetter: (params) => params.row.rack?.rackId || '',
    },
    {
      field: 'subDivision',
      headerName: 'Subdivision',
      width: 150,
    },
    {
      field: 'status',
      headerName: 'Status',
      width: 150,
      renderCell: (params) => (
        <Typography
          sx={{
            color: params.value === 'active' ? 'success.main' : 
                  params.value === 'transferred' ? 'warning.main' : 'error.main'
          }}
        >
          {params.value.charAt(0).toUpperCase() + params.value.slice(1)}
        </Typography>
      ),
    },
    {
      field: 'createdAt',
      headerName: 'Created Date',
      width: 200,
      valueGetter: (params) => new Date(params.value).toLocaleDateString(),
    },
    {
      field: 'actions',
      headerName: 'Actions',
      width: 150,
      sortable: false,
      renderCell: (params) => (
        <Stack direction="row" spacing={1}>
          <Tooltip title="View Location History">
            <IconButton
              size="small"
              onClick={() => handleLocationHistory(params.row)}
            >
              <LocationIcon />
            </IconButton>
          </Tooltip>
          <Tooltip title="View Patient Details">
            <IconButton
              size="small"
              onClick={() => {
                setSelectedFile(params.row);
                setPatientDetailsDialog(true);
              }}
            >
              <PersonIcon />
            </IconButton>
          </Tooltip>
        </Stack>
      ),
    },
  ];

  return (
    <Box sx={{ p: 3 }}>
      <Typography variant="h4" gutterBottom>
        Manage Files
      </Typography>

      {/* Search Section */}
      <Card sx={{ p: 3, mb: 3 }}>
                  <Paper sx={{ borderBottom: 1, borderColor: 'divider' }}>
                    <Tabs
                      value={tabValue}
                      onChange={(e, newValue) => {
                        setTabValue(newValue);
                        setSearchType(newValue === 0 ? 'patient' : 'case');
                        handleClearFilters();
                      }}
                    >
                      <Tab label="Search by Patient" />
                      <Tab label="Search by Case ID" />
                    </Tabs>
                  </Paper>
          
                  <SearchTab
                    searchType={searchType}
                    handleSearch={handleSearch}
                    loading={loading}
                  />
          
                  {/* Patient Search Results */}
                  {patientSearchResults.length > 0 && searchType === 'patient' && (
                    <Box sx={{ mt: 2 }}>
                      <Typography variant="subtitle2" gutterBottom>
                        Search Results:
                      </Typography>
                      <Stack spacing={1}>
                        {patientSearchResults.map((patient) => (
                          <Card
                            key={patient._id}
                            sx={{
                              p: 2,
                              cursor: 'pointer',
                              '&:hover': { bgcolor: 'action.hover' },
                            }}
                            onClick={() => handlePatientSelect(patient)}
                          >
                            <Stack direction="row" justifyContent="space-between" alignItems="center">
                              <Stack>
                                <Typography variant="subtitle1">{patient.patientName}</Typography>
                                <Typography variant="body2" color="text.secondary">
                                  Phone: {patient.phoneNumber}
                                </Typography>
                              </Stack>
                              <Button size="small">Select</Button>
                            </Stack>
                          </Card>
                        ))}
                      </Stack>
                    </Box>
                  )}
          
                  {/* Selected Patient Display */}
                  {selectedPatient && (
                    <Alert
                      severity="info"
                      sx={{ mt: 2 }}
                      action={
                        <Button color="inherit" size="small" onClick={handleClearFilters}>
                          Clear
                        </Button>
                      }
                    >
                      <Typography variant="body2">
                        Selected Patient: {selectedPatient.patientName}
                      </Typography>
                    </Alert>
                  )}
                </Card>

      {/* Files Grid */}
      <Card>
        <DataGrid
          rows={files}
          columns={columns}
          getRowId={(row) => row._id}
          pagination
          paginationMode="server"
          rowCount={totalFiles}
          page={pagination.page}
          pageSize={pagination.pageSize}
          onPageChange={(newPage) => setPagination(prev => ({ ...prev, page: newPage }))}
          onPageSizeChange={(newPageSize) => 
            setPagination(prev => ({ ...prev, pageSize: newPageSize }))
          }
          loading={loading}
          autoHeight
          disableSelectionOnClick
          components={{
            Toolbar: GridToolbar,
          }}
          componentsProps={{
            toolbar: {
              showQuickFilter: true,
              quickFilterProps: { debounceMs: 500 },
            },
          }}
        />
      </Card>

      {/* Location History Dialog */}
      <Dialog
        open={locationHistoryDialog}
        onClose={() => setLocationHistoryDialog(false)}
        maxWidth="sm"
        fullWidth
      >
        <DialogTitle>
          <Stack direction="row" alignItems="center" justifyContent="space-between">
            <Typography variant="h6">Location History</Typography>
            <IconButton onClick={() => setLocationHistoryDialog(false)}>
              <CloseIcon />
            </IconButton>
          </Stack>
        </DialogTitle>
        <DialogContent>
          {selectedFile && (
            <Box sx={{ mt: 2 }}>
              <Alert severity="info" sx={{ mb: 2 }}>
                <Typography variant="subtitle2">File Details:</Typography>
                <Typography variant="body2">Case ID: {selectedFile.caseId}</Typography>
                <Typography variant="body2">Patient: {selectedFile.patientName}</Typography>
                <Typography variant="body2">
                  Current Location: {selectedFile.rack?.rackId} - {selectedFile.subDivision}
                </Typography>
              </Alert>

              {locationHistory.length > 0 ? (
                <List>
                  {locationHistory.map((update, index) => (
                    <ListItem key={index} divider={index < locationHistory.length - 1}>
                      <ListItemText
                        primary={
                          <Typography variant="subtitle2">
                            {new Date(update.updatedAt).toLocaleDateString()}
                          </Typography>
                        }
                        secondary={
                          <>
                            <Typography variant="body2" color="text.secondary">
                              Moved from {update.changes.rack.from} - {update.changes.subDivision.from}
                            </Typography>
                            <Typography variant="body2" color="text.secondary">
                              to {update.changes.rack.to} - {update.changes.subDivision.to}
                            </Typography>
                            <Typography variant="caption" color="text.secondary">
                              Updated by: {update.updatedBy?.name}
                            </Typography>
                          </>
                        }
                      />
                    </ListItem>
                  ))}
                </List>
              ) : (
                <Alert severity="info">No location history available</Alert>
              )}
            </Box>
          )}
        </DialogContent>
      </Dialog>

      {/* Patient Details Dialog */}
      <Dialog
        open={patientDetailsDialog}
        onClose={() => setPatientDetailsDialog(false)}
        maxWidth="sm"
        fullWidth
      >
        <DialogTitle>
          <Stack direction="row" alignItems="center" justifyContent="space-between">
            <Typography variant="h6">File Details</Typography>
            <IconButton onClick={() => setPatientDetailsDialog(false)}>
              <CloseIcon />
            </IconButton>
          </Stack>
        </DialogTitle>
        <DialogContent>
          {selectedFile && (
            <Stack spacing={2} sx={{ mt: 2 }}>
              <Card sx={{ p: 2 }}>
                <Typography variant="subtitle1" gutterBottom>
                  File Information
                </Typography>
                <List dense>
                  <ListItem>
                    <ListItemText
                      primary="Case ID"
                      secondary={selectedFile.caseId}
                    />
                  </ListItem>
                  <ListItem>
                    <ListItemText
                      primary="Current Location"
                      secondary={`${selectedFile.rack?.rackId} - ${selectedFile.subDivision}`}
                    />
                  </ListItem>
                  <ListItem>
                    <ListItemText
                      primary="Status"
                      secondary={selectedFile.status.charAt(0).toUpperCase() + selectedFile.status.slice(1)}
                    />
                  </ListItem>
                  <ListItem>
                    <ListItemText
                      primary="Created Date"
                      secondary={new Date(selectedFile.createdAt).toLocaleDateString()}
                    />
                  </ListItem>
                </List>
              </Card>

              <Card sx={{ p: 2 }}>
                <Typography variant="subtitle1" gutterBottom>
                  Patient Information
                </Typography>
                <List dense>
                  <ListItem>
                    <ListItemText
                      primary="Patient Name"
                      secondary={selectedFile.patientName}
                    />
                  </ListItem>
                  {selectedFile.patient?.phoneNumber && (
                    <ListItem>
                      <ListItemText
                        primary="Phone Number"
                        secondary={selectedFile.patient.phoneNumber}
                      />
                    </ListItem>
                  )}
                  {selectedFile.patient?.email && (
                    <ListItem>
                      <ListItemText
                        primary="Email"
                        secondary={selectedFile.patient.email}
                      />
                    </ListItem>
                  )}
                  {selectedFile.patient?.byStanderName && (
                    <>
                      <ListItem>
                        <ListItemText
                          primary="Bystander Name"
                          secondary={selectedFile.patient.byStanderName}
                        />
                      </ListItem>
                      {selectedFile.patient?.byStanderPhone && (
                        <ListItem>
                          <ListItemText
                            primary="Bystander Phone"
                            secondary={selectedFile.patient.byStanderPhone}
                          />
                        </ListItem>
                      )}
                    </>
                  )}
                  {selectedFile.patient?.address && (
                    <ListItem>
                      <ListItemText
                        primary="Address"
                        secondary={selectedFile.patient.address}
                      />
                    </ListItem>
                  )}
                </List>
              </Card>
            </Stack>
          )}
        </DialogContent>
      </Dialog>

      {/* Loading Overlay */}
      {loading && (
        <Box
          sx={{
            position: 'fixed',
            top: 0,
            left: 0,
            right: 0,
            bottom: 0,
            display: 'flex',
            alignItems: 'center',
            justifyContent: 'center',
            backgroundColor: 'rgba(0, 0, 0, 0.5)',
            zIndex: 9999,
          }}
        >
          <CircularProgress />
        </Box>
      )}
    </Box>
  );
};

export default ManageFiles;