import React, { useState } from 'react';
import {
    Box,
    Typography,
    TextField,
    Button,
    Grid,
    FormControl,
    InputLabel,
    Select,
    MenuItem,
    Stack,
    Dialog,
    DialogTitle,
    DialogContent,
    DialogActions,
    DialogContentText,
    Snackbar,
    Alert,
    Card,
    CardContent,
    IconButton,
    Divider,
    Avatar
} from '@mui/material';
import {
    PersonAdd,
    ArrowBack,
    Badge,
    Email,
    Phone,
    Assignment,
    School,
    PhotoCamera
} from '@mui/icons-material';
import { useNavigate } from 'react-router-dom';
import hodService from '../../../features/services/hodService';
import { Visibility, VisibilityOff, Password as PasswordIcon } from '@mui/icons-material';
import { Tooltip } from '@mui/material';
import { CheckCircle, Error } from '@mui/icons-material';

const DEPARTMENTS = [
    'Audiology',
    'Speech-Language Pathology',
    'Clinical Psychology',
    'Special Education',
    'Physiotherapy',
    'Occupational Therapy',
    'Nursing',
    'General Medicine',
    'General Surgery',
    'Orthopaedics',
];

const CreateHOD = () => {
    const navigate = useNavigate();
    const [serverResponse, setServerResponse] = useState(null);
    const [dialogType, setDialogType] = useState('confirm');
    const [formData, setFormData] = useState({
        firstName: '',
        lastName: '',
        email: '',
        password: '',
        department: '',
        phone: '',
        employeeId: '',
        status: 'active',
        profilePhoto: null
    });

    const [error, setError] = useState({});
    const [openDialog, setOpenDialog] = useState(false);
    const [notification, setNotification] = useState({
        open: false,
        message: '',
        severity: 'success'
    });
    const [showPassword, setShowPassword] = useState(false);
    const handleInputChange = (e) => {
        const { name, value } = e.target;
        setFormData(prev => ({
            ...prev,
            [name]: value
        }));
        if (error[name]) {
            setError(prev => ({ ...prev, [name]: '' }));
        }
    };

    const handleFileChange = (event) => {
        const file = event.target.files[0];
        if (file) {
            setFormData(prev => ({ ...prev, profilePhoto: file }));
        }
    };
    const generatePassword = () => {
        const length = 12;
        const charset = "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789@$!%*?&";
        let newPassword = "";

        // Ensure at least one of each required character type
        newPassword += "ABCDEFGHIJKLMNOPQRSTUVWXYZ"[Math.floor(Math.random() * 26)]; // uppercase
        newPassword += "abcdefghijklmnopqrstuvwxyz"[Math.floor(Math.random() * 26)]; // lowercase
        newPassword += "0123456789"[Math.floor(Math.random() * 10)]; // number
        newPassword += "@$!%*?&"[Math.floor(Math.random() * 7)]; // special char

        // Fill the rest randomly
        for (let i = 4; i < length; i++) {
            newPassword += charset[Math.floor(Math.random() * charset.length)];
        }

        // Shuffle the password
        newPassword = newPassword.split('')
            .sort(() => Math.random() - 0.5)
            .join('');

        setFormData(prev => ({
            ...prev,
            password: newPassword
        }));
    };

    const validateForm = () => {
        const newErrors = {};
        if (!formData.firstName) newErrors.firstName = 'First name is required';
        if (!formData.lastName) newErrors.lastName = 'Last name is required';
        if (!formData.email) {
            newErrors.email = 'Email is required';
        } else if (!formData.email.endsWith('@nish.ac.in')) {
            newErrors.email = 'Email must be from @nish.ac.in domain';
        }

        const passwordRegex = /^(?=.*[a-z])(?=.*[A-Z])(?=.*\d)(?=.*[@$!%*?&])[A-Za-z\d@$!%*?&]{8,}$/;
        if (!formData.password) {
            newErrors.password = 'Password is required';
        } else if (!passwordRegex.test(formData.password)) {
            newErrors.password = 'Password must contain at least 8 characters, one uppercase, one lowercase, one number and one special character';
        }

        if (!formData.department) newErrors.department = 'Department is required';
        if (!formData.employeeId) newErrors.employeeId = 'Employee ID is required';
        if (!formData.phone) {
            newErrors.phone = 'Phone number is required';
        } else if (!/^\d{10}$/.test(formData.phone)) {
            newErrors.phone = 'Invalid phone number';
        }

        setError(newErrors);
        return Object.keys(newErrors).length === 0;
    };

    const handleSubmit = (e) => {
        e.preventDefault();
        if (!validateForm()) {
            showNotification('Please fill in all required fields correctly', 'error');
            return;
        }
        setOpenDialog(true);
    };

    const handleConfirmSubmit = async () => {
        try {
            const response = await hodService.createHOD(formData);
            setServerResponse(response);
            setDialogType('response');

            if (response.success) {
                showNotification('HOD created successfully', 'success');
                
            } else {
                showNotification(response.message || 'Error creating HOD', 'error');
            }
        } catch (error) {
            console.error('Error creating HOD:', error);
            setServerResponse({
                success: false,
                message: error.response?.data?.message || 'Error creating HOD. Please try again.'
            });
            setDialogType('response');
            showNotification(error.response?.data?.message || 'Error creating HOD', 'error');
        }
    };

    const showNotification = (message, severity) => {
        setNotification({
            open: true,
            message,
            severity
        });
    };
    const handleCloseResponseDialog = () => {
        setDialogType('confirm');
        setOpenDialog(false);
        setServerResponse(null);
       
    };
    const handleCloseNotification = (event, reason) => {
        if (reason === 'clickaway') return;
        setNotification(prev => ({ ...prev, open: false }));
    };

    return (
        <Box sx={{ p: 3, backgroundColor: '#f0f7ff', minHeight: '100vh' }}>
            <Card
                elevation={0}
                sx={{
                    // Remove maxWidth: 900,
                    mx: 'auto',
                    borderRadius: 4,
                    background: 'linear-gradient(135deg, #ffffff 0%, #f8faff 100%)',
                    boxShadow: '0 8px 32px rgba(0, 0, 0, 0.1)'
                }}
            >
                <CardContent sx={{ p: 3 }}>
                    {/* Header */}
                    <Box sx={{ mb: 3 }}>
                        <Stack
                            direction="row"
                            alignItems="flex-start"
                            spacing={3}
                        >
                            <Stack direction="row" spacing={2} flex={1}>
                                <IconButton
                                    onClick={() => navigate(-1)}
                                    sx={{
                                        backgroundColor: '#e3f2fd',
                                        '&:hover': { backgroundColor: '#bbdefb' }
                                    }}
                                >
                                    <ArrowBack />
                                </IconButton>
                                <Stack direction="column">
                                    <Typography
                                        variant="h5"
                                        sx={{
                                            fontWeight: 600,
                                            color: '#1976d2'
                                        }}
                                    >
                                        Create Head of Department
                                    </Typography>
                                    <Typography variant="body2" color="textSecondary">
                                        Fill in the information below to create a new HOD
                                    </Typography>
                                </Stack>
                            </Stack>


                        </Stack>
                    </Box>

                    <Divider sx={{ mb: 3 }} />

                    <form onSubmit={handleSubmit}>
                        <Grid container spacing={2.5}>
                            <Grid item xs={12} sm={6}>
                                <TextField
                                    fullWidth
                                    label="First Name"
                                    name="firstName"
                                    value={formData.firstName}
                                    onChange={handleInputChange}
                                    error={!!error.firstName}
                                    helperText={error.firstName}
                                    required
                                    InputProps={{
                                        sx: { borderRadius: 2 }
                                    }}
                                />
                            </Grid>
                            <Grid item xs={12} sm={6}>
                                <TextField
                                    fullWidth
                                    label="Last Name"
                                    name="lastName"
                                    value={formData.lastName}
                                    onChange={handleInputChange}
                                    error={!!error.lastName}
                                    helperText={error.lastName}
                                    required
                                    InputProps={{
                                        sx: { borderRadius: 2 }
                                    }}
                                />
                            </Grid>

                            <Grid item xs={12} sm={6}>
                                <FormControl
                                    fullWidth
                                    error={!!error.department}
                                    sx={{
                                        '& .MuiOutlinedInput-root': {
                                            borderRadius: 2
                                        }
                                    }}
                                >
                                    <InputLabel>Department</InputLabel>
                                    <Select
                                        name="department"
                                        value={formData.department}
                                        onChange={handleInputChange}
                                        label="Department"
                                        required
                                    >
                                        {DEPARTMENTS.map((dept) => (
                                            <MenuItem key={dept} value={dept}>
                                                {dept}
                                            </MenuItem>
                                        ))}
                                    </Select>
                                </FormControl>
                            </Grid>

                            <Grid item xs={12} sm={6}>
                                <FormControl
                                    fullWidth
                                    sx={{
                                        '& .MuiOutlinedInput-root': {
                                            borderRadius: 2
                                        }
                                    }}
                                >
                                    <InputLabel>Status</InputLabel>
                                    <Select
                                        name="status"
                                        value={formData.status}
                                        onChange={handleInputChange}
                                        label="Status"
                                    >
                                        <MenuItem value="active">Active</MenuItem>
                                        <MenuItem value="inactive">Inactive</MenuItem>
                                    </Select>
                                </FormControl>
                            </Grid>

                            <Grid item xs={12} sm={6}>
                                <TextField
                                    fullWidth
                                    label="Email"
                                    name="email"
                                    type="email"
                                    value={formData.email}
                                    onChange={handleInputChange}
                                    error={!!error.email}
                                    helperText={error.email}
                                    required
                                    InputProps={{
                                        sx: { borderRadius: 2 },
                                        startAdornment: <Email color="action" sx={{ mr: 1 }} />
                                    }}
                                />
                            </Grid>

                            <Grid item xs={12} sm={6}>
                                <TextField
                                    fullWidth
                                    label="Phone Number"
                                    name="phone"
                                    value={formData.phone}
                                    onChange={handleInputChange}
                                    error={!!error.phone}
                                    helperText={error.phone}
                                    required
                                    InputProps={{
                                        sx: { borderRadius: 2 },
                                        startAdornment: <Phone color="action" sx={{ mr: 1 }} />
                                    }}
                                />
                            </Grid>

                            <Grid item xs={12} sm={6}>
                                <TextField
                                    fullWidth
                                    label="Employee ID"
                                    name="employeeId"
                                    value={formData.employeeId}
                                    onChange={handleInputChange}
                                    error={!!error.employeeId}
                                    helperText={error.employeeId}
                                    required
                                    InputProps={{
                                        sx: { borderRadius: 2 }
                                    }}
                                />
                            </Grid>

                            <Grid item xs={12} sm={6}>
                                <TextField
                                    fullWidth
                                    label="Password"
                                    name="password"
                                    type={showPassword ? 'text' : 'password'}
                                    value={formData.password}
                                    onChange={handleInputChange}
                                    error={!!error.password}
                                    helperText={error.password}
                                    required
                                    InputProps={{
                                        sx: { borderRadius: 2 },
                                        endAdornment: (
                                            <Stack direction="row" spacing={1}>
                                                <Tooltip
                                                    title="Generate a strong password that includes uppercase, lowercase, numbers, and special characters"
                                                    arrow
                                                    placement="top"
                                                >
                                                    <IconButton
                                                        onClick={() => generatePassword()}
                                                        edge="end"
                                                        sx={{ color: 'action.active' }}
                                                    >
                                                        <PasswordIcon />
                                                    </IconButton>
                                                </Tooltip>
                                                <Tooltip
                                                    title={showPassword ? "Hide password" : "Show password"}
                                                    arrow
                                                    placement="top"
                                                >
                                                    <IconButton
                                                        onClick={() => setShowPassword(!showPassword)}
                                                        edge="end"
                                                        sx={{ color: 'action.active' }}
                                                    >
                                                        {showPassword ? <VisibilityOff /> : <Visibility />}
                                                    </IconButton>
                                                </Tooltip>
                                            </Stack>
                                        )
                                    }}
                                />
                            </Grid>

                            <Grid item xs={12}>
                                <Stack
                                    direction="row"
                                    spacing={2}
                                    justifyContent="flex-end"
                                    sx={{ mt: 2 }}
                                >
                                    <Button
                                        variant="outlined"
                                        onClick={() => navigate(-1)}
                                        sx={{
                                            borderRadius: 2,
                                            px: 4
                                        }}
                                    >
                                        Cancel
                                    </Button>
                                    <Button
                                        variant="contained"
                                        type="submit"
                                        startIcon={<PersonAdd />}
                                        sx={{
                                            borderRadius: 2,
                                            px: 4,
                                            background: 'linear-gradient(45deg, #1976d2 30%, #42a5f5 90%)',
                                            boxShadow: '0 3px 5px 2px rgba(33, 150, 243, .3)',
                                            '&:hover': {
                                                background: 'linear-gradient(45deg, #1565c0 30%, #1976d2 90%)',
                                                transform: 'translateY(-1px)'
                                            }
                                        }}
                                    >
                                        Create HOD
                                    </Button>
                                </Stack>
                            </Grid>
                        </Grid>
                    </form>
                </CardContent>
            </Card>


            {/* Dialogs */}
            {dialogType === 'confirm' ? (
                <Dialog
                    open={openDialog}
                    onClose={() => setOpenDialog(false)}
                    PaperProps={{
                        sx: { borderRadius: 3 }
                    }}
                >
                    <DialogTitle sx={{ pb: 1 }}>
                        <Stack direction="row" alignItems="center" spacing={1}>
                            <PersonAdd color="primary" />
                            <Typography variant="h6" color="primary">
                                Confirm HOD Creation
                            </Typography>
                        </Stack>
                    </DialogTitle>
                    <DialogContent>
                        <DialogContentText sx={{ mb: 2 }}>
                            Please review the following details:
                        </DialogContentText>
                        <Box sx={{
                            backgroundColor: '#f5f5f5',
                            p: 2,
                            borderRadius: 2
                        }}>
                            <Typography variant="body2" gutterBottom>
                                <strong>Name:</strong> {formData.firstName} {formData.lastName}
                            </Typography>
                            <Typography variant="body2" gutterBottom>
                                <strong>Department:</strong> {formData.department}
                            </Typography>
                            <Typography variant="body2" gutterBottom>
                                <strong>Employee ID:</strong> {formData.employeeId}
                            </Typography>
                            <Typography variant="body2" gutterBottom>
                                <strong>Email:</strong> {formData.email}
                            </Typography>
                            <Typography variant="body2">
                                <strong>Phone:</strong> {formData.phone}
                            </Typography>
                        </Box>
                    </DialogContent>
                    <DialogActions sx={{ p: 3 }}>
                        <Button
                            onClick={() => setOpenDialog(false)}
                            sx={{ borderRadius: 2 }}
                        >
                            Cancel
                        </Button>
                        <Button
                            onClick={handleConfirmSubmit}
                            variant="contained"
                            sx={{ borderRadius: 2 }}
                        >
                            Confirm Creation
                        </Button>
                    </DialogActions>
                </Dialog>
            ) : (
                <Dialog
                    open={openDialog}
                    onClose={handleCloseResponseDialog}
                    PaperProps={{
                        sx: { borderRadius: 3 }
                    }}
                >
                    <DialogTitle sx={{ pb: 1 }}>
                        <Stack direction="row" alignItems="center" spacing={1}>
                            {serverResponse?.success ? (
                                <CheckCircle color="success" />
                            ) : (
                                <Error color="error" />
                            )}
                            <Typography
                                variant="h6"
                                color={serverResponse?.success ? "success.main" : "error.main"}
                            >
                                {serverResponse?.success ? "HOD Created Successfully" : "Creation Failed"}
                            </Typography>
                        </Stack>
                    </DialogTitle>
                    <DialogContent>
                        <Box sx={{
                            backgroundColor: serverResponse?.success ? '#f1f8e9' : '#fde9e8',
                            p: 2,
                            borderRadius: 2,
                            mt: 2
                        }}>
                            <Typography variant="body2" gutterBottom>
                                <strong>Status:</strong> {serverResponse?.success ? "Success" : "Error"}
                            </Typography>
                            <Typography variant="body2" gutterBottom>
                                <strong>Message:</strong> {serverResponse?.message}
                            </Typography>
                            {serverResponse?.data && (
                                <>
                                    <Typography variant="body2" gutterBottom>
                                        <strong>HOD ID:</strong> {serverResponse.data.hod._id}
                                    </Typography>
                                    <Typography variant="body2" gutterBottom>
                                        <strong>User ID:</strong> {serverResponse.data.user.id}
                                    </Typography>
                                </>
                            )}
                            {serverResponse?.errors && (
                                <Box sx={{ mt: 1 }}>
                                    <Typography variant="body2" fontWeight="bold">Errors:</Typography>
                                    {Array.isArray(serverResponse.errors) ? (
                                        serverResponse.errors.map((error, index) => (
                                            <Typography key={index} variant="body2" color="error">
                                                • {error}
                                            </Typography>
                                        ))
                                    ) : (
                                        <Typography variant="body2" color="error">
                                            • {serverResponse.errors}
                                        </Typography>
                                    )}
                                </Box>
                            )}
                        </Box>
                    </DialogContent>
                   
                </Dialog>
            )}
            {/* Notification */}
            <Snackbar
                open={notification.open}
                autoHideDuration={6000}
                onClose={handleCloseNotification}
                anchorOrigin={{ vertical: 'top', horizontal: 'right' }}
            >
                <Alert
                    onClose={handleCloseNotification}
                    severity={notification.severity}
                    variant="filled"
                    sx={{
                        width: '100%',
                        borderRadius: 2
                    }}
                >
                    {notification.message}
                </Alert>
            </Snackbar>
        </Box>
    );
};

export default CreateHOD;