import React, { useState, useEffect } from 'react';
import {
  Box,
  Card,
  TextField,
  Button,
  Typography,
  Stack,
  InputAdornment,
  Dialog,
  DialogTitle,
  DialogContent,
  Alert,
  CircularProgress,
  Paper,
  Tabs,
  Tab,
  IconButton,
  Divider,
  Table,
  TableBody,
  TableCell,
  TableContainer,
  TableHead,
  TableRow,
} from '@mui/material';
import {
  Search as SearchIcon,
  Phone as PhoneIcon,
  History as HistoryIcon,
  Print as PrintIcon,
  Close as CloseIcon,
} from '@mui/icons-material';
import { DataGrid } from '@mui/x-data-grid';
import { useSnackbar } from 'notistack';
import { useSelector } from 'react-redux';
import { jwtDecode } from 'jwt-decode';
import moment from 'moment';
import jsPDF from 'jspdf';
import 'jspdf-autotable';
import api from '../../../api/axios';
import {

  useTheme,
  alpha,
  Tooltip,

  Fade,
} from '@mui/material';
import {

  Person as PersonIcon,
  Assignment as AssignmentIcon,
  Clear as ClearIcon,
} from '@mui/icons-material';
const FileHistory = () => {
  const [files, setFiles] = useState([]);
  const [loading, setLoading] = useState(false);
  const [tabValue, setTabValue] = useState(0);
  const [searchType, setSearchType] = useState('patient');
  const [searchQuery, setSearchQuery] = useState('');
  const [patientSearchResults, setPatientSearchResults] = useState([]);
  const [selectedPatient, setSelectedPatient] = useState(null);
  const [historyDialog, setHistoryDialog] = useState(false);
  const [historyData, setHistoryData] = useState(null);
  const [pagination, setPagination] = useState({
    page: 0,
    pageSize: 10,
    total: 0,
  });

  const { enqueueSnackbar } = useSnackbar();
  const token = useSelector(state => state.auth.token);
  const userId = token ? jwtDecode(token).userId : null;

  const SearchTab = ({ searchType, handleSearch, loading }) => {
    const [phoneNumber, setPhoneNumber] = useState('');
    const [name, setName] = useState('');
    const [caseId, setCaseId] = useState('');
    const [focused, setFocused] = useState('');
    const theme = useTheme();
  
    const handleClear = (field) => {
      switch (field) {
        case 'name':
          setName('');
          break;
        case 'phone':
          setPhoneNumber('');
          break;
        case 'case':
          setCaseId('');
          break;
        default:
          break;
      }
    };
  
    const CustomTextField = ({ 
      label, 
      value, 
      onChange, 
      icon, 
      onSearch, 
      disabled, 
      field,
      placeholder,
      helperText 
    }) => (
      <TextField
        fullWidth
        label={label}
        value={value}
        onChange={onChange}
        placeholder={placeholder}
        onFocus={() => setFocused(field)}
        onBlur={() => setFocused('')}
        helperText={helperText}
        InputProps={{
          startAdornment: (
            <InputAdornment position="start">
              {React.cloneElement(icon, {
                sx: {
                  color: focused === field ? theme.palette.primary.main : 'text.secondary',
                  transition: 'color 0.3s ease'
                }
              })}
            </InputAdornment>
          ),
          endAdornment: value && (
            <InputAdornment position="end">
              <Stack direction="row" spacing={1}>
                <Tooltip title="Clear">
                  <IconButton
                    size="small"
                    onClick={() => handleClear(field)}
                    sx={{ 
                      opacity: 0.7,
                      '&:hover': { opacity: 1 }
                    }}
                  >
                    <ClearIcon fontSize="small" />
                  </IconButton>
                </Tooltip>
                <Button
                  variant="contained"
                  onClick={onSearch}
                  disabled={disabled}
                  sx={{
                    borderRadius: '8px',
                    px: 3,
                    boxShadow: 'none',
                    '&:hover': {
                      boxShadow: 'none',
                      background: theme.palette.primary.dark,
                    },
                    transition: 'all 0.3s ease'
                  }}
                >
                  Search
                </Button>
              </Stack>
            </InputAdornment>
          )
        }}
        sx={{
          '& .MuiOutlinedInput-root': {
            borderRadius: '12px',
            transition: 'all 0.3s ease',
            backgroundColor: theme.palette.background.paper,
            '&:hover': {
              backgroundColor: alpha(theme.palette.primary.main, 0.02),
            },
            '&.Mui-focused': {
              backgroundColor: alpha(theme.palette.primary.main, 0.05),
              '& .MuiOutlinedInput-notchedOutline': {
                borderColor: theme.palette.primary.main,
                borderWidth: '2px'
              }
            }
          },
          '& .MuiInputLabel-root': {
            '&.Mui-focused': {
              color: theme.palette.primary.main
            }
          }
        }}
      />
    );
  
    return (
      <Stack spacing={3} sx={{ mt: 2 }}>
        {searchType === 'patient' ? (
          <>
            <CustomTextField
              label="Search by Patient Name"
              value={name}
              onChange={(e) => {
                setName(e.target.value);
                setPhoneNumber('');
              }}
              icon={<PersonIcon />}
              onSearch={() => handleSearch('name', name)}
              disabled={loading || name.length < 3}
              field="name"
              placeholder="Enter patient name..."
              helperText={name && name.length < 3 ? "Enter at least 3 characters" : ""}
            />
            <CustomTextField
              label="Search by Phone Number"
              value={phoneNumber}
              onChange={(e) => {
                setPhoneNumber(e.target.value.replace(/\D/g, '').slice(0, 10));
                setName('');
              }}
              icon={<PhoneIcon />}
              onSearch={() => handleSearch('phone', phoneNumber)}
              disabled={loading || phoneNumber.length !== 10}
              field="phone"
              placeholder="Enter 10-digit phone number..."
              helperText={phoneNumber && phoneNumber.length !== 10 ? "Enter a valid 10-digit number" : ""}
            />
          </>
        ) : (
          <CustomTextField
            label="Search by Case ID"
            value={caseId}
            onChange={(e) => setCaseId(e.target.value)}
            icon={<AssignmentIcon />}
            onSearch={() => handleSearch('case', caseId)}
            disabled={loading || !caseId}
            field="case"
            placeholder="Enter case ID..."
            helperText={caseId && !caseId.match(/^[A-Za-z0-9]+$/) ? "Enter a valid case ID" : ""}
          />
        )}
  
        {loading && (
          <Fade in={loading}>
            <Box sx={{ 
              display: 'flex', 
              alignItems: 'center', 
              justifyContent: 'center',
              p: 1,
              bgcolor: alpha(theme.palette.primary.main, 0.05),
              borderRadius: '8px'
            }}>
              <Typography variant="body2" color="primary">
                Searching...
              </Typography>
            </Box>
          </Fade>
        )}
      </Stack>
    );
  };
  useEffect(() => {
    fetchFiles();
  }, [pagination.page, pagination.pageSize]);

  const fetchFiles = async () => {
    setLoading(true);
    try {
      const response = await api.get('/file-records/all', {
        params: {
          page: pagination.page + 1,
          limit: pagination.pageSize,
          userId
        }
      });

      setFiles(response.data.data);
      setPagination(prev => ({
        ...prev,
        total: response.data.pagination.totalRecords
      }));
    } catch (error) {
      enqueueSnackbar('Error fetching files', { variant: 'error' });
    } finally {
      setLoading(false);
    }
  };


  const handleClearFilters = () => {
    setSelectedPatient(null);
    setPatientSearchResults([]);
    setFiles([]);
  };

  const handleSearch = async (type, value) => {
    if (!value) return;

    setLoading(true);
    try {
      let response;

      if (type === 'phone') {
        response = await api.get(`/patients/search/phone?phoneNumber=${value}&userId=${userId}`);
      }
      else if (type === 'name') {
        response = await api.get(`/patients/search/name?name=${value}&userId=${userId}`);
      }
      else if (type === 'case') {
        response = await api.get(`/file-records/case/${value}?userId=${userId}`);
        if (response.data.success) {
          const file = response.data.data;
          setFiles([file]);
          setPatientSearchResults([]);
          return;
        }
      }

      if (response?.data.success) {
        if (type === 'case') {
          setFiles([response.data.data]);
          setPatientSearchResults([]);
        } else {
          setPatientSearchResults(response.data.data || []);
        }
      }
    } catch (error) {
      enqueueSnackbar(error.response?.data?.message || 'Error searching', { variant: 'error' });
      setFiles([]);
      setPatientSearchResults([]);
    } finally {
      setLoading(false);
    }
  };

  const handlePatientSelect = async (patient) => {
    setSelectedPatient(patient);
    setPatientSearchResults([]);
    setLoading(true);
    try {
      const response = await api.get(`/file-records/patient/${patient._id}?userId=${userId}`);
      if (response.data.success) {
        setFiles(response.data.data || []);
      }
    } catch (error) {
      enqueueSnackbar('Error fetching patient files', { variant: 'error' });
      setFiles([]);
    } finally {
      setLoading(false);
    }
  };

  const handleViewHistory = async (file) => {
    setLoading(true);
    try {
      const response = await api.get(`/file-tracking/history/${file.caseId}`);
      if (response.data.success) {
        setHistoryData(response.data.data);
        setHistoryDialog(true);
      }
    } catch (error) {
      enqueueSnackbar('Error fetching file history', { variant: 'error' });
    } finally {
      setLoading(false);
    }
  };


  const formatDelay = (delay) => {
    if (delay < 1) return '0';
    return Math.floor(delay).toString();
  };

  const generatePDF = () => {
    if (!historyData) return;

    const doc = new jsPDF('p', 'mm', 'a4');

    // Add header with logos and title
    doc.setFillColor(0, 51, 102);
    doc.rect(0, 0, 210, 25, 'F');

    doc.setTextColor(255, 255, 255);
    doc.setFontSize(18);
    doc.text('NISH Medical Record Room', 105, 10, { align: 'center' });
    doc.setFontSize(14);
    doc.text('File History Report', 105, 18, { align: 'center' });

    // Reset text color for content
    doc.setTextColor(0, 0, 0);

    // Add file details in a box
    doc.setDrawColor(0, 51, 102);
    doc.setLineWidth(0.5);
    doc.rect(15, 35, 180, 40);

    doc.setFontSize(12);
    doc.setFont(undefined, 'bold');
    doc.text('File Details:', 20, 40);
    doc.setFont(undefined, 'normal');
    doc.setFontSize(10);

    const detailsY = 40;
    const details = [
      `Case ID: ${historyData.fileDetails.caseId}`,
      `Created By: ${historyData.fileDetails.createdBy}`,
      `Created At: ${moment(historyData.fileDetails.createdAt).format('DD/MM/YYYY')}`,
      `Current Location: ${historyData.fileDetails.currentLocation.rack.rackId} - ${historyData.fileDetails.currentLocation.subDivision}`,
      `Status: ${historyData.fileDetails.status}`
    ];

    details.forEach((detail, index) => {
      doc.text(detail, 25, detailsY + ((index + 1) * 6));
    });

    // Add transfer history table
    doc.setFontSize(12);
    doc.setFont(undefined, 'bold');
    doc.text('Transfer History:', 20, 90);

    const tableData = historyData.transfers.map(transfer => [
      moment(transfer.dispatch.time).format('DD/MM/YYYY'),
      transfer.dispatch.mrrs,
      transfer.dispatch.cs,
      transfer.return?.time ? moment(transfer.return.time).format('DD/MM/YYYY') : '-',
      transfer.return?.mrrs || '-',
      transfer.return?.cs || '-',
      transfer.delay > 0 ? `${formatDelay(transfer.delay)} days` : '-'
    ]);

    doc.autoTable({
      startY: 95,
      head: [['Dispatch Date', 'MRRS Staff', 'CS Staff', 'Return Date', 'Return MRRS', 'Return CS', 'Delay']],
      body: tableData,
      theme: 'grid',
      headStyles: {
        fillColor: [0, 51, 102],
        textColor: [255, 255, 255],
        fontStyle: 'bold',
        fontSize: 9,
        cellPadding: 3
      },
      bodyStyles: {
        fontSize: 9,
        cellPadding: 3
      },
      columnStyles: {
        0: { cellWidth: 25 }, // Dispatch Date
        1: { cellWidth: 30 }, // MRRS Staff
        2: { cellWidth: 30 }, // CS Staff
        3: { cellWidth: 25 }, // Return Date
        4: { cellWidth: 30 }, // Return MRRS
        5: { cellWidth: 30 }, // Return CS
        6: { cellWidth: 20 }  // Delay
      },
      alternateRowStyles: {
        fillColor: [240, 240, 240]
      },
      margin: { left: 15, right: 15 }
    });

    // Add notes if they exist
    let notesY = doc.autoTable.previous.finalY + 15;
    const notes = historyData.transfers.flatMap(transfer =>
      transfer.notes?.map(note => ({
        content: note.content,
        date: moment(note.createdAt).format('DD/MM/YYYY HH:mm')
      })) || []
    );

    if (notes.length > 0) {
      doc.setFontSize(12);
      doc.setFont(undefined, 'bold');
      doc.text('Notes:', 20, notesY);

      notes.forEach((note, index) => {
        notesY += 10;
        doc.setFontSize(9);
        doc.setFont(undefined, 'normal');
        doc.text(`${index + 1}. ${note.content}`, 25, notesY);
        doc.setFontSize(8);
        doc.setTextColor(100, 100, 100);
        doc.text(note.date, 170, notesY);
        doc.setTextColor(0, 0, 0);
      });
    }

    // Add footer
    const pageCount = doc.internal.getNumberOfPages();
    doc.setFontSize(8);
    doc.setTextColor(100, 100, 100);
    for (let i = 1; i <= pageCount; i++) {
      doc.setPage(i);
      doc.text(
        `Generated on: ${moment().format('DD/MM/YYYY HH:mm')} - Page ${i} of ${pageCount}`,
        105,
        285,
        { align: 'center' }
      );
    }

    doc.save(`File_History_${historyData.fileDetails.caseId}.pdf`)


  }

  const columns = [
    {
      field: 'caseId',
      headerName: 'Case ID',
      flex: 1,
      minWidth: 120,
    },
    {
      field: 'patientName',
      headerName: 'Patient',
      flex: 1,
      minWidth: 200,
      valueGetter: (params) => params.row.patient?.patientName || '-'
    },
    {
      field: 'rack',
      headerName: 'Location',
      flex: 1,
      minWidth: 150,
      valueGetter: (params) => `${params.row.rack?.rackId || '-'} - ${params.row.subDivision || '-'}`
    },
    {
      field: 'status',
      headerName: 'Status',
      width: 120,
    },
    {
      field: 'actions',
      headerName: 'Actions',
      width: 100,
      sortable: false,
      renderCell: (params) => (
        <IconButton
          color="primary"
          onClick={() => handleViewHistory(params.row)}
          size="small"
        >
          <HistoryIcon />
        </IconButton>
      ),
    },
  ];

  return (
    <Box sx={{ p: 3 }}>
      <Typography variant="h4" gutterBottom>
        File History
      </Typography>

      <Card sx={{ p: 3, mb: 3 }}>
        <Paper sx={{ borderBottom: 1, borderColor: 'divider' }}>
          <Tabs
            value={tabValue}
            onChange={(e, newValue) => {
              setTabValue(newValue);
              setSearchType(newValue === 0 ? 'patient' : 'case');
              handleClearFilters();
            }}
          >
            <Tab label="Search by Patient" />
            <Tab label="Search by Case ID" />
          </Tabs>
        </Paper>

        <SearchTab
          searchType={searchType}
          handleSearch={handleSearch}
          loading={loading}
        />

        {/* Patient Search Results */}
        {patientSearchResults.length > 0 && searchType === 'patient' && (
          <Box sx={{ mt: 2 }}>
            <Typography variant="subtitle2" gutterBottom>
              Search Results:
            </Typography>
            <Stack spacing={1}>
              {patientSearchResults.map((patient) => (
                <Card
                  key={patient._id}
                  sx={{
                    p: 2,
                    cursor: 'pointer',
                    '&:hover': { bgcolor: 'action.hover' },
                  }}
                  onClick={() => handlePatientSelect(patient)}
                >
                  <Stack direction="row" justifyContent="space-between" alignItems="center">
                    <Stack>
                      <Typography variant="subtitle1">{patient.patientName}</Typography>
                      <Typography variant="body2" color="text.secondary">
                        Phone: {patient.phoneNumber}
                      </Typography>
                    </Stack>
                    <Button size="small">Select</Button>
                  </Stack>
                </Card>
              ))}
            </Stack>
          </Box>
        )}

        {/* Selected Patient Display */}
        {selectedPatient && (
          <Alert
            severity="info"
            sx={{ mt: 2 }}
            action={
              <Button color="inherit" size="small" onClick={handleClearFilters}>
                Clear
              </Button>
            }
          >
            <Typography variant="body2">
              Selected Patient: {selectedPatient.patientName}
            </Typography>
          </Alert>
        )}
      </Card>

      <Card>
        <DataGrid
          rows={files}
          columns={columns}
          pagination
          paginationMode="server"
          rowCount={pagination.total}
          page={pagination.page}
          pageSize={pagination.pageSize}
          onPageChange={(newPage) => setPagination(prev => ({ ...prev, page: newPage }))}
          onPageSizeChange={(newPageSize) =>
            setPagination(prev => ({ ...prev, pageSize: newPageSize, page: 0 }))
          }
          loading={loading}
          getRowId={(row) => row._id}
          autoHeight
          disableSelectionOnClick
        />
      </Card>

      <Dialog
        open={historyDialog}
        onClose={() => setHistoryDialog(false)}
        maxWidth="md"
        fullWidth
      >
        <DialogTitle>
          <Stack direction="row" justifyContent="space-between" alignItems="center">
            <Typography variant="h6">File History</Typography>
            <Stack direction="row" spacing={1}>
              <IconButton onClick={generatePDF} color="primary">
                <PrintIcon />
              </IconButton>
              <IconButton onClick={() => setHistoryDialog(false)}>
                <CloseIcon />
              </IconButton>
            </Stack>
          </Stack>
        </DialogTitle>
        <DialogContent>
          {historyData && (
            <Stack spacing={3} sx={{ mt: 2 }}>
              <Card sx={{ p: 2 }}>
                <Typography variant="subtitle1" gutterBottom>
                  File Details
                </Typography>
                <Stack spacing={1}>
                  <Typography variant="body2">
                    Case ID: {historyData.fileDetails.caseId}
                  </Typography>
                  <Typography variant="body2">
                    Created By: {historyData.fileDetails.createdBy}
                  </Typography>
                  <Typography variant="body2">
                    Created At: {moment(historyData.fileDetails.createdAt).format('DD/MM/YYYY')}
                  </Typography>
                  <Typography variant="body2">
                    Current Location: {historyData.fileDetails.currentLocation.rack.rackId} - {historyData.fileDetails.currentLocation.subDivision}
                  </Typography>
                  <Typography variant="body2">
                    Status: {historyData.fileDetails.status}
                  </Typography>
                </Stack>
              </Card>

              <Divider />

              <Typography variant="h6">Transfer History</Typography>

              <TableContainer component={Paper}>
                <Table>
                  <TableHead>
                    <TableRow>
                      <TableCell>Dispatch Date</TableCell>
                      <TableCell>MRRS Staff</TableCell>
                      <TableCell>CS Staff</TableCell>
                      <TableCell>Return Date</TableCell>
                      <TableCell>Return MRRS</TableCell>
                      <TableCell>Return CS</TableCell>
                      <TableCell>File Hold In hand (Days)</TableCell>
                    </TableRow>
                  </TableHead>
                  <TableBody>
                    {historyData.transfers.map((transfer, index) => (
                      <TableRow key={index}>
                        <TableCell>
                          {moment(transfer.dispatch.time).format('DD/MM/YYYY')}
                        </TableCell>
                        <TableCell>{transfer.dispatch.mrrs}</TableCell>
                        <TableCell>{transfer.dispatch.cs}</TableCell>
                        <TableCell>
                          {transfer.return?.time ?
                            moment(transfer.return.time).format('DD/MM/YYYY') :
                            '-'}
                        </TableCell>
                        <TableCell>
                          {transfer.return?.mrrs || '-'}
                        </TableCell>
                        <TableCell>
                          {transfer.return?.cs || '-'}
                        </TableCell>
                        <TableCell>
                          {transfer.delay > 0 ? transfer.delay : '-'}
                        </TableCell>
                      </TableRow>
                    ))}
                  </TableBody>
                </Table>
              </TableContainer>

              {historyData.transfers.some(t => t.notes?.length > 0) && (
                <>
                  <Divider />
                  <Typography variant="h6">Notes</Typography>
                  <Stack spacing={2}>
                    {historyData.transfers.map((transfer, index) =>
                      transfer.notes?.map((note, noteIndex) => (
                        <Alert
                          key={`${index}-${noteIndex}`}
                          severity="info"
                          sx={{ '& .MuiAlert-message': { width: '100%' } }}
                        >
                          <Stack
                            direction="row"
                            justifyContent="space-between"
                            alignItems="center"
                            width="100%"
                          >
                            <Typography variant="body2">
                              {note.content}
                            </Typography>
                            <Typography variant="caption" color="text.secondary">
                              {moment(note.createdAt).format('DD/MM/YYYY HH:mm')}
                            </Typography>
                          </Stack>
                        </Alert>
                      ))
                    )}
                  </Stack>
                </>
              )}
            </Stack>
          )}
        </DialogContent>
      </Dialog>

      {loading && (
        <Box
          sx={{
            position: 'fixed',
            top: 0,
            left: 0,
            right: 0,
            bottom: 0,
            display: 'flex',
            alignItems: 'center',
            justifyContent: 'center',
            backgroundColor: 'rgba(0, 0, 0, 0.5)',
            zIndex: 9999,
          }}
        >
          <CircularProgress />
        </Box>
      )}
    </Box>
  );
};

export default FileHistory;