// pages/Users/ManageUsers.jsx
import React, { useState, useEffect } from 'react';
import {
  Box,
  Card,
  IconButton,
  Tooltip,
  FormControl,
  InputLabel,
  Select,
  MenuItem,
  Dialog,
  DialogTitle,
  DialogContent,
  DialogActions,
  Button,
  TextField,
  CircularProgress,
  Typography,
  Stack,
  DialogContentText,
} from '@mui/material';
import {
  DataGrid,
  GridToolbar,
} from '@mui/x-data-grid';
import {
  Edit as EditIcon,
  Block as BlockIcon,
  LockReset as ResetIcon,
  CheckCircle as ActiveIcon,
} from '@mui/icons-material';
import { useSnackbar } from 'notistack';
import * as yup from 'yup';
import { useFormik } from 'formik';
import api from '../../../api/axios';
import { useSelector } from 'react-redux';
import { jwtDecode } from 'jwt-decode';

// Validation schema for user updates
const userSchema = yup.object({
  name: yup.string().required('Name is required'),
  phoneNumber: yup.string()
    .matches(/^[0-9]{10}$/, 'Phone number must be 10 digits')
    .required('Phone number is required'),
  whatsApp: yup.string()
    .matches(/^[0-9]{10}$/, 'WhatsApp number must be 10 digits'),
  nishStaffId: yup.string(),
  address: yup.string(),
  pincode: yup.string()
    .matches(/^[0-9]{6}$/, 'Pincode must be 6 digits'),
});

const ManageUsers = () => {
  const [users, setUsers] = useState([]);
  const [loading, setLoading] = useState(true);
  const [editDialog, setEditDialog] = useState(false);
  const [selectedUser, setSelectedUser] = useState(null);
  const [confirmDialog, setConfirmDialog] = useState({
    open: false,
    title: '',
    message: '',
    action: null,
  });
  const [filters, setFilters] = useState({
    level: 'all',
    status: 'all',
  });
  const [pagination, setPagination] = useState({
    page: 0,
    pageSize: 10,
    total: 0,
  });

  const { enqueueSnackbar } = useSnackbar();
  const token = useSelector(state => state.auth.token);
  const adminId = token ? jwtDecode(token).userId : null;

  const formik = useFormik({
    initialValues: {
      name: '',
      phoneNumber: '',
      whatsApp: '',
      nishStaffId: '',
      address: '',
      pincode: '',
    },
    validationSchema: userSchema,
    onSubmit: async (values, { setSubmitting }) => {
      try {
        const response = await api.put('/users/update', {
          adminId,
          userId: selectedUser._id,
          ...values,
        });
        if (response.data.success) {
          enqueueSnackbar('User updated successfully', { variant: 'success' });
          setEditDialog(false);
          fetchUsers();
        }
      } catch (error) {
        enqueueSnackbar(error.response?.data?.message || 'Error updating user', { variant: 'error' });
      } finally {
        setSubmitting(false);
      }
    },
  });

  const handleEdit = (user) => {
    setSelectedUser(user);
    formik.setValues({
      name: user.name || '',
      phoneNumber: user.phoneNumber || '',
      whatsApp: user.whatsApp || '',
      nishStaffId: user.nishStaffId || '',
      address: user.address || '',
      pincode: user.pincode || '',
    });
    setEditDialog(true);
  };

  const handleStatusChange = async (user) => {
    const newStatus = user.status === 'active' ? 'blocked' : 'active';
    const action = newStatus === 'active' ? 'activate' : 'block';
    
    setConfirmDialog({
      open: true,
      title: `Confirm ${action} user`,
      message: `Are you sure you want to ${action} ${user.name}?`,
      action: async () => {
        try {
          const response = await api.put('/users/status', {
            adminId,
            userId: user._id,
            action: newStatus,
          });
          if (response.data.success) {
            enqueueSnackbar(`User ${action}d successfully`, { variant: 'success' });
            fetchUsers();
          }
        } catch (error) {
          enqueueSnackbar(error.response?.data?.message || `Error ${action}ing user`, { variant: 'error' });
          throw error;
        }
      },
    });
  };

 // Update the handleResetPassword function in ManageUsers.jsx
const handleResetPassword = (user) => {
    // Check if user is CS
    if (user.level === 'cs') {
      enqueueSnackbar("Clinical staff don't have login access, password reset not required.", { 
        variant: 'info' 
      });
      return;
    }
  
    setConfirmDialog({
      open: true,
      title: 'Confirm password reset',
      message: `Are you sure you want to reset the password for ${user.name}? A new password will be sent to their email.`,
      action: async () => {
        try {
          const response = await api.post('/users/reset-password', {
            email: user.email,
            adminId: adminId  // Add adminId to request
          });
          if (response.data.success) {
            enqueueSnackbar('Password reset successful. New password sent to email.', { variant: 'success' });
          }
        } catch (error) {
          enqueueSnackbar(error.response?.data?.message || 'Error resetting password', { variant: 'error' });
          throw error;
        }
      },
    });
  };

  const columns = [
    { 
      field: 'name', 
      headerName: 'Name', 
      flex: 1,
      minWidth: 150,
    },
    { 
      field: 'email', 
      headerName: 'Email', 
      flex: 1,
      minWidth: 200,
    },
    { 
      field: 'phoneNumber', 
      headerName: 'Phone', 
      width: 130,
    },
    { 
      field: 'level', 
      headerName: 'Role', 
      width: 150,
      valueGetter: (params) => params.row.level === 'mrrs' ? 'Med.Room Staff' : 'Clinical Staff',
    },
    { 
      field: 'status', 
      headerName: 'Status', 
      width: 130,
      renderCell: (params) => (
        <Typography
          sx={{
            color: params.row.status === 'active' ? 'success.main' : 'error.main',
            fontWeight: 'medium',
          }}
        >
          {params.row.status.charAt(0).toUpperCase() + params.row.status.slice(1)}
        </Typography>
      ),
    },
    {
      field: 'actions',
      headerName: 'Actions',
      width: 180,
      sortable: false,
      renderCell: (params) => (
        <Stack direction="row" spacing={1}>
          <Tooltip title="Edit User">
            <IconButton 
              size="small" 
              onClick={() => handleEdit(params.row)}
              color="primary"
            >
              <EditIcon />
            </IconButton>
          </Tooltip>
          <Tooltip title={params.row.status === 'active' ? 'Block User' : 'Activate User'}>
            <IconButton
              size="small"
              onClick={() => handleStatusChange(params.row)}
              color={params.row.status === 'active' ? 'error' : 'success'}
            >
              {params.row.status === 'active' ? <BlockIcon /> : <ActiveIcon />}
            </IconButton>
          </Tooltip>
          <Tooltip title="Reset Password">
            <IconButton
              size="small"
              onClick={() => handleResetPassword(params.row)}
              color="warning"
            >
              <ResetIcon />
            </IconButton>
          </Tooltip>
        </Stack>
      ),
    },
  ];

  const fetchUsers = async () => {
    try {
      setLoading(true);
      const queryParams = new URLSearchParams({
        page: pagination.page + 1,
        limit: pagination.pageSize,
        ...(filters.level !== 'all' && { level: filters.level }),
        ...(filters.status !== 'all' && { status: filters.status }),
      });

      const response = await api.get(`/users?${queryParams}`);
      const filteredUsers = response.data.data.filter(user => user.level !== 'superAdmin');
      setUsers(filteredUsers);
      setPagination(prev => ({
        ...prev,
        total: response.data.pagination.totalRecords,
      }));
    } catch (error) {
      enqueueSnackbar('Error fetching users', { variant: 'error' });
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchUsers();
  }, [pagination.page, pagination.pageSize, filters]);

  const handleFilterChange = (event) => {
    const { name, value } = event.target;
    setFilters(prev => ({ ...prev, [name]: value }));
    setPagination(prev => ({ ...prev, page: 0 }));
  };

  return (
    <Box sx={{ p: 3 }}>
      <Typography variant="h4" gutterBottom>
        Manage Users
      </Typography>

      <Card sx={{ mb: 3 }}>
        <Stack direction="row" spacing={2} p={2}>
          <FormControl sx={{ minWidth: 200 }}>
            <InputLabel>Role</InputLabel>
            <Select
              name="level"
              value={filters.level}
              label="Role"
              onChange={handleFilterChange}
            >
              <MenuItem value="all">All Roles</MenuItem>
              <MenuItem value="mrrs">Med.Room Staff</MenuItem>
              <MenuItem value="cs">Clinical Staff</MenuItem>
            </Select>
          </FormControl>

          <FormControl sx={{ minWidth: 200 }}>
            <InputLabel>Status</InputLabel>
            <Select
              name="status"
              value={filters.status}
              label="Status"
              onChange={handleFilterChange}
            >
              <MenuItem value="all">All Status</MenuItem>
              <MenuItem value="active">Active</MenuItem>
              <MenuItem value="blocked">Blocked</MenuItem>
            </Select>
          </FormControl>
        </Stack>
      </Card>

      <Card>
        <DataGrid
          rows={users}
          columns={columns}
          pagination
          paginationMode="server"
          rowCount={pagination.total}
          page={pagination.page}
          pageSize={pagination.pageSize}
          onPageChange={(newPage) => setPagination(prev => ({ ...prev, page: newPage }))}
          onPageSizeChange={(newPageSize) => 
            setPagination(prev => ({ ...prev, pageSize: newPageSize, page: 0 }))
          }
          loading={loading}
          getRowId={(row) => row._id}
          autoHeight
          disableSelectionOnClick
          components={{
            Toolbar: GridToolbar,
          }}
          componentsProps={{
            toolbar: {
              showQuickFilter: true,
              quickFilterProps: { 
                debounceMs: 500,
                sx: { 
                  '& .MuiInputBase-input': {
                    fontSize: '1rem',
                    fontWeight: 500,
                  }
                }
              },
              sx: {
                '& .MuiButton-root': {
                  fontSize: '0.875rem',
                  fontWeight: 600,
                },
                '& .MuiFormControl-root': {
                  '& .MuiInputBase-input': {
                    fontSize: '0.875rem',
                    fontWeight: 500,
                  }
                }
              }
            },
          }}
          sx={{
            '& .MuiDataGrid-toolbarContainer': {
              padding: 2,
              borderBottom: '1px solid',
              borderColor: 'divider',
            },
          }}
        />
      </Card>

      {/* Edit User Dialog */}
      <Dialog 
        open={editDialog} 
        onClose={() => setEditDialog(false)}
        maxWidth="sm"
        fullWidth
      >
        <form onSubmit={formik.handleSubmit}>
          <DialogTitle>Edit User</DialogTitle>
          <DialogContent>
            <Stack spacing={2} sx={{ mt: 2 }}>
              <TextField
                fullWidth
                name="name"
                label="Name"
                value={formik.values.name}
                onChange={formik.handleChange}
                error={formik.touched.name && Boolean(formik.errors.name)}
                helperText={formik.touched.name && formik.errors.name}
              />

              <TextField
                fullWidth
                name="phoneNumber"
                label="Phone Number"
                value={formik.values.phoneNumber}
                onChange={formik.handleChange}
                error={formik.touched.phoneNumber && Boolean(formik.errors.phoneNumber)}
                helperText={formik.touched.phoneNumber && formik.errors.phoneNumber}
              />

              <TextField
                fullWidth
                name="whatsApp"
                label="WhatsApp Number"
                value={formik.values.whatsApp}
                onChange={formik.handleChange}
                error={formik.touched.whatsApp && Boolean(formik.errors.whatsApp)}
                helperText={formik.touched.whatsApp && formik.errors.whatsApp}
              />

              <TextField
                fullWidth
                name="nishStaffId"
                label="NISH Staff ID"
                value={formik.values.nishStaffId}
                onChange={formik.handleChange}
              />

              <TextField
                fullWidth
                name="address"
                label="Address"
                multiline
                rows={3}
                value={formik.values.address}
                onChange={formik.handleChange}
              />

              <TextField
                fullWidth
                name="pincode"
                label="Pincode"
                value={formik.values.pincode}
                onChange={formik.handleChange}
                error={formik.touched.pincode && Boolean(formik.errors.pincode)}
                helperText={formik.touched.pincode && formik.errors.pincode}
              />
            </Stack>
          </DialogContent>
          <DialogActions>
            <Button 
              onClick={() => setEditDialog(false)}
              disabled={formik.isSubmitting}
            >
              Cancel
            </Button>
            <Button 
              type="submit"
              variant="contained"
              disabled={formik.isSubmitting}
            >
              {formik.isSubmitting ? <CircularProgress size={24} /> : 'Save Changes'}
            </Button>
          </DialogActions>
        </form>
      </Dialog>

      {/* Confirmation Dialog */}
      <Dialog
        open={confirmDialog.open}
        onClose={() => setConfirmDialog({ ...confirmDialog, open: false })}
      >
        <DialogTitle>{confirmDialog.title}</DialogTitle>
        <DialogContent>
          <DialogContentText>
            {confirmDialog.message}
          </DialogContentText>
        </DialogContent>
        <DialogActions>
          <Button 
            onClick={() => setConfirmDialog({ ...confirmDialog, open: false })}
            color="inherit"
          >
            Cancel
          </Button>
          <Button 
            onClick={async () => {
              try {
                await confirmDialog.action();
                setConfirmDialog({ ...confirmDialog, open: false });
              } catch (error) {
                console.error('Action failed:', error);
              }
            }}
            color="primary"
            variant="contained"
            autoFocus
          >
            Confirm
          </Button>
        </DialogActions>
      </Dialog>

      {/* Loading Overlay */}
      {loading && (
        <Box
          sx={{
            position: 'fixed',
            top: 0,
            left: 0,
            right: 0,
            bottom: 0,
            display: 'flex',
            alignItems: 'center',
            justifyContent: 'center',
            backgroundColor: 'rgba(0, 0, 0, 0.1)',
            zIndex: 9999,
          }}
        >
          <CircularProgress />
        </Box>
      )}
    </Box>
  );
};

export default ManageUsers;