import React, { useState, useEffect } from 'react';
import {
    Box,
    Card,
    CardContent,
    TextField,
    Button,
    Typography,
    Stack,
    Grid,
    IconButton,
    FormControl,
    InputLabel,
    Select,
    MenuItem,
    Paper,
    Chip,
    Tooltip,
    TableContainer,
    Table,
    TableHead,
    TableBody,
    TableRow,
    TableCell,
    TablePagination,
    InputAdornment,
    Dialog,
    DialogTitle,
    DialogContent,
    DialogActions,
    Alert,
    Snackbar,
    CircularProgress
} from '@mui/material';
import {
    Add,
    Search,
    FilterList,
    Edit,
    Delete,
    Visibility,
    ClearAll,
    Download
} from '@mui/icons-material';
import { useNavigate } from 'react-router-dom';
import deviceService from '../../../features/services/deviceService'; // Adjust path
import * as XLSX from 'xlsx';

const AllAccessories = () => {
    const navigate = useNavigate();

    // States
    const [accessories, setAccessories] = useState([]);
    const [filteredAccessories, setFilteredAccessories] = useState([]);
    const [page, setPage] = useState(0);
    const [rowsPerPage, setRowsPerPage] = useState(10);
    const [totalAccessories, setTotalAccessories] = useState(0);
    const [searchQuery, setSearchQuery] = useState('');
    const [filters, setFilters] = useState({
        status: '',
        device: '',
        supplier: ''
    });
    const [devices, setDevices] = useState([]);
    const [suppliers, setSuppliers] = useState([]);
    const [deleteDialog, setDeleteDialog] = useState({ open: false, accessory: null });
    const [notification, setNotification] = useState({
        open: false,
        message: '',
        severity: 'success'
    });
    const [showFilters, setShowFilters] = useState(false);
    const [loading, setLoading] = useState(false);

    // Fetch devices and initial accessories
    useEffect(() => {
        const fetchInitialData = async () => {
            setLoading(true);
            try {
                // Fetch devices
                const deviceResponse = await deviceService.getAllDevices();
                setDevices(deviceResponse.data || []);

                // Fetch initial accessories
                fetchAccessories();
            } catch (error) {
                showNotification('Failed to fetch initial data', 'error');
                console.error('Error fetching initial data:', error);
            } finally {
                setLoading(false);
            }
        };
        fetchInitialData();
    }, []);

    // Fetch accessories with pagination and filters
    const fetchAccessories = async () => {
        setLoading(true);
        try {
            const params = {
                page: page + 1, // Backend uses 1-based indexing
                limit: rowsPerPage,
                search: searchQuery || undefined,
                status: filters.status || undefined,
                deviceId: filters.device || undefined,
                supplier: filters.supplier || undefined
            };

            const response = await deviceService.getAllAccessories(params);
            // Adjust for API response structure: data is the array, pagination is separate
            setAccessories(response.data || []);
            setFilteredAccessories(response.data || []);
            setTotalAccessories(response.pagination?.total || 0);

            // Extract unique suppliers from fetched accessories
            const uniqueSuppliers = [...new Set(response.data.map(acc => acc.supplier))].filter(Boolean);
            setSuppliers(uniqueSuppliers);
        } catch (error) {
            showNotification('Failed to fetch accessories', 'error');
            console.error('Error fetching accessories:', error);
        } finally {
            setLoading(false);
        }
    };

    // Refetch when pagination or filters change
    useEffect(() => {
        fetchAccessories();
    }, [page, rowsPerPage, searchQuery, filters]);

    const handleChangePage = (event, newPage) => {
        setPage(newPage);
    };

    const handleChangeRowsPerPage = (event) => {
        setRowsPerPage(parseInt(event.target.value, 10));
        setPage(0);
    };

    const handleFilterChange = (event) => {
        const { name, value } = event.target;
        setFilters(prev => ({
            ...prev,
            [name]: value
        }));
    };

    const clearFilters = () => {
        setFilters({
            status: '',
            device: '',
            supplier: ''
        });
        setSearchQuery('');
    };

    const handleDeleteClick = (accessory) => {
        setDeleteDialog({ open: true, accessory });
    };

    const handleDeleteConfirm = async () => {
        setLoading(true);
        try {
            await deviceService.deleteAccessory(deleteDialog.accessory._id);

            setAccessories(prev => prev.filter(acc => acc._id !== deleteDialog.accessory._id));
            setFilteredAccessories(prev => prev.filter(acc => acc._id !== deleteDialog.accessory._id));
            setTotalAccessories(prev => prev - 1);

            setDeleteDialog({ open: false, accessory: null });
            showNotification('Accessory deleted successfully', 'success');
        } catch (error) {
            showNotification(error.response?.data?.message || 'Failed to delete accessory', 'error');
            console.error('Error deleting accessory:', error);
        } finally {
            setLoading(false);
        }
    };

    const exportToExcel = async () => {
        setLoading(true);
        try {
            const params = {
                limit: totalAccessories,
                page: 1,
                search: searchQuery || undefined,
                status: filters.status || undefined,
                deviceId: filters.device || undefined,
                supplier: filters.supplier || undefined
            };

            const response = await deviceService.getAllAccessories(params);
            const data = response.data.map(acc => ({
                'Item Name': acc.itemName,
                'Device': `${acc.device.deviceName} (SN: ${acc.device.serialNumber})`,
                'Supplier': acc.supplier,
                'Purchase Date': new Date(acc.purchaseDate).toLocaleDateString(),
                'Status': acc.status,
                'Side': acc.isRight && acc.isLeft ? 'Both' : acc.isRight ? 'Right' : acc.isLeft ? 'Left' : 'N/A'
            }));

            const ws = XLSX.utils.json_to_sheet(data);
            const wb = XLSX.utils.book_new();
            XLSX.utils.book_append_sheet(wb, ws, 'Accessories');
            XLSX.writeFile(wb, `accessories_export_${new Date().toISOString().split('T')[0]}.xlsx`);

            showNotification('Accessories exported successfully', 'success');
        } catch (error) {
            showNotification('Failed to export accessories', 'error');
            console.error('Error exporting to Excel:', error);
        } finally {
            setLoading(false);
        }
    };

    const showNotification = (message, severity) => {
        setNotification({
            open: true,
            message,
            severity
        });
    };

    return (
        <Box sx={{ p: 3, backgroundColor: '#f0f7ff', minHeight: '100vh' }}>
            <Card
                elevation={0}
                sx={{
                    borderRadius: 4,
                    background: 'linear-gradient(135deg, #ffffff 0%, #f8faff 100%)',
                    boxShadow: '0 8px 32px rgba(0, 0, 0, 0.1)'
                }}
            >
                <CardContent sx={{ p: 4 }}>
                    {/* Header */}
                    <Stack
                        direction={{ xs: 'column', sm: 'row' }}
                        justifyContent="space-between"
                        alignItems={{ xs: 'stretch', sm: 'center' }}
                        spacing={2}
                        mb={4}
                    >
                        <Typography
                            variant="h5"
                            sx={{
                                fontWeight: 600,
                                color: '#1976d2'
                            }}
                        >
                            All Accessories
                        </Typography>
                        <Stack
                            direction={{ xs: 'column', sm: 'row' }}
                            spacing={2}
                        >
                            <Button
                                variant="outlined"
                                startIcon={<Download />}
                                onClick={exportToExcel}
                                sx={{ borderRadius: 2 }}
                                disabled={loading}
                            >
                                Export
                            </Button>
                            <Button
                                variant="contained"
                                startIcon={<Add />}
                                onClick={() => navigate('/accessories/add')}
                                sx={{
                                    borderRadius: 2,
                                    backgroundColor: '#1976d2',
                                    '&:hover': {
                                        backgroundColor: '#1565c0'
                                    }
                                }}
                                disabled={loading}
                            >
                                Add New Accessory
                            </Button>
                        </Stack>
                    </Stack>

                    {/* Search and Filters */}
                    <Grid container spacing={2} mb={4}>
                        <Grid item xs={12} sm={6} md={4}>
                            <TextField
                                fullWidth
                                placeholder="Search accessories..."
                                value={searchQuery}
                                onChange={(e) => setSearchQuery(e.target.value)}
                                InputProps={{
                                    startAdornment: (
                                        <InputAdornment position="start">
                                            <Search />
                                        </InputAdornment>
                                    ),
                                    sx: { borderRadius: 2 }
                                }}
                                disabled={loading}
                            />
                        </Grid>
                        <Grid item xs={12} sm={6} md={8}>
                            <Stack
                                direction="row"
                                spacing={2}
                                alignItems="center"
                                justifyContent="flex-end"
                            >
                                <Button
                                    startIcon={<FilterList />}
                                    onClick={() => setShowFilters(!showFilters)}
                                    sx={{ borderRadius: 2 }}
                                    disabled={loading}
                                >
                                    Filters
                                </Button>
                                {(filters.status || filters.device || filters.supplier) && (
                                    <Button
                                        startIcon={<ClearAll />}
                                        onClick={clearFilters}
                                        sx={{ borderRadius: 2 }}
                                        disabled={loading}
                                    >
                                        Clear Filters
                                    </Button>
                                )}
                            </Stack>
                        </Grid>
                    </Grid>

                    {/* Filter Panel */}
                    {showFilters && (
                        <Paper
                            elevation={0}
                            sx={{
                                p: 2,
                                mb: 3,
                                borderRadius: 2,
                                backgroundColor: '#f8faff',
                                border: '1px solid #e0e0e0'
                            }}
                        >
                            <Grid container spacing={2}>
                                <Grid item xs={12} sm={4}>
                                    <FormControl fullWidth>
                                        <InputLabel>Status</InputLabel>
                                        <Select
                                            name="status"
                                            value={filters.status}
                                            onChange={handleFilterChange}
                                            label="Status"
                                            sx={{ borderRadius: 2 }}
                                            disabled={loading}
                                        >
                                            <MenuItem value="">All</MenuItem>
                                            <MenuItem value="active">Active</MenuItem>
                                            <MenuItem value="inactive">Inactive</MenuItem>
                                            <MenuItem value="maintenance">Under Maintenance</MenuItem>
                                        </Select>
                                    </FormControl>
                                </Grid>
                                <Grid item xs={12} sm={4}>
                                    <FormControl fullWidth>
                                        <InputLabel>Device</InputLabel>
                                        <Select
                                            name="device"
                                            value={filters.device}
                                            onChange={handleFilterChange}
                                            label="Device"
                                            sx={{ borderRadius: 2 }}
                                            disabled={loading}
                                        >
                                            <MenuItem value="">All</MenuItem>
                                            {devices.map(device => (
                                                <MenuItem key={device._id} value={device._id}>
                                                    {device.deviceName} - {device.serialNumber}
                                                </MenuItem>
                                            ))}
                                        </Select>
                                    </FormControl>
                                </Grid>
                                <Grid item xs={12} sm={4}>
                                    <FormControl fullWidth>
                                        <InputLabel>Supplier</InputLabel>
                                        <Select
                                            name="supplier"
                                            value={filters.supplier}
                                            onChange={handleFilterChange}
                                            label="Supplier"
                                            sx={{ borderRadius: 2 }}
                                            disabled={loading}
                                        >
                                            <MenuItem value="">All</MenuItem>
                                            {suppliers.map(supplier => (
                                                <MenuItem key={supplier} value={supplier}>
                                                    {supplier}
                                                </MenuItem>
                                            ))}
                                        </Select>
                                    </FormControl>
                                </Grid>
                            </Grid>
                        </Paper>
                    )}

                    {/* Accessories Table */}
                    <TableContainer component={Paper} sx={{ borderRadius: 2, mb: 3 }}>
                        <Table>
                            <TableHead>
                                <TableRow>
                                    <TableCell>Item Name</TableCell>
                                    <TableCell>Device</TableCell>
                                    <TableCell>Supplier</TableCell>
                                    <TableCell>Purchase Date</TableCell>
                                    <TableCell>Status</TableCell>
                                    <TableCell>Side</TableCell>
                                    <TableCell align="right">Actions</TableCell>
                                </TableRow>
                            </TableHead>
                            <TableBody>
                                {loading ? (
                                    <TableRow>
                                        <TableCell colSpan={7} align="center">
                                            <CircularProgress />
                                        </TableCell>
                                    </TableRow>
                                ) : filteredAccessories.length === 0 ? (
                                    <TableRow>
                                        <TableCell colSpan={7} align="center">
                                            <Typography variant="body1" color="textSecondary">
                                                No accessories found
                                            </Typography>
                                        </TableCell>
                                    </TableRow>
                                ) : (
                                    filteredAccessories.map((accessory) => (
                                        <TableRow key={accessory._id}>
                                            <TableCell>{accessory.itemName}</TableCell>
                                            <TableCell>
                                                {accessory.device.deviceName}
                                                <Typography variant="caption" display="block" color="textSecondary">
                                                    SN: {accessory.device.serialNumber}
                                                </Typography>
                                            </TableCell>
                                            <TableCell>{accessory.supplier}</TableCell>
                                            <TableCell>
                                                {new Date(accessory.purchaseDate).toLocaleDateString()}
                                            </TableCell>
                                            <TableCell>
                                                <Chip
                                                    label={accessory.status}
                                                    color={
                                                        accessory.status === 'active'
                                                            ? 'success'
                                                            : accessory.status === 'inactive'
                                                            ? 'error'
                                                            : 'warning'
                                                    }
                                                    size="small"
                                                />
                                            </TableCell>
                                            <TableCell>
                                                {accessory.isRight && accessory.isLeft
                                                    ? 'Both'
                                                    : accessory.isRight
                                                    ? 'Right'
                                                    : accessory.isLeft
                                                    ? 'Left'
                                                    : 'N/A'}
                                            </TableCell>
                                            <TableCell align="right">
                                                <Stack
                                                    direction="row"
                                                    spacing={1}
                                                    justifyContent="flex-end"
                                                >
                                                    <Tooltip title="View Details">
                                                        <IconButton
                                                            size="small"
                                                            onClick={() => navigate(`/accessories/${accessory._id}`)}
                                                            sx={{
                                                                backgroundColor: '#e3f2fd',
                                                                '&:hover': { backgroundColor: '#bbdefb' }
                                                            }}
                                                            disabled={loading}
                                                        >
                                                            <Visibility />
                                                        </IconButton>
                                                    </Tooltip>
                                                    <Tooltip title="Edit">
                                                        <IconButton
                                                            size="small"
                                                            onClick={() => navigate(`/accessories/${accessory._id}/edit`)}
                                                            sx={{
                                                                backgroundColor: '#e8f5e9',
                                                                '&:hover': { backgroundColor: '#c8e6c9' }
                                                            }}
                                                            disabled={loading}
                                                        >
                                                            <Edit />
                                                        </IconButton>
                                                    </Tooltip>
                                                    <Tooltip title="Delete">
                                                        <IconButton
                                                            size="small"
                                                            onClick={() => handleDeleteClick(accessory)}
                                                            sx={{
                                                                backgroundColor: '#ffebee',
                                                                '&:hover': { backgroundColor: '#ffcdd2' }
                                                            }}
                                                            disabled={loading}
                                                        >
                                                            <Delete />
                                                        </IconButton>
                                                    </Tooltip>
                                                </Stack>
                                            </TableCell>
                                        </TableRow>
                                    ))
                                )}
                            </TableBody>
                        </Table>
                    </TableContainer>

                    <TablePagination
                        component="div"
                        count={totalAccessories}
                        page={page}
                        onPageChange={handleChangePage}
                        rowsPerPage={rowsPerPage}
                        onRowsPerPageChange={handleChangeRowsPerPage}
                        rowsPerPageOptions={[5, 10, 25, 50]}
                        disabled={loading}
                    />
                </CardContent>
            </Card>

            {/* Delete Confirmation Dialog */}
            <Dialog
                open={deleteDialog.open}
                onClose={() => !loading && setDeleteDialog({ open: false, accessory: null })}
                PaperProps={{
                    sx: { borderRadius: 3 }
                }}
            >
                <DialogTitle>Confirm Deletion</DialogTitle>
                <DialogContent>
                    {loading ? (
                        <Box sx={{ display: 'flex', justifyContent: 'center', p: 3 }}>
                            <CircularProgress />
                        </Box>
                    ) : (
                        <Typography>
                            Are you sure you want to delete the accessory "{deleteDialog.accessory?.itemName}"?
                            This action cannot be undone.
                        </Typography>
                    )}
                </DialogContent>
                <DialogActions sx={{ p: 2 }}>
                    <Button
                        onClick={() => setDeleteDialog({ open: false, accessory: null })}
                        sx={{ borderRadius: 2 }}
                        disabled={loading}
                    >
                        Cancel
                    </Button>
                    <Button
                        onClick={handleDeleteConfirm}
                        variant="contained"
                        color="error"
                        sx={{ borderRadius: 2 }}
                        disabled={loading}
                    >
                        Delete
                    </Button>
                </DialogActions>
            </Dialog>

            {/* Notification */}
            <Snackbar
                open={notification.open}
                autoHideDuration={6000}
                onClose={() => setNotification(prev => ({ ...prev, open: false }))}
                anchorOrigin={{ vertical: 'top', horizontal: 'right' }}
            >
                <Alert
                    onClose={() => setNotification(prev => ({ ...prev, open: false }))}
                    severity={notification.severity}
                    variant="filled"
                    sx={{ width: '100%', borderRadius: 2 }}
                >
                    {notification.message}
                </Alert>
            </Snackbar>
        </Box>
    );
};

export default AllAccessories;