import React, { useState, useEffect } from 'react';
import {
    Box,
    Card,
    CardContent,
    TextField,
    Button,
    Typography,
    Stack,
    Grid,
    IconButton,
    FormControl,
    InputLabel,
    Select,
    MenuItem,
    FormControlLabel,
    Switch,
    Divider,
    Paper,
    Alert,
    Snackbar,
    Dialog,
    DialogTitle,
    DialogContent,
    DialogActions,
    CircularProgress
} from '@mui/material';
import {
    ArrowBack,
    Edit,
    Delete,
    Upload,
    Save,
    CheckCircle,
    Cancel,
    AddCircleOutline,
    MedicalServices
} from '@mui/icons-material';
import { useNavigate } from 'react-router-dom';
import { DatePicker } from '@mui/x-date-pickers/DatePicker';
import { LocalizationProvider } from '@mui/x-date-pickers';
import { AdapterDateFns } from '@mui/x-date-pickers/AdapterDateFns';
import deviceService from '../../../features/services/deviceService'; // Adjust path as needed

const ManageAccessories = () => {
    const navigate = useNavigate();

    // States
    const [selectedDevice, setSelectedDevice] = useState('');
    const [devices, setDevices] = useState([]);
    const [accessories, setAccessories] = useState([]);
    const [editingAccessory, setEditingAccessory] = useState(null);
    const [deleteDialog, setDeleteDialog] = useState({ open: false, accessory: null });
    const [notification, setNotification] = useState({
        open: false,
        message: '',
        severity: 'success'
    });
    const [loading, setLoading] = useState(false);

    // Fetch devices
    useEffect(() => {
        const fetchDevices = async () => {
            setLoading(true);
            try {
                const response = await deviceService.getAllDevices();
                setDevices(response.data || []);
            } catch (error) {
                showNotification('Failed to fetch devices', 'error');
                console.error('Error fetching devices:', error);
            } finally {
                setLoading(false);
            }
        };
        fetchDevices();
    }, []);

    // Fetch accessories when device is selected
    useEffect(() => {
        if (selectedDevice) {
            const fetchAccessories = async () => {
                setLoading(true);
                try {
                    const response = await deviceService.getAccessoriesByDevice(selectedDevice);
                    setAccessories(response.data || []);
                } catch (error) {
                    showNotification('Failed to fetch accessories', 'error');
                    console.error('Error fetching accessories:', error);
                } finally {
                    setLoading(false);
                }
            };
            fetchAccessories();
        } else {
            setAccessories([]);
        }
    }, [selectedDevice]);

    const handleDeviceChange = (event) => {
        setSelectedDevice(event.target.value);
        setEditingAccessory(null);
    };

    const handleEditAccessory = (accessory) => {
        setEditingAccessory({
            ...accessory,
            isEditing: true
        });
    };

    const handleUpdateAccessory = async (accessoryId) => {
        setLoading(true);
        try {
            const formData = new FormData();
            // Include all required fields to satisfy backend validation
            formData.append('itemName', editingAccessory.itemName || '');
            formData.append('supplier', editingAccessory.supplier || '');
            formData.append('purchaseDate', editingAccessory.purchaseDate ? new Date(editingAccessory.purchaseDate).toISOString() : '');
            formData.append('isRight', editingAccessory.isRight);
            formData.append('isLeft', editingAccessory.isLeft);
            formData.append('status', editingAccessory.status || 'active');
            if (editingAccessory.photo instanceof File) {
                formData.append('photo', editingAccessory.photo);
            }

            const response = await deviceService.updateAccessory(accessoryId, formData);

            setAccessories(prevAccessories =>
                prevAccessories.map(acc =>
                    acc._id === accessoryId ? { ...response.data } : acc
                )
            );

            setEditingAccessory(null);
            showNotification('Accessory updated successfully', 'success');
        } catch (error) {
            showNotification(error.response?.data?.message || 'Failed to update accessory', 'error');
            console.error('Error updating accessory:', error);
        } finally {
            setLoading(false);
        }
    };

    const handleDeleteConfirmation = (accessory) => {
        setDeleteDialog({ open: true, accessory });
    };

    const handleDeleteAccessory = async () => {
        setLoading(true);
        try {
            const accessoryId = deleteDialog.accessory._id;
            await deviceService.deleteAccessory(accessoryId);

            setAccessories(prevAccessories =>
                prevAccessories.filter(acc => acc._id !== accessoryId)
            );

            setDeleteDialog({ open: false, accessory: null });
            showNotification('Accessory deleted successfully', 'success');
        } catch (error) {
            showNotification(error.response?.data?.message || 'Failed to delete accessory', 'error');
            console.error('Error deleting accessory:', error);
        } finally {
            setLoading(false);
        }
    };

    const handlePhotoChange = (accessoryId, event) => {
        const file = event.target.files[0];
        if (file) {
            if (file.size > 5 * 1024 * 1024) {
                showNotification('File size should not exceed 5MB', 'error');
                return;
            }
            setEditingAccessory(prev => ({
                ...prev,
                photo: file
            }));
        }
    };

    const showNotification = (message, severity) => {
        setNotification({
            open: true,
            message,
            severity
        });
    };

    return (
        <Box sx={{ p: 3, backgroundColor: '#f0f7ff', minHeight: '100vh' }}>
            <Card
                elevation={0}
                sx={{
                    borderRadius: 4,
                    background: 'linear-gradient(135deg, #ffffff 0%, #f8faff 100%)',
                    boxShadow: '0 8px 32px rgba(0, 0, 0, 0.1)'
                }}
            >
                <CardContent sx={{ p: 4 }}>
                    {/* Header */}
                    <Stack
                        direction="row"
                        alignItems="center"
                        spacing={2}
                        mb={4}
                    >
                        <IconButton
                            onClick={() => navigate(-1)}
                            sx={{
                                backgroundColor: '#e3f2fd',
                                '&:hover': { backgroundColor: '#bbdefb' }
                            }}
                            disabled={loading}
                        >
                            <ArrowBack />
                        </IconButton>
                        <Stack direction="column">
                            <Typography
                                variant="h5"
                                sx={{
                                    fontWeight: 600,
                                    color: '#1976d2'
                                }}
                            >
                                Manage Accessories
                            </Typography>
                            <Typography variant="body2" color="textSecondary">
                                View and manage device accessories
                            </Typography>
                        </Stack>
                    </Stack>

                    <Divider sx={{ mb: 4 }} />

                    {/* Loading Indicator */}
                    {loading && (
                        <Box sx={{ display: 'flex', justifyContent: 'center', mb: 4 }}>
                            <CircularProgress />
                        </Box>
                    )}

                    {/* Device Selection */}
                    <Stack direction="row" alignItems="center" spacing={1} mb={3}>
                        <MedicalServices color="primary" />
                        <Typography variant="h6" color="primary">
                            Select Device
                        </Typography>
                    </Stack>

                    <Grid container spacing={3} mb={4}>
                        <Grid item xs={12}>
                            <FormControl fullWidth>
                                <InputLabel>Device</InputLabel>
                                <Select
                                    value={selectedDevice}
                                    onChange={handleDeviceChange}
                                    label="Device"
                                    sx={{ borderRadius: 2 }}
                                    disabled={loading}
                                >
                                    {devices.map((device) => (
                                        <MenuItem key={device._id} value={device._id}>
                                            {device.deviceName} - {device.serialNumber}
                                        </MenuItem>
                                    ))}
                                </Select>
                            </FormControl>
                        </Grid>
                    </Grid>

                    {/* Accessories List */}
                    {selectedDevice && !loading && (
                        <>
                            <Stack direction="row" alignItems="center" spacing={1} mb={3}>
                                <AddCircleOutline color="primary" />
                                <Typography variant="h6" color="primary">
                                    Device Accessories
                                </Typography>
                            </Stack>

                            {accessories.length === 0 ? (
                                <Typography variant="body1" color="textSecondary">
                                    No accessories found for this device.
                                </Typography>
                            ) : (
                                <Stack spacing={3}>
                                    {accessories.map((accessory) => (
                                        <Paper
                                            key={accessory._id}
                                            elevation={0}
                                            sx={{
                                                p: 3,
                                                borderRadius: 2,
                                                border: '1px solid #e0e0e0'
                                            }}
                                        >
                                            {editingAccessory?._id === accessory._id ? (
                                                // Edit Mode
                                                <Grid container spacing={3}>
                                                    <Grid item xs={12} sm={6}>
                                                        <TextField
                                                            fullWidth
                                                            label="Item Name"
                                                            value={editingAccessory.itemName}
                                                            onChange={(e) => setEditingAccessory(prev => ({
                                                                ...prev,
                                                                itemName: e.target.value
                                                            }))}
                                                            InputProps={{
                                                                sx: { borderRadius: 2 }
                                                            }}
                                                            disabled={loading}
                                                            required
                                                        />
                                                    </Grid>
                                                    <Grid item xs={12} sm={6}>
                                                        <TextField
                                                            fullWidth
                                                            label="Supplier"
                                                            value={editingAccessory.supplier}
                                                            onChange={(e) => setEditingAccessory(prev => ({
                                                                ...prev,
                                                                supplier: e.target.value
                                                            }))}
                                                            InputProps={{
                                                                sx: { borderRadius: 2 }
                                                            }}
                                                            disabled={loading}
                                                            required
                                                        />
                                                    </Grid>
                                                    <Grid item xs={12} sm={6}>
                                                        <LocalizationProvider dateAdapter={AdapterDateFns}>
                                                            <DatePicker
                                                                label="Purchase Date"
                                                                value={editingAccessory.purchaseDate}
                                                                onChange={(date) => setEditingAccessory(prev => ({
                                                                    ...prev,
                                                                    purchaseDate: date
                                                                }))}
                                                                disabled={loading}
                                                                renderInput={(params) => (
                                                                    <TextField
                                                                        {...params}
                                                                        fullWidth
                                                                        required
                                                                        InputProps={{
                                                                            ...params.InputProps,
                                                                            sx: { borderRadius: 2 }
                                                                        }}
                                                                    />
                                                                )}
                                                            />
                                                        </LocalizationProvider>
                                                    </Grid>
                                                    <Grid item xs={12} sm={6}>
                                                        <FormControl fullWidth>
                                                            <InputLabel>Status</InputLabel>
                                                            <Select
                                                                value={editingAccessory.status}
                                                                onChange={(e) => setEditingAccessory(prev => ({
                                                                    ...prev,
                                                                    status: e.target.value
                                                                }))}
                                                                label="Status"
                                                                sx={{ borderRadius: 2 }}
                                                                disabled={loading}
                                                            >
                                                                <MenuItem value="active">Active</MenuItem>
                                                                <MenuItem value="inactive">Inactive</MenuItem>
                                                                <MenuItem value="maintenance">Under Maintenance</MenuItem>
                                                            </Select>
                                                        </FormControl>
                                                    </Grid>
                                                    <Grid item xs={12} sm={6}>
                                                        <Paper
                                                            elevation={0}
                                                            sx={{
                                                                p: 2,
                                                                borderRadius: 2,
                                                                backgroundColor: '#e3f2fd',
                                                                border: '1px solid #bbdefb'
                                                            }}
                                                        >
                                                            <Stack direction="row" spacing={2}>
                                                                <FormControlLabel
                                                                    control={
                                                                        <Switch
                                                                            checked={editingAccessory.isRight}
                                                                            onChange={(e) => setEditingAccessory(prev => ({
                                                                                ...prev,
                                                                                isRight: e.target.checked
                                                                            }))}
                                                                            disabled={loading}
                                                                        />
                                                                    }
                                                                    label="Right"
                                                                />
                                                                <FormControlLabel
                                                                    control={
                                                                        <Switch
                                                                            checked={editingAccessory.isLeft}
                                                                            onChange={(e) => setEditingAccessory(prev => ({
                                                                                ...prev,
                                                                                isLeft: e.target.checked
                                                                            }))}
                                                                            disabled={loading}
                                                                        />
                                                                    }
                                                                    label="Left"
                                                                />
                                                            </Stack>
                                                        </Paper>
                                                    </Grid>
                                                    <Grid item xs={12}>
                                                        <Button
                                                            component="label"
                                                            variant="outlined"
                                                            startIcon={<Upload />}
                                                            sx={{ borderRadius: 2 }}
                                                            disabled={loading}
                                                        >
                                                            Update Photo
                                                            <input
                                                                type="file"
                                                                hidden
                                                                accept="image/*"
                                                                onChange={(e) => handlePhotoChange(accessory._id, e)}
                                                            />
                                                        </Button>
                                                        {editingAccessory.photo && (
                                                            <Typography variant="body2" sx={{ mt: 1, color: 'success.main' }}>
                                                                {editingAccessory.photo instanceof File ? editingAccessory.photo.name : 'Existing photo'}
                                                            </Typography>
                                                        )}
                                                    </Grid>
                                                    <Grid item xs={12}>
                                                        <Stack direction="row" spacing={2} justifyContent="flex-end">
                                                            <Button
                                                                variant="outlined"
                                                                startIcon={<Cancel />}
                                                                onClick={() => setEditingAccessory(null)}
                                                                sx={{ borderRadius: 2 }}
                                                                disabled={loading}
                                                            >
                                                                Cancel
                                                            </Button>
                                                            <Button
                                                                variant="contained"
                                                                startIcon={<Save />}
                                                                onClick={() => handleUpdateAccessory(accessory._id)}
                                                                sx={{ borderRadius: 2 }}
                                                                disabled={loading}
                                                            >
                                                                Save Changes
                                                            </Button>
                                                        </Stack>
                                                    </Grid>
                                                </Grid>
                                            ) : (
                                                // View Mode
                                                <Grid container spacing={3}>
                                                    <Grid item xs={12}>
                                                        <Stack
                                                            direction="row"
                                                            justifyContent="space-between"
                                                            alignItems="center"
                                                        >
                                                            <Typography variant="h6">
                                                                {accessory.itemName}
                                                            </Typography>
                                                            <Stack direction="row" spacing={1}>
                                                                <IconButton
                                                                    color="primary"
                                                                    onClick={() => handleEditAccessory(accessory)}
                                                                    sx={{ backgroundColor: '#e3f2fd' }}
                                                                    disabled={loading}
                                                                >
                                                                    <Edit />
                                                                </IconButton>
                                                                <IconButton
                                                                    color="error"
                                                                    onClick={() => handleDeleteConfirmation(accessory)}
                                                                    sx={{ backgroundColor: '#fee2e2' }}
                                                                    disabled={loading}
                                                                >
                                                                    <Delete />
                                                                </IconButton>
                                                            </Stack>
                                                        </Stack>
                                                    </Grid>
                                                    <Grid item xs={12} sm={6}>
                                                        <Typography variant="body2" color="textSecondary">
                                                            Supplier: {accessory.supplier}
                                                        </Typography>
                                                    </Grid>
                                                    <Grid item xs={12} sm={6}>
                                                        <Typography variant="body2" color="textSecondary">
                                                            Purchase Date: {new Date(accessory.purchaseDate).toLocaleDateString()}
                                                        </Typography>
                                                    </Grid>
                                                    <Grid item xs={12} sm={6}>
                                                        <Typography variant="body2" color="textSecondary">
                                                            Status: {accessory.status}
                                                        </Typography>
                                                    </Grid>
                                                    <Grid item xs={12} sm={6}>
                                                        <Stack direction="row" spacing={2}>
                                                            {accessory.isRight && (
                                                                <Typography variant="body2" color="textSecondary">
                                                                    Right
                                                                </Typography>
                                                            )}
                                                            {accessory.isLeft && (
                                                                <Typography variant="body2" color="textSecondary">
                                                                    Left
                                                                </Typography>
                                                            )}
                                                        </Stack>
                                                    </Grid>
                                                    {accessory.imageUrl && (
                                                        <Grid item xs={12}>
                                                            <Box
                                                                component="img"
                                                                src={`${process.env.REACT_APP_API_URL || 'http://localhost:5000'}${accessory.imageUrl}`}
                                                                alt={accessory.itemName}
                                                                sx={{
                                                                    maxWidth: 200,
                                                                    maxHeight: 200,
                                                                    objectFit: 'contain',
                                                                    borderRadius: 2
                                                                }}
                                                                onError={(e) => (e.target.src = '/path/to/fallback-image.jpg')} // Optional fallback
                                                            />
                                                        </Grid>
                                                    )}
                                                </Grid>
                                            )}
                                        </Paper>
                                    ))}
                                </Stack>
                            )}

                            <Button
                                variant="outlined"
                                startIcon={<AddCircleOutline />}
                                onClick={() => navigate('/accessories/add')}
                                sx={{ mt: 3, borderRadius: 2 }}
                                disabled={loading}
                            >
                                Add New Accessory
                            </Button>
                        </>
                    )}
                </CardContent>
            </Card>

            {/* Delete Confirmation Dialog */}
            <Dialog
                open={deleteDialog.open}
                onClose={() => !loading && setDeleteDialog({ open: false, accessory: null })}
                PaperProps={{
                    sx: { borderRadius: 3 }
                }}
            >
                <DialogTitle>Confirm Deletion</DialogTitle>
                <DialogContent>
                    {loading ? (
                        <Box sx={{ display: 'flex', justifyContent: 'center', p: 3 }}>
                            <CircularProgress />
                        </Box>
                    ) : (
                        <Typography>
                            Are you sure you want to delete the accessory "{deleteDialog.accessory?.itemName}"?
                            This action cannot be undone.
                        </Typography>
                    )}
                </DialogContent>
                <DialogActions sx={{ p: 2 }}>
                    <Button
                        onClick={() => setDeleteDialog({ open: false, accessory: null })}
                        sx={{ borderRadius: 2 }}
                        disabled={loading}
                    >
                        Cancel
                    </Button>
                    <Button
                        onClick={handleDeleteAccessory}
                        variant="contained"
                        color="error"
                        sx={{ borderRadius: 2 }}
                        disabled={loading}
                    >
                        Delete
                    </Button>
                </DialogActions>
            </Dialog>

            {/* Notification */}
            <Snackbar
                open={notification.open}
                autoHideDuration={6000}
                onClose={() => setNotification(prev => ({ ...prev, open: false }))}
                anchorOrigin={{ vertical: 'top', horizontal: 'right' }}
            >
                <Alert
                    onClose={() => setNotification(prev => ({ ...prev, open: false }))}
                    severity={notification.severity}
                    variant="filled"
                    sx={{ width: '100%', borderRadius: 2 }}
                >
                    {notification.message}
                </Alert>
            </Snackbar>
        </Box>
    );
};

export default ManageAccessories;