// src/services/hodService.js
import api from '../../api/axios';

const hodService = {
  createHOD: async (formData) => {
    try {
      console.log('Original formData:', formData);

      const form = new FormData();
      
      // Append all form fields with explicit type checking
      Object.keys(formData).forEach(key => {
        if (formData[key] !== null && formData[key] !== undefined) {
          form.append(key, formData[key]);
        }
      });

      // Log the actual form data entries
      console.log('FormData entries:', Array.from(form.entries()));

      const response = await api.post(`/device/hod/create`, form, {
        headers: {
          'Content-Type': 'multipart/form-data',
        },
      });
      return response.data;
    } catch (error) {
      console.error('Error in createHOD:', error);
      throw error;
    }
  },

  getAllHODs: async () => {
    const response = await api.get(`/device/hod/`);
    return response.data;
  },

  getHODById: async (id) => {
    const response = await api.get(`/device/hod//${id}`);
    return response.data;
  },

  updateHOD: async (id, formData) => {
    const form = new FormData();
    
    Object.keys(formData).forEach(key => {
      if (key === 'profilePhoto' && formData[key]) {
        form.append(key, formData[key]);
      } else if (key !== 'profilePhoto') {
        form.append(key, formData[key]);
      }
    });

    const response = await api.patch(`/device/hod//${id}`, form, {
      headers: {
        'Content-Type': 'multipart/form-data',
      },
    });
    return response.data;
  },

  deleteHOD: async (id) => {
    const response = await api.delete(`/device/hod//${id}`);
    return response.data;
  },

  updateHODStatus: async (id, status) => {
    const response = await api.patch(`/device/hod//${id}/status`, { status });
    return response.data;
  },
};

export default hodService;