import React, { useState, useEffect } from 'react';
import {
    Box,
    Card,
    CardContent,
    Typography,
    Stack,
    Table,
    TableBody,
    TableCell,
    TableContainer,
    TableHead,
    TableRow,
    Paper,
    CircularProgress,
    Pagination,
    Divider,
    Snackbar,
    Alert,
    Button,
    IconButton,
    Menu,
    MenuItem,
    Chip,
    Grid,
    TextField,
    FormControl,
    InputLabel,
    Select,
} from '@mui/material';
import {
    ArrowBack,
    FilterList,
    Visibility,
    PictureAsPdf,
    MoreVert,
    Refresh
} from '@mui/icons-material';
import { useNavigate } from 'react-router-dom';
import deviceService from '../../../features/services/deviceService';
import issueService from '../../../features/services/issueService';
import inspectionService from '../../../features/services/inspectionService';

const InspectionReportsPage = () => {
    const navigate = useNavigate();

    const [reports, setReports] = useState([]);
    const [loading, setLoading] = useState(false);
    const [pagination, setPagination] = useState({ page: 1, pages: 1, total: 0 });
    const [filters, setFilters] = useState({
        type: '',
        deviceId: '',
        dateFrom: '',
        dateTo: '',
        search: ''
    });
    const [notification, setNotification] = useState({
        open: false,
        message: '',
        severity: 'success'
    });
    const [anchorEl, setAnchorEl] = useState(null);
    const [selectedReport, setSelectedReport] = useState(null);

    useEffect(() => {
        const token = localStorage.getItem('token');
        if (!token) {
            navigate('/login');
            showNotification('Please log in to view inspection reports', 'error');
            return;
        }
        fetchReports();
    }, [filters, pagination.page, navigate]);

    const fetchReports = async () => {
        setLoading(true);
        try {
            const query = {
                page: pagination.page,
                limit: 10,
                inspectionType: filters.type ? filters.type.toLowerCase() : undefined,
                device: filters.deviceId || undefined,
                startDate: filters.dateFrom ? new Date(filters.dateFrom).toISOString().split('T')[0] : undefined,
                endDate: filters.dateTo ? new Date(filters.dateTo).toISOString().split('T')[0] : undefined,
                search: filters.search ? filters.search.toLowerCase() : undefined,
            };

            Object.keys(query).forEach(key => query[key] === undefined && delete query[key]);
            console.log('Query sent to backend:', query);

            const inspectionsResponse = await inspectionService.getAllInspections(query);
            console.log('Inspections Response:', inspectionsResponse);

            if (!inspectionsResponse || !inspectionsResponse.success) {
                throw new Error('Invalid response format from inspection service');
            }

            let inspectionsData = inspectionsResponse.data || inspectionsResponse.inspections;
            if (!Array.isArray(inspectionsData)) {
                throw new Error('No inspections data found in response');
            }
console.log('Inspections Data:_____________________', inspectionsData);

            const allReports = inspectionsData.map(inspection => {
                // For issue inspections, use the first issue ID from issuesChecked if available
                const issueId = (inspection.type === 'issue' && inspection.issuesChecked && inspection.issuesChecked.length > 0)
                    ? inspection.issuesChecked[0].issueId
                    : null;

                return {
                    id: inspection._id, // Inspection ID
                    issueId: inspection._id, // Issue ID for issue inspections
                    type: inspection.type,
                    deviceName: inspection.device?.deviceName || 'N/A',
                    date: inspection.inspectionDate,
                    status: inspection.status,
                    details: inspection.remarks || 'No details',
                };
            });

            const sortedReports = allReports.sort((a, b) => new Date(b.date) - new Date(a.date));
            setReports(sortedReports);
            console.log('allReports:', allReports);
            console.log('Reports:', sortedReports);

            const paginationData = inspectionsResponse.pagination || { page: 1, limit: 10, total: 0, pages: 1 };
            setPagination({
                page: paginationData.page,
                pages: paginationData.pages,
                total: paginationData.total,
            });
        } catch (error) {
            console.error('Fetch Reports Error:', error);
            setReports([]);
            setPagination({ page: 1, pages: 1, total: 0 });
            showNotification(error.message || 'Failed to load inspection reports', 'error');
        } finally {
            setLoading(false);
        }
    };

    const handleFilterChange = (event) => {
        const { name, value } = event.target;
        setFilters(prev => ({
            ...prev,
            [name]: value
        }));
        setPagination(prev => ({ ...prev, page: 1 }));
    };

    const handlePageChange = (event, value) => {
        setPagination(prev => ({ ...prev, page: value }));
    };

    const resetFilters = () => {
        setFilters({
            type: '',
            deviceId: '',
            dateFrom: '',
            dateTo: '',
            search: ''
        });
        setPagination(prev => ({ ...prev, page: 1 }));
    };

    const handleDownloadPDF = async (reportId, reportType, issueId) => {
        setLoading(true);
        try {
            let response;
            if (reportType === 'daily') {
                response = await deviceService.generateDailyReport(reportId);
            } else if (reportType === 'issue') {
                // Use issueId for issue inspections instead of reportId
                if (!issueId) throw new Error('No issue ID available for this inspection');
                response = await issueService.generateIssueReport(issueId);
            } else if (reportType === 'company') {
                response = await issueService.generateCompanyReport(reportId); // Use inspectionService here
            }

            console.log('Service response:', response);

            if (!(response instanceof Blob) && !(response instanceof ArrayBuffer)) {
                throw new Error('Invalid response type: Expected Blob or ArrayBuffer');
            }

            const blob = response instanceof Blob ? response : new Blob([response], { type: 'application/pdf' });
            const url = window.URL.createObjectURL(blob);
            const a = document.createElement('a');
            a.href = url;
            // Use issueId in filename for issue reports
            const idForFilename = reportType === 'issue' ? issueId : reportId;
            a.download = `inspection-report-${reportType}-${idForFilename}-${new Date().toISOString().split('T')[0]}.pdf`;
            document.body.appendChild(a);
            a.click();
            document.body.removeChild(a);
            window.URL.revokeObjectURL(url);
            showNotification('PDF downloaded successfully!', 'success');
        } catch (error) {
            console.error('Error downloading PDF:', error);
            showNotification(`Failed to download PDF: ${error.message}`, 'error');
        } finally {
            setLoading(false);
            setAnchorEl(null);
            setSelectedReport(null);
        }
    };

    const handleMenuOpen = (event, report) => {
        setAnchorEl(event.currentTarget);
        setSelectedReport(report);
    };

    const handleMenuClose = () => {
        setAnchorEl(null);
        setSelectedReport(null);
    };

    const showNotification = (message, severity) => {
        setNotification({
            open: true,
            message,
            severity
        });
    };

    if (loading) {
        return (
            <Box sx={{ display: 'flex', justifyContent: 'center', alignItems: 'center', minHeight: '100vh' }}>
                <CircularProgress />
            </Box>
        );
    }

    return (
        <Box sx={{ p: 3, backgroundColor: '#f0f7ff', minHeight: '100vh' }}>
            <Card
                elevation={0}
                sx={{
                    borderRadius: 4,
                    background: 'linear-gradient(135deg, #ffffff 0%, #f8faff 100%)',
                    boxShadow: '0 8px 32px rgba(0, 0, 0, 0.1)'
                }}
            >
                <CardContent sx={{ p: 4 }}>
                    <Stack direction="row" alignItems="center" spacing={2} mb={4}>
                        <IconButton
                            onClick={() => navigate('/clinical-incharge/issues')}
                            sx={{ backgroundColor: '#e3f2fd', '&:hover': { backgroundColor: '#bbdefb' } }}
                        >
                            <ArrowBack />
                        </IconButton>
                        <Stack direction="column">
                            <Typography variant="h5" sx={{ fontWeight: 600, color: '#1976d2' }}>
                                Inspection Reports
                            </Typography>
                            <Typography variant="body2" color="textSecondary">
                                View and manage all inspection reports (Daily, Issue-based, and Company)
                            </Typography>
                        </Stack>
                    </Stack>

                    <Divider sx={{ mb: 4 }} />

                    <Stack direction="row" spacing={2} mb={4} alignItems="center">
                        <FilterList color="primary" />
                        <Typography variant="h6" color="primary">Filters</Typography>
                    </Stack>
                    <Grid container spacing={3} mb={4}>
                        <Grid item xs={12} sm={3}>
                            <FormControl fullWidth>
                                <InputLabel>Type</InputLabel>
                                <Select
                                    name="type"
                                    size='small'
                                    value={filters.type}
                                    onChange={handleFilterChange}
                                    label="Type"
                                    sx={{ borderRadius: 2 }}
                                >
                                    <MenuItem size='small' value="">All</MenuItem>
                                    <MenuItem size='small' value="daily">Daily Inspection</MenuItem>
                                    <MenuItem size='small' value="issue">Issue Inspection</MenuItem>
                                    <MenuItem size='small' value="company">Company Inspection</MenuItem>
                                </Select>
                            </FormControl>
                        </Grid>
                        <Grid item xs={12} sm={3}>
                            <TextField
                                fullWidth
                                focused
                                size='small'
                                label="Date From"
                                name="dateFrom"
                                type="date"
                                value={filters.dateFrom}
                                onChange={handleFilterChange}
                                InputProps={{ sx: { borderRadius: 2 } }}
                            />
                        </Grid>
                        <Grid item xs={12} sm={3}>
                            <TextField
                                fullWidth
                                focused
                                size='small'
                                label="Date To"
                                name="dateTo"
                                type="date"
                                value={filters.dateTo}
                                onChange={handleFilterChange}
                                InputProps={{ sx: { borderRadius: 2 } }}
                            />
                        </Grid>
                        <Grid item xs={12} sm={3}>
                            <Stack direction="row" spacing={2}>
                                <Button
                                    variant="outlined"
                                    startIcon={<Refresh />}
                                    onClick={resetFilters}
                                    sx={{ borderRadius: 2 }}
                                />
                                <Button
                                    variant="contained"
                                    onClick={fetchReports}
                                    sx={{ borderRadius: 2, backgroundColor: '#1976d2', '&:hover': { backgroundColor: '#1565c0' } }}
                                >
                                    Apply Filters
                                </Button>
                            </Stack>
                        </Grid>
                    </Grid>

                    <TableContainer component={Paper} sx={{ borderRadius: 2, mb: 4 }}>
                        <Table>
                            <TableHead>
                                <TableRow sx={{ backgroundColor: '#e3f2fd' }}>
                                    <TableCell><Typography fontWeight={600} sx={{ fontSize: '14px' }}>Sl No</Typography></TableCell>
                                    <TableCell><Typography fontWeight={600} sx={{ fontSize: '14px' }}>Report Type</Typography></TableCell>
                                    <TableCell><Typography fontWeight={600} sx={{ fontSize: '14px' }}>Date</Typography></TableCell>
                                    <TableCell><Typography fontWeight={600} sx={{ fontSize: '14px' }}>Status</Typography></TableCell>
                                    <TableCell><Typography fontWeight={600} sx={{ fontSize: '14px' }}>Details</Typography></TableCell>
                                    <TableCell><Typography fontWeight={600} sx={{ fontSize: '14px' }}>Actions</Typography></TableCell>
                                </TableRow>
                            </TableHead>
                            <TableBody>
                                {reports.length === 0 ? (
                                    <TableRow>
                                        <TableCell colSpan={6} align="center">
                                            <Typography>No reports found</Typography>
                                        </TableCell>
                                    </TableRow>
                                ) : (
                                    reports.map(report => (
                                        <TableRow key={report.id} hover>
                                            <TableCell>{reports.indexOf(report) + 1}</TableCell>
                                            <TableCell>
                                                <Chip
                                                    label={report.type.charAt(0).toUpperCase() + report.type.slice(1) + ' Inspection'}
                                                    sx={{
                                                        textTransform: 'capitalize',
                                                        backgroundColor: report.type === 'daily' ? '#ff00ff' :
                                                            report.type === 'issue' ? '#0080ff' :
                                                                report.type === 'company' ? '#ff8000' : 'inherit',
                                                        color: '#ffffff',
                                                        fontWeight: 600,
                                                        border: 'none',
                                                        boxShadow: 'none',
                                                        textDecoration: 'none',
                                                    }}
                                                    size="small"
                                                />
                                            </TableCell>
                                            <TableCell>{new Date(report.date).toLocaleDateString()}</TableCell>
                                            <TableCell>
                                                <Chip
                                                    label={report.status}
                                                    sx={{
                                                        textTransform: 'capitalize',
                                                        backgroundColor: report.status === 'open' ? '#ff0000' :
                                                            report.status === 'resolved' ? '#008000' :
                                                                report.status === 'inprogress' ? '#ff8000' :
                                                                    report.status === 'closed' ? '#808080' :
                                                                        report.status === 'pending_company_inspection' ? '#ff4500' : 'inherit',
                                                        color: '#ffffff',
                                                        fontWeight: 600,
                                                        border: 'none',
                                                        boxShadow: 'none',
                                                        textDecoration: 'none',
                                                    }}
                                                    size="small"
                                                />
                                            </TableCell>
                                            <TableCell>{report.details}</TableCell>
                                            <TableCell>
                                                <IconButton
                                                    onClick={() => handleDownloadPDF(report.id, report.type, report.issueId)}
                                                    sx={{ p: 1 }}
                                                >
                                                    <PictureAsPdf color="error" />
                                                </IconButton>
                                            </TableCell>
                                        </TableRow>
                                    ))
                                )}
                            </TableBody>
                        </Table>
                    </TableContainer>

                    {pagination.pages > 1 && (
                        <Stack direction="row" justifyContent="center">
                            <Pagination
                                count={pagination.pages}
                                page={pagination.page}
                                onChange={handlePageChange}
                                color="primary"
                                sx={{ mb: 2 }}
                            />
                        </Stack>
                    )}

                    <Menu
                        anchorEl={anchorEl}
                        open={Boolean(anchorEl)}
                        onClose={handleMenuClose}
                        anchorOrigin={{ vertical: 'top', horizontal: 'right' }}
                        transformOrigin={{ vertical: 'top', horizontal: 'left' }}
                        sx={{ mt: 1 }}
                    >
                        <MenuItem
                            onClick={() => handleDownloadPDF(selectedReport?.id, selectedReport?.type, selectedReport?.issueId)}
                            disabled={loading}
                        >
                            <PictureAsPdf sx={{ mr: 1 }} /> Download PDF
                        </MenuItem>
                    </Menu>

                    <Snackbar
                        open={notification.open}
                        autoHideDuration={6000}
                        onClose={() => setNotification(prev => ({ ...prev, open: false }))}
                        anchorOrigin={{ vertical: 'top', horizontal: 'right' }}
                    >
                        <Alert
                            onClose={() => setNotification(prev => ({ ...prev, open: false }))}
                            severity={notification.severity}
                            variant="filled"
                            sx={{ width: '100%', borderRadius: 2 }}
                        >
                            {notification.message}
                        </Alert>
                    </Snackbar>
                </CardContent>
            </Card>
        </Box>
    );
};

export default InspectionReportsPage;