const SideBar = ({ open, handleDrawerToggle, currentPage, handlePageChange }) => {
  const [expandedItems, setExpandedItems] = React.useState({});
  const navigate = useNavigate();
  const theme = useTheme();
  
  const token = useSelector(state => state.auth.token);
  const userLevel = token ? JSON.parse(atob(token.split('.')[1])).level : null;
  const menuItems = getMenuItems(userLevel);

  const handleMenuClick = (page) => {
    handlePageChange(page);
    navigate(`/file-tracker/${page}`);
  };

  const handleExpand = (itemId) => {
    setExpandedItems(prev => ({
      ...prev,
      [itemId]: !prev[itemId]
    }));
  };

  const renderMenuItem = (item) => {
    const isSelected = currentPage === item.id;
    const isExpanded = expandedItems[item.id];

    return (
      <React.Fragment key={item.id}>
        <ListItem disablePadding>
          <ListItemButton
            selected={isSelected}
            onClick={() => {
              if (item.subItems) {
                handleExpand(item.id);
              } else {
                handleMenuClick(item.id);
              }
            }}
            sx={{
              minHeight: 48,
              justifyContent: open ? 'initial' : 'center',
              px: 2.5,
              mx: 1,
              my: 0.5,
              borderRadius: '8px',
              '&.Mui-selected': {
                background: theme.palette.mode === 'light'
                  ? `linear-gradient(90deg, ${alpha(theme.palette.primary.main, 0.15)} 0%, ${alpha(theme.palette.primary.main, 0.05)} 100%)`
                  : `linear-gradient(90deg, ${alpha(theme.palette.primary.main, 0.25)} 0%, ${alpha(theme.palette.primary.main, 0.15)} 100%)`,
                '&:hover': {
                  background: theme.palette.mode === 'light'
                    ? `linear-gradient(90deg, ${alpha(theme.palette.primary.main, 0.25)} 0%, ${alpha(theme.palette.primary.main, 0.15)} 100%)`
                    : `linear-gradient(90deg, ${alpha(theme.palette.primary.main, 0.35)} 0%, ${alpha(theme.palette.primary.main, 0.25)} 100%)`
                }
              },
              '&:hover': {
                background: theme.palette.mode === 'light'
                  ? alpha(theme.palette.primary.main, 0.05)
                  : alpha(theme.palette.primary.main, 0.15),
                borderRadius: '8px',
              },
              transition: 'all 0.2s ease-in-out',
            }}
          >
            <ListItemIcon
              sx={{
                minWidth: 0,
                mr: open ? 3 : 'auto',
                justifyContent: 'center',
                color: isSelected ? theme.palette.primary.main : 'inherit',
                transition: 'color 0.2s ease-in-out',
              }}
            >
              {item.icon}
            </ListItemIcon>
            {open && (
              <>
                <ListItemText 
                  primary={
                    <Typography
                      variant="body2"
                      sx={{
                        fontWeight: isSelected ? 600 : 400,
                        color: isSelected ? theme.palette.primary.main : 'inherit',
                      }}
                    >
                      {item.title}
                    </Typography>
                  }
                />
                {item.subItems && (
                  <IconButton
                    size="small"
                    sx={{
                      transform: isExpanded ? 'rotate(-180deg)' : 'rotate(0)',
                      transition: 'transform 0.3s',
                    }}
                  >
                    <ExpandMore />
                  </IconButton>
                )}
              </>
            )}
          </ListItemButton>
        </ListItem>

        {item.subItems && (
          <Collapse in={open && isExpanded} timeout="auto" unmountOnExit>
            <List component="div" disablePadding>
              {item.subItems.map((subItem) => {
                const isSubSelected = currentPage === subItem.id;
                return (
                  <ListItemButton
                    key={subItem.id}
                    selected={isSubSelected}
                    onClick={() => handleMenuClick(subItem.id)}
                    sx={{
                      pl: 4,
                      py: 1,
                      mx: 2,
                      borderRadius: '8px',
                      '&.Mui-selected': {
                        background: theme.palette.mode === 'light'
                          ? alpha(theme.palette.primary.main, 0.1)
                          : alpha(theme.palette.primary.main, 0.2),
                        '&:hover': {
                          background: theme.palette.mode === 'light'
                            ? alpha(theme.palette.primary.main, 0.15)
                            : alpha(theme.palette.primary.main, 0.25)
                        }
                      },
                      '&:hover': {
                        background: theme.palette.mode === 'light'
                          ? alpha(theme.palette.primary.main, 0.05)
                          : alpha(theme.palette.primary.main, 0.15),
                      },
                      transition: 'all 0.2s ease-in-out',
                    }}
                  >
                    <ListItemIcon
                      sx={{
                        color: isSubSelected ? theme.palette.primary.main : 'inherit',
                        minWidth: 36,
                      }}
                    >
                      {subItem.icon}
                    </ListItemIcon>
                    <ListItemText 
                      primary={
                        <Typography
                          variant="body2"
                          sx={{
                            fontWeight: isSubSelected ? 600 : 400,
                            color: isSubSelected ? theme.palette.primary.main : 'inherit',
                          }}
                        >
                          {subItem.title}
                        </Typography>
                      }
                    />
                  </ListItemButton>
                );
              })}
            </List>
          </Collapse>
        )}
      </React.Fragment>
    );
  };

  return (
    <Drawer
      variant="permanent"
      sx={{
        width: open ? DRAWER_WIDTH : 64,
        flexShrink: 0,
        '& .MuiDrawer-paper': {
          width: open ? DRAWER_WIDTH : 64,
          overflowX: 'hidden',
          borderRight: `1px solid ${theme.palette.divider}`,
          background: theme.palette.mode === 'light' 
            ? '#ffffff'
            : theme.palette.background.default,
          transition: theme.transitions.create(['width', 'background-color'], {
            easing: theme.transitions.easing.sharp,
            duration: theme.transitions.duration.enteringScreen,
          }),
        },
      }}
      open={open}
    >
      <DrawerHeader>
        {open && (
          <Box sx={{ display: 'flex', alignItems: 'center', gap: 1 }}>
            <HealthAndSafety 
              sx={{ 
                color: theme.palette.primary.main,
                fontSize: 28,
              }} 
            />
            <Typography
              variant="subtitle1"
              sx={{
                fontWeight: 600,
                color: theme.palette.primary.main,
              }}
            >
              NISH MRR
            </Typography>
          </Box>
        )}
        <IconButton onClick={handleDrawerToggle}>
          <ChevronLeft />
        </IconButton>
      </DrawerHeader>
      <Divider sx={{ mb: 1 }} />
      <List sx={{ px: 1 }}>
        {menuItems.map(renderMenuItem)}
      </List>
    </Drawer>
  );
};

export default SideBar;