import React, { useState, useEffect } from 'react';
import {
  Box,
  TextField,
  Button,
  Typography,
  FormControl,
  InputLabel,
  Select,
  MenuItem,
  Grid,
  Stack,
  Card,
  CardContent,
  Snackbar,
  Alert,
  IconButton,
  Divider,
  Dialog,
  DialogTitle,
  DialogContent,
  DialogActions,
  DialogContentText,
} from '@mui/material';
import {
  PersonAdd,
  ArrowBack,
  Badge,
  Email,
  Phone,
  Assignment,
  Close
} from '@mui/icons-material';
import ClinicalInchargeService from '../../../features/services/clinicalInchargeService';
import { useNavigate } from 'react-router-dom';
import { Visibility, VisibilityOff, Password as PasswordIcon } from '@mui/icons-material';
import { Tooltip } from '@mui/material';

const ClinicalInchargeForm = () => {
  const navigate = useNavigate();
  const [showPassword, setShowPassword] = useState(false);

  const [formData, setFormData] = useState({
    name: '',
    email: '',
    phone: '',
    employeeId: '',
    department: '',
    status: 'true',
    password: '' // Add password field
  });

  const [errors, setErrors] = useState({});
  const [openDialog, setOpenDialog] = useState(false);
  const [notification, setNotification] = useState({
    open: false,
    message: '',
    severity: 'success'
  });

  useEffect(() => {
    const token = localStorage.getItem('token');
    if (!token) {
      navigate('/login', {
        replace: true,
        state: { from: '/clinical-incharge/create' }
      });
    }
  }, [navigate]);
  const generatePassword = () => {
    const length = 12;
    const charset = "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789@$!%*?&";
    let newPassword = "";

    // Ensure at least one of each required character type
    newPassword += "ABCDEFGHIJKLMNOPQRSTUVWXYZ"[Math.floor(Math.random() * 26)]; // uppercase
    newPassword += "abcdefghijklmnopqrstuvwxyz"[Math.floor(Math.random() * 26)]; // lowercase
    newPassword += "0123456789"[Math.floor(Math.random() * 10)]; // number
    newPassword += "@$!%*?&"[Math.floor(Math.random() * 7)]; // special char

    // Fill the rest randomly
    for (let i = 4; i < length; i++) {
      newPassword += charset[Math.floor(Math.random() * charset.length)];
    }

    // Shuffle the password
    newPassword = newPassword.split('')
      .sort(() => Math.random() - 0.5)
      .join('');

    setFormData(prev => ({
      ...prev,
      password: newPassword
    }));
  };
  const validateForm = () => {
    const newErrors = {};

    if (!formData.name.trim()) {
      newErrors.name = 'Name is required';
    }

    if (!formData.email.trim()) {
      newErrors.email = 'Email is required';
    } else if (!/^[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,}$/i.test(formData.email)) {
      newErrors.email = 'Invalid email address';
    }

    if (!formData.phone.trim()) {
      newErrors.phone = 'Phone number is required';
    } else if (!/^\d{10}$/.test(formData.phone)) {
      newErrors.phone = 'Invalid phone number';
    }

    if (!formData.employeeId.trim()) {
      newErrors.employeeId = 'Employee ID is required';
    }

    if (!formData.department) {
      newErrors.department = 'Department is required';
    }
    const passwordRegex = /^(?=.*[a-z])(?=.*[A-Z])(?=.*\d)(?=.*[@$!%*?&])[A-Za-z\d@$!%*?&]{8,}$/;
    if (!formData.password) {
      newErrors.password = 'Password is required';
    } else if (!passwordRegex.test(formData.password)) {
      newErrors.password = 'Password must contain at least 8 characters, one uppercase, one lowercase, one number and one special character';
    }

    setErrors(newErrors);
    return Object.keys(newErrors).length === 0;
  };
  const handleSubmit = (e) => {
    e.preventDefault();
    if (validateForm()) {
      setOpenDialog(true);
    } else {
      showNotification('Please fill in all required fields correctly', 'error');
    }
  };

  const handleConfirmSubmit = async () => {
    try {
      await ClinicalInchargeService.createClinicalIncharge(formData);
      setOpenDialog(false);
      showNotification('Clinical Incharge created successfully!', 'success');

    } catch (error) {
      console.error('Error:', error);
      setOpenDialog(false);

      if (error.message === 'Your session has expired. Please login again.') {
        showNotification(error.message, 'error');
        
        return;
      }

      showNotification(
        error.message || 'Failed to create Clinical Incharge',
        'error'
      );
    }
  };

  const handleChange = (e) => {
    const { name, value } = e.target;
    setFormData(prev => ({
      ...prev,
      [name]: value
    }));
    if (errors[name]) {
      setErrors(prev => ({ ...prev, [name]: '' }));
    }
  };

  const showNotification = (message, severity) => {
    setNotification({
      open: true,
      message,
      severity
    });
  };

  const handleCloseNotification = (event, reason) => {
    if (reason === 'clickaway') return;
    setNotification(prev => ({ ...prev, open: false }));
  };

  return (

    <Box sx={{
      p: 3,
      backgroundColor: '#f0f7ff',
      minHeight: '100vh'
    }}>
      <Card
        elevation={0}
        sx={{
          width: '100%',
          borderRadius: 4,
          background: 'linear-gradient(135deg, #ffffff 0%, #f8faff 100%)',
          boxShadow: '0 8px 32px rgba(0, 0, 0, 0.1)'
        }}
      >
        <CardContent sx={{ p: 4 }}>
          {/* Header */}
          <Stack
            direction="row"
            alignItems="center"
            spacing={2}
            mb={4}
          >
            <IconButton
              onClick={() => navigate(-1)}
              sx={{
                backgroundColor: '#e3f2fd',
                '&:hover': { backgroundColor: '#bbdefb' }
              }}
            >
              <ArrowBack />
            </IconButton>
            <Stack direction="column">
              <Typography
                variant="h5"
                sx={{
                  fontWeight: 600,
                  color: '#1976d2'
                }}
              >
                Create Clinical Incharge
              </Typography>
              <Typography variant="body2" color="textSecondary">
                Fill in the information below to create a new Clinical Incharge
              </Typography>
            </Stack>
          </Stack>

          <Divider sx={{ mb: 4 }} />

          <form onSubmit={handleSubmit}>
            <Grid container spacing={3}>
              <Grid item xs={12} md={6}>
                <TextField
                  fullWidth
                  label="Name"
                  name="name"
                  value={formData.name}
                  onChange={handleChange}
                  error={!!errors.name}
                  helperText={errors.name}
                  required
                  InputProps={{
                    sx: { borderRadius: 2 }
                  }}
                />
              </Grid>

              <Grid item xs={12} md={6}>
                <TextField
                  fullWidth
                  label="Employee ID"
                  name="employeeId"
                  value={formData.employeeId}
                  onChange={handleChange}
                  error={!!errors.employeeId}
                  helperText={errors.employeeId}
                  required
                  InputProps={{
                    sx: { borderRadius: 2 }
                  }}
                />
              </Grid>

              <Grid item xs={12} md={6}>
                <TextField
                  fullWidth
                  label="Email"
                  name="email"
                  type="email"
                  value={formData.email}
                  onChange={handleChange}
                  error={!!errors.email}
                  helperText={errors.email}
                  required
                  InputProps={{
                    sx: { borderRadius: 2 },
                    startAdornment: <Email color="action" sx={{ mr: 1 }} />
                  }}
                />
              </Grid>

              <Grid item xs={12} md={6}>
                <TextField
                  fullWidth
                  label="Phone"
                  name="phone"
                  value={formData.phone}
                  onChange={handleChange}
                  error={!!errors.phone}
                  helperText={errors.phone}
                  required
                  InputProps={{
                    sx: { borderRadius: 2 },
                    startAdornment: <Phone color="action" sx={{ mr: 1 }} />
                  }}
                />
              </Grid>

              <Grid item xs={12} md={6}>
                <FormControl
                  fullWidth
                  required
                  error={!!errors.department}
                  sx={{
                    '& .MuiOutlinedInput-root': {
                      borderRadius: 2
                    }
                  }}
                >
                  <InputLabel>Department</InputLabel>
                  <Select
                    name="department"
                    value={formData.department}
                    onChange={handleChange}
                    label="Department"
                  >
                    <MenuItem value="">Select Department</MenuItem>
                    <MenuItem value="Audiology">Audiology</MenuItem>
                    <MenuItem value="Speech-Language Pathology">Speech-Language Pathology</MenuItem>
                    <MenuItem value="Clinical Psychology">Clinical Psychology</MenuItem>
                    <MenuItem value="Special Education">Special Education</MenuItem>
                    <MenuItem value="Occupational Therapy">Occupational Therapy</MenuItem>
                    <MenuItem value="Physical Therapy">Physical Therapy</MenuItem>
                    <MenuItem value="Nutrition and Dietetics">Nutrition and Dietetics</MenuItem>
                    <MenuItem value="Social Work">Social Work</MenuItem>
                    <MenuItem value="Medical Social Work">Medical Social Work</MenuItem>
                    <MenuItem value="others">Others</MenuItem>

                  </Select>
                </FormControl>
              </Grid>

              <Grid item xs={12} md={6}>
                <FormControl
                  fullWidth
                  sx={{
                    '& .MuiOutlinedInput-root': {
                      borderRadius: 2
                    }
                  }}
                >
                  <InputLabel>Status</InputLabel>
                  <Select
                    name="status"
                    value={formData.status}
                    onChange={handleChange}
                    label="Status"
                  >
                    <MenuItem value="true">Active</MenuItem>
                    <MenuItem value="false">Inactive</MenuItem>
                  </Select>
                </FormControl>
              </Grid>
              <Grid item xs={12} md={6}>
                <TextField
                  fullWidth
                  label="Password"
                  name="password"
                  type={showPassword ? 'text' : 'password'}
                  value={formData.password}
                  onChange={handleChange}
                  error={!!errors.password}
                  helperText={errors.password}
                  required
                  InputProps={{
                    sx: { borderRadius: 2 },
                    endAdornment: (
                      <Stack direction="row" spacing={1}>
                        <Tooltip
                          title="Generate a strong password that includes uppercase, lowercase, numbers, and special characters"
                          arrow
                          placement="top"
                        >
                          <IconButton
                            onClick={generatePassword}
                            edge="end"
                            sx={{ color: 'action.active' }}
                          >
                            <PasswordIcon />
                          </IconButton>
                        </Tooltip>
                        <Tooltip
                          title={showPassword ? "Hide password" : "Show password"}
                          arrow
                          placement="top"
                        >
                          <IconButton
                            onClick={() => setShowPassword(!showPassword)}
                            edge="end"
                            sx={{ color: 'action.active' }}
                          >
                            {showPassword ? <VisibilityOff /> : <Visibility />}
                          </IconButton>
                        </Tooltip>
                      </Stack>
                    )
                  }}
                />
              </Grid>
              <Grid item xs={12}>
                <Stack
                  direction="row"
                  spacing={2}
                  justifyContent="flex-end"
                  sx={{ mt: 2 }}
                >
                  <Button
                    variant="outlined"
                    onClick={() => navigate(-1)}
                    sx={{
                      borderRadius: 2,
                      px: 4
                    }}
                  >
                    Cancel
                  </Button>
                  <Button
                    variant="contained"
                    type="submit"
                    startIcon={<PersonAdd />}
                    sx={{
                      borderRadius: 2,
                      px: 4,
                      background: 'linear-gradient(45deg, #1976d2 30%, #42a5f5 90%)',
                      boxShadow: '0 3px 5px 2px rgba(33, 150, 243, .3)',
                      '&:hover': {
                        background: 'linear-gradient(45deg, #1565c0 30%, #1976d2 90%)',
                        transform: 'translateY(-1px)'
                      }
                    }}
                  >
                    Create Clinical Incharge
                  </Button>
                </Stack>
              </Grid>
            </Grid>
          </form>
        </CardContent>
      </Card>

      {/* Confirmation Dialog */}
      <Dialog
        open={openDialog}
        onClose={() => setOpenDialog(false)}
        PaperProps={{
          sx: { borderRadius: 3 }
        }}
      >
        <DialogTitle sx={{ pb: 1 }}>
          <Stack direction="row" alignItems="center" spacing={1}>
            <PersonAdd color="primary" />
            <Typography variant="h6" color="primary">
              Confirm Clinical Incharge Creation
            </Typography>
          </Stack>
        </DialogTitle>
        <DialogContent>
          <DialogContentText sx={{ mb: 2 }}>
            Please review the following details:
          </DialogContentText>
          <Box sx={{
            backgroundColor: '#f5f5f5',
            p: 2,
            borderRadius: 2
          }}>
            <Typography variant="body2" gutterBottom>
              <strong>Name:</strong> {formData.name}
            </Typography>
            <Typography variant="body2" gutterBottom>
              <strong>Employee ID:</strong> {formData.employeeId}
            </Typography>
            <Typography variant="body2" gutterBottom>
              <strong>Email:</strong> {formData.email}
            </Typography>
            <Typography variant="body2" gutterBottom>
              <strong>Phone:</strong> {formData.phone}
            </Typography>
            <Typography variant="body2">
              <strong>Department:</strong> {formData.department}
            </Typography>
          </Box>
        </DialogContent>
        <DialogActions sx={{ p: 3 }}>
          <Button
            onClick={() => setOpenDialog(false)}
            sx={{ borderRadius: 2 }}
          >
            Cancel
          </Button>
          <Button
            onClick={handleConfirmSubmit}
            variant="contained"
            sx={{ borderRadius: 2 }}
          >
            Confirm Creation
          </Button>
        </DialogActions>
      </Dialog>

      {/* Notification */}
      <Snackbar
        open={notification.open}
        autoHideDuration={6000}
        onClose={handleCloseNotification}
        anchorOrigin={{ vertical: 'top', horizontal: 'right' }}
      >
        <Alert
          onClose={handleCloseNotification}
          severity={notification.severity}
          variant="filled"
          sx={{
            width: '100%',
            borderRadius: 2
          }}
        >
          {notification.message}
        </Alert>
      </Snackbar>
    </Box>
  );
};

export default ClinicalInchargeForm;