import React, { useState, useEffect } from 'react';
import {
  Box,
  Table,
  TableBody,
  TableCell,
  TableContainer,
  TableHead,
  TableRow,
  Paper,
  TablePagination,
  IconButton,
  Chip,
  TextField,
  InputAdornment,
  Typography,
  Stack,
  Card,
  CardContent,
  Menu,
  MenuItem,
  FormControl,
  InputLabel,
  Select,
  Button,
  Dialog,
  DialogTitle,
  DialogContent,
  DialogActions,
  Alert,
  Snackbar,
  Tooltip
} from '@mui/material';
import {
  Search,
  MoreVert,
  Edit,
  Delete,
  Refresh,
  FilterList,
  PersonAdd,
  Group
} from '@mui/icons-material';
import { useNavigate } from 'react-router-dom';
import hodService from '../../../features/services/hodService';
import { CircularProgress } from '@mui/material';


const ManageHODPage = () => {
  const navigate = useNavigate();
  const [page, setPage] = useState(0);
  const [rowsPerPage, setRowsPerPage] = useState(10);
  const [searchQuery, setSearchQuery] = useState('');
  const [departmentFilter, setDepartmentFilter] = useState('all');
  const [statusFilter, setStatusFilter] = useState('all');
  const [anchorEl, setAnchorEl] = useState(null);
  const [selectedHOD, setSelectedHOD] = useState(null);
  const [deleteDialogOpen, setDeleteDialogOpen] = useState(false);
  const [eodDialogOpen, setEodDialogOpen] = useState(false);
  const [notification, setNotification] = useState({
    open: false,
    message: '',
    severity: 'success'
  });
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState(null);
  const [hods, setHODs] = useState([]);

  useEffect(() => {
    fetchHODs();
  }, []);

  const fetchHODs = async () => {
    try {
      setLoading(true);
      const response = await hodService.getAllHODs();
      setHODs(response.data || []);
    } catch (error) {
      console.error('Error fetching HODs:', error);
      showNotification('Failed to fetch HODs', 'error');
      setError(error.message || 'Failed to fetch HODs');
    } finally {
      setLoading(false);
    }
  };

  const confirmDelete = async () => {
    try {
      setLoading(true);
      await hodService.deleteHOD(selectedHOD.id);
      showNotification('HOD deleted successfully', 'success');
      setDeleteDialogOpen(false);
      fetchHODs(); // Refresh the list
    } catch (error) {
      console.error('Error deleting HOD:', error);
      showNotification(error.response?.data?.message || 'Failed to delete HOD', 'error');
    } finally {
      setLoading(false);
      setSelectedHOD(null);
    }
  };
  const handleAddNew = () => {
    console.log('Add New clicked');
    navigate('/device-portal/create-hod');
  };
  const handleStatusToggle = async (hodId, currentStatus) => {
    try {
      const newStatus = currentStatus === 'active' ? 'inactive' : 'active';
      await hodService.updateHODStatus(hodId, newStatus);
      showNotification('Status updated successfully', 'success');
      fetchHODs();
    } catch (error) {
      console.error('Error updating status:', error);
      showNotification(error.response?.data?.message || 'Failed to update status', 'error');
    }
  };
  // // Sample data - Replace with actual API data
  // const [hods, setHODs] = useState([
  //   {
  //     id: 1,
  //     name: 'Dr. John Doe',
  //     email: 'john@nish.ac.in',
  //     department: 'Audiology',
  //     employeeId: 'HOD001',
  //     contactNumber: '1234567890',
  //     status: 'active',
  //     lastLogin: '2024-02-19T10:30:00',
  //     eods: [
  //       { id: 1, name: 'EOD 1', status: 'active' },
  //       { id: 2, name: 'EOD 2', status: 'inactive' },
  //     ],
  //   },
  //   // Add more sample data
  // ]);

  const handleChangePage = (event, newPage) => {
    setPage(newPage);
  };

  const handleChangeRowsPerPage = (event) => {
    setRowsPerPage(parseInt(event.target.value, 10));
    setPage(0);
  };

  const handleSearchChange = (event) => {
    setSearchQuery(event.target.value);
    setPage(0);
  };

  const handleDepartmentFilterChange = (event) => {
    setDepartmentFilter(event.target.value);
    setPage(0);
  };

  const handleStatusFilterChange = (event) => {
    setStatusFilter(event.target.value);
    setPage(0);
  };

  const handleMenuClick = (event, hod) => {
    setAnchorEl(event.currentTarget);
    setSelectedHOD(hod);
  };

  const handleMenuClose = () => {
    setAnchorEl(null);
    setSelectedHOD(null);
  };

  const handleEdit = () => {
    handleMenuClose();
    if (selectedHOD) {
      navigate(`/hod/edit/${selectedHOD.id}`);
    }
  };

  const handleDelete = () => {
    handleMenuClose();
    setDeleteDialogOpen(true);
  };

  const handleViewEODs = () => {
    handleMenuClose();
    setEodDialogOpen(true);
  };

  // const confirmDelete = async () => {
  //   try {
  //     // API call to delete HOD
  //     // await deleteHOD(selectedHOD.id);
  //     showNotification('HOD deleted successfully', 'success');
  //     setDeleteDialogOpen(false);
  //     // Refresh HODs list
  //   } catch (error) {
  //     console.error('Error deleting HOD:', error);
  //     showNotification('Failed to delete HOD', 'error');
  //   }
  // };
  const renderTableContent = () => {
    if (loading) {
      return (
        <TableRow>
          <TableCell colSpan={8} align="center" sx={{ py: 3 }}>
            <CircularProgress size={40} />
          </TableCell>
        </TableRow>
      );
    }

    if (error) {
      return (
        <TableRow>
          <TableCell colSpan={8} align="center" sx={{ py: 3 }}>
            <Alert
              severity="error"
              action={
                <Button color="inherit" size="small" onClick={fetchHODs}>
                  Retry
                </Button>
              }
            >
              {error}
            </Alert>
          </TableCell>
        </TableRow>
      );
    }

    if (filteredHODs.length === 0) {
      return (
        <TableRow>
          <TableCell colSpan={8} align="center" sx={{ py: 3 }}>
            <Typography variant="body1" color="textSecondary">
              No HODs found
            </Typography>
          </TableCell>
        </TableRow>
      );
    }

    return filteredHODs
      .slice(page * rowsPerPage, page * rowsPerPage + rowsPerPage)
      .map((hod) => (
        <TableRow key={hod._id} hover>
          <TableCell>{hod.employeeId}</TableCell>
          <TableCell>{`${hod.firstName} ${hod.lastName}`}</TableCell>
          <TableCell>{hod.email}</TableCell>
          <TableCell>{hod.department}</TableCell>
          <TableCell>{hod.phone}</TableCell>
          <TableCell>
            <Chip
              label={hod.status}
              color={getStatusColor(hod.status)}
              size="small"
              onClick={() => handleStatusToggle(hod._id, hod.status)}
            />
          </TableCell>
          <TableCell>
            {hod.lastLogin ? new Date(hod.lastLogin).toLocaleString() : 'Never'}
          </TableCell>
          <TableCell align="center">
            <IconButton
              size="small"
              onClick={(event) => handleMenuClick(event, hod)}
            >
              <MoreVert />
            </IconButton>
          </TableCell>
        </TableRow>
      ));
  };

  // Update the filteredHODs function to match the API response structure
  const filteredHODs = hods.filter(hod => {
    const fullName = `${hod.firstName} ${hod.lastName}`.toLowerCase();
    const matchesSearch =
      fullName.includes(searchQuery.toLowerCase()) ||
      hod.email.toLowerCase().includes(searchQuery.toLowerCase()) ||
      hod.employeeId.toLowerCase().includes(searchQuery.toLowerCase());

    const matchesDepartment = departmentFilter === 'all' ||
      hod.department.toLowerCase() === departmentFilter.toLowerCase();
    const matchesStatus = statusFilter === 'all' ||
      hod.status.toLowerCase() === statusFilter.toLowerCase();

    return matchesSearch && matchesDepartment && matchesStatus;
  });


  const showNotification = (message, severity) => {
    setNotification({
      open: true,
      message,
      severity
    });
  };

  const handleCloseNotification = () => {
    setNotification(prev => ({ ...prev, open: false }));
  };

  const getStatusColor = (status) => {
    switch (status.toLowerCase()) {
      case 'active':
        return 'success';
      case 'inactive':
        return 'error';
      default:
        return 'default';
    }
  };

  return (
    <Box sx={{ p: 3, backgroundColor: '#f0f7ff', minHeight: '100vh' }}>
      <Card
        elevation={0}
        sx={{
          borderRadius: 4,
          background: 'linear-gradient(135deg, #ffffff 0%, #f8faff 100%)',
          boxShadow: '0 8px 32px rgba(0, 0, 0, 0.1)'
        }}
      >
        <CardContent>
          {/* Header */}
          <Stack
            direction={{ xs: 'column', sm: 'row' }}
            justifyContent="space-between"
            alignItems={{ xs: 'stretch', sm: 'center' }}
            spacing={2}
            mb={4}
          >
            <Typography variant="h5" sx={{ fontWeight: 600, color: '#1976d2' }}>
              Manage HODs
            </Typography>
            <Button
              variant="contained"
              onClick={handleAddNew}
              startIcon={<PersonAdd />}
              sx={{
                borderRadius: 2,
                px: 4,
                background: 'linear-gradient(45deg, #1976d2 30%, #42a5f5 90%)',
                boxShadow: '0 3px 5px 2px rgba(33, 150, 243, .3)',
                '&:hover': {
                  background: 'linear-gradient(45deg, #1565c0 30%, #1976d2 90%)',
                  transform: 'translateY(-1px)'
                }
              }}
            >
              Add New HOD
            </Button>
          </Stack>

          {/* Filters */}
          <Stack
            direction={{ xs: 'column', md: 'row' }}
            spacing={2}
            mb={4}
            alignItems="center"
          >
            <TextField
              placeholder="Search HODs..."
              value={searchQuery}
              onChange={handleSearchChange}
              variant="outlined"
              sx={{ minWidth: 240 }}
              InputProps={{
                startAdornment: (
                  <InputAdornment position="start">
                    <Search />
                  </InputAdornment>
                ),
                sx: { borderRadius: 2 }
              }}
            />

            <FormControl sx={{ minWidth: 120 }}>
              <InputLabel>Department</InputLabel>
              <Select
                value={departmentFilter}
                onChange={handleDepartmentFilterChange}
                label="Department"
                sx={{ borderRadius: 2 }}
              >
                <MenuItem value="all">All Departments</MenuItem>
                <MenuItem value="audiology">Audiology</MenuItem>
                <MenuItem value="speech-language pathology">Speech-Language Pathology</MenuItem>
                <MenuItem value="clinical psychology">Clinical Psychology</MenuItem>
                <MenuItem value="special education">Special Education</MenuItem>
              </Select>
            </FormControl>

            <FormControl sx={{ minWidth: 120 }}>
              <InputLabel>Status</InputLabel>
              <Select
                value={statusFilter}
                onChange={handleStatusFilterChange}
                label="Status"
                sx={{ borderRadius: 2 }}
              >
                <MenuItem value="all">All Status</MenuItem>
                <MenuItem value="active">Active</MenuItem>
                <MenuItem value="inactive">Inactive</MenuItem>
              </Select>
            </FormControl>

            <Button
              startIcon={<Refresh />}
              onClick={() => {
                setSearchQuery('');
                setDepartmentFilter('all');
                setStatusFilter('all');
              }}
              sx={{ borderRadius: 2 }}
            >
              Reset Filters
            </Button>
          </Stack>

          {/* Table */}
          <TableContainer component={Paper} sx={{ borderRadius: 2, boxShadow: 'none' }}>
            <Table>
              <TableHead>
                <TableRow sx={{ backgroundColor: '#f8faff' }}>
                  <TableCell>Employee ID</TableCell>
                  <TableCell>Name</TableCell>
                  <TableCell>Email</TableCell>
                  <TableCell>Department</TableCell>
                  <TableCell>Contact</TableCell>
                  <TableCell>Status</TableCell>
                  <TableCell>Last Login</TableCell>
                  <TableCell align="center">Actions</TableCell>
                </TableRow>
              </TableHead>
              <TableBody>
                {renderTableContent()}
              </TableBody>
            </Table>
            <TablePagination
              rowsPerPageOptions={[5, 10, 25]}
              component="div"
              count={filteredHODs.length}
              rowsPerPage={rowsPerPage}
              page={page}
              onPageChange={handleChangePage}
              onRowsPerPageChange={handleChangeRowsPerPage}
            />
          </TableContainer>
        </CardContent>
      </Card>

      {/* Action Menu */}
      <Menu
        anchorEl={anchorEl}
        open={Boolean(anchorEl)}
        onClose={handleMenuClose}
        PaperProps={{
          sx: { borderRadius: 2 }
        }}
      >
        <MenuItem onClick={handleEdit}>
          <Edit sx={{ mr: 1 }} fontSize="small" />
          Edit
        </MenuItem>
        <MenuItem onClick={handleViewEODs}>
          <Group sx={{ mr: 1 }} fontSize="small" />
          View EODs
        </MenuItem>
        <MenuItem onClick={handleDelete} sx={{ color: 'error.main' }}>
          <Delete sx={{ mr: 1 }} fontSize="small" />
          Delete
        </MenuItem>
      </Menu>

      {/* Delete Confirmation Dialog */}
      <Dialog
        open={deleteDialogOpen}
        onClose={() => setDeleteDialogOpen(false)}
        PaperProps={{
          sx: { borderRadius: 3 }
        }}
      >
        <DialogTitle>Confirm Delete</DialogTitle>
        <DialogContent>
          Are you sure you want to delete this HOD? This action cannot be undone.
        </DialogContent>
        <DialogActions sx={{ p: 2 }}>
          <Button
            onClick={() => setDeleteDialogOpen(false)}
            sx={{ borderRadius: 2 }}
          >
            Cancel
          </Button>
          <Button
            onClick={confirmDelete}
            variant="contained"
            color="error"
            sx={{ borderRadius: 2 }}
          >
            Delete
          </Button>
        </DialogActions>
      </Dialog>

      {/* EODs Dialog */}
      <Dialog
        open={eodDialogOpen}
        onClose={() => setEodDialogOpen(false)}
        maxWidth="md"
        fullWidth
        PaperProps={{
          sx: { borderRadius: 3 }
        }}
      >
        <DialogTitle>
          EODs under {selectedHOD?.name}
        </DialogTitle>
        <DialogContent>
          <Table>
            <TableHead>
              <TableRow sx={{ backgroundColor: '#f8faff' }}>
                <TableCell>EOD Name</TableCell>
                <TableCell>Status</TableCell>
                <TableCell align="center">Actions</TableCell>
              </TableRow>
            </TableHead>
            <TableBody>
              {selectedHOD?.eods.map((eod) => (
                <TableRow key={eod.id} hover>
                  <TableCell>{eod.name}</TableCell>
                  <TableCell>
                    <Chip
                      label={eod.status}
                      color={getStatusColor(eod.status)}
                      size="small"
                    />
                  </TableCell>
                  <TableCell align="center">
                    <IconButton size="small">
                      <Edit />
                    </IconButton>
                  </TableCell>
                </TableRow>
              ))}
            </TableBody>
          </Table>
        </DialogContent>
        <DialogActions sx={{ p: 2 }}>
          <Button
            onClick={() => setEodDialogOpen(false)}
            sx={{ borderRadius: 2 }}
          >
            Close
          </Button>
        </DialogActions>
      </Dialog>

      {/* Notification */}
      <Snackbar
        open={notification.open}
        autoHideDuration={6000}
        onClose={handleCloseNotification}
        anchorOrigin={{ vertical: 'top', horizontal: 'right' }}
      >
        <Alert
          onClose={handleCloseNotification}
          severity={notification.severity}
          variant="filled"
          sx={{ width: '100%', borderRadius: 2 }}
        >
          {notification.message}
        </Alert>
      </Snackbar>
    </Box>
  );
};

export default ManageHODPage;