// services/clinicalInchargeService.js
import axios from 'axios';

const API_URL = process.env.REACT_APP_API_URL || 'http://localhost:5000/api';

class ClinicalInchargeService {
  // Create new clinical incharge
  static async createClinicalIncharge(clinicalInchargeData) {
    try {
      const token = localStorage.getItem('token');

      console.log('Token being sent:', token);
    
      // You can also decode the token to verify its contents
      if (token) {
        const tokenParts = token.split('.');
        if (tokenParts.length === 3) {
          const payload = JSON.parse(atob(tokenParts[1]));
          console.log('Token payload:', payload);
        }
      }
      const response = await axios.post(
        `${API_URL}/device/clinical-incharge/create`,
        clinicalInchargeData,
        {
          headers: {
            'Content-Type': 'application/json',
            Authorization: `Bearer ${localStorage.getItem('token')}`
          }
        }
      );
      return response.data;
    } catch (error) {
      throw this.handleError(error);
    }
  }

  // Get all clinical incharges
  static async getAllClinicalIncharges() {
    try {
      const response = await axios.get(
        `${API_URL}/device/clinical-incharge/get-all`,
        {
          headers: {
            Authorization: `Bearer ${localStorage.getItem('token')}`
          }
        }
      );
      return response.data;
    } catch (error) {
      throw this.handleError(error);
    }
  }

  // Get clinical incharge by ID
  static async getClinicalInchargeById(id) {
    try {
      const response = await axios.get(
        `${API_URL}/clinical-incharge/${id}`,
        {
          headers: {
            Authorization: `Bearer ${localStorage.getItem('token')}`
          }
        }
      );
      return response.data;
    } catch (error) {
      throw this.handleError(error);
    }
  }

  // Update clinical incharge
  static async updateClinicalIncharge(id, updateData) {
    try {
      const response = await axios.put(
        `${API_URL}/clinical-incharge/${id}`,
        updateData,
        {
          headers: {
            'Content-Type': 'application/json',
            Authorization: `Bearer ${localStorage.getItem('token')}`
          }
        }
      );
      return response.data;
    } catch (error) {
      throw this.handleError(error);
    }
  }

  // Delete clinical incharge
  static async deleteClinicalIncharge(id) {
    try {
      const response = await axios.delete(
        `${API_URL}/clinical-incharge/${id}`,
        {
          headers: {
            Authorization: `Bearer ${localStorage.getItem('token')}`
          }
        }
      );
      return response.data;
    } catch (error) {
      throw this.handleError(error);
    }
  }

  // Update clinical incharge status
  static async updateStatus(id, status) {
    try {
      const response = await axios.patch(
        `${API_URL}/clinical-incharge/${id}/status`,
        { status },
        {
          headers: {
            'Content-Type': 'application/json',
            Authorization: `Bearer ${localStorage.getItem('token')}`
          }
        }
      );
      return response.data;
    } catch (error) {
      throw this.handleError(error);
    }
  }

  // Error handler
  static handleError(error) {
    if (error.response) {
      // Server responded with error
      const errorMessage = error.response.data.message || 'An error occurred';
      return new Error(errorMessage);
    } else if (error.request) {
      // Request made but no response
      return new Error('No response from server');
    } else {
      // Error in request setup
      return new Error('Error in making request');
    }
  }
}

export default ClinicalInchargeService;