import React, { useState, useEffect } from 'react';
import {
  Box,
  Table,
  TableBody,
  TableCell,
  TableContainer,
  TableHead,
  TableRow,
  Paper,
  TablePagination,
  IconButton,
  Chip,
  TextField,
  InputAdornment,
  Typography,
  Stack,
  Card,
  CardContent,
  Menu,
  MenuItem,
  FormControl,
  InputLabel,
  Select,
  Button,
  Dialog,
  DialogTitle,
  DialogContent,
  DialogActions,
  Alert,
  Snackbar,
  Tooltip,
  CircularProgress
} from '@mui/material';
import {
  Search,
  MoreVert,
  Edit,
  Delete,
  Refresh,
  FilterList,
  PersonAdd
} from '@mui/icons-material';
import { useNavigate } from 'react-router-dom';
import UserService from '../../../features/services/userService';

const UsersTable = () => {
  const navigate = useNavigate();
  const [users, setUsers] = useState([]);
  const [loading, setLoading] = useState(false);
  const [page, setPage] = useState(0);
  const [rowsPerPage, setRowsPerPage] = useState(10);
  const [searchQuery, setSearchQuery] = useState('');
  const [roleFilter, setRoleFilter] = useState('all');
  const [statusFilter, setStatusFilter] = useState('all');
  const [anchorEl, setAnchorEl] = useState(null);
  const [selectedUser, setSelectedUser] = useState(null);
  const [deleteDialogOpen, setDeleteDialogOpen] = useState(false);
  const [notification, setNotification] = useState({
    open: false,
    message: '',
    severity: 'success'
  });
  const [totalUsers, setTotalUsers] = useState(0);
  const [serverSidePagination, setServerSidePagination] = useState(false);

  // Normalize user data to handle API field name differences
  const normalizeUser = (user) => {
    if (!user) return null;
    
    return {
      ...user,
      _id: user._id,
      role: user.userType || user.role,
      status: user.isActive !== undefined ? (user.isActive ? 'active' : 'inactive') : user.status,
      employeeId: user.employeeId || user._id,
      department: user.designation || user.department || 'N/A',
      lastLogin: user.lastLogin || user.updatedAt
    };
  };

  // Updated fetchUsers function
  const fetchUsers = async () => {
    setLoading(true);
    try {
      let response;
      
      if (serverSidePagination) {
        // Server-side pagination and filtering
        response = await UserService.getAllUsers({
          search: searchQuery,
          role: roleFilter,
          status: statusFilter,
          page: page + 1, // API is 1-indexed
          limit: rowsPerPage
        });
        
        // Normalize and set users
        const normalizedUsers = (response.users || []).map(normalizeUser);
        setUsers(normalizedUsers);
        setTotalUsers(response.pagination?.total || 0);
      } else {
        // Client-side filtering
        response = await UserService.getAllUsers();
        
        // Handle different response formats and normalize
        const userData = Array.isArray(response) ? response : response.users || [];
        const normalizedUsers = userData.map(normalizeUser);
        setUsers(normalizedUsers);
        setTotalUsers(userData.length);
      }
      
      console.log('API Response:', response);
    } catch (error) {
      console.error('Error fetching users:', error);
      showNotification('Failed to fetch users', 'error');
      setUsers([]);
    } finally {
      setLoading(false);
    }
  };

  // Initial fetch when component mounts
  useEffect(() => {
    fetchUsers();
  }, [serverSidePagination]);

  // Fetch users when filters or pagination changes (if using server-side)
  useEffect(() => {
    if (serverSidePagination) {
      fetchUsers();
    }
  }, [page, rowsPerPage, searchQuery, roleFilter, statusFilter, serverSidePagination]);

  const handleChangePage = (event, newPage) => {
    setPage(newPage);
  };

  const handleChangeRowsPerPage = (event) => {
    setRowsPerPage(parseInt(event.target.value, 10));
    setPage(0);
  };

  const handleSearchChange = (event) => {
    setSearchQuery(event.target.value);
    if (!serverSidePagination) {
      setPage(0);
    }
  };

  const handleRoleFilterChange = (event) => {
    setRoleFilter(event.target.value);
    if (!serverSidePagination) {
      setPage(0);
    }
  };

  const handleStatusFilterChange = (event) => {
    setStatusFilter(event.target.value);
    if (!serverSidePagination) {
      setPage(0);
    }
  };

  const handleMenuClick = (event, user) => {
    setAnchorEl(event.currentTarget);
    setSelectedUser(user);
  };

  const handleMenuClose = () => {
    setAnchorEl(null);
    setSelectedUser(null);
  };

  const handleEdit = () => {
    handleMenuClose();
    if (selectedUser) {
      navigate(`/users/edit/${selectedUser._id}`);
    }
  };

  const handleDelete = () => {
    handleMenuClose();
    setDeleteDialogOpen(true);
  };

  const confirmDelete = async () => {
    if (!selectedUser) return;

    setLoading(true);
    try {
      await UserService.deleteUser(selectedUser._id);
      showNotification('User deleted successfully', 'success');
      setDeleteDialogOpen(false);
      fetchUsers(); // Refresh users list
    } catch (error) {
      console.error('Error deleting user:', error);
      showNotification(error.message || 'Failed to delete user', 'error');
    } finally {
      setLoading(false);
    }
  };

  const showNotification = (message, severity = 'success') => {
    setNotification({
      open: true,
      message,
      severity
    });
  };

  const handleCloseNotification = () => {
    setNotification(prev => ({ ...prev, open: false }));
  };

  const resetFilters = () => {
    setSearchQuery('');
    setRoleFilter('all');
    setStatusFilter('all');
    setPage(0);
  };

  // Filter users on client-side
  const filteredUsers = serverSidePagination ? users : users.filter(user => {
    if (!user) return false;
    
    const matchesSearch = !searchQuery || 
      user.name?.toLowerCase().includes(searchQuery.toLowerCase()) ||
      user.email?.toLowerCase().includes(searchQuery.toLowerCase()) ||
      (user.employeeId && user.employeeId.toString().toLowerCase().includes(searchQuery.toLowerCase()));
    
    const matchesRole = roleFilter === 'all' || user.role?.toLowerCase() === roleFilter.toLowerCase();
    const matchesStatus = statusFilter === 'all' || user.status?.toLowerCase() === statusFilter.toLowerCase();
    
    return matchesSearch && matchesRole && matchesStatus;
  });

  // Apply pagination on client-side
  const paginatedUsers = serverSidePagination 
    ? filteredUsers 
    : filteredUsers.slice(page * rowsPerPage, page * rowsPerPage + rowsPerPage);

  const getStatusColor = (status) => {
    if (!status) return 'default';
    
    switch (status.toLowerCase()) {
      case 'active':
        return 'success';
      case 'inactive':
        return 'error';
      default:
        return 'default';
    }
  };

  const getRoleColor = (role) => {
    if (!role) return '#757575';
    
    switch (role.toLowerCase()) {
      case 'super_admin':
        return '#025cb5';
      case 'hod':
        return '#2e7d32';
      case 'eod':
        return '#ed6c02';
      case 'clinical_incharge':
        return '#9c27b0';
      default:
        return '#757575';
    }
  };

  const formatRoleDisplay = (role) => {
    if (!role) return 'Unknown';
    
    // Convert from DB format to display format
    switch (role.toLowerCase()) {
      case 'super_admin':
        return 'Super Admin';
      case 'hod':
        return 'HOD';
      case 'eod':
        return 'EOD';
      case 'clinical_incharge':
        return 'Clinical Incharge';
      default:
        return role;
    }
  };

  const handleAddUser = () => {
    navigate('/users/create');
  };

  return (
    <Box sx={{ p: 3, backgroundColor: '#f0f7ff', minHeight: '100vh' }}>
      <Card
        elevation={0}
        sx={{
          borderRadius: 4,
          background: 'linear-gradient(135deg, #ffffff 0%, #f8faff 100%)',
          boxShadow: '0 8px 32px rgba(0, 0, 0, 0.1)'
        }}
      >
        <CardContent>
          {/* Header */}
          <Stack
            direction={{ xs: 'column', sm: 'row' }}
            justifyContent="space-between"
            alignItems={{ xs: 'stretch', sm: 'center' }}
            spacing={2}
            mb={4}
          >
            <Typography variant="h5" sx={{ fontWeight: 600, color: '#1976d2' }}>
              All Users
            </Typography>
           
          </Stack>

          {/* Filters */}
          <Stack
            direction={{ xs: 'column', md: 'row' }}
            spacing={2}
            mb={4}
            alignItems="center"
          >
            <TextField
              placeholder="Search users..."
              value={searchQuery}
              onChange={handleSearchChange}
              variant="outlined"
              sx={{ minWidth: 240 }}
              InputProps={{
                startAdornment: (
                  <InputAdornment position="start">
                    <Search />
                  </InputAdornment>
                ),
                sx: { borderRadius: 2 }
              }}
            />

            <FormControl sx={{ minWidth: 120 }}>
              <InputLabel>Role</InputLabel>
              <Select
                value={roleFilter}
                onChange={handleRoleFilterChange}
                label="Role"
                sx={{ borderRadius: 2 }}
              >
                <MenuItem value="all">All Roles</MenuItem>
                <MenuItem value="super_admin">Super Admin</MenuItem>
                <MenuItem value="hod">HOD</MenuItem>
                <MenuItem value="eod">EOD</MenuItem>
                <MenuItem value="clinical_incharge">Clinical Incharge</MenuItem>
              </Select>
            </FormControl>

            <FormControl sx={{ minWidth: 120 }}>
              <InputLabel>Status</InputLabel>
              <Select
                value={statusFilter}
                onChange={handleStatusFilterChange}
                label="Status"
                sx={{ borderRadius: 2 }}
              >
                <MenuItem value="all">All Status</MenuItem>
                <MenuItem value="active">Active</MenuItem>
                <MenuItem value="inactive">Inactive</MenuItem>
              </Select>
            </FormControl>

            <Button
              startIcon={<Refresh />}
              onClick={resetFilters}
              sx={{ borderRadius: 2 }}
            >
              Reset Filters
            </Button>
          </Stack>

          {/* Loading indicator */}
          {loading && (
            <Box display="flex" justifyContent="center" my={4}>
              <CircularProgress />
            </Box>
          )}

          {/* Table */}
          {!loading && (
            <TableContainer component={Paper} sx={{ borderRadius: 2, boxShadow: 'none' }}>
              <Table>
                <TableHead>
                  <TableRow sx={{ backgroundColor: '#f8faff' }}>
                    {/* <TableCell>ID</TableCell> */}
                    <TableCell>Name</TableCell>
                    <TableCell>Email</TableCell>
                    <TableCell>Role</TableCell>
                    {/* <TableCell>Department</TableCell> */}
                    <TableCell>Status</TableCell>
                    <TableCell>Last Activity</TableCell>
                    <TableCell align="center">Actions</TableCell>
                  </TableRow>
                </TableHead>
                <TableBody>
                  {paginatedUsers.length > 0 ? (
                    paginatedUsers.map((user) => (
                      <TableRow key={user._id} hover>
                        {/* <TableCell>{user.employeeId}</TableCell> */}
                        <TableCell>{user.name}</TableCell>
                        <TableCell>{user.email}</TableCell>
                        <TableCell>
                          <Chip
                            label={formatRoleDisplay(user.role)}
                            sx={{
                              backgroundColor: `${getRoleColor(user.role)}20`,
                              color: getRoleColor(user.role),
                              fontWeight: 500
                            }}
                          />
                        </TableCell>
                        {/* <TableCell>{user.department}</TableCell> */}
                        <TableCell>
                          <Chip
                            label={user.status || 'Unknown'}
                            color={getStatusColor(user.status)}
                            size="small"
                          />
                        </TableCell>
                        <TableCell>
                          {user.lastLogin ? new Date(user.lastLogin).toLocaleString() : 'Never'}
                        </TableCell>
                        <TableCell align="center">
                          <IconButton
                            size="small"
                            onClick={(event) => handleMenuClick(event, user)}
                          >
                            <MoreVert />
                          </IconButton>
                        </TableCell>
                      </TableRow>
                    ))
                  ) : (
                    <TableRow>
                      <TableCell colSpan={8} align="center" sx={{ py: 3 }}>
                        <Typography color="text.secondary">
                          No users found matching the criteria
                        </Typography>
                      </TableCell>
                    </TableRow>
                  )}
                </TableBody>
              </Table>
              <TablePagination
                rowsPerPageOptions={[5, 10, 25, 50]}
                component="div"
                count={serverSidePagination ? totalUsers : filteredUsers.length}
                rowsPerPage={rowsPerPage}
                page={page}
                onPageChange={handleChangePage}
                onRowsPerPageChange={handleChangeRowsPerPage}
              />
            </TableContainer>
          )}
        </CardContent>
      </Card>

      {/* Action Menu */}
      <Menu
        anchorEl={anchorEl}
        open={Boolean(anchorEl)}
        onClose={handleMenuClose}
        PaperProps={{
          sx: { borderRadius: 2 }
        }}
      >
        <MenuItem onClick={handleEdit}>
          <Edit sx={{ mr: 1 }} fontSize="small" />
          Edit
        </MenuItem>
        <MenuItem onClick={handleDelete} sx={{ color: 'error.main' }}>
          <Delete sx={{ mr: 1 }} fontSize="small" />
          Delete
        </MenuItem>
      </Menu>

      {/* Delete Confirmation Dialog */}
      <Dialog
        open={deleteDialogOpen}
        onClose={() => setDeleteDialogOpen(false)}
        PaperProps={{
          sx: { borderRadius: 3 }
        }}
      >
        <DialogTitle>Confirm Delete</DialogTitle>
        <DialogContent>
          <Typography>
            Are you sure you want to delete user "{selectedUser?.name}"? This action cannot be undone.
          </Typography>
        </DialogContent>
        <DialogActions sx={{ p: 2 }}>
          <Button 
            onClick={() => setDeleteDialogOpen(false)}
            disabled={loading}
            sx={{ borderRadius: 2 }}
          >
            Cancel
          </Button>
          <Button
            onClick={confirmDelete}
            variant="contained"
            color="error"
            disabled={loading}
            startIcon={loading ? <CircularProgress size={20} /> : null}
            sx={{ borderRadius: 2 }}
          >
            {loading ? 'Deleting...' : 'Delete'}
          </Button>
        </DialogActions>
      </Dialog>

      {/* Notification */}
      <Snackbar
        open={notification.open}
        autoHideDuration={6000}
        onClose={handleCloseNotification}
        anchorOrigin={{ vertical: 'top', horizontal: 'right' }}
      >
        <Alert
          onClose={handleCloseNotification}
          severity={notification.severity}
          variant="filled"
          sx={{ width: '100%', borderRadius: 2 }}
        >
          {notification.message}
        </Alert>
      </Snackbar>
    </Box>
  );
};

export default UsersTable;