import React, { useState, useEffect } from 'react';
import {
  Box,
  Table,
  TableBody,
  TableCell,
  TableContainer,
  TableHead,
  TableRow,
  Paper,
  TablePagination,
  IconButton,
  Chip,
  TextField,
  InputAdornment,
  Typography,
  Stack,
  Card,
  CardContent,
  Menu,
  MenuItem,
  FormControl,
  InputLabel,
  Select,
  Button,
  Dialog,
  DialogTitle,
  DialogContent,
  DialogActions,
  Alert,
  Snackbar,
  Tooltip,
  CircularProgress
} from '@mui/material';
import {
  Search,
  MoreVert,
  Edit,
  Delete,
  Refresh,
  FilterList,
  PersonAdd
} from '@mui/icons-material';
import { useNavigate } from 'react-router-dom';
import eodService from '../../../features/services/eodService';

const ManageEODPage = () => {
  const navigate = useNavigate();
  const [page, setPage] = useState(0);
  const [rowsPerPage, setRowsPerPage] = useState(10);
  const [searchQuery, setSearchQuery] = useState('');
  const [departmentFilter, setDepartmentFilter] = useState('all');
  const [statusFilter, setStatusFilter] = useState('all');
  const [anchorEl, setAnchorEl] = useState(null);
  const [selectedEOD, setSelectedEOD] = useState(null);
  const [deleteDialogOpen, setDeleteDialogOpen] = useState(false);
  const [eods, setEODs] = useState([]);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState(null);
  const [notification, setNotification] = useState({
    open: false,
    message: '',
    severity: 'success'
  });

  useEffect(() => {
    fetchEODs();
  }, []);

  const fetchEODs = async () => {
    try {
      setLoading(true);
      const response = await eodService.getAllEODAdmins();
      setEODs(response.data || []);
    } catch (error) {
      console.error('Error fetching EODs:', error);
      showNotification('Failed to fetch EODs', 'error');
      setError(error.message || 'Failed to fetch EODs');
    } finally {
      setLoading(false);
    }
  };

  const handleChangePage = (event, newPage) => {
    setPage(newPage);
  };

  const handleChangeRowsPerPage = (event) => {
    setRowsPerPage(parseInt(event.target.value, 10));
    setPage(0);
  };

  const handleSearchChange = (event) => {
    setSearchQuery(event.target.value);
    setPage(0);
  };

  const handleDepartmentFilterChange = (event) => {
    setDepartmentFilter(event.target.value);
    setPage(0);
  };

  const handleStatusFilterChange = (event) => {
    setStatusFilter(event.target.value);
    setPage(0);
  };

  const handleMenuClick = (event, eod) => {
    setAnchorEl(event.currentTarget);
    setSelectedEOD(eod);
  };

  const handleMenuClose = () => {
    setAnchorEl(null);
    setSelectedEOD(null);
  };

  const handleEdit = () => {
    handleMenuClose();
    if (selectedEOD) {
      navigate(`/device-portal/edit-eod/${selectedEOD._id}`);
    }
  };

  const handleDelete = () => {
    handleMenuClose();
    setDeleteDialogOpen(true);
  };

  const handleStatusToggle = async (eodId, currentStatus) => {
    try {
      const newStatus = currentStatus === 'active' ? 'inactive' : 'active';
      await eodService.updateEODStatus(eodId, newStatus);
      showNotification('Status updated successfully', 'success');
      fetchEODs();
    } catch (error) {
      console.error('Error updating status:', error);
      showNotification(error.response?.data?.message || 'Failed to update status', 'error');
    }
  };

  const confirmDelete = async () => {
    try {
      setLoading(true);
      await eodService.deleteEOD(selectedEOD._id);
      showNotification('EOD deleted successfully', 'success');
      setDeleteDialogOpen(false);
      fetchEODs();
    } catch (error) {
      console.error('Error deleting EOD:', error);
      showNotification(error.response?.data?.message || 'Failed to delete EOD', 'error');
    } finally {
      setLoading(false);
      setSelectedEOD(null);
    }
  };

  const showNotification = (message, severity) => {
    setNotification({
      open: true,
      message,
      severity
    });
  };

  const handleCloseNotification = () => {
    setNotification(prev => ({ ...prev, open: false }));
  };

  const filteredEODs = eods.filter(eod => {
    const fullName = `${eod.firstName} ${eod.lastName}`.toLowerCase();
    const matchesSearch = 
      fullName.includes(searchQuery.toLowerCase()) ||
      eod.email.toLowerCase().includes(searchQuery.toLowerCase()) ||
      eod.employeeId.toLowerCase().includes(searchQuery.toLowerCase());
    
    const matchesDepartment = departmentFilter === 'all' || 
      eod.department.toLowerCase() === departmentFilter.toLowerCase();
    const matchesStatus = statusFilter === 'all' || 
      eod.status.toLowerCase() === statusFilter.toLowerCase();
    
    return matchesSearch && matchesDepartment && matchesStatus;
  });

  const getStatusColor = (status) => {
    switch (status.toLowerCase()) {
      case 'active':
        return 'success';
      case 'inactive':
        return 'error';
      default:
        return 'default';
    }
  };

  const renderTableContent = () => {
    if (loading) {
      return (
        <TableRow>
          <TableCell colSpan={8} align="center" sx={{ py: 3 }}>
            <CircularProgress size={40} />
          </TableCell>
        </TableRow>
      );
    }

    if (error) {
      return (
        <TableRow>
          <TableCell colSpan={8} align="center" sx={{ py: 3 }}>
            <Alert 
              severity="error"
              action={
                <Button color="inherit" size="small" onClick={fetchEODs}>
                  Retry
                </Button>
              }
            >
              {error}
            </Alert>
          </TableCell>
        </TableRow>
      );
    }

    if (filteredEODs.length === 0) {
      return (
        <TableRow>
          <TableCell colSpan={8} align="center" sx={{ py: 3 }}>
            <Typography variant="body1" color="textSecondary">
              No EODs found
            </Typography>
          </TableCell>
        </TableRow>
      );
    }

    return filteredEODs
      .slice(page * rowsPerPage, page * rowsPerPage + rowsPerPage)
      .map((eod) => (
        <TableRow key={eod._id} hover>
          <TableCell>{eod.employeeId}</TableCell>
          <TableCell>{`${eod.firstName} ${eod.lastName}`}</TableCell>
          <TableCell>{eod.email}</TableCell>
          <TableCell>{eod.phone}</TableCell>
          <TableCell>
            <Chip
              label={eod.status}
              color={getStatusColor(eod.status)}
              size="small"
              onClick={() => handleStatusToggle(eod._id, eod.status)}
            />
          </TableCell>
          <TableCell>
            {eod.lastLogin ? new Date(eod.lastLogin).toLocaleString() : 'Never'}
          </TableCell>
          <TableCell align="center">
            <IconButton
              size="small"
              onClick={(event) => handleMenuClick(event, eod)}
            >
              <MoreVert />
            </IconButton>
          </TableCell>
        </TableRow>
      ));
  };

  return (
    <Box sx={{ p: 3, backgroundColor: '#f0f7ff', minHeight: '100vh' }}>
      <Card
        elevation={0}
        sx={{
          borderRadius: 4,
          background: 'linear-gradient(135deg, #ffffff 0%, #f8faff 100%)',
          boxShadow: '0 8px 32px rgba(0, 0, 0, 0.1)'
        }}
      >
        <CardContent>
          {/* Header */}
          <Stack
            direction={{ xs: 'column', sm: 'row' }}
            justifyContent="space-between"
            alignItems={{ xs: 'stretch', sm: 'center' }}
            spacing={2}
            mb={4}
          >
            <Typography variant="h5" sx={{ fontWeight: 600, color: '#1976d2' }}>
              Manage EODs
            </Typography>
            <Button
              variant="contained"
              onClick={() => navigate('/device-portal/create-eod')}
              startIcon={<PersonAdd />}
              sx={{ 
                borderRadius: 2,
                px: 4,
                background: 'linear-gradient(45deg, #1976d2 30%, #42a5f5 90%)',
                boxShadow: '0 3px 5px 2px rgba(33, 150, 243, .3)',
                '&:hover': {
                  background: 'linear-gradient(45deg, #1565c0 30%, #1976d2 90%)',
                  transform: 'translateY(-1px)'
                }
              }}
            >
              Add New EOD
            </Button>
          </Stack>

          {/* Filters */}
          <Stack
            direction={{ xs: 'column', md: 'row' }}
            spacing={2}
            mb={4}
            alignItems="center"
          >
            <TextField
              placeholder="Search EODs..."
              value={searchQuery}
              onChange={handleSearchChange}
              variant="outlined"
              sx={{ minWidth: 240 }}
              InputProps={{
                startAdornment: (
                  <InputAdornment position="start">
                    <Search />
                  </InputAdornment>
                ),
                sx: { borderRadius: 2 }
              }}
            />


            <FormControl sx={{ minWidth: 120 }}>
              <InputLabel>Status</InputLabel>
              <Select
                value={statusFilter}
                onChange={handleStatusFilterChange}
                label="Status"
                sx={{ borderRadius: 2 }}
              >
                <MenuItem value="all">All Status</MenuItem>
                <MenuItem value="active">Active</MenuItem>
                <MenuItem value="inactive">Inactive</MenuItem>
              </Select>
            </FormControl>

            <Button
              startIcon={<Refresh />}
              onClick={() => {
                setSearchQuery('');
                setDepartmentFilter('all');
                setStatusFilter('all');
              }}
              sx={{ borderRadius: 2 }}
            >
              Reset Filters
            </Button>
          </Stack>

          {/* Table */}
          <TableContainer component={Paper} sx={{ borderRadius: 2, boxShadow: 'none' }}>
            <Table>
              <TableHead>
                <TableRow sx={{ backgroundColor: '#f8faff' }}>
                  <TableCell>Employee ID</TableCell>
                  <TableCell>Name</TableCell>
                  <TableCell>Email</TableCell>
                  <TableCell>Contact</TableCell>
                  <TableCell>Status</TableCell>
                  <TableCell>Last Login</TableCell>
                  <TableCell align="center">Actions</TableCell>
                </TableRow>
              </TableHead>
              <TableBody>
                {renderTableContent()}
              </TableBody>
            </Table>
            <TablePagination
              rowsPerPageOptions={[5, 10, 25]}
              component="div"
              count={filteredEODs.length}
              rowsPerPage={rowsPerPage}
              page={page}
              onPageChange={handleChangePage}
              onRowsPerPageChange={handleChangeRowsPerPage}
            />
          </TableContainer>
        </CardContent>
      </Card>

      {/* Action Menu */}
      <Menu
        anchorEl={anchorEl}
        open={Boolean(anchorEl)}
        onClose={handleMenuClose}
        PaperProps={{
          sx: { borderRadius: 2 }
        }}
      >
        <MenuItem onClick={handleEdit}>
          <Edit sx={{ mr: 1 }} fontSize="small" />
          Edit
        </MenuItem>
        <MenuItem onClick={handleDelete} sx={{ color: 'error.main' }}>
          <Delete sx={{ mr: 1 }} fontSize="small" />
          Delete
        </MenuItem>
      </Menu>

      {/* Delete Confirmation Dialog */}
      <Dialog
        open={deleteDialogOpen}
        onClose={() => setDeleteDialogOpen(false)}
        PaperProps={{
          sx: { borderRadius: 3 }
        }}
      >
        <DialogTitle>Confirm Delete</DialogTitle>
        <DialogContent>
          <Typography>
            Are you sure you want to delete this EOD? This action cannot be undone.
          </Typography>
          <Box sx={{ 
            mt: 2,
            p: 2,
            bgcolor: 'background.default',
            borderRadius: 1
          }}>
            <Typography variant="body2" gutterBottom>
              <strong>Name:</strong> {selectedEOD?.firstName} {selectedEOD?.lastName}
            </Typography>
            <Typography variant="body2" gutterBottom>
              <strong>Employee ID:</strong> {selectedEOD?.employeeId}
            </Typography>
            <Typography variant="body2">
              <strong>Department:</strong> {selectedEOD?.department}
            </Typography>
          </Box>
        </DialogContent>
        <DialogActions sx={{ p: 2 }}>
          <Button 
            onClick={() => setDeleteDialogOpen(false)}
            sx={{ borderRadius: 2 }}
          >
            Cancel
          </Button>
          <Button
            onClick={confirmDelete}
            variant="contained"
            color="error"
            sx={{ borderRadius: 2 }}
          >
            Delete
          </Button>
        </DialogActions>
      </Dialog>

      {/* Notification */}
      <Snackbar
        open={notification.open}
        autoHideDuration={6000}
        onClose={handleCloseNotification}
        anchorOrigin={{ vertical: 'top', horizontal: 'right' }}
      >
        <Alert
          onClose={handleCloseNotification}
          severity={notification.severity}
          variant="filled"
          sx={{ 
            width: '100%',
            borderRadius: 2 
          }}
        >
          {notification.message}
        </Alert>
      </Snackbar>
    </Box>
  );
};

export default ManageEODPage;