// AccessControl.js - A utility for managing permissions
import React from 'react';

// Role hierarchy (from lowest to highest access) with lowercase keys
const ROLE_HIERARCHY = {
  'clinical_incharge': 1,
  'eod': 2,
  'hod': 3,
  'super_admin': 4
};

/**
 * Normalizes role string to lowercase for consistent comparison
 * @param {string} role - The role to normalize
 * @returns {string} - Normalized lowercase role
 */
const normalizeRole = (role) => {
  return typeof role === 'string' ? role.toLowerCase() : '';
};

/**
 * Checks if the user has access based on their role
 * @param {string} userRole - The role of the current user
 * @param {string|string[]} requiredRole - The role(s) required for access
 * @returns {boolean} - Whether the user has access
 */
export const hasAccess = (userRole, requiredRole) => {
  if (!userRole || !requiredRole) return false;
  
  // Normalize user role to lowercase
  const normalizedUserRole = normalizeRole(userRole);
  
  // Convert to array if single role is provided
  const requiredRoles = Array.isArray(requiredRole) ? requiredRole : [requiredRole];
  
  // Get the user's role level
  const userRoleLevel = ROLE_HIERARCHY[normalizedUserRole] || 0;
  
  // Check if user's role level is sufficient for any of the required roles
  return requiredRoles.some(role => {
    const normalizedRequiredRole = normalizeRole(role);
    const requiredLevel = ROLE_HIERARCHY[normalizedRequiredRole] || 0;
    return userRoleLevel >= requiredLevel;
  });
};

/**
 * Get user's role from localStorage
 * @returns {string|null} - The user's role or null if not found
 */
export const getUserRole = () => {
  try {
    const userData = localStorage.getItem('userData');
    if (!userData) return null;
    
    const parsedData = JSON.parse(userData);
    return parsedData?.device?.userType || null;
  } catch (error) {
    console.error('Error retrieving user role:', error);
    return null;
  }
};

/**
 * Get full user data from localStorage
 * @returns {Object|null} - The user data or null if not found
 */
export const getUserData = () => {
  try {
    const userData = localStorage.getItem('userData');
    if (!userData) return null;
    
    return JSON.parse(userData);
  } catch (error) {
    console.error('Error retrieving user data:', error);
    return null;
  }
};

/**
 * Check if the user is authenticated
 * @returns {boolean} - Whether the user is authenticated
 */
export const isAuthenticated = () => {
  try {
    const token = localStorage.getItem('token');
    const userData = localStorage.getItem('userData');
    return !!token && !!userData;
  } catch (error) {
    console.error('Error checking authentication:', error);
    return false;
  }
};

/**
 * Higher-order component for route protection
 * @param {React.Component} Component - The component to protect
 * @param {string|string[]} requiredRoles - The role(s) required to access the component
 * @returns {React.Component} - Protected component
 */
export const withAccessControl = (Component, requiredRoles) => {
  return (props) => {
    const userRole = getUserRole();
    
    if (!hasAccess(userRole, requiredRoles)) {
      // Replace with your access denied component
      return <AccessDenied />;
    }
    
    return <Component {...props} />;
  };
};

/**
 * Custom hook for checking permissions
 * @param {string|string[]} requiredRoles - The role(s) required
 * @returns {boolean} - Whether the user has permission
 */
export const usePermission = (requiredRoles) => {
  const userRole = getUserRole();
  return hasAccess(userRole, requiredRoles);
};

/**
 * Function to handle logout
 * @param {Function} navigateFunction - React Router's navigate function
 */
export const logout = (navigateFunction) => {
  localStorage.removeItem('token');
  localStorage.removeItem('userData');
  localStorage.removeItem('todayInspections'); // Clear any other app-specific data
  
  if (navigateFunction) {
    navigateFunction('/login');
  } else {
    window.location.href = '/login';
  }
};

// Simple access denied component
const AccessDenied = () => (
  <div style={{ 
    padding: '2rem', 
    textAlign: 'center',
    color: '#d32f2f',
    display: 'flex',
    flexDirection: 'column',
    alignItems: 'center',
    justifyContent: 'center',
    height: '70vh'
  }}>
    <h2>Access Denied</h2>
    <p>You don't have permission to access this resource.</p>
    <button 
      onClick={() => window.history.back()}
      style={{
        padding: '0.5rem 1rem',
        backgroundColor: '#f5f5f5',
        border: '1px solid #ccc',
        borderRadius: '4px',
        cursor: 'pointer',
        marginTop: '1rem'
      }}
    >
      Go Back
    </button>
  </div>
);

// Export an object with all functions for easier imports
export default {
  hasAccess,
  getUserRole,
  getUserData,
  isAuthenticated,
  withAccessControl,
  usePermission,
  logout,
  ROLE_HIERARCHY
};