import React, { useState } from 'react';
import {
  Box,
  Grid,
  Card,
  CardContent,
  Typography,
  Button,
  Tab,
  Tabs,
  Paper,
  Stack,
  Chip,
  LinearProgress,
  IconButton,
  Avatar,
  Divider,
  Table,
  TableBody,
  TableCell,
  TableContainer,
  TableHead,
  TableRow
} from '@mui/material';
import {
  Inventory as DeviceIcon,
  Assignment as InspectionIcon,
  Warning as AlertIcon,
  Business as SupplierIcon,
  Add as AddIcon,
  Schedule as ScheduleIcon,
  Report as ReportIcon,
  CheckCircle as CheckIcon,
  Error as ErrorIcon,
  ArrowUpward as TrendUpIcon,
  AccessTime as TimeIcon
} from '@mui/icons-material';

const EODAdminDashboard = () => {
  const [activeTab, setActiveTab] = useState(0);

  // Summary data (to be fetched from API)
  const summaryData = {
    totalDevices: 120,
    activeDevices: 98,
    pendingInspections: 5,
    criticalAlerts: 2,
    activeSuppliers: 15,
    deviceUtilization: 87,
    maintenanceRate: 92,
    inspectionCompliance: 95
  };

  // Recent activities data
  const recentActivities = [
    {
      type: 'inspection',
      device: 'MRI Scanner',
      action: 'Inspection Completed',
      time: '2 hours ago',
      status: 'success'
    },
    {
      type: 'alert',
      device: 'CT Scanner',
      action: 'Maintenance Required',
      time: '4 hours ago',
      status: 'warning'
    },
    {
      type: 'issue',
      device: 'X-Ray Machine',
      action: 'Critical Issue Reported',
      time: '1 day ago',
      status: 'error'
    }
  ];

  // Upcoming inspections data
  const upcomingInspections = [
    {
      device: 'Ultrasound Machine',
      department: 'Cardiology',
      date: '2024-02-15',
      priority: 'high'
    },
    {
      device: 'Ventilator',
      department: 'ICU',
      date: '2024-02-16',
      priority: 'medium'
    }
  ];

  const statsCards = [
    {
      title: 'Device Status',
      mainStat: `${summaryData.activeDevices}/${summaryData.totalDevices}`,
      subStat: 'Devices Active',
      trend: '+5% from last month',
      icon: <DeviceIcon />,
      color: '#1976d2',
      backgroundColor: '#e3f2fd'
    },
    {
      title: 'Pending Inspections',
      mainStat: summaryData.pendingInspections,
      subStat: 'Need Attention',
      trend: '-2 from last week',
      icon: <InspectionIcon />,
      color: '#ed6c02',
      backgroundColor: '#fff3e0'
    },
    {
      title: 'Critical Alerts',
      mainStat: summaryData.criticalAlerts,
      subStat: 'Immediate Action Required',
      trend: 'No change',
      icon: <AlertIcon />,
      color: '#d32f2f',
      backgroundColor: '#ffebee'
    },
    {
      title: 'Active Suppliers',
      mainStat: summaryData.activeSuppliers,
      subStat: 'Currently Engaged',
      trend: '+2 new this month',
      icon: <SupplierIcon />,
      color: '#2e7d32',
      backgroundColor: '#e8f5e9'
    }
  ];

  const handleTabChange = (event, newValue) => {
    setActiveTab(newValue);
  };

  const getStatusColor = (status) => {
    switch (status) {
      case 'success': return '#2e7d32';
      case 'warning': return '#ed6c02';
      case 'error': return '#d32f2f';
      default: return '#1976d2';
    }
  };

  const getStatusIcon = (status) => {
    switch (status) {
      case 'success': return <CheckIcon />;
      case 'warning': return <ErrorIcon color="warning" />;
      case 'error': return <ErrorIcon color="error" />;
      default: return <TimeIcon />;
    }
  };

  const getPriorityColor = (priority) => {
    switch (priority) {
      case 'high': return '#d32f2f';
      case 'medium': return '#ed6c02';
      case 'low': return '#2e7d32';
      default: return '#1976d2';
    }
  };

  return (
    <Box sx={{ 
      p: 3, 
      backgroundColor: '#f8faff',
      minHeight: '100vh'
    }}>
      {/* Quick Actions */}
      <Paper 
        elevation={0}
        sx={{ 
          p: 2, 
          mb: 3, 
          borderRadius: 3,
          backgroundColor: 'white',
          border: '1px solid #e0e0e0'
        }}
      >
        <Stack 
          direction={{ xs: 'column', sm: 'row' }} 
          spacing={2}
          alignItems={{ xs: 'stretch', sm: 'center' }}
        >
          <Button 
            variant="contained" 
            startIcon={<AddIcon />}
            sx={{ 
              borderRadius: 2,
              backgroundColor: '#1976d2',
              '&:hover': { backgroundColor: '#1565c0' }
            }}
          >
            Add New Device
          </Button>
          <Button 
            variant="contained" 
            startIcon={<ScheduleIcon />}
            sx={{ 
              borderRadius: 2,
              backgroundColor: '#7b1fa2',
              '&:hover': { backgroundColor: '#6a1b9a' }
            }}
          >
            Schedule Inspection
          </Button>
          <Button 
            variant="outlined" 
            startIcon={<ReportIcon />}
            color="warning"
            sx={{ borderRadius: 2 }}
          >
            Report Issue
          </Button>
        </Stack>
      </Paper>

      {/* Stats Cards */}
      <Grid container spacing={3} sx={{ mb: 3 }}>
        {statsCards.map((card, index) => (
          <Grid item xs={12} sm={6} md={3} key={index}>
            <Card 
              elevation={0}
              sx={{ 
                borderRadius: 3,
                border: '1px solid #e0e0e0'
              }}
            >
              <CardContent>
                <Box sx={{ display: 'flex', justifyContent: 'space-between', mb: 2 }}>
                  <Avatar 
                    sx={{ 
                      bgcolor: card.backgroundColor,
                      color: card.color
                    }}
                  >
                    {card.icon}
                  </Avatar>
                  <Box>
                    <Typography variant="body2" color="textSecondary">
                      {card.title}
                    </Typography>
                    <Typography variant="h4" sx={{ color: card.color, fontWeight: 600 }}>
                      {card.mainStat}
                    </Typography>
                  </Box>
                </Box>
                <Stack 
                  direction="row" 
                  justifyContent="space-between" 
                  alignItems="center"
                >
                  <Typography color="textSecondary" variant="body2">
                    {card.subStat}
                  </Typography>
                  <Chip
                    icon={<TrendUpIcon sx={{ fontSize: 16 }} />}
                    label={card.trend}
                    size="small"
                    sx={{ 
                      backgroundColor: card.backgroundColor,
                      color: card.color,
                      '& .MuiChip-icon': { color: card.color }
                    }}
                  />
                </Stack>
              </CardContent>
            </Card>
          </Grid>
        ))}
      </Grid>

      {/* Main Content Area */}
      <Paper 
        elevation={0}
        sx={{ 
          width: '100%', 
          mb: 3, 
          borderRadius: 3,
          border: '1px solid #e0e0e0'
        }}
      >
        <Tabs
          value={activeTab}
          onChange={handleTabChange}
          sx={{
            borderBottom: '1px solid #e0e0e0',
            '& .MuiTab-root': {
              minHeight: 64,
              fontSize: '0.875rem'
            }
          }}
        >
          <Tab label="Overview" />
          <Tab label="Devices" />
          <Tab label="Inspections" />
          <Tab label="Issues" />
          <Tab label="Reports" />
        </Tabs>

        <Box sx={{ p: 3 }}>
          {activeTab === 0 && (
            <Grid container spacing={3}>
              {/* Performance Metrics */}
              <Grid item xs={12}>
                <Card 
                  elevation={0}
                  sx={{ 
                    borderRadius: 3,
                    border: '1px solid #e0e0e0',
                    mb: 3
                  }}
                >
                  <CardContent>
                    <Typography variant="h6" gutterBottom>
                      Performance Metrics
                    </Typography>
                    <Grid container spacing={3}>
                      {[
                        { label: 'Device Utilization', value: summaryData.deviceUtilization },
                        { label: 'Maintenance Rate', value: summaryData.maintenanceRate },
                        { label: 'Inspection Compliance', value: summaryData.inspectionCompliance }
                      ].map((metric, index) => (
                        <Grid item xs={12} md={4} key={index}>
                          <Box sx={{ mb: 1 }}>
                            <Typography variant="body2" color="textSecondary">
                              {metric.label}
                            </Typography>
                            <Box sx={{ display: 'flex', alignItems: 'center', mt: 1 }}>
                              <Box sx={{ flex: 1, mr: 1 }}>
                                <LinearProgress 
                                  variant="determinate" 
                                  value={metric.value} 
                                  sx={{ 
                                    height: 8, 
                                    borderRadius: 4,
                                    backgroundColor: '#e0e0e0',
                                    '& .MuiLinearProgress-bar': {
                                      backgroundColor: metric.value >= 90 ? '#2e7d32' : '#1976d2'
                                    }
                                  }}
                                />
                              </Box>
                              <Typography variant="body2" color="textSecondary">
                                {metric.value}%
                              </Typography>
                            </Box>
                          </Box>
                        </Grid>
                      ))}
                    </Grid>
                  </CardContent>
                </Card>
              </Grid>

              {/* Recent Activity */}
              <Grid item xs={12} md={6}>
                <Card 
                  elevation={0}
                  sx={{ 
                    borderRadius: 3,
                    border: '1px solid #e0e0e0',
                    height: '100%'
                  }}
                >
                  <CardContent>
                    <Typography variant="h6" gutterBottom>
                      Recent Activity
                    </Typography>
                    <Stack spacing={2}>
                      {recentActivities.map((activity, index) => (
                        <Box key={index}>
                          <Stack 
                            direction="row" 
                            spacing={2} 
                            alignItems="center"
                          >
                            <Avatar 
                              sx={{ 
                                bgcolor: `${getStatusColor(activity.status)}15`,
                                color: getStatusColor(activity.status)
                              }}
                            >
                              {getStatusIcon(activity.status)}
                            </Avatar>
                            <Box sx={{ flex: 1 }}>
                              <Typography variant="subtitle2">
                                {activity.device}
                              </Typography>
                              <Typography variant="body2" color="textSecondary">
                                {activity.action}
                              </Typography>
                              <Typography variant="caption" color="textSecondary">
                                {activity.time}
                              </Typography>
                            </Box>
                          </Stack>
                          {index < recentActivities.length - 1 && (
                            <Divider sx={{ my: 2 }} />
                          )}
                        </Box>
                      ))}
                    </Stack>
                  </CardContent>
                </Card>
              </Grid>

              {/* Upcoming Inspections */}
              <Grid item xs={12} md={6}>
                <Card 
                  elevation={0}
                  sx={{ 
                    borderRadius: 3,
                    border: '1px solid #e0e0e0',
                    height: '100%'
                  }}
                >
                  <CardContent>
                    <Typography variant="h6" gutterBottom>
                      Upcoming Inspections
                    </Typography>
                    <TableContainer>
                      <Table>
                        <TableHead>
                          <TableRow>
                            <TableCell>Device</TableCell>
                            <TableCell>Department</TableCell>
                            <TableCell>Date</TableCell>
                            <TableCell>Priority</TableCell>
                          </TableRow>
                        </TableHead>
                        <TableBody>
                          {upcomingInspections.map((inspection, index) => (
                            <TableRow key={index}>
                              <TableCell>{inspection.device}</TableCell>
                              <TableCell>{inspection.department}</TableCell>
                              <TableCell>{inspection.date}</TableCell>
                              <TableCell>
                                <Chip
                                  label={inspection.priority}
                                  size="small"
                                  sx={{ 
                                    backgroundColor: `${getPriorityColor(inspection.priority)}15`,
                                    color: getPriorityColor(inspection.priority),
                                    fontWeight: 500
                                  }}
                                />
                              </TableCell>
                            </TableRow>
                          ))}
                        </TableBody>
                      </Table>
                    </TableContainer>
                  </CardContent>
                </Card>
              </Grid>
            </Grid>
          )}
        </Box>
      </Paper>
    </Box>
  );
};

export default EODAdminDashboard;