import React, { useState, useEffect } from 'react';
import {
    Box,
    Card,
    CardContent,
    TextField,
    Button,
    Typography,
    Stack,
    Grid,
    IconButton,
    FormControl,
    InputLabel,
    Select,
    MenuItem,
    Divider,
    Dialog,
    DialogTitle,
    DialogContent,
    DialogActions,
    Alert,
    Snackbar,
    CircularProgress
} from '@mui/material';
import {
    ArrowBack,
    Upload,
    Save,
    ReportProblem,
    DeleteOutline
} from '@mui/icons-material';
import { useNavigate } from 'react-router-dom';
import issueService from '../../../features/services/issueService'; // Your provided service
import deviceService from '../../../features/services/deviceService'; // Assuming this exists based on your pattern

const IssueReportingForm = () => {
    const navigate = useNavigate();

    // Form State
    const [issueData, setIssueData] = useState({
        device: '',
        accessory: '',
        title: '',
        description: '',
        priority: 'medium',
        images: []
    });

    // Additional state
    const [devices, setDevices] = useState([]);
    const [accessories, setAccessories] = useState([]);
    const [openDialog, setOpenDialog] = useState(false);
    const [notification, setNotification] = useState({
        open: false,
        message: '',
        severity: 'success'
    });
    const [loading, setLoading] = useState(false);

    // Fetch devices on component mount
    useEffect(() => {
        const fetchDevices = async () => {
            try {
                const response = await deviceService.getAllDevices();
                setDevices(response.data); // Assuming response.data is an array of devices
            } catch (error) {
                showNotification('Failed to load devices', 'error');
            }
        };
        fetchDevices();
    }, []);

    // Fetch accessories when device is selected
    useEffect(() => {
        if (issueData.device) {
            const selectedDevice = devices.find(d => d._id === issueData.device);
            setAccessories(selectedDevice?.accessories || []);
            setIssueData(prev => ({ ...prev, accessory: '' })); // Reset accessory when device changes
        } else {
            setAccessories([]);
        }
    }, [issueData.device, devices]);

    // Handle Input Changes
    const handleChange = (event) => {
        const { name, value } = event.target;
        setIssueData(prev => ({
            ...prev,
            [name]: value
        }));
    };

    // Handle Image Upload
    const handleImageChange = (event) => {
        const files = Array.from(event.target.files);
        setIssueData(prev => ({
            ...prev,
            images: [...prev.images, ...files]
        }));
    };

    // Remove Image
    const removeImage = (index) => {
        setIssueData(prev => ({
            ...prev,
            images: prev.images.filter((_, i) => i !== index)
        }));
    };

    // Form Submission
    const handleSubmit = (e) => {
        e.preventDefault();
        setOpenDialog(true);
    };

    const handleConfirmSubmit = async () => {
        setLoading(true);
        try {
            const formData = new FormData();
            
            // Append issue data
            formData.append('device', issueData.device);
            if (issueData.accessory) formData.append('accessory', issueData.accessory);
            formData.append('title', issueData.title);
            formData.append('description', issueData.description);
            formData.append('priority', issueData.priority);
            
            // Append images
            issueData.images.forEach((image) => {
                formData.append('images', image); // Matches your backend upload middleware
            });

            // API call using your issueService
            const response = await issueService.createIssue(formData);

            setOpenDialog(false);
            showNotification('Issue reported successfully!', 'success');
            // setTimeout(() => navigate('/clinical-incharge/dashboard'), 2000); // Adjust path as needed
        } catch (error) {
            console.error('Error reporting issue:', error);
            setOpenDialog(false);
            showNotification(error.response?.data?.message || 'Failed to report issue', 'error');
        } finally {
            setLoading(false);
        }
    };

    const showNotification = (message, severity) => {
        setNotification({
            open: true,
            message,
            severity
        });
    };

    return (
        <Box sx={{ p: 3, backgroundColor: '#f0f7ff', minHeight: '100vh' }}>
            <Card
                elevation={0}
                sx={{
                    borderRadius: 4,
                    background: 'linear-gradient(135deg, #ffffff 0%, #f8faff 100%)',
                    boxShadow: '0 8px 32px rgba(0, 0, 0, 0.1)'
                }}
            >
                <CardContent sx={{ p: 4 }}>
                    {/* Header */}
                    <Stack direction="row" alignItems="center" spacing={2} mb={4}>
                        <IconButton
                            onClick={() => navigate(-1)}
                            sx={{
                                backgroundColor: '#e3f2fd',
                                '&:hover': { backgroundColor: '#bbdefb' }
                            }}
                        >
                            <ArrowBack />
                        </IconButton>
                        <Stack direction="column">
                            <Typography variant="h5" sx={{ fontWeight: 600, color: '#1976d2' }}>
                                Report New Issue
                            </Typography>
                            <Typography variant="body2" color="textSecondary">
                                Submit an issue for a device or accessory
                            </Typography>
                        </Stack>
                    </Stack>

                    <Divider sx={{ mb: 4 }} />

                    <form onSubmit={handleSubmit}>
                        {/* Issue Information Section */}
                        <Stack direction="row" alignItems="center" spacing={1} mb={3}>
                            <ReportProblem color="primary" />
                            <Typography variant="h6" color="primary">
                                Issue Details
                            </Typography>
                        </Stack>

                        <Grid container spacing={3} mb={4}>
                            <Grid item xs={12} sm={6}>
                                <FormControl fullWidth required>
                                    <InputLabel>Device</InputLabel>
                                    <Select
                                        name="device"
                                        value={issueData.device}
                                        onChange={handleChange}
                                        label="Device"
                                        sx={{ borderRadius: 2 }}
                                    >
                                        <MenuItem value="">Select a device</MenuItem>
                                        {devices.map(device => (
                                            <MenuItem key={device._id} value={device._id}>
                                                {device.deviceName} (SN: {device.serialNumber})
                                            </MenuItem>
                                        ))}
                                    </Select>
                                </FormControl>
                            </Grid>
                            <Grid item xs={12} sm={6}>
                                <FormControl fullWidth>
                                    <InputLabel>Accessory (Optional)</InputLabel>
                                    <Select
                                        name="accessory"
                                        value={issueData.accessory}
                                        onChange={handleChange}
                                        label="Accessory (Optional)"
                                        sx={{ borderRadius: 2 }}
                                        disabled={!issueData.device}
                                    >
                                        <MenuItem value="">None</MenuItem>
                                        {accessories.map(acc => (
                                            <MenuItem key={acc._id} value={acc._id}>
                                                {acc.itemName}
                                            </MenuItem>
                                        ))}
                                    </Select>
                                </FormControl>
                            </Grid>
                            <Grid item xs={12}>
                                <TextField
                                    fullWidth
                                    label="Issue Title"
                                    name="title"
                                    value={issueData.title}
                                    onChange={handleChange}
                                    required
                                    InputProps={{ sx: { borderRadius: 2 } }}
                                />
                            </Grid>
                            <Grid item xs={12}>
                                <TextField
                                    fullWidth
                                    label="Description"
                                    name="description"
                                    value={issueData.description}
                                    onChange={handleChange}
                                    required
                                    multiline
                                    rows={4}
                                    InputProps={{ sx: { borderRadius: 2 } }}
                                />
                            </Grid>
                            <Grid item xs={12} sm={6}>
                                <FormControl fullWidth>
                                    <InputLabel>Priority</InputLabel>
                                    <Select
                                        name="priority"
                                        value={issueData.priority}
                                        onChange={handleChange}
                                        label="Priority"
                                        sx={{ borderRadius: 2 }}
                                    >
                                        <MenuItem value="low">Low</MenuItem>
                                        <MenuItem value="medium">Medium</MenuItem>
                                        <MenuItem value="high">High</MenuItem>
                                        <MenuItem value="critical">Critical</MenuItem>
                                    </Select>
                                </FormControl>
                            </Grid>
                            <Grid item xs={12}>
                                {/* <Button
                                    component="label"
                                    variant="outlined"
                                    startIcon={<Upload />}
                                    sx={{ borderRadius: 2 }}
                                >
                                    Upload Images
                                    <input
                                        type="file"
                                        hidden
                                        accept="image/*"
                                        multiple
                                        onChange={handleImageChange}
                                    />
                                </Button> */}
                                {issueData.images.length > 0 && (
                                    <Stack spacing={1} mt={2}>
                                        {issueData.images.map((image, index) => (
                                            <Stack key={index} direction="row" alignItems="center" spacing={2}>
                                                <Typography variant="body2" color="success.main">
                                                    {image.name}
                                                </Typography>
                                                <IconButton
                                                    color="error"
                                                    onClick={() => removeImage(index)}
                                                >
                                                    <DeleteOutline />
                                                </IconButton>
                                            </Stack>
                                        ))}
                                    </Stack>
                                )}
                            </Grid>
                        </Grid>

                        {/* Form Actions */}
                        <Stack direction="row" spacing={2} justifyContent="flex-end">
                            <Button
                                variant="outlined"
                                onClick={() => navigate(-1)}
                                sx={{ borderRadius: 2, px: 4 }}
                            >
                                Cancel
                            </Button>
                            <Button
                                type="submit"
                                variant="contained"
                                startIcon={<Save />}
                                sx={{
                                    borderRadius: 2,
                                    px: 4,
                                    backgroundColor: '#1976d2',
                                    '&:hover': {
                                        backgroundColor: '#1565c0',
                                        boxShadow: '0 4px 12px rgba(25, 118, 210, 0.3)',
                                    }
                                }}
                                disabled={!issueData.device || !issueData.title || !issueData.description}
                            >
                                Report Issue
                            </Button>
                        </Stack>
                    </form>
                </CardContent>
            </Card>

            {/* Confirmation Dialog */}
            <Dialog
                open={openDialog}
                onClose={() => !loading && setOpenDialog(false)}
                PaperProps={{ sx: { borderRadius: 3 } }}
            >
                <DialogTitle>Confirm Issue Report</DialogTitle>
                <DialogContent>
                    {loading ? (
                        <Box sx={{ display: 'flex', justifyContent: 'center', alignItems: 'center', py: 3 }}>
                            <CircularProgress />
                        </Box>
                    ) : (
                        <>
                            <Typography gutterBottom>
                                Please review the issue details before confirming:
                            </Typography>
                            <Box sx={{ mt: 2 }}>
                                <Typography variant="body2" gutterBottom>
                                    <strong>Device:</strong> {devices.find(d => d._id === issueData.device)?.deviceName}
                                </Typography>
                                {issueData.accessory && (
                                    <Typography variant="body2" gutterBottom>
                                        <strong>Accessory:</strong> {accessories.find(a => a._id === issueData.accessory)?.itemName}
                                    </Typography>
                                )}
                                <Typography variant="body2" gutterBottom>
                                    <strong>Title:</strong> {issueData.title}
                                </Typography>
                                <Typography variant="body2" gutterBottom>
                                    <strong>Priority:</strong> {issueData.priority}
                                </Typography>
                                <Typography variant="body2" gutterBottom>
                                    <strong>Images:</strong> {issueData.images.length}
                                </Typography>
                            </Box>
                        </>
                    )}
                </DialogContent>
                <DialogActions sx={{ p: 2 }}>
                    <Button
                        onClick={() => setOpenDialog(false)}
                        sx={{ borderRadius: 2 }}
                        disabled={loading}
                    >
                        Cancel
                    </Button>
                    <Button
                        onClick={handleConfirmSubmit}
                        variant="contained"
                        sx={{ borderRadius: 2 }}
                        disabled={loading}
                    >
                        {loading ? 'Processing...' : 'Confirm & Submit'}
                    </Button>
                </DialogActions>
            </Dialog>

            {/* Notification */}
            <Snackbar
                open={notification.open}
                autoHideDuration={6000}
                onClose={() => setNotification(prev => ({ ...prev, open: false }))}
                anchorOrigin={{ vertical: 'top', horizontal: 'right' }}
            >
                <Alert
                    onClose={() => setNotification(prev => ({ ...prev, open: false }))}
                    severity={notification.severity}
                    variant="filled"
                    sx={{ width: '100%', borderRadius: 2 }}
                >
                    {notification.message}
                </Alert>
            </Snackbar>
        </Box>
    );
};

export default IssueReportingForm;