import React, { useState, useEffect } from 'react';
import {
    Box,
    Card,
    CardContent,
    Typography,
    Stack,
    Grid,
    Button,
    IconButton,
    FormControl,
    InputLabel,
    Select,
    MenuItem,
    TextField,
    Table,
    TableBody,
    TableCell,
    TableContainer,
    TableHead,
    TableRow,
    Chip,
    Paper,
    CircularProgress,
    Pagination,
    Divider,
    Snackbar,
    Alert
} from '@mui/material';
import {
    ArrowBack,
    FilterList,
    Visibility,
    Refresh
} from '@mui/icons-material';
import { useNavigate } from 'react-router-dom';
import issueService from '../../../features/services/issueService';

const ViewIssuesPage = () => {
    const navigate = useNavigate();

    // State management
    const [issues, setIssues] = useState([]);
    const [loading, setLoading] = useState(false);
    const [pagination, setPagination] = useState({ page: 1, pages: 1, total: 0 });

    // Separate filter state from actual API query
    const [filterValues, setFilterValues] = useState({
        deviceId: '',
        status: '',
        priority: '',
        search: ''
    });

    // This will be the actual query sent to the API
    const [activeQuery, setActiveQuery] = useState({
        page: 1,
        limit: 10
    });

    const [notification, setNotification] = useState({
        open: false,
        message: '',
        severity: 'success'
    });

    // Effect to check authentication on component mount
    useEffect(() => {
        const token = localStorage.getItem('token');
        if (!token) {
            navigate('/login');
            showNotification('Please log in to view issues', 'error');
        }
    }, [navigate]);

    // Effect to fetch issues when activeQuery changes
    useEffect(() => {
        if (localStorage.getItem('token')) {
            fetchIssues();
        }
    }, [activeQuery]);

    const fetchIssues = async () => {
        setLoading(true);
        try {
            console.log('Fetching issues with query:', activeQuery);
            const response = await issueService.getAllIssues(activeQuery);

            if (!response || !response.data) {
                throw new Error('Invalid response from server');
            }

            const issuesData = Array.isArray(response.data) ? response.data : [];
            console.log('Received issues data:', issuesData);

            setIssues(issuesData);

            // Handle pagination data safely
            const paginationData = response.data.pagination || {};
            setPagination({
                page: paginationData.page || 1,
                pages: paginationData.pages || 1,
                total: paginationData.total || 0
            });
        } catch (error) {
            console.error('Error fetching issues:', error);
            setIssues([]);
            setPagination({ page: 1, pages: 1, total: 0 });
            showNotification(
                error.response?.data?.message || 'Failed to load issues',
                'error'
            );
        } finally {
            setLoading(false);
        }
    };

    // Handle user input in filter fields (but don't apply filters yet)
    const handleFilterChange = (event) => {
        const { name, value } = event.target;
        console.log(`Filter field changed: ${name} = ${value}`);

        setFilterValues(prev => ({
            ...prev,
            [name]: value
        }));
    };

    // Apply filters only when the button is clicked
    const applyFilters = () => {
        console.log('Applying filters:', filterValues);

        // Build a clean query object
        const newQuery = {
            page: 1, // Reset to page 1 when applying new filters
            limit: 10
        };

        // Only add non-empty filter values
        Object.entries(filterValues).forEach(([key, value]) => {
            if (value && String(value).trim() !== '') {
                newQuery[key] = value;
            }
        });

        console.log('Setting new active query:', newQuery);
        setActiveQuery(newQuery);
    };

    // Reset filters to initial state
    const resetFilters = () => {
        const emptyFilters = {
            deviceId: '',
            status: '',
            priority: '',
            search: ''
        };

        console.log('Resetting filters to:', emptyFilters);
        setFilterValues(emptyFilters);

        // Also reset active query to initial state
        const initialQuery = {
            page: 1,
            limit: 10
        };

        console.log('Resetting active query to:', initialQuery);
        setActiveQuery(initialQuery);
    };

    // Handle page change
    const handlePageChange = (event, value) => {
        console.log(`Changing page to ${value}`);

        // Update the active query with the new page
        setActiveQuery(prev => ({
            ...prev,
            page: value
        }));
    };

    const showNotification = (message, severity) => {
        setNotification({
            open: true,
            message,
            severity
        });
    };

    const viewIssueDetails = (issueId) => {
        navigate(`/clinical-incharge/issues/${issueId}`);
    };

    return (
        <Box sx={{ p: 3, backgroundColor: '#f0f7ff', minHeight: '100vh' }}>
            <Card
                elevation={0}
                sx={{
                    borderRadius: 4,
                    background: 'linear-gradient(135deg, #ffffff 0%, #f8faff 100%)',
                    boxShadow: '0 8px 32px rgba(0, 0, 0, 0.1)'
                }}
            >
                <CardContent sx={{ p: 4 }}>
                    <Stack direction="row" alignItems="center" spacing={2} mb={4}>
                        <IconButton
                            onClick={() => navigate(-1)}
                            sx={{ backgroundColor: '#e3f2fd', '&:hover': { backgroundColor: '#bbdefb' } }}
                        >
                            <ArrowBack />
                        </IconButton>
                        <Stack direction="column">
                            <Typography variant="h5" sx={{ fontWeight: 600, color: '#1976d2' }}>
                                View Issues
                            </Typography>
                            <Typography variant="body2" color="textSecondary">
                                List of all reported issues with filtering options
                            </Typography>
                        </Stack>
                    </Stack>

                    <Divider sx={{ mb: 4 }} />

                    <Stack direction="row" spacing={2} mb={4} alignItems="center">
                        <FilterList color="primary" />
                        <Typography variant="h6" color="primary">Filters</Typography>
                    </Stack>
                    <Grid container spacing={3} mb={4}>
                        <Grid item xs={12} sm={3}>
                            <TextField
                                fullWidth
                                label="Search by Title/Description"
                                name="search"
                                value={filterValues.search}
                                onChange={handleFilterChange}
                                InputProps={{ sx: { borderRadius: 2 } }}
                            />
                        </Grid>
                        <Grid item xs={12} sm={3}>
                            <FormControl fullWidth>
                                <InputLabel>Status</InputLabel>
                                <Select
                                    name="status"
                                    value={filterValues.status}
                                    onChange={handleFilterChange}
                                    label="Status"
                                    sx={{ borderRadius: 2 }}
                                >
                                    <MenuItem value="">All</MenuItem>
                                    <MenuItem value="open">Open</MenuItem>
                                    <MenuItem value="inprogress">In Progress</MenuItem>
                                    <MenuItem value="resolved">Resolved</MenuItem>
                                    <MenuItem value="closed">Closed</MenuItem>
                                    <MenuItem value="pending_company_inspection">Pending Company Inspection</MenuItem>
                                </Select>
                            </FormControl>
                        </Grid>
                        <Grid item xs={12} sm={3}>
                            <FormControl fullWidth>
                                <InputLabel>Priority</InputLabel>
                                <Select
                                    name="priority"
                                    value={filterValues.priority}
                                    onChange={handleFilterChange}
                                    label="Priority"
                                    sx={{ borderRadius: 2 }}
                                >
                                    <MenuItem value="">All</MenuItem>
                                    <MenuItem value="low">Low</MenuItem>
                                    <MenuItem value="medium">Medium</MenuItem>
                                    <MenuItem value="high">High</MenuItem>
                                    <MenuItem value="critical">Critical</MenuItem>
                                </Select>
                            </FormControl>
                        </Grid>
                        <Grid item xs={12} sm={3}>
                            <Stack direction="row" spacing={2}>
                                <Button
                                    variant="outlined"
                                    startIcon={<Refresh />}
                                    onClick={resetFilters}
                                    sx={{ borderRadius: 2 }}
                                >
                                    Reset
                                </Button>
                                <Button
                                    variant="contained"
                                    onClick={applyFilters}
                                    sx={{ borderRadius: 2, backgroundColor: '#1976d2', '&:hover': { backgroundColor: '#1565c0' } }}
                                >
                                    Apply Filters
                                </Button>
                            </Stack>
                        </Grid>
                    </Grid>

                    {loading ? (
                        <Box sx={{ display: 'flex', justifyContent: 'center', py: 4 }}>
                            <CircularProgress />
                        </Box>
                    ) : (
                        <>
                            <TableContainer component={Paper} sx={{ borderRadius: 2, mb: 4 }}>
                                <Table>
                                    <TableHead>
                                        <TableRow sx={{ backgroundColor: '#e3f2fd' }}>
                                            <TableCell><Typography fontWeight={600} sx={{ fontSize: '14px' }}>Title</Typography></TableCell>
                                            <TableCell><Typography fontWeight={600} sx={{ fontSize: '14px' }}>Device</Typography></TableCell>
                                            <TableCell><Typography fontWeight={600} sx={{ fontSize: '14px' }}>Accessory</Typography></TableCell>
                                            <TableCell><Typography fontWeight={600} sx={{ fontSize: '14px' }}>Status</Typography></TableCell>
                                            <TableCell><Typography fontWeight={600} sx={{ fontSize: '14px' }}>Priority</Typography></TableCell>
                                            <TableCell><Typography fontWeight={600} sx={{ fontSize: '14px' }}>Reported By</Typography></TableCell>
                                            <TableCell><Typography fontWeight={600} sx={{ fontSize: '14px' }}>Created At</Typography></TableCell>
                                            <TableCell><Typography fontWeight={600} sx={{ fontSize: '14px' }}>Actions</Typography></TableCell>
                                        </TableRow>
                                    </TableHead>
                                    <TableBody>
                                        {issues.length === 0 ? (
                                            <TableRow>
                                                <TableCell colSpan={8} align="center">
                                                    <Typography>No issues found</Typography>
                                                </TableCell>
                                            </TableRow>
                                        ) : (
                                            issues.map(issue => (
                                                <TableRow key={issue._id} hover>
                                                    <TableCell sx={{ fontWeight: '600' }}>{issue.title}</TableCell>
                                                    <TableCell>
                                                        {issue.device?.deviceName}
                                                        {issue.device?.serialNumber && ` (SN: ${issue.device.serialNumber})`}
                                                    </TableCell>
                                                    <TableCell>{issue.accessory?.itemName || '-'}</TableCell>
                                                    <TableCell>
                                                        <Chip
                                                            label={issue.status}
                                                            sx={{
                                                                textTransform: 'capitalize',
                                                                backgroundColor: issue.status === 'open' ? '#ff0000' :
                                                                    issue.status === 'resolved' ? '#008000' :
                                                                        issue.status === 'inprogress' ? '#ff8000' :
                                                                            issue.status === 'closed' ? '#808080' :
                                                                                issue.status === 'pending_company_inspection' ? '#ff4500' : // Orange-red for pending company inspection
                                                                                    'inherit',
                                                                color: '#ffffff',
                                                                fontWeight: 600,
                                                                border: 'none',
                                                                boxShadow: 'none',
                                                                textDecoration: 'none',
                                                            }}
                                                            size="small"
                                                        />
                                                    </TableCell>
                                                    <TableCell>
                                                        <Chip
                                                            label={issue.priority}
                                                            sx={{
                                                                textTransform: 'capitalize',
                                                                backgroundColor: issue.priority === 'low' ? '#e8f5e9' :
                                                                    issue.priority === 'medium' ? '#fff3e0' :
                                                                        issue.priority === 'high' ? '#ffebee' :
                                                                            issue.priority === 'critical' ? '#ffcdd2' :
                                                                                'inherit',
                                                                color: issue.priority === 'low' ? 'success.main' :
                                                                    issue.priority === 'medium' ? 'warning.main' :
                                                                        issue.priority === 'high' ? 'error.main' :
                                                                            issue.priority === 'critical' ? '#d32f2f' :
                                                                                'text.primary',
                                                                fontWeight: 600,
                                                                border: 'none',
                                                                boxShadow: 'none',
                                                                textDecoration: 'none',
                                                            }}
                                                            size="small"
                                                        />
                                                    </TableCell>
                                                    <TableCell>{issue.reportedBy?.name || '-'}</TableCell>
                                                    <TableCell>
                                                        {new Date(issue.createdAt).toLocaleDateString()}
                                                    </TableCell>
                                                    <TableCell>
                                                        <IconButton
                                                            color="primary"
                                                            onClick={() => viewIssueDetails(issue._id)}
                                                        >
                                                            <Visibility />
                                                        </IconButton>
                                                    </TableCell>
                                                </TableRow>
                                            ))
                                        )}
                                    </TableBody>
                                </Table>
                            </TableContainer>

                            {pagination.pages > 1 && (
                                <Stack direction="row" justifyContent="center">
                                    <Pagination
                                        count={pagination.pages}
                                        page={pagination.page}
                                        onChange={handlePageChange}
                                        color="primary"
                                        sx={{ mb: 2 }}
                                    />
                                </Stack>
                            )}
                        </>
                    )}
                </CardContent>
            </Card>

            <Snackbar
                open={notification.open}
                autoHideDuration={6000}
                onClose={() => setNotification(prev => ({ ...prev, open: false }))}
                anchorOrigin={{ vertical: 'top', horizontal: 'right' }}
            >
                <Alert
                    onClose={() => setNotification(prev => ({ ...prev, open: false }))}
                    severity={notification.severity}
                    variant="filled"
                    sx={{ width: '100%', borderRadius: 2 }}
                >
                    {notification.message}
                </Alert>
            </Snackbar>
        </Box>
    );
};

export default ViewIssuesPage;