import { createSlice, createAsyncThunk } from '@reduxjs/toolkit';
import api from '../../api/axios';
import { jwtDecode } from 'jwt-decode';

export const login = createAsyncThunk(
  'auth/login',
  async ({ email, password }, { rejectWithValue }) => {
    try {
      console.log("Login request initiated", { email });

      const response = await api.post('/device/users/login', { email, password });

      console.log("API response received", response.data);

      if (response.data.success === false) {
        console.error("Login failed on API response", response.data.message);
        throw new Error(response.data.message);
      }

      const { token, types, userData } = response.data.data;

      console.log("Token and types received", { token, types });
      
      if (!token) {
        console.error("Token not received in response");
        throw new Error('Token not received');
      }

      // Store auth data in localStorage
      localStorage.setItem('token', token);
      localStorage.setItem('userData', JSON.stringify(userData));
      localStorage.setItem('availableTypes', JSON.stringify(types));

      // Set type based on available access
      if (types.length === 1) {
        localStorage.setItem('type', types[0]);
      } else if (types.includes('device-inspection') && types.includes('file-tracking')) {
        localStorage.setItem('type', 'device-inspection'); // Default to device when logging in through device portal
      }

      return { token, types, userData };
    } catch (error) {
      const errorMessage = error.response?.data?.message || error.message || 'Login failed';
      console.error("Login request error", errorMessage);
      return rejectWithValue(errorMessage);
    }
  }
);

export const logout = createAsyncThunk('auth/logout', async (_, { dispatch }) => {
  try {
    localStorage.clear();
    window.location.href = '/login';
  } catch (error) {
    console.error('Logout error:', error);
  }
});

const initialState = {
  token: localStorage.getItem('token'),
  user: null,
  userData: JSON.parse(localStorage.getItem('userData') || '{}'),
  type: localStorage.getItem('type'),
  availableTypes: JSON.parse(localStorage.getItem('availableTypes') || '[]'),
  loading: false,
  error: null
};

// Try to decode the token if it exists
try {
  if (initialState.token) {
    initialState.user = jwtDecode(initialState.token);
  }
} catch {
  localStorage.removeItem('token');
  initialState.token = null;
}

const authSlice = createSlice({
  name: 'auth',
  initialState,
  reducers: {
    clearError: (state) => {
      state.error = null;
    },
    switchType: (state, action) => {
      const newType = action.payload;
      if (state.availableTypes.includes(newType)) {
        state.type = newType;
        localStorage.setItem('type', newType);
      }
    }
  },
  extraReducers: (builder) => {
    builder
      .addCase(login.pending, (state) => {
        state.loading = true;
        state.error = null;
      })
      .addCase(login.fulfilled, (state, action) => {
        state.loading = false;
        state.token = action.payload.token;
        state.userData = action.payload.userData;
        state.type = localStorage.getItem('type');
        state.availableTypes = action.payload.types || [];
        try {
          state.user = jwtDecode(action.payload.token);
        } catch (error) {
          state.user = null;
          state.error = 'Invalid token received';
        }
      })
      .addCase(login.rejected, (state, action) => {
        state.loading = false;
        state.error = action.payload;
        state.token = null;
        state.user = null;
        state.userData = {};
        state.type = null;
        state.availableTypes = [];
      })
      .addCase(logout.fulfilled, (state) => {
        state.token = null;
        state.user = null;
        state.userData = {};
        state.type = null;
        state.availableTypes = [];
        state.error = null;
      });
  }
});

export const { clearError, switchType } = authSlice.actions;
export default authSlice.reducer;