import React, { useState, useEffect } from 'react';
import {
  Box,
  Card,
  CardContent,
  Table,
  TableBody,
  TableCell,
  TableContainer,
  TableHead,
  TableRow,
  TablePagination,
  Paper,
  IconButton,
  TextField,
  InputAdornment,
  Typography,
  Stack,
  Chip,
  Button,
  Menu,
  MenuItem,
  FormControl,
  InputLabel,
  Select,
  Dialog,
  DialogTitle,
  DialogContent,
  DialogActions,
  Alert,
  Snackbar,
  Tooltip,
  Divider,
  CircularProgress
} from '@mui/material';
import {
  Search,
  FilterList,
  MoreVert,
  Edit,
  Delete,
  Visibility,
  Add,
  Refresh,
  Build,
  CheckCircle,
  Warning
} from '@mui/icons-material';
import { useNavigate } from 'react-router-dom';
import deviceService from '../../../features/services/deviceService';

const ManageDevicesTable = () => {
  const navigate = useNavigate();
  
  // State management
  const [devices, setDevices] = useState([]);
  const [loading, setLoading] = useState(true);
  const [page, setPage] = useState(0);
  const [rowsPerPage, setRowsPerPage] = useState(10);
  const [totalDevices, setTotalDevices] = useState(0);
  const [searchQuery, setSearchQuery] = useState('');
  const [statusFilter, setStatusFilter] = useState('all');
  const [amcFilter, setAMCFilter] = useState('all');
  const [anchorEl, setAnchorEl] = useState(null);
  const [selectedDevice, setSelectedDevice] = useState(null);
  const [deleteDialogOpen, setDeleteDialogOpen] = useState(false);
  const [notification, setNotification] = useState({
    open: false,
    message: '',
    severity: 'success'
  });

  // Fetch devices data with pagination, search, and filters
  const fetchDevices = async (pageNum = page, rowsPerPageNum = rowsPerPage) => {
    setLoading(true);
    try {
      // Prepare query parameters for API
      const params = {
        page: pageNum + 1, // API typically uses 1-indexed pagination
        limit: rowsPerPageNum
      };

      // Add search and filters
      if (searchQuery) {
        params.search = searchQuery;
      }
      if (statusFilter !== 'all') {
        params.status = statusFilter;
      }
      if (amcFilter !== 'all') {
        params.hasAMC = amcFilter === 'yes';
      }

      // Fetch devices from API
      const response = await deviceService.getAllDevices(params);
      
      setDevices(response.data);
      setTotalDevices(response.pagination.total);
    } catch (error) {
      console.error('Error fetching devices:', error);
      showNotification('Failed to fetch devices', 'error');
      setDevices([]);
    } finally {
      setLoading(false);
    }
  };

  // Initial fetch
  useEffect(() => {
    fetchDevices();
  }, []);

  // Refetch when page or filters change
  useEffect(() => {
    fetchDevices(page, rowsPerPage);
  }, [page, rowsPerPage, searchQuery, statusFilter, amcFilter]);

  // Handle table pagination
  const handleChangePage = (event, newPage) => {
    setPage(newPage);
  };

  const handleChangeRowsPerPage = (event) => {
    setRowsPerPage(parseInt(event.target.value, 10));
    setPage(0);
  };

  // Handle search and filters with debounce
  const handleSearchChange = (event) => {
    setSearchQuery(event.target.value);
    setPage(0);
  };

  const handleStatusFilterChange = (event) => {
    setStatusFilter(event.target.value);
    setPage(0);
  };

  const handleAMCFilterChange = (event) => {
    setAMCFilter(event.target.value);
    setPage(0);
  };

  const resetFilters = () => {
    setSearchQuery('');
    setStatusFilter('all');
    setAMCFilter('all');
    setPage(0);
  };

  // Handle device actions
  const handleMenuClick = (event, device) => {
    setAnchorEl(event.currentTarget);
    setSelectedDevice(device);
  };

  const handleMenuClose = () => {
    setAnchorEl(null);
  };

  const handleEdit = () => {
    handleMenuClose();
    if (selectedDevice) {
      navigate(`/devices/edit/${selectedDevice._id}`);
    }
  };

  const handleView = () => {
    handleMenuClose();
    if (selectedDevice) {
      navigate(`/devices/view/${selectedDevice._id}`);
    }
  };

  const handleDelete = () => {
    handleMenuClose();
    setDeleteDialogOpen(true);
  };

  const confirmDelete = async () => {
    try {
      setLoading(true);
      await deviceService.deleteDevice(selectedDevice._id);
      showNotification('Device deleted successfully', 'success');
      setDeleteDialogOpen(false);
      // Refresh devices list
      fetchDevices();
    } catch (error) {
      console.error('Error deleting device:', error);
      showNotification('Failed to delete device: ' + (error.response?.data?.message || error.message), 'error');
    } finally {
      setLoading(false);
    }
  };

  const showNotification = (message, severity) => {
    setNotification({
      open: true,
      message,
      severity
    });
  };

  // Helper function to get status color
  const getStatusColor = (status) => {
    switch (status.toLowerCase()) {
      case 'active':
        return 'success';
      case 'inactive':
        return 'error';
      case 'maintenance':
        return 'warning';
      default:
        return 'default';
    }
  };

  // Calculate days until next calibration
  const getDaysUntilCalibration = (dateString) => {
    if (!dateString) return -999; // Handle missing dates
    
    const today = new Date();
    const calibrationDate = new Date(dateString);
    const diffTime = calibrationDate - today;
    const diffDays = Math.ceil(diffTime / (1000 * 60 * 60 * 24));
    return diffDays;
  };

  return (
    <Box sx={{ p: 3, backgroundColor: '#f0f7ff', minHeight: '100vh' }}>
      <Card
        elevation={0}
        sx={{
          borderRadius: 4,
          background: 'linear-gradient(135deg, #ffffff 0%, #f8faff 100%)',
          boxShadow: '0 8px 32px rgba(0, 0, 0, 0.1)'
        }}
      >
        <CardContent>
          {/* Header */}
          <Stack
            direction={{ xs: 'column', sm: 'row' }}
            justifyContent="space-between"
            alignItems={{ xs: 'stretch', sm: 'center' }}
            spacing={2}
            mb={4}
          >
            <Typography variant="h5" sx={{ fontWeight: 600, color: '#1976d2' }}>
              All Devices
            </Typography>
            <Button
              variant="contained"
              startIcon={<Add />}
              onClick={() => navigate('/devices/add')}
              sx={{
                borderRadius: 2,
                px: 3,
                backgroundColor: '#1976d2',
                '&:hover': {
                  backgroundColor: '#1565c0',
                  boxShadow: '0 4px 12px rgba(25, 118, 210, 0.3)',
                }
              }}
            >
              Add New Device
            </Button>
          </Stack>

          {/* Filters */}
          <Stack
            direction={{ xs: 'column', md: 'row' }}
            spacing={2}
            mb={4}
            alignItems="center"
          >
            <TextField
              placeholder="Search devices..."
              value={searchQuery}
              onChange={handleSearchChange}
              variant="outlined"
              sx={{ minWidth: 240 }}
              InputProps={{
                startAdornment: (
                  <InputAdornment position="start">
                    <Search />
                  </InputAdornment>
                ),
                sx: { borderRadius: 2 }
              }}
            />

            <FormControl sx={{ minWidth: 120 }}>
              <InputLabel>Status</InputLabel>
              <Select
                value={statusFilter}
                onChange={handleStatusFilterChange}
                label="Status"
                sx={{ borderRadius: 2 }}
              >
                <MenuItem value="all">All Status</MenuItem>
                <MenuItem value="active">Active</MenuItem>
                <MenuItem value="inactive">Inactive</MenuItem>
                <MenuItem value="maintenance">Under Maintenance</MenuItem>
              </Select>
            </FormControl>

            <FormControl sx={{ minWidth: 120 }}>
              <InputLabel>AMC</InputLabel>
              <Select
                value={amcFilter}
                onChange={handleAMCFilterChange}
                label="AMC"
                sx={{ borderRadius: 2 }}
              >
                <MenuItem value="all">All AMC</MenuItem>
                <MenuItem value="yes">With AMC</MenuItem>
                <MenuItem value="no">Without AMC</MenuItem>
              </Select>
            </FormControl>

            <Button
              startIcon={<Refresh />}
              onClick={resetFilters}
              sx={{ borderRadius: 2 }}
            >
              Reset Filters
            </Button>
          </Stack>

          {/* Table */}
          <TableContainer component={Paper} sx={{ borderRadius: 2, boxShadow: 'none' }}>
            <Table>
              <TableHead>
                <TableRow sx={{ backgroundColor: '#f8faff' }}>
                  <TableCell>Device Name</TableCell>
                  <TableCell>Serial Number</TableCell>
                  <TableCell>Make/Model</TableCell>
                  <TableCell>Room No</TableCell>
                  <TableCell>Status</TableCell>
                  <TableCell>AMC</TableCell>
                  <TableCell>Calibration</TableCell>
                  <TableCell>Accessories</TableCell>
                  <TableCell align="center">Actions</TableCell>
                </TableRow>
              </TableHead>
              <TableBody>
                {loading ? (
                  <TableRow>
                    <TableCell colSpan={9} align="center" sx={{ py: 3 }}>
                      <CircularProgress size={40} />
                    </TableCell>
                  </TableRow>
                ) : devices.length === 0 ? (
                  <TableRow>
                    <TableCell colSpan={9} align="center" sx={{ py: 3 }}>
                      <Typography variant="body1" color="textSecondary">
                        No devices found
                      </Typography>
                    </TableCell>
                  </TableRow>
                ) : (
                  devices.map((device) => {
                    const daysUntilCalibration = getDaysUntilCalibration(device.calibrationDate);
                    
                    return (
                      <TableRow key={device._id} hover>
                        <TableCell>{device.deviceName}</TableCell>
                        <TableCell>{device.serialNumber}</TableCell>
                        <TableCell>{`${device.make} / ${device.model}`}</TableCell>
                        <TableCell>{device.roomNo}</TableCell>
                        <TableCell>
                          <Chip
                            label={device.status}
                            color={getStatusColor(device.status)}
                            size="small"
                          />
                        </TableCell>
                        <TableCell>
                          {device.hasAMC ? (
                            <Tooltip title={`AMC Provider: ${device.amcCompany}`}>
                              <Chip
                                icon={<CheckCircle sx={{ fontSize: 16 }} />}
                                label="Active AMC"
                                color="success"
                                size="small"
                              />
                            </Tooltip>
                          ) : (
                            <Chip
                              label="No AMC"
                              color="error"
                              size="small"
                            />
                          )}
                        </TableCell>
                        <TableCell>
                          <Tooltip title={`Next Calibration: ${new Date(device.calibrationDate).toLocaleDateString()}`}>
                            <Chip
                              icon={daysUntilCalibration <= 30 ? <Warning sx={{ fontSize: 16 }} /> : null}
                              label={
                                daysUntilCalibration <= 0
                                  ? 'Overdue'
                                  : daysUntilCalibration <= 30
                                    ? `Due in ${daysUntilCalibration} days`
                                    : 'Up to date'
                              }
                              color={
                                daysUntilCalibration <= 0
                                  ? 'error'
                                  : daysUntilCalibration <= 30
                                    ? 'warning'
                                    : 'success'
                              }
                              size="small"
                            />
                          </Tooltip>
                        </TableCell>
                        <TableCell>
                          <Stack direction="row" spacing={1}>
                            {(device.accessories || []).slice(0, 3).map((acc, index) => (
                              <Tooltip
                                key={index}
                                title={`${acc.itemName} - ${acc.status}`}
                              >
                                <Chip
                                  label={acc.itemName}
                                  size="small"
                                  color={getStatusColor(acc.status)}
                                  variant="outlined"
                                />
                              </Tooltip>
                            ))}
                            {(device.accessories || []).length > 3 && (
                              <Chip
                                label={`+${device.accessories.length - 3} more`}
                                size="small"
                                variant="outlined"
                              />
                            )}
                          </Stack>
                        </TableCell>
                        <TableCell align="center">
                          <IconButton
                            size="small"
                            onClick={(event) => handleMenuClick(event, device)}
                          >
                            <MoreVert />
                          </IconButton>
                        </TableCell>
                      </TableRow>
                    );
                  })
                )}
              </TableBody>
            </Table>
            <TablePagination
              rowsPerPageOptions={[5, 10, 25, 50]}
              component="div"
              count={totalDevices}
              rowsPerPage={rowsPerPage}
              page={page}
              onPageChange={handleChangePage}
              onRowsPerPageChange={handleChangeRowsPerPage}
            />
          </TableContainer>
        </CardContent>
      </Card>

      {/* Action Menu */}
      <Menu
        anchorEl={anchorEl}
        open={Boolean(anchorEl)}
        onClose={handleMenuClose}
        PaperProps={{
          sx: { borderRadius: 2 }
        }}
      >
        <MenuItem onClick={handleView}>
          <Visibility sx={{ mr: 1 }} fontSize="small" />
          View Details
        </MenuItem>
        <MenuItem onClick={handleEdit}>
          <Edit sx={{ mr: 1 }} fontSize="small" />
          Edit
        </MenuItem>
        <MenuItem
          onClick={() => {
            handleMenuClose();
            navigate(`/devices/${selectedDevice?._id}/inspection`);
          }}
        >
          <Build sx={{ mr: 1 }} fontSize="small" />
          Inspection
        </MenuItem>
        <Divider />
        <MenuItem onClick={handleDelete} sx={{ color: 'error.main' }}>
          <Delete sx={{ mr: 1 }} fontSize="small" />
          Delete
        </MenuItem>
      </Menu>

      {/* Delete Confirmation Dialog */}
      <Dialog
        open={deleteDialogOpen}
        onClose={() => !loading && setDeleteDialogOpen(false)}
        PaperProps={{
          sx: { borderRadius: 3 }
        }}
      >
        <DialogTitle>Confirm Delete</DialogTitle>
        <DialogContent>
          {loading ? (
            <Box sx={{ display: 'flex', justifyContent: 'center', p: 3 }}>
              <CircularProgress />
            </Box>
          ) : (
            <>
              <Typography gutterBottom>
                Are you sure you want to delete this device? This action cannot be undone.
              </Typography>
              {selectedDevice && (
                <Box sx={{ mt: 2 }}>
                  <Typography variant="body2" gutterBottom>
                    <strong>Device Name:</strong> {selectedDevice.deviceName}
                  </Typography>
                  <Typography variant="body2" gutterBottom>
                    <strong>Serial Number:</strong> {selectedDevice.serialNumber}
                  </Typography>
                  <Typography variant="body2" gutterBottom>
                    <strong>Room Number:</strong> {selectedDevice.roomNo}
                  </Typography>
                </Box>
              )}
            </>
          )}
        </DialogContent>
        <DialogActions sx={{ p: 2 }}>
          <Button
            onClick={() => setDeleteDialogOpen(false)}
            sx={{ borderRadius: 2 }}
            disabled={loading}
          >
            Cancel
          </Button>
          <Button
            onClick={confirmDelete}
            variant="contained"
            color="error"
            sx={{ borderRadius: 2 }}
            disabled={loading}
          >
            Delete
          </Button>
        </DialogActions>
      </Dialog>

      {/* Notification */}
      <Snackbar
        open={notification.open}
        autoHideDuration={6000}
        onClose={() => setNotification(prev => ({ ...prev, open: false }))}
        anchorOrigin={{ vertical: 'top', horizontal: 'right' }}
      >
        <Alert
          onClose={() => setNotification(prev => ({ ...prev, open: false }))}
          severity={notification.severity}
          variant="filled"
          sx={{ width: '100%', borderRadius: 2 }}
        >
          {notification.message}
        </Alert>
      </Snackbar>
    </Box>
  );
};

export default ManageDevicesTable;