// features/services/inspectionService.js

import axios from 'axios';

const API_URL = process.env.REACT_APP_API_URL || 'http://localhost:5000';

// Create axios instance with default config
const api = axios.create({
  baseURL: `${API_URL}/device`,
  headers: {
    'Content-Type': 'application/json'
  }
});

// Add auth token to requests
api.interceptors.request.use(
  (config) => {
    const token = localStorage.getItem('token');
    if (token) {
      config.headers.Authorization = `Bearer ${token}`;
    }
    return config;
  },
  (error) => Promise.reject(error)
);

// Handle response errors
api.interceptors.response.use(
  (response) => response,
  (error) => {
    const errorMessage = error.response?.data?.message || 'Something went wrong';
    console.error('API Error:', errorMessage);
    return Promise.reject(error);
  }
);

const inspectionService = {
    // Create a new inspection
    createInspection: async (inspectionData, token) => {
        console.log('Creating inspection with data:_________________3', inspectionData);
        try {
            const response = await api.post('/inspection/create', inspectionData, {
                headers: {
                    'Authorization': `Bearer ${token}`,
                    'Content-Type': 'application/json'
                }
            });
            console.log('response___________________4', response);
            
            return response.data;
        } catch (error) {
            console.error('Error creating inspection:', error);
            throw error.response?.data?.message || 'Failed to create inspection';
        }
    },

    // Update an existing inspection
    updateInspection: async (inspectionId, inspectionData, token) => {
        console.log('Updating inspection with ID:', inspectionId, 'data:', inspectionData);
        try {
            const response = await api.put(`/inspection/${inspectionId}`, inspectionData, {
                headers: {
                    'Authorization': `Bearer ${token}`,
                    'Content-Type': 'application/json'
                }
            });
            return response.data;
        } catch (error) {
            console.error('Error updating inspection:', error);
            throw error.response?.data?.message || 'Failed to update inspection';
        }
    },

    // Get inspection by device ID with optional filters
    getInspectionsByDevice: async (deviceId, filters = {}, token) => {
        console.log('Fetching inspection for device ID:', deviceId, 'with filters:', filters);
        try {
            const query = new URLSearchParams({
                deviceId,
                ...filters
            }).toString();
            const response = await api.get(`/inspection?${query}`, {
                headers: {
                    'Authorization': `Bearer ${token}`
                }
            });
            return response.data;
        } catch (error) {
            console.error('Error fetching inspection:', error);
            throw error.response?.data?.message || 'Failed to fetch inspection';
        }
    },

    // Get a single inspection by ID
    getInspectionById: async (inspectionId, token) => {
        console.log('Fetching inspection with ID:', inspectionId);
        try {
            const response = await api.get(`/inspection/${inspectionId}`, {
                headers: {
                    'Authorization': `Bearer ${token}`
                }
            });
            return response.data;
        } catch (error) {
            console.error('Error fetching inspection:', error);
            throw error.response?.data?.message || 'Failed to fetch inspection';
        }
    },
    // Get all inspection with optional filters and pagination
    getAllInspections: async (filters = {}, token) => {
        console.log('Fetching all inspection with filters:', filters);
        try {
            const query = new URLSearchParams({
                ...filters,
                limit: filters.limit || 10, // Default limit of 10 per page
                page: filters.page || 1, // Default to page 1
                sort: filters.sort || '-inspectionDate' // Default sort by inspectionDate descending
            }).toString();
            const response = await api.get(`/inspection/all?${query}`, {
                headers: {
                    'Authorization': `Bearer ${token}`
                }
            });
            console.log('response___________________5', response);
            
            return response.data; // Expecting { data: [inspection], pagination: { page, pages, total } }
        } catch (error) {
            console.error('Error fetching all inspection:', error);
            throw error.response?.data?.message || 'Failed to fetch all inspection';
        }
    },

    // Delete an inspection (if needed, optional)
    deleteInspection: async (inspectionId, token) => {
        console.log('Deleting inspection with ID:', inspectionId);
        try {
            const response = await api.delete(`/inspection/${inspectionId}`, {
                headers: {
                    'Authorization': `Bearer ${token}`
                }
            });
            return response.data;
        } catch (error) {
            console.error('Error deleting inspection:', error);
            throw error.response?.data?.message || 'Failed to delete inspection';
        }
    }
};

export default inspectionService;