import React, { useEffect, useState } from 'react';
import {
  Table,
  TableBody,
  TableCell,
  TableContainer,
  TableHead,
  TableRow,
  Typography,
  Box,
  Skeleton,
  Paper,
  Chip,
  Stack,
  IconButton,
  Tooltip,
  Alert,
  LinearProgress,
  useTheme,
  alpha,
  TablePagination,
} from '@mui/material';
import {
  Warning,
  ErrorOutline,
  AccessTime,
  Refresh,
  Search,
  NotificationsActive,
  Schedule,
  FilterList
} from '@mui/icons-material';
import api from '../../../../api/axios';
import { useSelector } from 'react-redux';
import { jwtDecode } from 'jwt-decode';

const DelayedFilesTable = () => {
  const [data, setData] = useState({ delayedFiles: [], totalDelayed: 0 });
  const [loading, setLoading] = useState(true);
  const [page, setPage] = useState(0);
  const [rowsPerPage, setRowsPerPage] = useState(5);
  const [stats, setStats] = useState({
    criticalDelays: 0,
    averageDelay: 0,
    mostDelayed: { fileId: '', days: 0 }
  });

  const token = useSelector(state => state.auth.token);
  const userId = token ? jwtDecode(token).userId : null;
  const theme = useTheme();

  const fetchData = async () => {
    setLoading(true);
    try {
      const response = await api.get(`/reports/delayed-files?userId=${userId}`);
      if (response.data.success) {
        const files = response.data.data.delayedFiles;
        
        // Calculate statistics
        const criticalCount = files.filter(f => f.daysDelayed > 14).length;
        const avgDelay = files.reduce((acc, curr) => acc + curr.daysDelayed, 0) / files.length;
        const mostDelayed = files.reduce((max, file) => 
          file.daysDelayed > max.days ? 
          { fileId: file.fileId, days: file.daysDelayed } : max, 
          { fileId: '', days: 0 }
        );

        setData(response.data.data);
        setStats({
          criticalDelays: criticalCount,
          averageDelay: Math.round(avgDelay * 10) / 10,
          mostDelayed
        });
      }
    } catch (error) {
      console.error('Error fetching delayed files:', error);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    if (userId) {
      fetchData();
    }
  }, [userId]);

  const handleChangePage = (event, newPage) => {
    setPage(newPage);
  };

  const handleChangeRowsPerPage = (event) => {
    setRowsPerPage(parseInt(event.target.value, 10));
    setPage(0);
  };

  const getDelayStatus = (days) => {
    if (days > 14) return { color: 'error', icon: <ErrorOutline /> };
    if (days > 7) return { color: 'warning', icon: <Warning /> };
    return { color: 'info', icon: <AccessTime /> };
  };

  if (loading) {
    return (
      <Box sx={{ width: '100%' }}>
        <Skeleton variant="text" width="200px" sx={{ mb: 2 }} />
        <Skeleton variant="rectangular" height={300} />
      </Box>
    );
  }

  return (
    <Box>
      <Stack
        direction="row"
        justifyContent="space-between"
        alignItems="center"
        mb={2}
      >
        <Stack direction="row" alignItems="center" spacing={1}>
          <NotificationsActive color="error" />
          <Typography variant="h6">
            Delayed Files
          </Typography>
          <Chip
            label={data.totalDelayed}
            color="error"
            size="small"
            sx={{ ml: 1 }}
          />
        </Stack>
        <Tooltip title="Refresh">
          <IconButton onClick={fetchData} size="small">
            <Refresh />
          </IconButton>
        </Tooltip>
      </Stack>

      <Stack
        direction={{ xs: 'column', sm: 'row' }}
        spacing={1}
        mb={2}
      >
        <Chip
          icon={<ErrorOutline />}
          label={`Critical: ${stats.criticalDelays}`}
          color="error"
          variant="outlined"
          size="small"
        />
        <Chip
          icon={<Schedule />}
          label={`Avg Delay: ${stats.averageDelay} days`}
          color="warning"
          variant="outlined"
          size="small"
        />
        <Chip
          icon={<AccessTime />}
          label={`Longest: ${stats.mostDelayed.days} days`}
          color="info"
          variant="outlined"
          size="small"
        />
      </Stack>

      <TableContainer
        component={Paper}
        elevation={0}
        sx={{
          maxHeight: 300,
          border: `1px solid ${alpha(theme.palette.primary.main, 0.1)}`,
          borderRadius: 2,
        }}
      >
        <Table stickyHeader size="small">
          <TableHead>
            <TableRow>
              <TableCell
                sx={{
                  bgcolor: theme.palette.mode === 'light' 
                    ? alpha(theme.palette.primary.main, 0.05)
                    : alpha(theme.palette.primary.main, 0.15),
                  fontWeight: 600,
                }}
              >
                File ID
              </TableCell>
              <TableCell
                align="right"
                sx={{
                  bgcolor: theme.palette.mode === 'light' 
                    ? alpha(theme.palette.primary.main, 0.05)
                    : alpha(theme.palette.primary.main, 0.15),
                  fontWeight: 600,
                }}
              >
                Days Delayed
              </TableCell>
              <TableCell
                align="right"
                sx={{
                  bgcolor: theme.palette.mode === 'light' 
                    ? alpha(theme.palette.primary.main, 0.05)
                    : alpha(theme.palette.primary.main, 0.15),
                  fontWeight: 600,
                }}
              >
                Status
              </TableCell>
            </TableRow>
          </TableHead>
          <TableBody>
            {data.delayedFiles.length > 0 ? (
              data.delayedFiles
                .slice(page * rowsPerPage, page * rowsPerPage + rowsPerPage)
                .map((file) => {
                  const status = getDelayStatus(file.daysDelayed);
                  return (
                    <TableRow
                      key={file.fileId}
                      sx={{
                        '&:hover': {
                          bgcolor: theme.palette.action.hover,
                        },
                      }}
                    >
                      <TableCell>
                        <Stack direction="row" alignItems="center" spacing={1}>
                          <Search sx={{ fontSize: 16, color: 'text.secondary' }} />
                          {file.fileId}
                        </Stack>
                      </TableCell>
                      <TableCell align="right">
                        {file.daysDelayed} days
                      </TableCell>
                      <TableCell align="right">
                        <Chip
                          icon={status.icon}
                          label={file.daysDelayed > 14 ? 'Critical' : 'Delayed'}
                          color={status.color}
                          size="small"
                          variant="outlined"
                        />
                      </TableCell>
                    </TableRow>
                  );
                })
            ) : (
              <TableRow>
                <TableCell colSpan={3}>
                  <Alert severity="success" sx={{ mt: 1 }}>
                    No delayed files at the moment
                  </Alert>
                </TableCell>
              </TableRow>
            )}
          </TableBody>
        </Table>
      </TableContainer>

      {data.delayedFiles.length > 0 && (
        <TablePagination
          rowsPerPageOptions={[5, 10, 25]}
          component="div"
          count={data.delayedFiles.length}
          rowsPerPage={rowsPerPage}
          page={page}
          onPageChange={handleChangePage}
          onRowsPerPageChange={handleChangeRowsPerPage}
          sx={{
            borderTop: `1px solid ${theme.palette.divider}`,
          }}
        />
      )}
    </Box>
  );
};

export default DelayedFilesTable;