import React, { useEffect, useState } from 'react';
import { 
  Grid, 
  Paper, 
  Box, 
  Typography, 
  useTheme, 
  alpha,
  Skeleton,
  Card,
  CardContent,
  LinearProgress,
  Divider
} from '@mui/material';
import {
  PeopleAlt as PeopleIcon,
  Folder as FolderIcon,
  Folder as TransferIcon,
  Warning as WarningIcon,
  TrendingUp,
  LocalHospital,
  AccessTime,
  FileCopy
} from '@mui/icons-material';
import StatsCard from './StatsCard';
import DailyTransfersChart from './DailyTransfersChart';
import DelayedFilesTable from './DelayedFilesTable';
import api from '../../../../api/axios';
import { useSelector } from 'react-redux';
import { jwtDecode } from 'jwt-decode';

const DashboardComponents = () => {
  const [stats, setStats] = useState({
    totalPatients: 0,
    filesHandledLast7Days: 0,
    totalCsUsers: 0,
    totalFiles: 0,
    patientsHandledLast7Days: 0,
    notReturnedCount: 0,
  });
  const [loading, setLoading] = useState(true);
  const token = useSelector(state => state.auth.token);
  const userId = token ? jwtDecode(token).userId : null;
  const theme = useTheme();

  useEffect(() => {
    const fetchDashboardData = async () => {
      try {
        const [totalCountsResponse, notReturnedResponse] = await Promise.all([
          api.get(`/reports/total-counts?userId=${userId}`),
          api.get(`/reports/not-returned?userId=${userId}`)
        ]);
        
        if (totalCountsResponse.data.success && notReturnedResponse.data.success) {
          setStats({
            ...totalCountsResponse.data.data,
            notReturnedCount: notReturnedResponse.data.data.notReturnedCount
          });
        }
      } catch (error) {
        console.error('Error fetching dashboard data:', error);
      } finally {
        setLoading(false);
      }
    };

    if (userId) {
      fetchDashboardData();
    }
  }, [userId]);

  const statsCards = [
    {
      title: "Total Patients",
      value: stats.totalPatients,
      icon: <LocalHospital />,
      color: theme.palette.primary.main,
      trend: "+12%",
      subtitle: "Active patient records"
    },
    {
      title: "Files This Week",
      value: stats.filesHandledLast7Days,
      icon: <FileCopy />,
      color: theme.palette.success.main,
      trend: "+8%",
      subtitle: "Weekly file processing"
    },
    {
      title: "Active Transfers",
      value: stats.notReturnedCount,
      icon: <FileCopy />,
      color: theme.palette.warning.main,
      trend: "-5%",
      subtitle: "Pending returns"
    },
    {
      title: "Total Files",
      value: stats.totalFiles,
      icon: <FolderIcon />,
      color: theme.palette.error.main,
      trend: "+15%",
      subtitle: "Total records managed"
    }
  ];

  return (
    <Box
      sx={{
        p: { xs: 2, md: 4 },
        pt: { xs: 8, md: 9 },
        minHeight: '100vh',
        bgcolor: theme.palette.mode === 'light' 
          ? alpha(theme.palette.primary.main, 0.02)
          : theme.palette.background.default,
      }}
    >
      <Box
        sx={{
          mb: 4,
          display: 'flex',
          flexDirection: { xs: 'column', md: 'row' },
          alignItems: { xs: 'flex-start', md: 'center' },
          justifyContent: 'space-between',
          gap: 2
        }}
      >
        <Box>
          <Typography 
            variant="h4" 
            sx={{ 
              fontWeight: 700,
              color: theme.palette.mode === 'light' ? theme.palette.grey[800] : theme.palette.grey[100]
            }}
          >
            Dashboard Overview
          </Typography>
          <Typography 
            variant="subtitle1" 
            color="text.secondary"
            sx={{ mt: 1 }}
          >
            Welcome to NISH Medical Records Room
          </Typography>
        </Box>
        <Box
          sx={{
            display: 'flex',
            alignItems: 'center',
            gap: 1,
            bgcolor: theme.palette.mode === 'light' 
              ? alpha(theme.palette.primary.main, 0.1)
              : alpha(theme.palette.primary.main, 0.2),
            py: 1,
            px: 2,
            borderRadius: 2
          }}
        >
          <AccessTime sx={{ color: theme.palette.primary.main }} />
          <Typography variant="body2" color="primary">
            Last updated: {new Date().toLocaleTimeString()}
          </Typography>
        </Box>
      </Box>

      <Grid container spacing={3}>
        {statsCards.map((card, index) => (
          <Grid item xs={12} sm={6} md={3} key={index}>
            <Card
              elevation={0}
              sx={{
                bgcolor: theme.palette.mode === 'light' 
                  ? '#fff'
                  : alpha(theme.palette.primary.main, 0.1),
                border: `1px solid ${alpha(card.color, 0.1)}`,
                borderRadius: 3,
                transition: 'transform 0.2s, box-shadow 0.2s',
                '&:hover': {
                  transform: 'translateY(-4px)',
                  boxShadow: `0 4px 20px ${alpha(card.color, 0.2)}`
                }
              }}
            >
              <CardContent>
                <Box sx={{ display: 'flex', alignItems: 'center', mb: 2 }}>
                  <Box
                    sx={{
                      p: 1.5,
                      borderRadius: 2,
                      bgcolor: alpha(card.color, 0.1),
                      color: card.color
                    }}
                  >
                    {card.icon}
                  </Box>
                  <Box
                    sx={{
                      ml: 'auto',
                      display: 'flex',
                      alignItems: 'center',
                      gap: 0.5,
                      color: card.trend.startsWith('+') ? 'success.main' : 'error.main'
                    }}
                  >
                    <TrendingUp fontSize="small" />
                    <Typography variant="body2" fontWeight="medium">
                      {card.trend}
                    </Typography>
                  </Box>
                </Box>

                {loading ? (
                  <Skeleton variant="text" width="60%" />
                ) : (
                  <Typography variant="h4" sx={{ mb: 1, fontWeight: 700 }}>
                    {card.value.toLocaleString()}
                  </Typography>
                )}

                <Typography variant="body2" color="text.secondary" sx={{ mb: 1 }}>
                  {card.subtitle}
                </Typography>

                <LinearProgress 
                  variant="determinate" 
                  value={70} 
                  sx={{
                    height: 6,
                    borderRadius: 3,
                    bgcolor: alpha(card.color, 0.1),
                    '& .MuiLinearProgress-bar': {
                      bgcolor: card.color
                    }
                  }}
                />
              </CardContent>
            </Card>
          </Grid>
        ))}

        <Grid item xs={12} md={8}>
          <Card
            elevation={0}
            sx={{
              height: '100%',
              borderRadius: 3,
              border: `1px solid ${alpha(theme.palette.primary.main, 0.1)}`,
            }}
          >
            <CardContent>
              <Typography variant="h6" sx={{ mb: 3, fontWeight: 600 }}>
                File Transfer Activity
              </Typography>
              <DailyTransfersChart />
            </CardContent>
          </Card>
        </Grid>

        <Grid item xs={12} md={4}>
          <Card
            elevation={0}
            sx={{
              height: '100%',
              borderRadius: 3,
              border: `1px solid ${alpha(theme.palette.primary.main, 0.1)}`,
            }}
          >
            <CardContent>
              <Typography variant="h6" sx={{ mb: 3, fontWeight: 600 }}>
                Delayed Returns
              </Typography>
              <DelayedFilesTable />
            </CardContent>
          </Card>
        </Grid>
      </Grid>
    </Box>
  );
};

export default DashboardComponents;