import React, { useState, useEffect } from 'react';
import {
  Box,
  Card,
  TextField,
  Button,
  Typography,
  Stack,
  Dialog,
  DialogTitle,
  DialogContent,
  DialogActions,
  CircularProgress,
  Alert,
  Divider,
  FormControl,
  InputLabel,
  Select,
  MenuItem,
  InputAdornment,
  Tooltip,
} from '@mui/material';
import {
  Add as AddIcon,
  Search as SearchIcon,
  Phone as PhoneIcon,
} from '@mui/icons-material';
import { useFormik } from 'formik';
import * as yup from 'yup';
import { useSnackbar } from 'notistack';
import { useSelector } from 'react-redux';
import { jwtDecode } from 'jwt-decode';
import api from '../../../api/axios';
import { debounce } from 'lodash';

// Patient creation validation schema
const patientSchema = yup.object({
  patientName: yup.string()
    .required('Patient name is required')
    .min(3, 'Name must be at least 3 characters')
    .max(50, 'Name must be at most 50 characters'),
  email: yup.string()
    .email('Enter a valid email'),
  phoneNumber: yup.string()
    .required('Phone number is required')
    .matches(/^[0-9]{10}$/, 'Phone number must be 10 digits'),
  whatsApp: yup.string()
    .matches(/^[0-9]{10}$/, 'WhatsApp number must be 10 digits'),
  byStanderName: yup.string()
    .min(3, 'Bystander name must be at least 3 characters')
    .max(50, 'Bystander name must be at most 50 characters'),
  byStanderPhone: yup.string()
    .matches(/^[0-9]{10}$/, 'Phone number must be 10 digits'),
  address: yup.string()
    .min(5, 'Address must be at least 5 characters'),
  pincode: yup.string()
    .matches(/^[0-9]{6}$/, 'Pincode must be 6 digits')
});

// File creation validation schema
const fileSchema = yup.object({
  caseId: yup.string()
    .required('Case ID is required')
    .min(3, 'Case ID must be at least 3 characters')
    .max(20, 'Case ID must be at most 20 characters'),
  rack: yup.string()
    .required('Rack is required'),
  subDivision: yup.string()
    .required('Subdivision is required'),
});

const CreateFile = () => {
  // States
  const [loading, setLoading] = useState(false);
  const [addPatientDialog, setAddPatientDialog] = useState(false);
  const [confirmDialog, setConfirmDialog] = useState(false);
  const [racks, setRacks] = useState([]);
  const [subdivisions, setSubdivisions] = useState([]);
  const [searchType, setSearchType] = useState('name');
  const [searchQuery, setSearchQuery] = useState('');
  const [selectedPatient, setSelectedPatient] = useState(null);
  const [searchResults, setSearchResults] = useState([]);
  const [searching, setSearching] = useState(false);

  const { enqueueSnackbar } = useSnackbar();
  
  // Get user ID from token
  const token = useSelector(state => state.auth.token);
  const userId = token ? jwtDecode(token).userId : null;

  // Patient creation formik
  const patientFormik = useFormik({
    initialValues: {
      patientName: '',
      email: '',
      phoneNumber: '',
      whatsApp: '',
      byStanderName: '',
      byStanderPhone: '',
      address: '',
      pincode: ''
    },
    validationSchema: patientSchema,
    onSubmit: async (values, { setSubmitting, resetForm }) => {
      try {
        const response = await api.post('/patients', {
          userId,
          ...values
        });

        if (response.data.success) {
          enqueueSnackbar('Patient created successfully', { variant: 'success' });
          setSelectedPatient(response.data.data);
          resetForm();
          setAddPatientDialog(false);
        }
      } catch (error) {
        enqueueSnackbar(error.response?.data?.message || 'Error creating patient', {
          variant: 'error'
        });
      } finally {
        setSubmitting(false);
      }
    }
  });

  // File creation formik
  const fileFormik = useFormik({
    initialValues: {
      caseId: '',
      rack: '',
      subDivision: '',
    },
    validationSchema: fileSchema,
    onSubmit: () => {
      if (!selectedPatient) {
        enqueueSnackbar('Please select a patient first', { variant: 'error' });
        return;
      }
      setConfirmDialog(true);
    }
  });

  // Fetch racks on component mount
  useEffect(() => {
    const fetchRacks = async () => {
      try {
        const response = await api.get('/racks/active');
        setRacks(response.data.data);
      } catch (error) {
        enqueueSnackbar('Error fetching racks', { variant: 'error' });
      }
    };
    fetchRacks();
  }, [enqueueSnackbar]);

  // Fetch subdivisions when rack is selected
  useEffect(() => {
    const fetchSubdivisions = async () => {
      if (!fileFormik.values.rack) {
        setSubdivisions([]);
        return;
      }
      try {
        // Get the rackId from the selected rack object
        const selectedRack = racks.find(r => r._id === fileFormik.values.rack);
        if (!selectedRack) return;
        
        const response = await api.get(`/racks/subdivisions/${selectedRack.rackId}`);
        setSubdivisions(response.data.data);
      } catch (error) {
        enqueueSnackbar('Error fetching subdivisions', { variant: 'error' });
      }
    };
    fetchSubdivisions();
  }, [fileFormik.values.rack, racks, enqueueSnackbar]);

  // Debounced search function for name search
  const debouncedNameSearch = debounce(async (searchValue) => {
    if (!searchValue || searchValue.length < 3) return;
    
    setSearching(true);
    try {
      const response = await api.get(`/patients/search/name?userId=${userId}&name=${searchValue}`);
      setSearchResults(response.data.data);
    } catch (error) {
      enqueueSnackbar('Error searching patients', { variant: 'error' });
    } finally {
      setSearching(false);
    }
  }, 300);

  // Handle search query change
  const handleSearchQueryChange = async (value) => {
    setSearchQuery(value);
    if (searchType === 'name') {
      debouncedNameSearch(value);
    }
  };

  // Handle phone search
  const handlePhoneSearch = async () => {
    if (!searchQuery || searchQuery.length !== 10) {
      enqueueSnackbar('Please enter a valid 10-digit phone number', { variant: 'error' });
      return;
    }

    setSearching(true);
    try {
      const response = await api.get(`/patients/search/phone?userId=${userId}&phoneNumber=${searchQuery}`);
      if (response.data.data.length > 0) {
        setSearchResults(response.data.data);
      } else {
        enqueueSnackbar('No patient found with this phone number', { variant: 'info' });
      }
    } catch (error) {
      enqueueSnackbar('Error searching patients', { variant: 'error' });
    } finally {
      setSearching(false);
    }
  };

  // Handle patient selection
  const handlePatientSelect = (patient) => {
    setSelectedPatient(patient);
    setSearchResults([]);
    setSearchQuery('');
  };

  // Handle file creation
  const handleCreateFile = async () => {
    setLoading(true);
    try {
      const response = await api.post('/file-records/create', {
        userId,
        patientId: selectedPatient._id,
        files: [{
          caseId: fileFormik.values.caseId,
          rack: fileFormik.values.rack,
          subDivision: fileFormik.values.subDivision,
        }]
      });

      if (response.data.success) {
        enqueueSnackbar('File created successfully', { variant: 'success' });
        fileFormik.resetForm();
        setSelectedPatient(null);
        setSearchQuery('');
        setSearchResults([]);
        setConfirmDialog(false);
      }
    } catch (error) {
      enqueueSnackbar(error.response?.data?.message || 'Error creating file', {
        variant: 'error'
      });
    } finally {
      setLoading(false);
    }
  };

  return (
    <Box sx={{ p: 3 }}>
      <Typography variant="h4" gutterBottom>
        Create File Record
      </Typography>

      {/* Patient Search Section */}
      <Card sx={{ p: 3, mb: 3 }}>
        <Stack spacing={3}>
          <Stack
            direction="row"
            spacing={2}
            alignItems="center"
            justifyContent="space-between"
          >
            <Typography variant="h6">Patient Search</Typography>
            <Button
              variant="contained"
              startIcon={<AddIcon />}
              onClick={() => setAddPatientDialog(true)}
            >
              Add New Patient
            </Button>
          </Stack>

          <Stack direction="row" spacing={2} alignItems="center">
            <TextField
              fullWidth
              label={`Search by ${searchType === 'name' ? 'Name' : 'Phone'}`}
              value={searchQuery}
              onChange={(e) => handleSearchQueryChange(e.target.value)}
              InputProps={{
                startAdornment: (
                  <InputAdornment position="start">
                    {searchType === 'name' ? <SearchIcon /> : <PhoneIcon />}
                  </InputAdornment>
                ),
                endAdornment: searchType === 'phone' && (
                  <InputAdornment position="end">
                    <Button
                      variant="contained"
                      onClick={handlePhoneSearch}
                      disabled={searching || !searchQuery || searchQuery.length !== 10}
                    >
                      Search
                    </Button>
                  </InputAdornment>
                ),
              }}
            />
            <Button
              variant="outlined"
              onClick={() => {
                setSearchType(prev => prev === 'name' ? 'phone' : 'name');
                setSearchQuery('');
                setSearchResults([]);
              }}
            >
              Search by {searchType === 'name' ? 'Phone' : 'Name'}
            </Button>
          </Stack>

          {/* Search Results */}
          {searchResults.length > 0 && !selectedPatient && (
            <Box sx={{ mt: 2 }}>
              <Typography variant="subtitle2" gutterBottom>
                Search Results:
              </Typography>
              <Stack spacing={1}>
                {searchResults.map((patient) => (
                  <Card
                    key={patient._id}
                    sx={{
                      p: 2,
                      cursor: 'pointer',
                      '&:hover': {
                        bgcolor: 'action.hover',
                      },
                    }}
                    onClick={() => handlePatientSelect(patient)}
                  >
                    <Stack direction="row" justifyContent="space-between" alignItems="center">
                      <Stack>
                        <Typography variant="subtitle1">{patient.patientName}</Typography>
                        <Typography variant="body2" color="text.secondary">
                          Phone: {patient.phoneNumber}
                        </Typography>
                      </Stack>
                      <Button size="small">Select</Button>
                    </Stack>
                  </Card>
                ))}
              </Stack>
            </Box>
          )}

          {selectedPatient && (
            <Alert 
              severity="info"
              action={
                <Button
                  color="inherit"
                  size="small"
                  onClick={() => {
                    setSelectedPatient(null);
                    setSearchQuery('');
                  }}
                >
                  Change
                </Button>
              }
            >
              <Typography variant="subtitle2">
                Selected Patient: {selectedPatient.patientName}
              </Typography>
              <Typography variant="body2">
                Phone: {selectedPatient.phoneNumber}
              </Typography>
            </Alert>
          )}
        </Stack>
      </Card>

      {/* File Creation Form */}
      <Card sx={{ p: 3 }}>
        <form onSubmit={fileFormik.handleSubmit}>
          <Stack spacing={3}>
            <Typography variant="h6">File Details</Typography>

            <TextField
              fullWidth
              name="caseId"
              label="Case ID"
              value={fileFormik.values.caseId}
              onChange={fileFormik.handleChange}
              error={fileFormik.touched.caseId && Boolean(fileFormik.errors.caseId)}
              helperText={fileFormik.touched.caseId && fileFormik.errors.caseId}
              disabled={loading || !selectedPatient}
            />

            <FormControl fullWidth>
              <InputLabel>Rack</InputLabel>
              <Select
                name="rack"
                value={fileFormik.values.rack}
                label="Rack"
                onChange={fileFormik.handleChange}
                error={fileFormik.touched.rack && Boolean(fileFormik.errors.rack)}
                disabled={loading || !selectedPatient}
              >
                {racks.map((rack) => (
                  <MenuItem key={rack._id} value={rack._id}>
                    {rack.rackId}
                  </MenuItem>
                ))}
              </Select>
            </FormControl>

            <FormControl fullWidth>
              <InputLabel>Subdivision</InputLabel>
              <Select
                name="subDivision"
                value={fileFormik.values.subDivision}
                label="Subdivision"
                onChange={fileFormik.handleChange}
                error={fileFormik.touched.subDivision && Boolean(fileFormik.errors.subDivision)}
                disabled={loading || !fileFormik.values.rack || !selectedPatient}
              >
                {subdivisions.map((sub) => (
                  <MenuItem key={sub} value={sub}>
                    {sub}
                  </MenuItem>
                ))}
              </Select>
            </FormControl>

            <Button
              type="submit"
              variant="contained"
              size="large"
              disabled={loading || !selectedPatient}
            >
              Create File Record
            </Button>
          </Stack>
        </form>
      </Card>

      {/* Add Patient Dialog */}
      <Dialog
        open={addPatientDialog}
        onClose={() => !patientFormik.isSubmitting && setAddPatientDialog(false)}
        maxWidth="md"
        fullWidth
      >
        <form onSubmit={patientFormik.handleSubmit}>
          <DialogTitle>Add New Patient</DialogTitle>
          <DialogContent>
            <Stack spacing={3} sx={{ mt: 2 }}>
              <Typography variant="h6">Patient Information</Typography>
              
              <Stack spacing={3} direction={{ xs: 'column', md: 'row' }}>
                <TextField
                  fullWidth
                  name="patientName"
                  label="Patient Name"
                  value={patientFormik.values.patientName}
                  onChange={patientFormik.handleChange}
                  error={patientFormik.touched.patientName && Boolean(patientFormik.errors.patientName)}
                  helperText={patientFormik.touched.patientName && patientFormik.errors.patientName}
                  disabled={patientFormik.isSubmitting}
                />
                <TextField
                  fullWidth
                  name="email"
                  label="Email"
                  value={patientFormik.values.email}
                  onChange={patientFormik.handleChange}
                  error={patientFormik.touched.email && Boolean(patientFormik.errors.email)}
                  helperText={patientFormik.touched.email && patientFormik.errors.email}
                  disabled={patientFormik.isSubmitting}
                />
              </Stack>

              <Stack spacing={3} direction={{ xs: 'column', md: 'row' }}>
                <TextField
                  fullWidth
                  name="phoneNumber"
                  label="Phone Number"
                  value={patientFormik.values.phoneNumber}
                  onChange={patientFormik.handleChange}
                  error={patientFormik.touched.phoneNumber && Boolean(patientFormik.errors.phoneNumber)}
                  helperText={patientFormik.touched.phoneNumber && patientFormik.errors.phoneNumber}
                  disabled={patientFormik.isSubmitting}
                />
                <TextField
                  fullWidth
                  name="whatsApp"
                  label="WhatsApp Number"
                  value={patientFormik.values.whatsApp}
                  onChange={patientFormik.handleChange}
                  error={patientFormik.touched.whatsApp && Boolean(patientFormik.errors.whatsApp)}
                  helperText={patientFormik.touched.whatsApp && patientFormik.errors.whatsApp}
                  disabled={patientFormik.isSubmitting}
                />
              </Stack>

              <Divider />
              
              <Typography variant="h6">Bystander Information</Typography>

              <Stack spacing={3} direction={{ xs: 'column', md: 'row' }}>
                <TextField
                  fullWidth
                  name="byStanderName"
                  label="Bystander Name"
                  value={patientFormik.values.byStanderName}
                  onChange={patientFormik.handleChange}
                  error={patientFormik.touched.byStanderName && Boolean(patientFormik.errors.byStanderName)}
                  helperText={patientFormik.touched.byStanderName && patientFormik.errors.byStanderName}
                  disabled={patientFormik.isSubmitting}
                />
                <TextField
                  fullWidth
                  name="byStanderPhone"
                  label="Bystander Phone"
                  value={patientFormik.values.byStanderPhone}
                  onChange={patientFormik.handleChange}
                  error={patientFormik.touched.byStanderPhone && Boolean(patientFormik.errors.byStanderPhone)}
                  helperText={patientFormik.touched.byStanderPhone && patientFormik.errors.byStanderPhone}
                  disabled={patientFormik.isSubmitting}
                />
              </Stack>

              <Divider />
              
              <Typography variant="h6">Address Information</Typography>

              <TextField
                fullWidth
                name="address"
                label="Address"
                multiline
                rows={3}
                value={patientFormik.values.address}
                onChange={patientFormik.handleChange}
                error={patientFormik.touched.address && Boolean(patientFormik.errors.address)}
                helperText={patientFormik.touched.address && patientFormik.errors.address}
                disabled={patientFormik.isSubmitting}
              />

              <TextField
                fullWidth
                name="pincode"
                label="Pincode"
                value={patientFormik.values.pincode}
                onChange={patientFormik.handleChange}
                error={patientFormik.touched.pincode && Boolean(patientFormik.errors.pincode)}
                helperText={patientFormik.touched.pincode && patientFormik.errors.pincode}
                disabled={patientFormik.isSubmitting}
              />
            </Stack>
          </DialogContent>
          <DialogActions>
            <Button
              onClick={() => setAddPatientDialog(false)}
              disabled={patientFormik.isSubmitting}
            >
              Cancel
            </Button>
            <Button
              type="submit"
              variant="contained"
              disabled={patientFormik.isSubmitting}
            >
              {patientFormik.isSubmitting ? <CircularProgress size={24} /> : 'Add Patient'}
            </Button>
          </DialogActions>
        </form>
      </Dialog>

      {/* Confirmation Dialog */}
      <Dialog
        open={confirmDialog}
        onClose={() => !loading && setConfirmDialog(false)}
      >
        <DialogTitle>Confirm File Creation</DialogTitle>
        <DialogContent>
          <Stack spacing={2} sx={{ mt: 2 }}>
            <Typography>
              Please confirm the following details:
            </Typography>
            <Alert severity="info">
              <Stack spacing={1}>
                <Typography variant="body2">
                  Patient: {selectedPatient?.patientName}
                </Typography>
                <Typography variant="body2">
                  Case ID: {fileFormik.values.caseId}
                </Typography>
                <Typography variant="body2">
                  Rack: {racks.find(r => r._id === fileFormik.values.rack)?.rackId}
                </Typography>
                <Typography variant="body2">
                  Subdivision: {fileFormik.values.subDivision}
                </Typography>
              </Stack>
            </Alert>
          </Stack>
        </DialogContent>
        <DialogActions>
          <Button
            onClick={() => setConfirmDialog(false)}
            disabled={loading}
          >
            Cancel
          </Button>
          <Button
            onClick={handleCreateFile}
            variant="contained"
            disabled={loading}
          >
            {loading ? <CircularProgress size={24} /> : 'Create File'}
          </Button>
        </DialogActions>
      </Dialog>

      {/* Loading Overlay */}
      {loading && (
        <Box
          sx={{
            position: 'fixed',
            top: 0,
            left: 0,
            right: 0,
            bottom: 0,
            display: 'flex',
            alignItems: 'center',
            justifyContent: 'center',
            backgroundColor: 'rgba(0, 0, 0, 0.5)',
            zIndex: 9999,
          }}
        >
          <CircularProgress />
        </Box>
      )}
    </Box>
  );
};

export default CreateFile;