import React, { useState, useEffect } from 'react';
import {
  Box,
  Card,
  CardContent,
  Typography,
  Avatar,
  Grid,
  Button,
  TextField,
  Dialog,
  DialogTitle,
  DialogContent,
  DialogActions,
  LinearProgress,
  InputAdornment,
  IconButton,
} from '@mui/material';
import {
  Visibility,
  VisibilityOff,
  Edit as EditIcon,
} from '@mui/icons-material';
import { useDispatch, useSelector } from 'react-redux';
import { useSnackbar } from 'notistack';
import * as Yup from 'yup';
import { useFormik } from 'formik';
import api from '../../../api/axios';
import { jwtDecode } from 'jwt-decode';

// Password validation schema
const passwordSchema = Yup.object().shape({
  currentPassword: Yup.string().required('Current password is required'),
  newPassword: Yup.string()
    .min(8, 'Password must be at least 8 characters')
    .matches(
      /^(?=.*[a-z])(?=.*[A-Z])(?=.*\d)(?=.*[@$!%*?&])[A-Za-z\d@$!%*?&]/,
      'Password must contain at least one uppercase letter, one lowercase letter, one number, and one special character'
    )
    .required('New password is required'),
  confirmPassword: Yup.string()
    .oneOf([Yup.ref('newPassword'), null], 'Passwords must match')
    .required('Confirm password is required'),
});

const getPasswordStrength = (password) => {
  let strength = 0;
  if (password.length >= 8) strength += 25;
  if (/[A-Z]/.test(password)) strength += 25;
  if (/[a-z]/.test(password)) strength += 25;
  if (/[0-9]/.test(password)) strength += 12.5;
  if (/[@$!%*?&]/.test(password)) strength += 12.5;
  return strength;
};

const getInitials = (name) => {
  return name
    .split(' ')
    .map(word => word[0])
    .join('')
    .toUpperCase()
    .slice(0, 2);
};

const Profile = () => {
  const dispatch = useDispatch();
  const { enqueueSnackbar } = useSnackbar();
  const [userData, setUserData] = useState(null);
  const [openPasswordDialog, setOpenPasswordDialog] = useState(false);
  const [showPassword, setShowPassword] = useState({
    current: false,
    new: false,
    confirm: false,
  });
  const token = useSelector(state => state.auth.token);

  useEffect(() => {
    const fetchUserData = async () => {
      try {
        const decoded = jwtDecode(token);
        const userId = decoded.userId;
        const response = await api.get(`/users/${userId}`);
        setUserData(response.data.data);
      } catch (error) {
        enqueueSnackbar(error.response?.data?.message || 'Failed to fetch profile', { 
          variant: 'error' 
        });
      }
    };
    if (token) {
      fetchUserData();
    }
  }, [token, enqueueSnackbar]);

  const passwordFormik = useFormik({
    initialValues: {
      currentPassword: '',
      newPassword: '',
      confirmPassword: '',
    },
    validationSchema: passwordSchema,
    onSubmit: async (values, { setSubmitting, resetForm }) => {
      try {
        await api.post('/users/change-password', {
          email: userData.email,
          currentPassword: values.currentPassword,
          newPassword: values.newPassword,
        });
        enqueueSnackbar('Password changed successfully', { variant: 'success' });
        setOpenPasswordDialog(false);
        resetForm();
      } catch (error) {
        enqueueSnackbar(error.response?.data?.message || 'Failed to change password', {
          variant: 'error',
        });
      } finally {
        setSubmitting(false);
      }
    },
  });

  const handleTogglePassword = (field) => {
    setShowPassword(prev => ({
      ...prev,
      [field]: !prev[field]
    }));
  };

  if (!userData) {
    return <LinearProgress />;
  }

  return (
    <Box sx={{ p: 3 }}>
      <Card>
        <CardContent>
        <Grid container spacing={3}>
            {/* Profile Header */}
            <Grid item xs={12} display="flex" alignItems="center" gap={3}>
              <Avatar 
                sx={{ 
                  width: 100, 
                  height: 100, 
                  bgcolor: 'primary.main',
                  fontSize: '2.5rem'
                }}
              >
                {getInitials(userData.name)}
              </Avatar>
              <Box>
                <Typography variant="h4">{userData.name}</Typography>
                <Typography variant="subtitle1" color="textSecondary">
                  {userData.level.toUpperCase()} User
                </Typography>
              </Box>
            </Grid>

            {/* User Details */}
            <Grid item xs={12} md={6}>
              <Typography variant="h6" gutterBottom>Personal Information</Typography>
              <Box sx={{ display: 'grid', gap: 2 }}>
                <TextField
                  fullWidth
                  label="Name"
                  value={userData.name}
                  InputProps={{
                    readOnly: userData.level !== 'superAdmin',
                  }}
                />
                <TextField
                  fullWidth
                  label="Email"
                  value={userData.email}
                  InputProps={{
                    readOnly: true,
                  }}
                />
                <TextField
                  fullWidth
                  label="Phone Number"
                  value={userData.phoneNumber}
                  InputProps={{
                    readOnly: userData.level !== 'superAdmin',
                  }}
                />
                <TextField
                  fullWidth
                  label="WhatsApp"
                  value={userData.whatsApp || 'Not provided'}
                  InputProps={{
                    readOnly: userData.level !== 'superAdmin',
                  }}
                />
              </Box>
            </Grid>

            <Grid item xs={12} md={6}>
              <Typography variant="h6" gutterBottom>Additional Information</Typography>
              <Box sx={{ display: 'grid', gap: 2 }}>
                <TextField
                  fullWidth
                  label="NISH Staff ID"
                  value={userData.nishStaffId || 'Not provided'}
                  InputProps={{
                    readOnly: userData.level !== 'superAdmin',
                  }}
                />
                <TextField
                  fullWidth
                  multiline
                  rows={3}
                  label="Address"
                  value={userData.address || 'Not provided'}
                  InputProps={{
                    readOnly: userData.level !== 'superAdmin',
                  }}
                />
                <TextField
                  fullWidth
                  label="Pincode"
                  value={userData.pincode || 'Not provided'}
                  InputProps={{
                    readOnly: userData.level !== 'superAdmin',
                  }}
                />
              </Box>
            </Grid>

            {/* Actions */}
            <Grid item xs={12}>
              <Box sx={{ display: 'flex', gap: 2, justifyContent: 'flex-end' }}>
                <Button
                  variant="contained"
                  color="primary"
                  onClick={() => setOpenPasswordDialog(true)}
                >
                  Change Password
                </Button>
                {userData.level === 'superAdmin' && (
                  <Button
                    variant="contained"
                    startIcon={<EditIcon />}
                    onClick={() => {/* Implement edit functionality */}}
                  >
                    Edit Profile
                  </Button>
                )}
              </Box>
            </Grid>
          </Grid>
        </CardContent>
      </Card>

      {/* Password Change Dialog */}
      <Dialog open={openPasswordDialog} onClose={() => setOpenPasswordDialog(false)} maxWidth="sm" fullWidth>
        <form onSubmit={passwordFormik.handleSubmit}>
          <DialogTitle>Change Password</DialogTitle>
          <DialogContent>
            <Box sx={{ display: 'grid', gap: 2, pt: 2 }}>
              <TextField
                fullWidth
                name="currentPassword"
                label="Current Password"
                type={showPassword.current ? 'text' : 'password'}
                value={passwordFormik.values.currentPassword}
                onChange={passwordFormik.handleChange}
                error={passwordFormik.touched.currentPassword && Boolean(passwordFormik.errors.currentPassword)}
                helperText={passwordFormik.touched.currentPassword && passwordFormik.errors.currentPassword}
                InputProps={{
                  endAdornment: (
                    <InputAdornment position="end">
                      <IconButton onClick={() => handleTogglePassword('current')}>
                        {showPassword.current ? <VisibilityOff /> : <Visibility />}
                      </IconButton>
                    </InputAdornment>
                  ),
                }}
              />

              <TextField
                fullWidth
                name="newPassword"
                label="New Password"
                type={showPassword.new ? 'text' : 'password'}
                value={passwordFormik.values.newPassword}
                onChange={passwordFormik.handleChange}
                error={passwordFormik.touched.newPassword && Boolean(passwordFormik.errors.newPassword)}
                helperText={passwordFormik.touched.newPassword && passwordFormik.errors.newPassword}
                InputProps={{
                  endAdornment: (
                    <InputAdornment position="end">
                      <IconButton onClick={() => handleTogglePassword('new')}>
                        {showPassword.new ? <VisibilityOff /> : <Visibility />}
                      </IconButton>
                    </InputAdornment>
                  ),
                }}
              />

              {passwordFormik.values.newPassword && (
                <Box>
                  <LinearProgress
                    variant="determinate"
                    value={getPasswordStrength(passwordFormik.values.newPassword)}
                    sx={{ mb: 1 }}
                  />
                  <Typography variant="caption" color="textSecondary">
                    Password Strength: {Math.round(getPasswordStrength(passwordFormik.values.newPassword))}%
                  </Typography>
                </Box>
              )}

              <TextField
                fullWidth
                name="confirmPassword"
                label="Confirm New Password"
                type={showPassword.confirm ? 'text' : 'password'}
                value={passwordFormik.values.confirmPassword}
                onChange={passwordFormik.handleChange}
                error={passwordFormik.touched.confirmPassword && Boolean(passwordFormik.errors.confirmPassword)}
                helperText={passwordFormik.touched.confirmPassword && passwordFormik.errors.confirmPassword}
                InputProps={{
                  endAdornment: (
                    <InputAdornment position="end">
                      <IconButton onClick={() => handleTogglePassword('confirm')}>
                        {showPassword.confirm ? <VisibilityOff /> : <Visibility />}
                      </IconButton>
                    </InputAdornment>
                  ),
                }}
              />
            </Box>
          </DialogContent>
          <DialogActions>
            <Button onClick={() => setOpenPasswordDialog(false)}>Cancel</Button>
            <Button 
              type="submit" 
              variant="contained" 
              disabled={passwordFormik.isSubmitting}
            >
              Change Password
            </Button>
          </DialogActions>
        </form>
      </Dialog>
    </Box>
  );
};

export default Profile;