import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import { useDispatch, useSelector } from 'react-redux';
import {
  Box,
  Card,
  CardContent,
  TextField,
  Button,
  Typography,
  InputAdornment,
  IconButton,
  CircularProgress,
  Divider,
  useTheme,
  alpha,
} from '@mui/material';
import {
  Visibility,
  VisibilityOff,
  MedicalServices,
  Email,
  LockOutlined,
  WavingHand
} from '@mui/icons-material';
import { login } from '../../features/auth/authSlice';
import { useSnackbar } from 'notistack';

const Login = () => {
  const theme = useTheme();
  const navigate = useNavigate();
  const dispatch = useDispatch();
  const { enqueueSnackbar } = useSnackbar();
  const [showPassword, setShowPassword] = useState(false);
  const [credentials, setCredentials] = useState({
    email: '',
    password: ''
  });
  const [formTouched, setFormTouched] = useState(false);

  const { loading, error, token } = useSelector((state) => state.auth);

  useEffect(() => {
    if (token) {
      navigate('/file-tracker/overview');
    }
  }, [token, navigate]);

  useEffect(() => {
    if (error) {
      enqueueSnackbar(error, {
        variant: 'error',
        anchorOrigin: {
          vertical: 'top',
          horizontal: 'right'
        }
      });
    }
  }, [error, enqueueSnackbar]);

  const handleSubmit = async (e) => {
    e.preventDefault();
    setFormTouched(true);
    
    if (!credentials.email || !credentials.password) {
      enqueueSnackbar('Please fill in all fields', { variant: 'warning' });
      return;
    }
    
    try {
      const resultAction = await dispatch(login(credentials));
      if (login.fulfilled.match(resultAction)) {
        enqueueSnackbar('Welcome back!', { 
          variant: 'success',
          icon: <WavingHand sx={{ mr: 1 }} />
        });
      }
    } catch (err) {
      // Error is handled by the useEffect above
    }
  };

  const handleChange = (e) => {
    const { name, value } = e.target;
    setCredentials(prev => ({
      ...prev,
      [name]: value
    }));
  };

  const isValidEmail = (email) => {
    return /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email);
  };

  return (
    <Box
      sx={{
        minHeight: '100vh',
        display: 'flex',
        alignItems: 'center',
        justifyContent: 'center',
        background: `linear-gradient(135deg, 
          ${alpha(theme.palette.primary.main, 0.8)} 0%, 
          ${alpha(theme.palette.secondary.main, 0.8)} 100%)`,
        p: 2,
      }}
    >
      <Card
        sx={{
          maxWidth: 450,
          width: '100%',
          borderRadius: '20px',
          boxShadow: '0 8px 32px rgba(0,0,0,0.1)',
          overflow: 'visible',
          position: 'relative',
        }}
      >
        <Box
          sx={{
            position: 'absolute',
            top: -45,
            left: '50%',
            transform: 'translateX(-50%)',
            backgroundColor: theme.palette.primary.main,
            borderRadius: '50%',
            width: 90,
            height: 90,
            display: 'flex',
            alignItems: 'center',
            justifyContent: 'center',
            boxShadow: '0 4px 20px rgba(0,0,0,0.1)',
          }}
        >
          <MedicalServices sx={{ fontSize: 45, color: 'white' }} />
        </Box>

        <CardContent sx={{ p: 4, pt: 7 }}>
          <Box
            sx={{
              display: 'flex',
              flexDirection: 'column',
              alignItems: 'center',
              mb: 4,
            }}
          >
            <Typography
              variant="h4"
              component="h1"
              gutterBottom
              sx={{
                fontWeight: 700,
                background: `linear-gradient(45deg, ${theme.palette.primary.main}, ${theme.palette.secondary.main})`,
                backgroundClip: 'text',
                WebkitBackgroundClip: 'text',
                color: 'transparent',
                textAlign: 'center',
              }}
            >
              Welcome to NISH
            </Typography>
            <Typography
              variant="subtitle1"
              sx={{ color: 'text.secondary', textAlign: 'center', mb: 3 }}
            >
              Medical Record Room File Management System
            </Typography>
          </Box>

          <form onSubmit={handleSubmit}>
            <TextField
              fullWidth
              id="email"
              name="email"
              label="Email Address"
              variant="outlined"
              margin="normal"
              value={credentials.email}
              onChange={handleChange}
              disabled={loading}
              error={formTouched && (!credentials.email || !isValidEmail(credentials.email))}
              helperText={formTouched && (!credentials.email 
                ? 'Email is required' 
                : !isValidEmail(credentials.email) 
                ? 'Please enter a valid email' 
                : ' ')}
              InputProps={{
                startAdornment: (
                  <InputAdornment position="start">
                    <Email color="action" />
                  </InputAdornment>
                ),
              }}
              sx={{
                '& .MuiOutlinedInput-root': {
                  borderRadius: '12px',
                },
              }}
            />

            <TextField
              fullWidth
              id="password"
              name="password"
              label="Password"
              type={showPassword ? 'text' : 'password'}
              variant="outlined"
              margin="normal"
              value={credentials.password}
              onChange={handleChange}
              disabled={loading}
              error={formTouched && !credentials.password}
              helperText={formTouched && !credentials.password ? 'Password is required' : ' '}
              InputProps={{
                startAdornment: (
                  <InputAdornment position="start">
                    <LockOutlined color="action" />
                  </InputAdornment>
                ),
                endAdornment: (
                  <InputAdornment position="end">
                    <IconButton
                      aria-label="toggle password visibility"
                      onClick={() => setShowPassword(!showPassword)}
                      onMouseDown={(e) => e.preventDefault()}
                      edge="end"
                    >
                      {showPassword ? <VisibilityOff /> : <Visibility />}
                    </IconButton>
                  </InputAdornment>
                ),
              }}
              sx={{
                '& .MuiOutlinedInput-root': {
                  borderRadius: '12px',
                },
              }}
            />

            <Button
              fullWidth
              type="submit"
              variant="contained"
              size="large"
              sx={{
                mt: 3,
                mb: 2,
                borderRadius: '12px',
                height: '48px',
                textTransform: 'none',
                fontSize: '1.1rem',
                background: `linear-gradient(45deg, ${theme.palette.primary.main}, ${theme.palette.secondary.main})`,
                boxShadow: '0 4px 10px rgba(0,0,0,0.1)',
                '&:hover': {
                  background: `linear-gradient(45deg, ${theme.palette.primary.dark}, ${theme.palette.secondary.dark})`,
                },
              }}
              disabled={loading}
            >
              {loading ? (
                <CircularProgress size={24} color="inherit" />
              ) : (
                'Sign In'
              )}
            </Button>

            <Divider sx={{ my: 2 }}>
              <Typography variant="body2" color="text.secondary">
                Need Help?
              </Typography>
            </Divider>

            <Box sx={{ display: 'flex', justifyContent: 'space-between', mt: 1 }}>
              <Button
                color="primary"
                size="small"
                sx={{ textTransform: 'none' }}
                onClick={() => navigate('/forgot-password')}
              >
                Forgot Password?
              </Button>
              <Button
                color="primary"
                size="small"
                sx={{ textTransform: 'none' }}
                onClick={() => navigate('/contact-support')}
              >
                Contact Support
              </Button>
            </Box>
          </form>
        </CardContent>
      </Card>
    </Box>
  );
};

export default Login;