import React, { useState } from 'react';
import {
  Box,
  Card,
  TextField,
  Button,
  Typography,
  Stack,
  Chip,
  IconButton,
  Divider,
  Dialog,
  DialogTitle,
  DialogContent,
  DialogActions,
  CircularProgress,
  Alert,
} from '@mui/material';
import { Add as AddIcon, Delete as DeleteIcon } from '@mui/icons-material';
import { useFormik } from 'formik';
import * as yup from 'yup';
import { useSnackbar } from 'notistack';
import { useSelector } from 'react-redux';
import { jwtDecode } from 'jwt-decode';
import api from '../../../api/axios';

// Validation schema for rack creation
const rackSchema = yup.object({
  rackId: yup.string()
    .required('Rack ID is required')
    .matches(/^[A-Za-z0-9-]+$/, 'Only alphanumeric characters and hyphens are allowed')
    .min(2, 'Rack ID must be at least 2 characters')
    .max(20, 'Rack ID must be at most 20 characters'),
  subDivision: yup.string()
    .matches(/^[A-Za-z0-9-]*$/, 'Only alphanumeric characters and hyphens are allowed')
});

const CreateRack = () => {
  const [subDivisions, setSubDivisions] = useState([]);
  const [confirmDialog, setConfirmDialog] = useState(false);
  const [loading, setLoading] = useState(false);
  const { enqueueSnackbar } = useSnackbar();
  
  // Get admin ID from redux store
  const token = useSelector(state => state.auth.token);
  const adminId = token ? jwtDecode(token).userId : null;

  const formik = useFormik({
    initialValues: {
      rackId: '',
      subDivision: ''
    },
    validationSchema: rackSchema,
    onSubmit: async () => {
      if (subDivisions.length === 0) {
        enqueueSnackbar('At least one subdivision is required', { variant: 'error' });
        return;
      }
      setConfirmDialog(true);
    }
  });

  const handleAddSubDivision = () => {
    if (!formik.values.subDivision) return;
    
    if (subDivisions.includes(formik.values.subDivision)) {
      enqueueSnackbar('Subdivision already exists', { variant: 'error' });
      return;
    }

    setSubDivisions([...subDivisions, formik.values.subDivision]);
    formik.setFieldValue('subDivision', '');
  };

  const handleDeleteSubDivision = (index) => {
    const newSubDivisions = subDivisions.filter((_, i) => i !== index);
    setSubDivisions(newSubDivisions);
  };

  const handleConfirm = async () => {
    setLoading(true);
    try {
      await api.post('/racks', {
        adminId,
        rackId: formik.values.rackId,
        subDivision: subDivisions
      });

      enqueueSnackbar('Rack created successfully', { variant: 'success' });
      
      // Reset form and state
      formik.resetForm();
      setSubDivisions([]);
      setConfirmDialog(false);
    } catch (error) {
      enqueueSnackbar(error.response?.data?.message || 'Error creating rack', { 
        variant: 'error' 
      });
    } finally {
      setLoading(false);
    }
  };

  return (
    <Box sx={{ p: 3 }}>
      <Typography variant="h4" gutterBottom>
        Create New Rack
      </Typography>

      <Card sx={{ p: 3 }}>
        <form onSubmit={formik.handleSubmit}>
          <Stack spacing={3}>
            {/* Rack ID Input */}
            <TextField
              fullWidth
              name="rackId"
              label="Rack ID"
              value={formik.values.rackId}
              onChange={formik.handleChange}
              error={formik.touched.rackId && Boolean(formik.errors.rackId)}
              helperText={formik.touched.rackId && formik.errors.rackId}
              disabled={loading}
            />

            {/* Subdivisions Input */}
            <Stack direction="row" spacing={2}>
              <TextField
                fullWidth
                name="subDivision"
                label="Add Subdivision"
                value={formik.values.subDivision}
                onChange={formik.handleChange}
                error={formik.touched.subDivision && Boolean(formik.errors.subDivision)}
                helperText={formik.touched.subDivision && formik.errors.subDivision}
                disabled={loading}
              />
              <Button
                variant="contained"
                onClick={handleAddSubDivision}
                disabled={!formik.values.subDivision || loading}
                startIcon={<AddIcon />}
              >
                Add
              </Button>
            </Stack>

            {/* Subdivisions Display */}
            {subDivisions.length > 0 && (
              <Box>
                <Typography variant="subtitle2" gutterBottom>
                  Subdivisions:
                </Typography>
                <Stack direction="row" flexWrap="wrap" gap={1}>
                  {subDivisions.map((sub, index) => (
                    <Chip
                      key={index}
                      label={sub}
                      onDelete={() => handleDeleteSubDivision(index)}
                      disabled={loading}
                    />
                  ))}
                </Stack>
              </Box>
            )}

            <Divider />

            {/* Submit Button */}
            <Button
              type="submit"
              variant="contained"
              size="large"
              disabled={loading}
            >
              Create Rack
            </Button>
          </Stack>
        </form>
      </Card>

      {/* Confirmation Dialog */}
      <Dialog 
        open={confirmDialog} 
        onClose={() => !loading && setConfirmDialog(false)}
      >
        <DialogTitle>Confirm Rack Creation</DialogTitle>
        <DialogContent>
          <Stack spacing={2}>
            <Typography>
              Are you sure you want to create a rack with the following details?
            </Typography>
            <Alert severity="info">
              <Typography variant="subtitle2">
                Rack ID: {formik.values.rackId}
              </Typography>
              <Typography variant="subtitle2">
                Subdivisions: {subDivisions.join(', ')}
              </Typography>
            </Alert>
          </Stack>
        </DialogContent>
        <DialogActions>
          <Button 
            onClick={() => setConfirmDialog(false)} 
            disabled={loading}
          >
            Cancel
          </Button>
          <Button 
            onClick={handleConfirm}
            variant="contained"
            disabled={loading}
          >
            {loading ? <CircularProgress size={24} /> : 'Confirm'}
          </Button>
        </DialogActions>
      </Dialog>
    </Box>
  );
};

export default CreateRack;