import React, { useEffect, useState } from 'react';
import {
  LineChart,
  Line,
  XAxis,
  YAxis,
  CartesianGrid,
  Tooltip,
  ResponsiveContainer,
  Legend,
  Area,
  AreaChart
} from 'recharts';
import {
  Typography,
  Box,
  Skeleton,
  useTheme,
  alpha,
  Stack,
  Chip,
  IconButton,
  Card,
  CardContent,
} from '@mui/material';
import {
  TrendingUp,
  TrendingDown,
  SwapHoriz,
  CalendarToday,
  BarChart,
  ShowChart
} from '@mui/icons-material';
import api from '../../../../api/axios';
import { useSelector } from 'react-redux';
import { jwtDecode } from 'jwt-decode';

const CustomTooltip = ({ active, payload, label }) => {
  const theme = useTheme();
  
  if (active && payload && payload.length) {
    return (
      <Card
        elevation={3}
        sx={{
          bgcolor: 'background.paper',
          border: `1px solid ${alpha(theme.palette.primary.main, 0.1)}`,
          borderRadius: 2,
          minWidth: 200
        }}
      >
        <CardContent sx={{ p: 2 }}>
          <Typography variant="subtitle2" color="text.secondary" gutterBottom>
            {label}
          </Typography>
          <Stack direction="row" alignItems="center" spacing={1}>
            <Box
              sx={{
                width: 8,
                height: 8,
                borderRadius: '50%',
                bgcolor: theme.palette.primary.main
              }}
            />
            <Typography variant="h6" color="primary" sx={{ fontWeight: 600 }}>
              {payload[0].value} Files
            </Typography>
          </Stack>
        </CardContent>
      </Card>
    );
  }
  return null;
};

const DailyTransfersChart = () => {
  const [data, setData] = useState([]);
  const [loading, setLoading] = useState(true);
  const [chartType, setChartType] = useState('area');
  const [stats, setStats] = useState({
    totalTransfers: 0,
    averageDaily: 0,
    trend: 0,
    peakDay: { date: '', count: 0 }
  });

  const token = useSelector(state => state.auth.token);
  const userId = token ? jwtDecode(token).userId : null;
  const theme = useTheme();

  useEffect(() => {
    const fetchData = async () => {
      try {
        const response = await api.get(`/reports/week-dispatch?userId=${userId}`);
        if (response.data.success) {
          const formattedData = response.data.data.map(item => ({
            ...item,
            date: new Date(item.date).toLocaleDateString('en-US', {
              month: 'short',
              day: 'numeric'
            }),
            dispatchCount: Number(item.dispatchCount)
          }));

          // Calculate statistics
          const total = formattedData.reduce((sum, item) => sum + item.dispatchCount, 0);
          const avg = total / formattedData.length;
          const trend = ((formattedData[formattedData.length - 1]?.dispatchCount || 0) -
            (formattedData[0]?.dispatchCount || 0)) /
            (formattedData[0]?.dispatchCount || 1) * 100;
          const peak = formattedData.reduce((max, item) => 
            item.dispatchCount > max.count ? 
            { date: item.date, count: item.dispatchCount } : max, 
            { date: '', count: 0 }
          );

          setData(formattedData);
          setStats({
            totalTransfers: total,
            averageDaily: Math.round(avg * 10) / 10,
            trend: Math.round(trend),
            peakDay: peak
          });
        }
      } catch (error) {
        console.error('Error fetching transfer data:', error);
      } finally {
        setLoading(false);
      }
    };

    if (userId) {
      fetchData();
    }
  }, [userId]);

  if (loading) {
    return (
      <Box sx={{ width: '100%' }}>
        <Skeleton variant="text" width="200px" sx={{ mb: 2 }} />
        <Skeleton variant="rectangular" height={300} />
      </Box>
    );
  }

  const renderChart = () => {
    const ChartComponent = chartType === 'area' ? AreaChart : LineChart;
    
    return (
      <ChartComponent
        data={data}
        margin={{ top: 10, right: 30, left: 0, bottom: 0 }}
      >
        <defs>
          <linearGradient id="colorTransfers" x1="0" y1="0" x2="0" y2="1">
            <stop
              offset="5%"
              stopColor={theme.palette.primary.main}
              stopOpacity={0.2}
            />
            <stop
              offset="95%"
              stopColor={theme.palette.primary.main}
              stopOpacity={0}
            />
          </linearGradient>
        </defs>
        <CartesianGrid
          strokeDasharray="3 3"
          stroke={alpha(theme.palette.text.primary, 0.1)}
        />
        <XAxis
          dataKey="date"
          stroke={theme.palette.text.secondary}
          tick={{ fill: theme.palette.text.secondary }}
        />
        <YAxis
          stroke={theme.palette.text.secondary}
          tick={{ fill: theme.palette.text.secondary }}
        />
        <Tooltip content={<CustomTooltip />} />
        {chartType === 'area' ? (
          <Area
            type="monotone"
            dataKey="dispatchCount"
            name="Files Dispatched"
            stroke={theme.palette.primary.main}
            fill="url(#colorTransfers)"
            strokeWidth={2}
          />
        ) : (
          <Line
            type="monotone"
            dataKey="dispatchCount"
            name="Files Dispatched"
            stroke={theme.palette.primary.main}
            strokeWidth={2}
            dot={{ stroke: theme.palette.primary.main, strokeWidth: 2, r: 4 }}
            activeDot={{ r: 8 }}
          />
        )}
      </ChartComponent>
    );
  };

  return (
    <Box sx={{ width: '100%' }}>
      <Stack
        direction="row"
        justifyContent="space-between"
        alignItems="center"
        mb={3}
      >
        <Typography variant="h6" fontWeight="600">
          File Transfers - Last 7 Days
        </Typography>
        <Stack direction="row" spacing={1}>
          <IconButton
            size="small"
            onClick={() => setChartType('line')}
            color={chartType === 'line' ? 'primary' : 'default'}
          >
            <ShowChart />
          </IconButton>
          <IconButton
            size="small"
            onClick={() => setChartType('area')}
            color={chartType === 'area' ? 'primary' : 'default'}
          >
            <BarChart />
          </IconButton>
        </Stack>
      </Stack>

      <Stack
        direction={{ xs: 'column', sm: 'row' }}
        spacing={2}
        sx={{ mb: 3 }}
      >
        <Chip
          icon={<SwapHoriz />}
          label={`Total: ${stats.totalTransfers}`}
          color="primary"
          variant="outlined"
        />
        <Chip
          icon={<CalendarToday />}
          label={`Daily Avg: ${stats.averageDaily}`}
          color="secondary"
          variant="outlined"
        />
        <Chip
          icon={stats.trend >= 0 ? <TrendingUp /> : <TrendingDown />}
          label={`${stats.trend}% Trend`}
          color={stats.trend >= 0 ? "success" : "error"}
          variant="outlined"
        />
      </Stack>

      <Box sx={{ width: '100%', height: 300 }}>
        <ResponsiveContainer>
          {renderChart()}
        </ResponsiveContainer>
      </Box>

      <Typography
        variant="caption"
        color="text.secondary"
        sx={{ mt: 2, display: 'block', textAlign: 'center' }}
      >
        Peak Day: {stats.peakDay.date} ({stats.peakDay.count} files)
      </Typography>
    </Box>
  );
};

export default DailyTransfersChart;