import React, { useState, useEffect } from 'react';
import {
  AppBar,
  Toolbar,
  IconButton,
  Typography,
  Badge,
  Avatar,
  Menu,
  MenuItem,
  Box,
  List,
  ListItem,
  ListItemText,
  Divider,
  Fade,
  Button,
  Tooltip,
} from '@mui/material';
import {
  Menu as MenuIcon,
  Notifications as NotificationsIcon,
  Brightness4,
  Brightness7,
  Dashboard as DashboardIcon,
  DevicesOther as DevicesIcon,
  SettingsRemote as RemoteIcon,
  Warning as WarningIcon,
  Update as UpdateIcon,
  Info as InfoIcon,
  Error as ErrorIcon,
  Message as MessageIcon,
  Logout as LogoutIcon,
  AccountCircle as AccountCircleIcon,
  Settings as SettingsIcon,
  DoneAll as DoneAllIcon,
  MoreVert as MoreVertIcon,
  Visibility as VisibilityIcon,
  VisibilityOff as VisibilityOffIcon,
} from '@mui/icons-material';
import { useNavigate } from 'react-router-dom';
import notificationService from '../../../features/services/notificationService';
import { io } from 'socket.io-client';

const NavBar = ({ open, handleDrawerToggle, mode, toggleColorMode }) => {
  const [anchorEl, setAnchorEl] = useState(null);
  const [notificationsAnchor, setNotificationsAnchor] = useState(null);
  const [notifications, setNotifications] = useState([]);
  const [unreadCount, setUnreadCount] = useState(0);
  const [notificationActionAnchor, setNotificationActionAnchor] = useState(null);
  const [selectedNotification, setSelectedNotification] = useState(null);
  const navigate = useNavigate();

  // Enhanced styles for the notification menu
  const notificationMenuStyles = {
    elevation: 3,
    sx: {
      overflow: 'visible',
      mt: 1.5,
      '& .MuiPaper-root': {
        borderRadius: 2,
        minWidth: 320,
        maxWidth: 400,
        bgcolor: mode === 'dark' ? 'grey.900' : 'grey.10',
        boxShadow: '0 4px 20px rgba(0,0,0,0.1)',
      },
    },
  };

  // Format time ago function
  const formatTimeAgo = (date) => {
    const now = new Date();
    const diffInSeconds = Math.floor((now - new Date(date)) / 1000);
    
    if (diffInSeconds < 60) return `${diffInSeconds}s ago`;
    if (diffInSeconds < 3600) return `${Math.floor(diffInSeconds / 60)}m ago`;
    if (diffInSeconds < 86400) return `${Math.floor(diffInSeconds / 3600)}h ago`;
    return new Date(date).toLocaleDateString();
  };

  useEffect(() => {
    const token = localStorage.getItem('token');
    if (!token) {
      console.warn('No token found, skipping notification setup');
      return;
    }

    // Fetch existing notifications
    const fetchNotifications = async () => {
      try {
        const response = await notificationService.getNotifications(token);
        setNotifications(response.data || []);
        setUnreadCount((response.data || []).filter(n => !n.read).length || 0);
      } catch (error) {
        console.error('Error fetching notifications:', error);
      }
    };

    fetchNotifications();

    // Set up Socket.IO
    const socket = io(process.env.REACT_APP_API_UR || 'http://localhost:4000', {
      transports: ['websocket', 'polling'],
      auth: { token },
    });

    socket.on('connect', () => {
      console.log('Socket.IO connected');
      socket.emit('authenticate', token);
    });

    socket.on('notification', (newNotification) => {
      console.log('New notification received:', newNotification);
      setNotifications(prev => [newNotification, ...prev]);
      setUnreadCount(prev => prev + 1);
    });

    socket.on('notificationUpdate', (updatedNotification) => {
      console.log('Notification updated:', updatedNotification);
      setNotifications(prev =>
        prev.map(n =>
          n._id === updatedNotification._id ? updatedNotification : n
        )
      );
      setUnreadCount(prev => (updatedNotification.read ? prev - 1 : prev + 1));
    });

    socket.on('connect_error', (error) => {
      console.error('Socket.IO connection error:', error.message);
    });

    socket.on('error', (error) => {
      console.error('Socket.IO error:', error.message);
    });

    socket.on('disconnect', (reason) => {
      console.log('Socket.IO disconnected:', reason);
    });

    // Cleanup on unmount
    return () => {
      socket.disconnect();
    };
  }, []);

  const handleProfileMenuOpen = (event) => {
    setAnchorEl(event.currentTarget);
  };

  const handleNotificationsOpen = (event) => {
    setNotificationsAnchor(event.currentTarget);
  };

  const handleMenuClose = () => {
    setAnchorEl(null);
    setNotificationsAnchor(null);
    setNotificationActionAnchor(null);
    setSelectedNotification(null);
  };

  const handleLogout = () => {
    localStorage.clear();
    handleMenuClose();
    navigate('/login');
  };

  const handleNotificationClick = async (notification) => {
    // Navigate to appropriate page or perform appropriate action based on notification type
    console.log('Notification clicked:', notification);
    
    // Only mark as read if it's currently unread
    if (!notification.read) {
      await markNotificationAsRead(notification._id);
    }
  };

  const markNotificationAsRead = async (notificationId) => {
    try {
      const token = localStorage.getItem('token');
      await notificationService.markNotificationAsRead(notificationId, token);
      setNotifications(notifications.map(n =>
        n._id === notificationId ? { ...n, read: true } : n
      ));
      setUnreadCount(prev => prev - 1);
    } catch (error) {
      console.error('Error marking notification as read:', error);
    }
  };

  const markNotificationAsUnread = async (notificationId) => {
    try {
      const token = localStorage.getItem('token');
      await notificationService.markNotificationAsUnread(notificationId, token);
      setNotifications(notifications.map(n =>
        n._id === notificationId ? { ...n, read: false } : n
      ));
      setUnreadCount(prev => prev + 1);
    } catch (error) {
      console.error('Error marking notification as unread:', error);
    }
  };

  const toggleNotificationReadStatus = async (notification) => {
    try {
      const token = localStorage.getItem('token');
      await notificationService.toggleNotificationReadStatus(notification, token);
      
      // Update local state
      setNotifications(notifications.map(n =>
        n._id === notification._id ? { ...n, read: !n.read } : n
      ));
      
      // Update unread count
      setUnreadCount(prev => notification.read ? prev + 1 : prev - 1);
      
      // Close the action menu
      handleMenuClose();
    } catch (error) {
      console.error('Error toggling notification status:', error);
    }
  };

  const markAllNotificationsAsRead = async () => {
    try {
      const token = localStorage.getItem('token');
      await notificationService.markAllNotificationsAsRead(token);
      
      // Update local state
      setNotifications(notifications.map(n => ({ ...n, read: true })));
      setUnreadCount(0);
    } catch (error) {
      console.error('Error marking all notifications as read:', error);
    }
  };

  const handleNotificationActionClick = (event, notification) => {
    event.stopPropagation();
    setSelectedNotification(notification);
    setNotificationActionAnchor(event.currentTarget);
  };

  // Helper functions for notification icons and dots
  const getNotificationIcon = (notification) => {
    // Determine icon based on notification type/content
    // You can customize this based on your notification structure
    if (!notification) return <NotificationsIcon fontSize="small" />;
    
    // Example: Choose icon based on a 'type' field that might exist in your notification object
    // If your notifications don't have a type field, you could parse the message text
    const type = notification.type || parseNotificationType(notification.message);
    
    switch(type) {
      case 'alert':
        return <ErrorIcon fontSize="small" />;
      case 'update':
        return <UpdateIcon fontSize="small" />;
      case 'message':
        return <MessageIcon fontSize="small" />;
      case 'warning':
        return <WarningIcon fontSize="small" />;
      default:
        return <NotificationsIcon fontSize="small" />;
    }
  };
  
  // Helper function to parse notification type from message text (if needed)
  const parseNotificationType = (message) => {
    if (!message) return 'default';
    
    // Example logic to determine type based on message content
    const messageLower = message.toLowerCase();
    if (messageLower.includes('alert') || messageLower.includes('critical'))
      return 'alert';
    if (messageLower.includes('update') || messageLower.includes('upgraded'))
      return 'update';
    if (messageLower.includes('message') || messageLower.includes('sent'))
      return 'message';
    if (messageLower.includes('warning') || messageLower.includes('caution'))
      return 'warning';
    
    return 'default';
  };
  
  const getNotificationIconColor = (notification) => {
    // Return color based on notification type/importance
    if (!notification) return 'inherit';
    
    const type = notification.type || parseNotificationType(notification.message);
    
    switch(type) {
      case 'alert':
        return '#F44336'; // Red
      case 'warning':
        return '#FFC107'; // Yellow
      case 'update':
        return '#2196F3'; // Blue
      case 'message':
        return '#4CAF50'; // Green
      default:
        return notification.read ? 'text.secondary' : 'inherit';
    }
  };
  
  const getNotificationDotsCount = (notification) => {
    // Determine how many dots to show based on notification priority/importance
    if (!notification) return 1;
    
    // Example: Base dot count on priority field or determine from message
    const priority = notification.priority || getNotificationPriority(notification.message);
    
    // Return 1-3 dots based on priority level
    return Math.min(Math.max(priority, 1), 3);
  };
  
  const getNotificationPriority = (message) => {
    if (!message) return 1;
    
    // Simple priority detection from message text
    const messageLower = message.toLowerCase();
    if (messageLower.includes('urgent') || messageLower.includes('critical') || messageLower.includes('immediate'))
      return 3; // High priority
    if (messageLower.includes('important') || messageLower.includes('attention'))
      return 2; // Medium priority
    
    return 1; // Default priority
  };
  
  const getNotificationDotColor = (notification, index) => {
    // Return different colors for different dot positions
    if (!notification) return '#4CAF50';
    
    const type = notification.type || parseNotificationType(notification.message);
    
    // Base color on notification type
    let baseColor;
    switch(type) {
      case 'alert':
        baseColor = '#F44336'; // Red for alerts
        break;
      case 'warning':
        baseColor = '#FFC107'; // Yellow for warnings
        break;
      case 'update':
        baseColor = '#2196F3'; // Blue for updates
        break;
      case 'message':
        baseColor = '#4CAF50'; // Green for messages
        break;
      default:
        baseColor = '#9C27B0'; // Purple for others
    }
    
    // Slightly vary colors for different dots
    switch(index) {
      case 0: return baseColor;
      case 1: return lightenDarkenColor(baseColor, 20); // Slightly lighter
      case 2: return lightenDarkenColor(baseColor, -20); // Slightly darker
      default: return baseColor;
    }
  };
  
  // Helper function to lighten or darken a color
  const lightenDarkenColor = (color, amount) => {
    let usePound = false;
    
    if (color[0] === '#') {
      color = color.slice(1);
      usePound = true;
    }
    
    const num = parseInt(color, 16);
    let r = (num >> 16) + amount;
    let g = ((num >> 8) & 0x00FF) + amount;
    let b = (num & 0x0000FF) + amount;
    
    r = Math.min(Math.max(0, r), 255);
    g = Math.min(Math.max(0, g), 255);
    b = Math.min(Math.max(0, b), 255);
    
    return (usePound ? '#' : '') + (
      (b | (g << 8) | (r << 16)) | 0x1000000
    ).toString(16).slice(1);
  };

  return (
    <AppBar position="fixed" sx={{ zIndex: (theme) => theme.zIndex.drawer + 1 }}>
      <Toolbar>
        <Typography variant="h6" noWrap component="div" sx={{ display: { xs: 'none', sm: 'block' } }}>
          Device Management
        </Typography>

        <Box sx={{ flexGrow: 1 }} />

        <Box sx={{ display: 'flex', alignItems: 'center' }}>
          <IconButton color="inherit" onClick={toggleColorMode}>
            {mode === 'dark' ? <Brightness7 /> : <Brightness4 />}
          </IconButton>

          <IconButton
            color="inherit"
            onClick={handleNotificationsOpen}
            aria-label="show notifications"
          >
            <Badge badgeContent={unreadCount} color="error">
              <NotificationsIcon />
            </Badge>
          </IconButton>

          <IconButton
            edge="end"
            onClick={handleProfileMenuOpen}
            color="inherit"
            aria-label="profile menu"
          >
            <Avatar sx={{ width: 32, height: 32 }}>U</Avatar>
          </IconButton>
        </Box>

        <Menu
          anchorEl={anchorEl}
          open={Boolean(anchorEl)}
          onClose={handleMenuClose}
          anchorOrigin={{ vertical: 'bottom', horizontal: 'right' }}
          transformOrigin={{ vertical: 'top', horizontal: 'right' }}
          TransitionComponent={Fade}
          TransitionProps={{ timeout: 200 }}
          sx={{
            mt: 1.5,
            '& .MuiPaper-root': {
              borderRadius: 2,
              minWidth: 180,
              boxShadow: '0px 5px 15px rgba(0,0,0,0.15)',
              bgcolor: mode === 'dark' ? 'grey.900' : 'background.paper',
              padding: 1,
              '& .MuiMenuItem-root': {
                borderRadius: 1,
                margin: '2px 0',
                px: 1.5,
                py: 1,
                '&:hover': {
                  bgcolor: mode === 'dark' ? 'grey.800' : 'grey.100',
                },
              },
            },
          }}
        >
          <Box sx={{ p: 1, pb: 1.5 }}>
            <Typography 
              variant="subtitle2" 
              sx={{ 
                px: 1, 
                pb: 1,
                fontWeight: 'medium',
                color: 'text.primary'
              }}
            >
              User Settings
            </Typography>
            <Divider sx={{ mb: 1 }} />
            
            <MenuItem onClick={() => navigate('/device-portal/my-profile')} sx={{ display: 'flex', alignItems: 'center' }}>
              <Avatar sx={{ width: 20, height: 20, mr: 1.5 }}>U</Avatar>
              Profile
            </MenuItem>
            
            <MenuItem onClick={() => navigate('/device-portal/all-device')} sx={{ display: 'flex', alignItems: 'center' }}>
              <Box sx={{ mr: 1.5, color: 'text.secondary' }}>
                <DevicesIcon fontSize="small" />
              </Box>
              My Devices
            </MenuItem>
            
            <MenuItem onClick={() => navigate('/device-portal/overview')} sx={{ display: 'flex', alignItems: 'center' }}>
              <Box sx={{ mr: 1.5, color: 'text.secondary' }}>
                <DashboardIcon fontSize="small" />
              </Box>
              Dashboard
            </MenuItem>
            
            <Divider sx={{ my: 1 }} />
            
            <MenuItem 
              onClick={handleLogout} 
              sx={{ 
                display: 'flex', 
                alignItems: 'center',
                color: 'error.main',
                '&:hover': {
                  bgcolor: mode === 'dark' ? 'rgba(244, 67, 54, 0.15)' : 'rgba(244, 67, 54, 0.08)',
                },
              }}
            >
              <Box sx={{ mr: 1.5, color: 'inherit' }}>
                <LogoutIcon fontSize="small" />
              </Box>
              Logout
            </MenuItem>
          </Box>
        </Menu>

        <Menu
          anchorEl={notificationsAnchor}
          open={Boolean(notificationsAnchor)}
          onClose={handleMenuClose}
          anchorOrigin={{ vertical: 'bottom', horizontal: 'right' }}
          transformOrigin={{ vertical: 'top', horizontal: 'right' }}
          TransitionComponent={Fade}
          TransitionProps={{ timeout: 200 }}
          {...notificationMenuStyles}
        >
          <Box sx={{ p: 1, bgcolor: 'background.paper' }}>
            <Box sx={{ 
              px: 2, 
              py: 1, 
              display: 'flex', 
              justifyContent: 'space-between', 
              alignItems: 'center' 
            }}>
              <Typography 
                variant="subtitle2" 
                sx={{ 
                  fontWeight: 'medium',
                  color: 'text.primary'
                }}
              >
                Notifications ({notifications.length})
              </Typography>
              
              {notifications.length > 0 && (
                <Tooltip title="Mark all as read">
                  <IconButton 
                    size="small" 
                    onClick={markAllNotificationsAsRead}
                    disabled={unreadCount === 0}
                  >
                    <DoneAllIcon fontSize="small" />
                  </IconButton>
                </Tooltip>
              )}
            </Box>
            <Divider />
            {notifications.length === 0 ? (
              <Box sx={{ p: 2, textAlign: 'center' }}>
                <Typography 
                  variant="body2" 
                  color="text.secondary"
                  sx={{ fontStyle: 'italic' }}
                >
                  No new notifications
                </Typography>
              </Box>
            ) : (
              <List dense sx={{ maxHeight: 300, overflow: 'auto' }}>
                {notifications.map((notification) => (
                  <ListItem
                    key={notification._id}
                    button
                    onClick={() => handleNotificationClick(notification)}
                    sx={{
                      py: 1.5,
                      px: 2,
                      transition: 'all 0.2s',
                      '&:hover': {
                        bgcolor: mode === 'dark' ? 'grey.800' : 'grey.100',
                      },
                      bgcolor: notification.read ? 'transparent' : 
                        mode === 'dark' ? 'grey.800' : 'grey.200',
                      position: 'relative',
                    }}
                    secondaryAction={
                      <IconButton 
                        edge="end" 
                        size="small"
                        onClick={(e) => handleNotificationActionClick(e, notification)}
                        sx={{ mr: -1 }}
                      >
                        <MoreVertIcon fontSize="small" />
                      </IconButton>
                    }
                  >
                    {/* Notification icon at the start */}
                    <Box 
                      sx={{ 
                        mr: 2, 
                        display: 'flex', 
                        alignItems: 'center',
                        color: getNotificationIconColor(notification)
                      }}
                    >
                      {getNotificationIcon(notification)}
                    </Box>
                    
                    <ListItemText
                      primary={
                        <Typography
                          variant="body2"
                          sx={{
                            fontWeight: notification.read ? 'normal' : 'medium',
                            color: notification.read ? 'text.secondary' : 'text.primary',
                            pr: 4, // Make space for the action button
                          }}
                        >
                          {notification.message}
                        </Typography>
                      }
                      secondary={
                        <Typography
                          variant="caption"
                          sx={{ 
                            color: 'text.secondary',
                            display: 'block',
                            mt: 0.5,
                          }}
                        >
                          {formatTimeAgo(notification.createdAt)}
                        </Typography>
                      }
                    />
                    
                    {/* Colorful dots at the end */}
                    <Box sx={{ display: 'flex', ml: 1, mr: 3 }}>
                      {Array.from({ length: getNotificationDotsCount(notification) }).map((_, index) => (
                        <Box
                          key={index}
                          sx={{
                            width: 6,
                            height: 6,
                            bgcolor: getNotificationDotColor(notification, index),
                            borderRadius: '50%',
                            ml: 0.3,
                            opacity: notification.read ? 0.5 : 1
                          }}
                        />
                      ))}
                    </Box>
                  </ListItem>
                ))}
              </List>
            )}
          </Box>
        </Menu>
        
        {/* Notification actions menu */}
        <Menu
          anchorEl={notificationActionAnchor}
          open={Boolean(notificationActionAnchor)}
          onClose={handleMenuClose}
          anchorOrigin={{ vertical: 'top', horizontal: 'right' }}
          transformOrigin={{ vertical: 'top', horizontal: 'right' }}
          sx={{
            '& .MuiPaper-root': {
              borderRadius: 2,
              minWidth: 150,
              boxShadow: '0px 5px 15px rgba(0,0,0,0.1)',
              bgcolor: mode === 'dark' ? 'grey.900' : 'background.paper',
            },
          }}
        >
          <MenuItem 
            onClick={() => selectedNotification && toggleNotificationReadStatus(selectedNotification)}
            sx={{ py: 1 }}
          >
            <Box sx={{ mr: 1.5, color: 'text.secondary' }}>
              {selectedNotification?.read ? (
                <VisibilityOffIcon fontSize="small" />
              ) : (
                <VisibilityIcon fontSize="small" />
              )}
            </Box>
            {selectedNotification?.read ? 'Mark as unread' : 'Mark as read'}
          </MenuItem>
        </Menu>
      </Toolbar>
    </AppBar>
  );
};

export default NavBar;