import React, { useState, useContext } from 'react';
import {
  AppBar,
  Box,
  Toolbar,
  IconButton,
  Typography,
  Menu,
  MenuItem,
  Tooltip,
  Avatar,
  useTheme,
  Badge,
  Divider,
} from '@mui/material';
import {
  Menu as MenuIcon,
  AccountCircle,
  Brightness4,
  Brightness7,
  ExitToApp,
  LocalHospital,
  NotificationsNone,
  Settings,
  Person,
} from '@mui/icons-material';
import { useDispatch } from 'react-redux';
import { useNavigate } from 'react-router-dom';
import { logout } from '../../../../features/auth/authSlice';
import { useSnackbar } from 'notistack';
import { ColorModeContext } from '../../../../App';

const DRAWER_WIDTH = 240;

const NavBar = ({ open, handleDrawerToggle }) => {
  const [anchorEl, setAnchorEl] = useState(null);
  const dispatch = useDispatch();
  const navigate = useNavigate();
  const { enqueueSnackbar } = useSnackbar();
  const theme = useTheme();
  const colorMode = useContext(ColorModeContext) || {
    toggleColorMode: () => {
      console.warn('ColorMode context not available');
      enqueueSnackbar('Theme toggle unavailable', { variant: 'warning' });
    }
  };

  const handleMenu = (event) => {
    setAnchorEl(event.currentTarget);
  };

  const handleClose = () => {
    setAnchorEl(null);
  };

  const handleProfile = () => {
    handleClose();
    navigate('/file-tracker/profile');
  };

  const handleLogout = async () => {
    try {
      await dispatch(logout()).unwrap();
      enqueueSnackbar('Logged out successfully', { variant: 'success' });
      navigate('/file-tracker/login');
    } catch (error) {
      enqueueSnackbar('Logout failed', { variant: 'error' });
    }
  };

  return (
    <AppBar
      position="fixed"
      elevation={0}
      sx={{
        width: { sm: `calc(100% - ${open ? DRAWER_WIDTH : 64}px)` },
        ml: { sm: `${open ? DRAWER_WIDTH : 64}px` },
        transition: theme.transitions.create(['margin', 'width'], {
          easing: theme.transitions.easing.sharp,
          duration: theme.transitions.duration.leavingScreen,
        }),
        background: theme.palette.mode === 'light' 
          ? 'linear-gradient(135deg, #ffffff 0%, #f5f5f5 100%)'
          : 'linear-gradient(135deg, #1a237e 0%, #121212 100%)',
        borderBottom: `1px solid ${theme.palette.divider}`,
      }}
    >
      <Toolbar>
        <IconButton
          color={theme.palette.mode === 'light' ? 'primary' : 'inherit'}
          aria-label="open drawer"
          edge="start"
          onClick={handleDrawerToggle}
          sx={{
            mr: 2,
            '&:hover': {
              transform: 'scale(1.1)',
              transition: 'transform 0.2s',
            },
          }}
        >
          <MenuIcon />
        </IconButton>

        <Box sx={{ display: 'flex', alignItems: 'center', gap: 1 }}>
          <LocalHospital 
            sx={{ 
              color: theme.palette.primary.main,
              fontSize: '2rem',
              mr: 1,
            }} 
          />
          <Typography
            variant="h6"
            noWrap
            component="div"
            sx={{
              fontWeight: 700,
              background: theme.palette.mode === 'light'
                ? 'linear-gradient(45deg, #1a237e 30%, #0d47a1 90%)'
                : 'linear-gradient(45deg, #90caf9 30%, #64b5f6 90%)',
              WebkitBackgroundClip: 'text',
              WebkitTextFillColor: 'transparent',
              letterSpacing: '0.5px',
            }}
          >
            NISH Medical Records
          </Typography>
        </Box>

        <Box sx={{ flexGrow: 1 }} />

        <Box sx={{ display: 'flex', alignItems: 'center', gap: 2 }}>
          <Tooltip title="Notifications">
            <IconButton
              color={theme.palette.mode === 'light' ? 'primary' : 'inherit'}
              sx={{
                '&:hover': {
                  transform: 'scale(1.1)',
                  transition: 'transform 0.2s',
                },
              }}
            >
              <Badge badgeContent={3} color="error">
                <NotificationsNone />
              </Badge>
            </IconButton>
          </Tooltip>

          <IconButton
            color={theme.palette.mode === 'light' ? 'primary' : 'inherit'}
            onClick={colorMode.toggleColorMode}
            sx={{
              '&:hover': {
                transform: 'scale(1.1)',
                transition: 'transform 0.2s',
              },
            }}
          >
            {theme.palette.mode === 'dark' ? <Brightness7 /> : <Brightness4 />}
          </IconButton>

          <Tooltip title="Account settings">
            <IconButton
              onClick={handleMenu}
              sx={{
                p: 0.5,
                border: `2px solid ${theme.palette.primary.main}`,
                '&:hover': {
                  transform: 'scale(1.1)',
                  transition: 'transform 0.2s',
                },
              }}
            >
              <Avatar
                sx={{
                  width: 32,
                  height: 32,
                  bgcolor: theme.palette.primary.main,
                  color: theme.palette.primary.contrastText,
                }}
              >
                <Person />
              </Avatar>
            </IconButton>
          </Tooltip>

          <Menu
            anchorEl={anchorEl}
            open={Boolean(anchorEl)}
            onClose={handleClose}
            onClick={handleClose}
            transformOrigin={{ horizontal: 'right', vertical: 'top' }}
            anchorOrigin={{ horizontal: 'right', vertical: 'bottom' }}
            PaperProps={{
              elevation: 4,
              sx: {
                mt: 1.5,
                minWidth: 200,
                borderRadius: '12px',
                overflow: 'visible',
                filter: 'drop-shadow(0px 2px 8px rgba(0,0,0,0.15))',
                '&:before': {
                  content: '""',
                  display: 'block',
                  position: 'absolute',
                  top: 0,
                  right: 14,
                  width: 10,
                  height: 10,
                  bgcolor: 'background.paper',
                  transform: 'translateY(-50%) rotate(45deg)',
                  zIndex: 0,
                },
              },
            }}
          >
            <Box sx={{ p: 2, pb: 1.5 }}>
              <Typography variant="subtitle1" fontWeight="bold">
                User Settings
              </Typography>
              <Typography variant="body2" color="text.secondary">
                Manage your account
              </Typography>
            </Box>
            
            <Divider />

            <MenuItem onClick={handleProfile} sx={{ py: 1.5 }}>
              <Person sx={{ mr: 2, color: theme.palette.primary.main }} />
              Profile
            </MenuItem>

            <MenuItem onClick={() => {}} sx={{ py: 1.5 }}>
              <Settings sx={{ mr: 2, color: theme.palette.primary.main }} />
              Settings
            </MenuItem>

            <Divider />

            <MenuItem 
              onClick={handleLogout}
              sx={{
                py: 1.5,
                color: theme.palette.error.main,
                '&:hover': {
                  bgcolor: theme.palette.error.light + '20',
                },
              }}
            >
              <ExitToApp sx={{ mr: 2 }} />
              Logout
            </MenuItem>
          </Menu>
        </Box>
      </Toolbar>
    </AppBar>
  );
};

export default NavBar;