// services/eodService.js
import axios from 'axios';

const API_URL = process.env.REACT_APP_API_URL || 'http://localhost:5000/api';

const eodService = {
  // Create EOD Admin
  createEODAdmin: async (eodData) => {
    try {
        console.log("reached here",eodData);
        
      const response = await axios.post(`${API_URL}/device/eod/create-eod`, eodData, {
        headers: {
          'Content-Type': 'application/json',
          Authorization: `Bearer ${localStorage.getItem('token')}`
        }
      });
      console.log(response.data);
      
      return response.data;
    } catch (error) {
      throw error.response?.data || error.message;
    }
  },

  // Get all EOD Admins
  getAllEODAdmins: async () => {
    try {
      const response = await axios.get(`${API_URL}/device/eod/getall`, {
        headers: {
          Authorization: `Bearer ${localStorage.getItem('token')}`
        }
      });
      return response.data;
    } catch (error) {
      throw error.response?.data || error.message;
    }
  },

  // Get EOD Admin by ID
  getEODAdminById: async (id) => {
    try {
      const response = await axios.get(`${API_URL}/eod/${id}`, {
        headers: {
          Authorization: `Bearer ${localStorage.getItem('token')}`
        }
      });
      return response.data;
    } catch (error) {
      throw error.response?.data || error.message;
    }
  },

  // Update EOD Admin
  updateEODAdmin: async (id, updateData) => {
    try {
      const response = await axios.put(`${API_URL}/eod/${id}`, updateData, {
        headers: {
          'Content-Type': 'application/json',
          Authorization: `Bearer ${localStorage.getItem('token')}`
        }
      });
      return response.data;
    } catch (error) {
      throw error.response?.data || error.message;
    }
  },

  // Delete EOD Admin
  deleteEODAdmin: async (id) => {
    try {
      const response = await axios.delete(`${API_URL}/eod/${id}`, {
        headers: {
          Authorization: `Bearer ${localStorage.getItem('token')}`
        }
      });
      return response.data;
    } catch (error) {
      throw error.response?.data || error.message;
    }
  }
};

export default eodService;