import React, { useState, useEffect, useRef } from 'react';
import { 
  Box, 
  Typography, 
  Card, 
  Stack, 
  Button,
  Alert,
  Chip
} from '@mui/material';
import { 
  DataGrid, 
  GridToolbar 
} from '@mui/x-data-grid';
import { 
  Print as PrintIcon,
  Warning as WarningIcon
} from '@mui/icons-material';
import { DatePicker } from '@mui/x-date-pickers';
import moment from 'moment';
import jsPDF from 'jspdf';
import 'jspdf-autotable';
import { useSnackbar } from 'notistack';
import { useSelector } from 'react-redux';
import { jwtDecode } from 'jwt-decode';
import api from '../../../api/axios';

const FileNotReturnedReport = () => {
  // State for managing date range, files, and pagination
  const [startDate, setStartDate] = useState(moment().subtract(30, 'days'));
  const [endDate, setEndDate] = useState(moment());
  const [files, setFiles] = useState([]);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState(null);
  const [pagination, setPagination] = useState({
    page: 0,
    pageSize: 10,
    total: 0
  });

  const { enqueueSnackbar } = useSnackbar();
  const token = useSelector(state => state.auth.token);
  const userId = token ? jwtDecode(token).userId : null;
  const pdfRef = useRef(null);

  // Fetch not returned file transfer data based on date range
  const fetchNotReturnedFiles = async () => {
    // Validate dates
    if (!startDate || !endDate) {
      enqueueSnackbar('Please select both start and end dates', { variant: 'warning' });
      return;
    }

    setLoading(true);
    setError(null);
    try {
      const params = {
        startDate: startDate.toISOString(),
        endDate: endDate.toISOString(),
        page: pagination.page + 1,
        limit: pagination.pageSize,
        userId
      };

      const response = await api.get('/file-transfers/not-returned', { params });
      
      // Ensure we have a successful response with data
      if (response.data.success && Array.isArray(response.data.data)) {
        // Process and set files, ensuring each file has a unique id
        const processedFiles = response.data.data.map((file, index) => ({
          ...file,
          id: file._id || `transfer-${index}`, // Fallback id if _id is missing
          caseId: file.caseId || 'N/A',
          patientName: file.patientName || 'N/A',
          // Round days dispatched to integer
          daysDispatched: Math.floor(file.daysDispatched || 0)
        }));

        setFiles(processedFiles);

        // Update pagination from response or use defaults
        if (response.data.pagination) {
          setPagination(prev => ({
            ...prev,
            total: response.data.pagination.totalRecords || 0
          }));
        }
      } else {
        // Handle case where response doesn't match expected structure
        setFiles([]);
        setError('Unexpected response format from server');
      }
    } catch (error) {
      console.error('Not returned files fetch error:', error);
      setError(error.response?.data?.message || 'Error fetching not returned files');
      setFiles([]);
      enqueueSnackbar('Failed to fetch not returned files report', { variant: 'error' });
    } finally {
      setLoading(false);
    }
  };

  // Fetch data when dates or pagination changes
  useEffect(() => {
    if (userId) {
      fetchNotReturnedFiles();
    }
  }, [startDate, endDate, pagination.page, pagination.pageSize, userId]);

  // Generate PDF report
  const generatePDF = () => {
    const doc = new jsPDF('landscape');

    // Add title and subtitle
    doc.setFontSize(16);
    doc.text('NISH Medical Record Room - FMS', 148.5, 15, { align: 'center' });

    doc.setFontSize(12);
    doc.text(`Not Returned Files Report (${startDate.format('YYYY-MM-DD')} to ${endDate.format('YYYY-MM-DD')})`, 148.5, 22, { align: 'center' });

    // Define columns for PDF table
    const columns = [
      { header: 'Case ID', dataKey: 'caseId' },
      { header: 'Patient Name', dataKey: 'patientName' },
      { header: 'MRRS User', dataKey: 'mrrsName' },
      { header: 'CS User', dataKey: 'csName' },
      { header: 'Dispatched Date', dataKey: 'dispatchedDate' },
      { header: 'Days Dispatched', dataKey: 'daysDispatched' }
    ];

    // Format data for PDF
    const formattedData = files.map(file => ({
      caseId: file.caseId || 'N/A',
      patientName: file.patientName || 'N/A',
      mrrsName: file.mrrsId?.name || 'N/A',
      csName: file.csId?.name || 'N/A',
      dispatchedDate: moment(file.dispatchedAt).format('YYYY-MM-DD'),
      daysDispatched: `${Math.floor(file.daysDispatched || 0)} days`
    }));

    // Generate PDF table
    doc.autoTable({
      columns,
      body: formattedData,
      startY: 30,
      theme: 'striped',
      styles: { 
        fontSize: 9,
        cellPadding: 3 
      },
      headStyles: { 
        fillColor: [0, 51, 102],
        textColor: 255 
      },
      columnStyles: {
        dispatchedDate: { cellWidth: 30, halign: 'center' },
        daysDispatched: { cellWidth: 30, halign: 'center' }
      }
    });

    // Save PDF
    doc.save(`Not_Returned_Files_Report_${moment().format('YYYYMMDD')}.pdf`);
  };

  // Define columns for DataGrid
  const columns = [
    { 
      field: 'caseId', 
      headerName: 'Case ID', 
      flex: 1,
      minWidth: 120
    },
    { 
      field: 'patientName', 
      headerName: 'Patient Name', 
      flex: 1,
      minWidth: 150
    },
    { 
      field: 'mrrsName', 
      headerName: 'MRRS User', 
      flex: 1,
      minWidth: 150,
      valueGetter: (params) => params.row.mrrsId?.name || 'N/A'
    },
    { 
      field: 'csName', 
      headerName: 'CS User', 
      flex: 1,
      minWidth: 150,
      valueGetter: (params) => params.row.csId?.name || 'N/A'
    },
    { 
      field: 'dispatchedAt', 
      headerName: 'Dispatched Date', 
      flex: 1,
      minWidth: 120,
      valueGetter: (params) => moment(params.value).format('YYYY-MM-DD')
    },
    { 
      field: 'daysDispatched', 
      headerName: 'Days Dispatched', 
      flex: 1,
      minWidth: 120,
      renderCell: (params) => {
        const days = Math.floor(params.value || 0);
        return (
          <Chip 
            icon={<WarningIcon />} 
            label={`${days} days`} 
            color={days > 7 ? 'error' : 'warning'}
            size="small"
          />
        );
      }
    }
  ];

  return (
    <Box sx={{ p: 3 }}>
      <Typography variant="h4" gutterBottom align="center">
        Not Returned Files Report
      </Typography>

      <Card sx={{ p: 3, mb: 3 }}>
        <Stack 
          direction="row" 
          spacing={2} 
          alignItems="center" 
          justifyContent="space-between"
        >
          <Stack direction="row" spacing={2}>
            <DatePicker
              label="Start Date"
              value={startDate}
              onChange={(newValue) => setStartDate(newValue)}
              slotProps={{ textField: { variant: 'outlined', fullWidth: true } }}
              maxDate={endDate}
            />
            <DatePicker
              label="End Date"
              value={endDate}
              onChange={(newValue) => setEndDate(newValue)}
              slotProps={{ textField: { variant: 'outlined', fullWidth: true } }}
              minDate={startDate}
            />
          </Stack>
          <Button
            variant="contained"
            startIcon={<PrintIcon />}
            onClick={generatePDF}
            disabled={files.length === 0}
          >
            Print Report
          </Button>
        </Stack>
      </Card>

      {error && (
        <Alert severity="error" sx={{ mb: 2 }}>
          {error}
        </Alert>
      )}

      <Card>
        <DataGrid
          ref={pdfRef}
          rows={files}
          columns={columns}
          getRowId={(row) => row.id} // Use generated id
          pagination
          paginationMode="server"
          rowCount={pagination.total}
          page={pagination.page}
          pageSize={pagination.pageSize}
          loading={loading}
          onPageChange={(newPage) => setPagination(prev => ({ ...prev, page: newPage }))}
          onPageSizeChange={(newPageSize) => 
            setPagination(prev => ({ ...prev, pageSize: newPageSize, page: 0 }))
          }
          components={{
            Toolbar: GridToolbar,
          }}
          componentsProps={{
            toolbar: {
              showQuickFilter: true,
              quickFilterProps: { debounceMs: 500 },
            },
          }}
          sx={{
            height: '70vh'
          }}
          slots={{
            noRowsOverlay: () => (
              <Stack height="100%" alignItems="center" justifyContent="center" py={3}>
                <Typography variant="body2" color="text.secondary">
                  {files.length === 0 
                    ? 'No not returned files found for the selected date range' 
                    : 'Loading...'}
                </Typography>
              </Stack>
            ),
          }}
        />
      </Card>
    </Box>
    );
};

export default FileNotReturnedReport;