
import axios from 'axios';

const API_URL = process.env.REACT_APP_API_URL || 'http://localhost:5000';

// Create axios instance with default config
const api = axios.create({
  baseURL: `${API_URL}/device`,
  headers: {
    'Content-Type': 'application/json'
  }
});

// Add request interceptor for authentication
api.interceptors.request.use(
  (config) => {
    const token = localStorage.getItem('token');
    if (token) {
      config.headers.Authorization = `Bearer ${token}`;
    }
    return config;
  },
  (error) => Promise.reject(error)
);

// Add response interceptor for error handling
api.interceptors.response.use(
  (response) => response,
  (error) => {
    console.error('API Error:', error);
    return Promise.reject(error);
  }
);

const overviewService = {
  getStats: async () => {
    try {
      const response = await api.get('/overview/stats');
      console.log('response',response.data.data);
      
      return response.data.data; // Return the data portion of the response
    } catch (error) {
      throw new Error(error.response?.data?.message || 'Failed to fetch overview stats');
    }
  },

  getActivityData: async () => {
    try {
      const response = await api.get('/overview/activity');
      return response.data.data; // Return the data portion of the response
    } catch (error) {
      throw new Error(error.response?.data?.message || 'Failed to fetch activity data');
    }
  },

  getRecentInspections: async () => {
    try {
      const response = await api.get('/overview/recent-inspections');
      return response.data.data; // Return the data portion of the response
    } catch (error) {
      throw new Error(error.response?.data?.message || 'Failed to fetch recent inspections');
    }
  },

  getMaintenanceAlerts: async () => {
    try {
      const response = await api.get('/overview/maintenance-alerts');
      return response.data.data; // Return the data portion of the response
    } catch (error) {
      throw new Error(error.response?.data?.message || 'Failed to fetch maintenance alerts');
    }
  },
};

export default overviewService;