import React, { useState, useEffect } from 'react';
import { Link, useLocation } from 'react-router-dom';
import {
  Drawer,
  List,
  ListItemIcon,
  ListItemText,
  ListItemButton,
  Collapse,
  Box,
  Typography,
  useTheme,
  useMediaQuery,
  Toolbar,
  alpha
} from '@mui/material';
import { ExpandMore, Circle } from '@mui/icons-material';
import DashboardTwoToneIcon from '@mui/icons-material/DashboardTwoTone';
import AdminPanelSettingsTwoToneIcon from '@mui/icons-material/AdminPanelSettingsTwoTone';
import ImportantDevicesTwoToneIcon from '@mui/icons-material/ImportantDevicesTwoTone';
import BuildTwoToneIcon from '@mui/icons-material/BuildTwoTone';
import BookmarkAddedTwoToneIcon from '@mui/icons-material/BookmarkAddedTwoTone';
import BugReportTwoToneIcon from '@mui/icons-material/BugReportTwoTone';
import AssessmentTwoToneIcon from '@mui/icons-material/AssessmentTwoTone';
import SettingsSuggestTwoToneIcon from '@mui/icons-material/SettingsSuggestTwoTone';
import { useNavigate } from 'react-router-dom';
import { getUserRole, hasAccess } from './AccessControl'; // Import access control functions

const drawerWidth = 280;

const Sidebar = ({ open, handleDrawerToggle }) => {
  const theme = useTheme();
  const [openMenus, setOpenMenus] = useState({});
  const isSmUp = useMediaQuery(theme.breakpoints.up('sm'));
  const location = useLocation();
  const currentPath = location.pathname;
  const navigate = useNavigate();
  // const hasAccess = (allowedRoles) => {
  //   const roleHierarchy = {
  //     'SUPER_ADMIN': 4,
  //     'HOD': 3,
  //     'EOD': 2,
  //     'CLINICAL_INCHARGE': 1
  //   };
  //   return roleHierarchy[userRole] >= roleHierarchy[allowedRoles];
  // };
  const [userRole, setUserRole] = useState(null);
  useEffect(() => {
    const role = getUserRole();
    console.log('User Role:', role);
    
    setUserRole(role);
  }, []);
  const handleClick = (title) => {
    setOpenMenus(prev => ({
      ...prev,
      [title]: !prev[title]
    }));
  };

  // Updated navigation items with path properties
  const navigationItems = [
    {
      title: 'Dashboard',
      icon: <DashboardTwoToneIcon />,
      access: ['clinical_incharge'],
      path: 'overview'
    },
    {
      title: 'User Management',
      icon: <AdminPanelSettingsTwoToneIcon />,
      access: ['super_admin', 'hod', 'eod'],
      subItems: [
        { title: 'Create HOD', access: ['super_admin'], path: 'create-hod' },
        { title: 'Manage HOD', access: ['super_admin'], path: 'manage-hod' },
        { title: 'Create EOD', access: ['hod'], path: 'create-eod' },
        { title: 'Manage EOD', access: ['hod'], path: 'manage-eod' },
        { title: 'Create Clinical Incharge', access: ['hod', 'eod'], path: 'create-clinical-incharge' },
        { title: 'Manage Clinical Incharge', access: ['hod', 'eod'], path: 'manage-clinical-incharge' },
        { title: 'All Users', access: ['super_admin'], path: 'all-users' }
      ]
    },
    {
      title: 'Devices',
      icon: <ImportantDevicesTwoToneIcon />,
      access: ['super_admin', 'hod', 'eod','clinical_incharge'],
      subItems: [
        { title: 'Add Device', access: ['hod', 'eod'], path: 'add-device' },
        { title: 'Manage Devices', access: ['hod', 'eod'], path: 'device-manage' },
        { title: 'Manage Accessories', access: ['hod', 'eod'], path: 'manage-accessories' },
        { title: 'View Devices', access: ['clinical_incharge'], path: 'all-device' }
      ]
    },
    {
      title: 'Accessories',
      icon: <BuildTwoToneIcon />,
      access: ['super_admin', 'hod', 'eod','clinical_incharge'],
      subItems: [
        { title: 'Manage Accessories', access: ['eod'], path: 'manage-accessories' },
        { title: 'View Accessories', access: ['clinical_incharge'], path: 'all-accessories' }
      ]
    },
    {
      title: 'Inspections',
      icon: <BookmarkAddedTwoToneIcon />,
      access: ['eod'],
      subItems: [ 
        { title: 'Daily Inspections', access: ['eod'], path: 'daily-inspection' },
      ]
    },
    {
      title: 'Issues',
      icon: <BugReportTwoToneIcon />,
      access: ['super_admin', 'hod', 'eod','clinical_incharge'],
      subItems: [
        { title: 'Report Issue', access: ['clinical_incharge'], path: 'report-issue' },
        { title: 'View Issues', access: ['hod','clinical_incharge'], path: 'view-issue' },
        { title: 'Manage Issues', access: ['eod'], path: 'manage-issue' }
      ]
    },
    {
      title: 'Reports',
      icon: <AssessmentTwoToneIcon />,
      access: ['super_admin', 'hod', 'eod'],
      subItems: [
        { title: 'Inspection Reports', access: ['hod','eod'], path: 'reports-inspections' },
      ]
    },
  ];
  // Check if a menu should be shown based on user role
  const shouldShowMenu = (menuItem) => {
    if (!userRole || !menuItem.access) return false;
    return hasAccess(userRole, menuItem.access);
  };

  // Check if a menu has any accessible sub-items
  const hasAccessibleSubItems = (menuItem) => {
    if (!menuItem.subItems) return false;
    return menuItem.subItems.some(subItem => hasAccess(userRole, subItem.access));
  };
  const drawer = (
    <>
      <Toolbar sx={{ 
        px: 2,
        borderBottom: `1px solid ${theme.palette.divider}`,
        background: theme.palette.background.paper,
        color: theme.palette.primary.main,
      }}>
        <Typography variant="h6" component="div" sx={{ 
          fontWeight: 600,
          letterSpacing: '0.5px'
        }}>
          Equipment MMS
        </Typography>
      </Toolbar>

      <Box 
        sx={{ 
          overflow: 'auto',
          height: '100%',
          background: theme.palette.background.paper,
          pt: 2
        }}
      >
        <List component="nav" sx={{ px: 2 }}>
          {navigationItems.map((item, index) => (
            // Only render if user has access or if there are accessible sub-items
            (shouldShowMenu(item) || hasAccessibleSubItems(item)) && (
              <Box key={index} sx={{ mb: 0.5 }}>
                <ListItemButton
                  component={item.path && !item.subItems ? Link : 'div'}
                  to={item.path && !item.subItems ? item.path : undefined}
                  onClick={() => {
                    if (item.subItems) {
                      handleClick(item.title);
                    }
                  }}
                  selected={item.path ? currentPath === item.path : false}
                  sx={{
                    borderRadius: '8px',
                    mb: 0.5,
                    position: 'relative',
                    transition: 'all 0.2s ease-in-out',
                    color: 'inherit',
                    '&.Mui-selected': {
                      backgroundColor: theme.palette.mode === 'light' 
                        ? alpha(theme.palette.primary.main, 0.1)
                        : alpha(theme.palette.primary.main, 0.2),
                      '&:hover': {
                        backgroundColor: theme.palette.mode === 'light'
                          ? alpha(theme.palette.primary.main, 0.15)
                          : alpha(theme.palette.primary.main, 0.25),
                      },
                      '& .MuiListItemIcon-root': {
                        color: theme.palette.primary.main,
                      },
                      '& .MuiTypography-root': {
                        color: theme.palette.primary.main,
                        fontWeight: 600,
                      },
                    },
                    '&:hover': {
                      backgroundColor: theme.palette.mode === 'light'
                        ? alpha(theme.palette.primary.main, 0.08)
                        : alpha(theme.palette.primary.main, 0.15),
                    },
                  }}
                >
                  <ListItemIcon sx={{ 
                    minWidth: 40,
                    color: theme.palette.text.secondary,
                    transition: 'color 0.2s ease-in-out',
                  }}>
                    {item.icon}
                  </ListItemIcon>
                  <ListItemText 
                    primary={item.title}
                    primaryTypographyProps={{
                      fontSize: '0.9rem',
                      fontWeight: openMenus[item.title] ? 600 : 400,
                      color: theme.palette.text.primary,
                    }}
                  />
                  {item.subItems && (
                    <Box sx={{ 
                      transition: 'transform 0.3s ease',
                      transform: openMenus[item.title] ? 'rotate(-180deg)' : 'none'
                    }}>
                      <ExpandMore />
                    </Box>
                  )}
                </ListItemButton>

                {item.subItems && (
                  <Collapse in={openMenus[item.title]} timeout="auto" unmountOnExit>
                    <List component="div" disablePadding>
                      {item.subItems.map((subItem, subIndex) => (
                        hasAccess(userRole, subItem.access) && (
                          <ListItemButton
                            key={subIndex}
                            component={Link}
                            to={subItem.path}
                            selected={currentPath.includes(subItem.path)}
                            sx={{
                              pl: 4,
                              py: 1,
                              borderRadius: '8px',
                              ml: 2,
                              mb: 0.5,
                              position: 'relative',
                              transition: 'all 0.2s ease-in-out',
                              textDecoration: 'none',
                              color: 'inherit',
                              '&.Mui-selected': {
                                backgroundColor: theme.palette.mode === 'light'
                                  ? alpha(theme.palette.primary.main, 0.1)
                                  : alpha(theme.palette.primary.main, 0.2),
                                '&:hover': {
                                  backgroundColor: theme.palette.mode === 'light'
                                    ? alpha(theme.palette.primary.main, 0.15)
                                    : alpha(theme.palette.primary.main, 0.25),
                                },
                              },
                              '&:hover': {
                                backgroundColor: theme.palette.mode === 'light'
                                  ? alpha(theme.palette.primary.main, 0.08)
                                  : alpha(theme.palette.primary.main, 0.15),
                              },
                            }}
                          >
                            <ListItemIcon sx={{ 
                              minWidth: 30,
                              color: theme.palette.text.secondary,
                            }}>
                              <Circle sx={{ fontSize: 8 }} />
                            </ListItemIcon>
                            <ListItemText 
                              primary={subItem.title}
                              primaryTypographyProps={{
                                fontSize: '0.85rem',
                                fontWeight: currentPath === subItem.path ? 600 : 400,
                              }}
                            />

                          </ListItemButton>
                        )
                      ))}
                    </List>
                  </Collapse>
                )}
              </Box>
            )
          ))}
        </List>
      </Box>
    </>
  );

  return (
    <Box
      component="nav"
      sx={{ width: { sm: drawerWidth }, flexShrink: { sm: 0 } }}
    >
      <Drawer
        variant="temporary"
        open={open}
        onClose={handleDrawerToggle}
        ModalProps={{
          keepMounted: true,
        }}
        sx={{
          display: { xs: 'block', sm: 'none' },
          '& .MuiDrawer-paper': {
            boxSizing: 'border-box',
            width: drawerWidth,
            borderRight: 'none',
            boxShadow: theme.shadows[8],
          },
        }}
      >
        {drawer}
      </Drawer>
      
      <Drawer
        variant="permanent"
        sx={{
          display: { xs: 'none', sm: 'block' },
          '& .MuiDrawer-paper': {
            boxSizing: 'border-box',
            width: drawerWidth,
            borderRight: `1px solid ${theme.palette.divider}`,
            boxShadow: theme.shadows[1],
            background: theme.palette.background.paper,
          },
        }}
        open
      >
        {drawer}
      </Drawer>
    </Box>
  );

  return (
    <Box
      component="nav"
      sx={{ width: { sm: drawerWidth }, flexShrink: { sm: 0 } }}
    >
      <Drawer
        variant="temporary"
        open={open}
        onClose={handleDrawerToggle}
        ModalProps={{
          keepMounted: true,
        }}
        sx={{
          display: { xs: 'block', sm: 'none' },
          '& .MuiDrawer-paper': {
            boxSizing: 'border-box',
            width: drawerWidth,
            borderRight: 'none',
            boxShadow: theme.shadows[8],
          },
        }}
      >
        {drawer}
      </Drawer>
      
      <Drawer
        variant="permanent"
        sx={{
          display: { xs: 'none', sm: 'block' },
          '& .MuiDrawer-paper': {
            boxSizing: 'border-box',
            width: drawerWidth,
            borderRight: `1px solid ${theme.palette.divider}`,
            boxShadow: theme.shadows[1],
            background: theme.palette.background.paper,
          },
        }}
        open
      >
        {drawer}
      </Drawer>
    </Box>
  );
};

export default Sidebar;