import React, { useState } from 'react';
import {
    Box,
    Card,
    CardContent,
    TextField,
    Button,
    Typography,
    Stack,
    Grid,
    IconButton,
    FormControl,
    InputLabel,
    Select,
    MenuItem,
    FormControlLabel,
    Switch,
    Divider,
    Dialog,
    DialogTitle,
    DialogContent,
    DialogActions,
    Alert,
    Snackbar,
    Paper,
    CircularProgress
} from '@mui/material';
import {
    ArrowBack,
    AddCircleOutline,
    DeleteOutline,
    MedicalServices,
    Upload,
    Save
} from '@mui/icons-material';
import { useNavigate } from 'react-router-dom';
import { DatePicker } from '@mui/x-date-pickers/DatePicker';
import { LocalizationProvider } from '@mui/x-date-pickers';
import { AdapterDateFns } from '@mui/x-date-pickers/AdapterDateFns';
import deviceService from '../../../features/services/deviceService';

const AddDeviceForm = () => {
    const navigate = useNavigate();

    // Device State
    const [deviceData, setDeviceData] = useState({
        deviceName: '',
        serialNumber: '',
        make: '',
        model: '',
        purchasedYear: null,
        calibrationDate: null,
        roomNo: '',
        status: 'active',
        hasAMC: false,
        amcCompany: '',
        amcDetails: '',
        noAMCReason: '',
        deviceImage: null
    });

    // Accessories State
    const [accessories, setAccessories] = useState([{
        itemName: '',
        supplier: '',
        purchaseDate: null,
        isRight: false,
        isLeft: false,
        status: 'active',
        image: null
    }]);

    const [openDialog, setOpenDialog] = useState(false);
    const [notification, setNotification] = useState({
        open: false,
        message: '',
        severity: 'success'
    });
    const [loading, setLoading] = useState(false);

    // Handle Device Input Changes
    const handleDeviceChange = (event) => {
        const { name, value, checked } = event.target;
        setDeviceData(prev => ({
            ...prev,
            [name]: event.target.type === 'checkbox' ? checked : value
        }));
    };

    // Handle Device Image Upload
    const handleDeviceImageChange = (event) => {
        const file = event.target.files[0];
        if (file) {
            setDeviceData(prev => ({
                ...prev,
                deviceImage: file
            }));
        }
    };

    // Handle Accessory Changes
    const handleAccessoryChange = (index, field, value) => {
        const newAccessories = [...accessories];
        newAccessories[index] = {
            ...newAccessories[index],
            [field]: value
        };
        setAccessories(newAccessories);
    };

    // Handle Accessory Image Upload
    const handleAccessoryImageChange = (index, event) => {
        const file = event.target.files[0];
        if (file) {
            const newAccessories = [...accessories];
            newAccessories[index] = {
                ...newAccessories[index],
                image: file
            };
            setAccessories(newAccessories);
        }
    };

    // Add New Accessory
    const addAccessory = () => {
        setAccessories(prev => [...prev, {
            itemName: '',
            supplier: '',
            purchaseDate: null,
            isRight: false,
            isLeft: false,
            status: 'active',
            image: null
        }]);
    };

    // Remove Accessory
    const removeAccessory = (index) => {
        setAccessories(prev => prev.filter((_, i) => i !== index));
    };

    // Form Submission
    const handleSubmit = (e) => {
        e.preventDefault();
        setOpenDialog(true);
    };

    const handleConfirmSubmit = async () => {
        setLoading(true);
        try {
            // Create FormData for multipart/form-data submission
            const formData = new FormData();
    
            // Append device data
            Object.keys(deviceData).forEach(key => {
                if (key === 'deviceImage') {
                    if (deviceData[key]) {
                        formData.append('deviceImage', deviceData[key]);
                    }
                } else if (key === 'purchasedYear' || key === 'calibrationDate') {
                    if (deviceData[key]) {
                        formData.append(key, deviceData[key].toISOString());
                    }
                } else {
                    formData.append(key, deviceData[key]);
                }
            });
    
            // Prepare accessories data for JSON (without images)
            const accessoriesForJson = accessories.map(acc => {
                const { image, ...rest } = acc;
                return {
                    ...rest,
                    purchaseDate: rest.purchaseDate ? rest.purchaseDate.toISOString() : null
                };
            });
            
            // Append accessories JSON
            formData.append('accessories', JSON.stringify(accessoriesForJson));
    
            // Append accessory images with indexed field names
            // This matches the pattern expected by your backend upload middleware
            accessories.forEach((accessory, index) => {
                if (accessory.image) {
                    formData.append(`accessoryImages[${index}]`, accessory.image);
                }
            });
    
            // API call
            const response = await deviceService.createDevice(formData);
    
            setOpenDialog(false);
            showNotification('Device created successfully!', 'success');
    
            
        } catch (error) {
            console.error('Error creating device:', error);
            setOpenDialog(false);
            showNotification(error.response?.data?.message || 'Failed to create device', 'error');
        } finally {
            setLoading(false);
        }
    };

    const showNotification = (message, severity) => {
        setNotification({
            open: true,
            message,
            severity
        });
    };

    return (
        <Box sx={{ p: 3, backgroundColor: '#f0f7ff', minHeight: '100vh' }}>
            <Card
                elevation={0}
                sx={{
                    borderRadius: 4,
                    background: 'linear-gradient(135deg, #ffffff 0%, #f8faff 100%)',
                    boxShadow: '0 8px 32px rgba(0, 0, 0, 0.1)'
                }}
            >
                <CardContent sx={{ p: 4 }}>
                    {/* Header */}
                    <Stack
                        direction="row"
                        alignItems="center"
                        spacing={2}
                        mb={4}
                    >
                        <IconButton
                            onClick={() => navigate(-1)}
                            sx={{
                                backgroundColor: '#e3f2fd',
                                '&:hover': { backgroundColor: '#bbdefb' }
                            }}
                        >
                            <ArrowBack />
                        </IconButton>
                        <Stack direction="column">
                            <Typography
                                variant="h5"
                                sx={{
                                    fontWeight: 600,
                                    color: '#1976d2'
                                }}
                            >
                                Add New Device
                            </Typography>
                            <Typography variant="body2" color="textSecondary">
                                Fill in the details to add a new medical device
                            </Typography>
                        </Stack>
                    </Stack>

                    <Divider sx={{ mb: 4 }} />

                    <form onSubmit={handleSubmit}>
                        {/* Device Information Section */}
                        <Stack direction="row" alignItems="center" spacing={1} mb={3}>
                            <MedicalServices color="primary" />
                            <Typography variant="h6" color="primary">
                                Device Information
                            </Typography>
                        </Stack>

                        <Grid container spacing={3} mb={4}>
                            <Grid item xs={12} sm={6}>
                                <TextField
                                    fullWidth
                                    label="Device Name"
                                    name="deviceName"
                                    value={deviceData.deviceName}
                                    onChange={handleDeviceChange}
                                    required
                                    InputProps={{
                                        sx: { borderRadius: 2 }
                                    }}
                                />
                            </Grid>
                            <Grid item xs={12} sm={6}>
                                <TextField
                                    fullWidth
                                    label="Serial Number"
                                    name="serialNumber"
                                    value={deviceData.serialNumber}
                                    onChange={handleDeviceChange}
                                    required
                                    InputProps={{
                                        sx: { borderRadius: 2 }
                                    }}
                                />
                            </Grid>
                            <Grid item xs={12} sm={6}>
                                <TextField
                                    fullWidth
                                    label="Make"
                                    name="make"
                                    value={deviceData.make}
                                    onChange={handleDeviceChange}
                                    required
                                    InputProps={{
                                        sx: { borderRadius: 2 }
                                    }}
                                />
                            </Grid>
                            <Grid item xs={12} sm={6}>
                                <TextField
                                    fullWidth
                                    label="Model"
                                    name="model"
                                    value={deviceData.model}
                                    onChange={handleDeviceChange}
                                    required
                                    InputProps={{
                                        sx: { borderRadius: 2 }
                                    }}
                                />
                            </Grid>
                            <Grid item xs={12} sm={6}>
                                <LocalizationProvider dateAdapter={AdapterDateFns}>
                                    <DatePicker
                                        label="Purchase Year"
                                        value={deviceData.purchasedYear}
                                        onChange={(date) => handleDeviceChange({
                                            target: { name: 'purchasedYear', value: date }
                                        })}
                                        renderInput={(params) => (
                                            <TextField
                                                {...params}
                                                fullWidth
                                                required
                                                InputProps={{
                                                    ...params.InputProps,
                                                    sx: { borderRadius: 2 }
                                                }}
                                            />
                                        )}
                                    />
                                </LocalizationProvider>
                            </Grid>
                            <Grid item xs={12} sm={6}>
                                <LocalizationProvider dateAdapter={AdapterDateFns}>
                                    <DatePicker
                                        label="Calibration Date"
                                        value={deviceData.calibrationDate}
                                        onChange={(date) => handleDeviceChange({
                                            target: { name: 'calibrationDate', value: date }
                                        })}
                                        renderInput={(params) => (
                                            <TextField
                                                {...params}
                                                fullWidth
                                                required
                                                InputProps={{
                                                    ...params.InputProps,
                                                    sx: { borderRadius: 2 }
                                                }}
                                            />
                                        )}
                                    />
                                </LocalizationProvider>
                            </Grid>
                            <Grid item xs={12} sm={6}>
                                <TextField
                                    fullWidth
                                    label="Room Number"
                                    name="roomNo"
                                    value={deviceData.roomNo}
                                    onChange={handleDeviceChange}
                                    required
                                    InputProps={{
                                        sx: { borderRadius: 2 }
                                    }}
                                />
                            </Grid>
                            <Grid item xs={12} sm={6}>
                                <FormControl fullWidth>
                                    <InputLabel>Status</InputLabel>
                                    <Select
                                        name="status"
                                        value={deviceData.status}
                                        onChange={handleDeviceChange}
                                        label="Status"
                                        sx={{ borderRadius: 2 }}
                                    >
                                        <MenuItem value="active">Active</MenuItem>
                                        <MenuItem value="inactive">Inactive</MenuItem>
                                        <MenuItem value="maintenance">Under Maintenance</MenuItem>
                                    </Select>
                                </FormControl>
                            </Grid>
                            <Grid item xs={12}>
                                <Paper
                                    elevation={0}
                                    sx={{
                                        p: 2,
                                        borderRadius: 2,
                                        backgroundColor: '#e3f2fd',
                                        border: '1px solid #bbdefb'
                                    }}
                                >
                                    <FormControlLabel
                                        control={
                                            <Switch
                                                checked={deviceData.hasAMC}
                                                onChange={handleDeviceChange}
                                                name="hasAMC"
                                            />
                                        }
                                        label="Annual Maintenance Contract (AMC)"
                                    />
                                </Paper>
                            </Grid>
                            {deviceData.hasAMC ? (
                                <>
                                    <Grid item xs={12} sm={6}>
                                        <TextField
                                            fullWidth
                                            label="AMC Company"
                                            name="amcCompany"
                                            value={deviceData.amcCompany}
                                            onChange={handleDeviceChange}
                                            required
                                            InputProps={{
                                                sx: { borderRadius: 2 }
                                            }}
                                        />
                                    </Grid>
                                    <Grid item xs={12} sm={6}>
                                        <TextField
                                            fullWidth
                                            label="AMC Details"
                                            name="amcDetails"
                                            value={deviceData.amcDetails}
                                            onChange={handleDeviceChange}
                                            multiline
                                            rows={2}
                                            InputProps={{
                                                sx: { borderRadius: 2 }
                                            }}
                                        />
                                    </Grid>
                                </>
                            ) : (
                                <Grid item xs={12}>
                                    <TextField
                                        fullWidth
                                        label="Reason for No AMC"
                                        name="noAMCReason"
                                        value={deviceData.noAMCReason}
                                        onChange={handleDeviceChange}
                                        required
                                        multiline
                                        rows={2}
                                        InputProps={{
                                            sx: { borderRadius: 2 }
                                        }}
                                    />
                                </Grid>
                            )}
                            <Grid item xs={12}>
                                <Button
                                    component="label"
                                    variant="outlined"
                                    startIcon={<Upload />}
                                    sx={{ borderRadius: 2 }}
                                >
                                    Upload Device Image
                                    <input
                                        type="file"
                                        hidden
                                        accept="image/*"
                                        onChange={handleDeviceImageChange}
                                    />
                                </Button>
                                {deviceData.deviceImage && (
                                    <Typography variant="body2" sx={{ mt: 1, color: 'success.main' }}>
                                        Image uploaded: {deviceData.deviceImage.name}
                                    </Typography>
                                )}
                            </Grid>
                        </Grid>

                        {/* Accessories Section */}
                        <Stack direction="row" alignItems="center" spacing={1} mb={3}>
                            <AddCircleOutline color="primary" />
                            <Typography variant="h6" color="primary">
                                Accessories
                            </Typography>
                        </Stack>

                        {accessories.map((accessory, index) => (
                            <Box key={index} sx={{ mb: 4 }}>
                                <Paper
                                    elevation={0}
                                    sx={{
                                        p: 3,
                                        borderRadius: 2,
                                        border: '1px solid #e0e0e0'
                                    }}
                                >
                                    <Stack
                                        direction="row"
                                        justifyContent="space-between"
                                        alignItems="center"
                                        mb={2}
                                    >
                                        <Typography variant="subtitle1" fontWeight={500}>
                                            Accessory #{index + 1}
                                        </Typography>
                                        {index > 0 && (
                                            <IconButton
                                                onClick={() => removeAccessory(index)}
                                                color="error"
                                                size="small"
                                            >
                                                <DeleteOutline />
                                            </IconButton>
                                        )}
                                    </Stack>

                                    <Grid container spacing={3}>
                                        <Grid item xs={12} sm={6}>
                                            <TextField
                                                fullWidth
                                                label="Item Name"
                                                value={accessory.itemName}
                                                onChange={(e) => handleAccessoryChange(index, 'itemName', e.target.value)}
                                                required
                                                InputProps={{
                                                    sx: { borderRadius: 2 }
                                                }}
                                            />
                                        </Grid>
                                        <Grid item xs={12} sm={6}>
                                            <TextField
                                                fullWidth
                                                label="Supplier"
                                                value={accessory.supplier}
                                                onChange={(e) => handleAccessoryChange(index, 'supplier', e.target.value)}
                                                required
                                                InputProps={{
                                                    sx: { borderRadius: 2 }
                                                }}
                                            />
                                        </Grid>
                                        <Grid item xs={12} sm={6}>
                                            <LocalizationProvider dateAdapter={AdapterDateFns}>
                                                <DatePicker
                                                    label="Purchase Date"
                                                    value={accessory.purchaseDate}
                                                    onChange={(date) => handleAccessoryChange(index, 'purchaseDate', date)}
                                                    renderInput={(params) => (
                                                        <TextField
                                                            {...params}
                                                            fullWidth
                                                            required
                                                            InputProps={{
                                                                ...params.InputProps,
                                                                sx: { borderRadius: 2 }
                                                            }}
                                                        />
                                                    )}
                                                />
                                            </LocalizationProvider>
                                        </Grid>
                                        <Grid item xs={12} sm={6}>
                                            <FormControl fullWidth>
                                                <InputLabel>Status</InputLabel>
                                                <Select
                                                    value={accessory.status}
                                                    onChange={(e) => handleAccessoryChange(index, 'status', e.target.value)}
                                                    label="Status"
                                                    sx={{ borderRadius: 2 }}
                                                >
                                                    <MenuItem value="active">Active</MenuItem>
                                                    <MenuItem value="inactive">Inactive</MenuItem>
                                                    <MenuItem value="maintenance">Under Maintenance</MenuItem>
                                                </Select>
                                            </FormControl>
                                        </Grid>
                                        <Grid item xs={12} sm={6}>
                                            <Paper
                                                elevation={0}
                                                sx={{
                                                    p: 2,
                                                    borderRadius: 2,
                                                    backgroundColor: '#e3f2fd',
                                                    border: '1px solid #bbdefb'
                                                }}
                                            >
                                                <Stack direction="row" spacing={2}>
                                                    <FormControlLabel
                                                        control={
                                                            <Switch
                                                                checked={accessory.isRight}
                                                                onChange={(e) => handleAccessoryChange(index, 'isRight', e.target.checked)}
                                                            />
                                                        }
                                                        label="Right"
                                                    />
                                                    <FormControlLabel
                                                        control={
                                                            <Switch
                                                                checked={accessory.isLeft}
                                                                onChange={(e) => handleAccessoryChange(index, 'isLeft', e.target.checked)}
                                                            />
                                                        }
                                                        label="Left"
                                                    />
                                                </Stack>
                                            </Paper>
                                        </Grid>
                                        <Grid item xs={12} sm={6}>
                                            <Stack spacing={2}>
                                                <Button
                                                    component="label"
                                                    variant="outlined"
                                                    startIcon={<Upload />}
                                                    sx={{ borderRadius: 2 }}
                                                >
                                                    Upload Accessory Image
                                                    <input
                                                        type="file"
                                                        hidden
                                                        accept="image/*"
                                                        onChange={(e) => handleAccessoryImageChange(index, e)}
                                                    />
                                                </Button>
                                                {accessory.image && (
                                                    <Typography variant="body2" color="success.main">
                                                        Image uploaded: {accessory.image.name}
                                                    </Typography>
                                                )}
                                            </Stack>
                                        </Grid>
                                    </Grid>
                                </Paper>
                            </Box>
                        ))}

                        <Button
                            variant="outlined"
                            startIcon={<AddCircleOutline />}
                            onClick={addAccessory}
                            sx={{ mb: 4, borderRadius: 2 }}
                        >
                            Add Another Accessory
                        </Button>

                        {/* Form Actions */}
                        <Stack direction="row" spacing={2} justifyContent="flex-end">
                            <Button
                                variant="outlined"
                                onClick={() => navigate(-1)}
                                sx={{ borderRadius: 2, px: 4 }}
                            >
                                Cancel
                            </Button>
                            <Button
                                type="submit"
                                variant="contained"
                                startIcon={<Save />}
                                sx={{
                                    borderRadius: 2,
                                    px: 4,
                                    backgroundColor: '#1976d2',
                                    '&:hover': {
                                        backgroundColor: '#1565c0',
                                        boxShadow: '0 4px 12px rgba(25, 118, 210, 0.3)',
                                    }
                                }}
                            >
                                Save Device
                            </Button>
                        </Stack>
                    </form>
                </CardContent>
            </Card>

            {/* Confirmation Dialog */}
            <Dialog
                open={openDialog}
                onClose={() => !loading && setOpenDialog(false)}
                PaperProps={{
                    sx: { borderRadius: 3 }
                }}
            >
                <DialogTitle>Confirm Device Creation</DialogTitle>
                <DialogContent>
                    {loading ? (
                        <Box sx={{ display: 'flex', justifyContent: 'center', alignItems: 'center', py: 3 }}>
                            <CircularProgress />
                        </Box>
                    ) : (
                        <>
                            <Typography gutterBottom>
                                Please review the device details before confirming:
                            </Typography>
                            <Box sx={{ mt: 2 }}>
                                <Typography variant="body2" gutterBottom>
                                    <strong>Device Name:</strong> {deviceData.deviceName}
                                </Typography>
                                <Typography variant="body2" gutterBottom>
                                    <strong>Serial Number:</strong> {deviceData.serialNumber}
                                </Typography>
                                <Typography variant="body2" gutterBottom>
                                    <strong>Make/Model:</strong> {deviceData.make} / {deviceData.model}
                                </Typography>
                                <Typography variant="body2" gutterBottom>
                                    <strong>Room Number:</strong> {deviceData.roomNo}
                                </Typography>
                                <Typography variant="body2" gutterBottom>
                                    <strong>Number of Accessories:</strong> {accessories.length}
                                </Typography>
                            </Box>
                        </>
                    )}
                </DialogContent>
                <DialogActions sx={{ p: 2 }}>
                    <Button
                        onClick={() => setOpenDialog(false)}
                        sx={{ borderRadius: 2 }}
                        disabled={loading}
                    >
                        Cancel
                    </Button>
                    <Button
                        onClick={handleConfirmSubmit}
                        variant="contained"
                        sx={{ borderRadius: 2 }}
                        disabled={loading}
                    >
                        {loading ? 'Processing...' : 'Confirm & Save'}
                    </Button>
                </DialogActions>
            </Dialog>

            {/* Notification */}
            <Snackbar
                open={notification.open}
                autoHideDuration={6000}
                onClose={() => setNotification(prev => ({ ...prev, open: false }))}
                anchorOrigin={{ vertical: 'top', horizontal: 'right' }}
            >
                <Alert
                    onClose={() => setNotification(prev => ({ ...prev, open: false }))}
                    severity={notification.severity}
                    variant="filled"
                    sx={{ width: '100%', borderRadius: 2 }}
                >
                    {notification.message}
                </Alert>
            </Snackbar>
        </Box>
    );
};

export default AddDeviceForm;