import React, { useState, useMemo } from 'react';
import { Routes, Route, Navigate } from 'react-router-dom';
import { ThemeProvider, CssBaseline } from '@mui/material';
import { createTheme } from '@mui/material/styles';
import  baseTheme from './theme/theme';  // Fixed import
import PrivateRoute from './routes/PrivateRoute';

import Login from './pages/FileTracker/Login';
import Frame from './pages/FileTracker/Frame';
import Profile from './pages/FileTracker/Profile';
import DashboardComponents from './pages/FileTracker/Dashboard/components/DashboardComponents';
import UserManagement from './pages/FileTracker/Users/UserManagement';
import ManageUsers from './pages/FileTracker/Users/ManageUsers';
import CreateRack from './pages/FileTracker/Racks/CreateRack';
import ManageRacks from './pages/FileTracker/Racks/ManageRacks';
import CreatePatient from './pages/FileTracker/Patient/CreatePatient';
import ManagePatients from './pages/FileTracker/Patient/ManagePatients';
import CreateFile from './pages/FileTracker/Files/CreateFile';
import ManageFiles from './pages/FileTracker/Files/ManageFiles';
import DispatchFile from './pages/FileTracker/FileTransfer/DispatchFile';
import ReturnFile from './pages/FileTracker/FileTransfer/ReturnFile';
import GetDispatchedFiles from './pages/FileTracker/Reports/GetDispatchedFiles';
import FileTransferReport from './pages/FileTracker/Reports/FileTransferReport';
import FileNotReturnedReport from './pages/FileTracker/Reports/FileNotReturnedReport';
import FileHistory from './pages/FileTracker/FileTracking/FileHistory';

import LoginDevice from './pages/DeviceManagement/Login';
import FrameDevice from './pages/DeviceManagement/FrameDevice';
import DashboardDevice from './pages/DeviceManagement/Dashboard/DashboardDevice';

import EodDashboard from './pages/DeviceManagement/Eod/EodDashboard';
import CreateEod from './pages/DeviceManagement/Eod/CreateEod';
import ClinicalInchargeForm from './pages/DeviceManagement/ClinicalIncharge/ClinicalInchargeForm';
import AllUsers from './pages/DeviceManagement/Users/AllUsers';
import AddDevice from './pages/DeviceManagement/Device/CreateDevice';
import ManageDevice from './pages/DeviceManagement/Device/ManageDevice';
import AddAccessory from './pages/DeviceManagement/Device/AddAccessory';
import ManageAccessory from './pages/DeviceManagement/Device/ManageAccessory';
import AllAccessory from './pages/DeviceManagement/Device/AllAccessory';
import AllDevice from './pages/DeviceManagement/Device/AllDevice';
import DailyInspection from './pages/DeviceManagement/Inspection/DailyInspection';
import Home from './pages/Home';
import CreateHod from './pages/DeviceManagement/Hod/CreateHod';
import ManageHodPage from './pages/DeviceManagement/Hod/ManageHODPage';
import ManageEodPage from './pages/DeviceManagement/Eod/ManageEod';
import ManageClinicalIncharge from './pages/DeviceManagement/ClinicalIncharge/ManageClinicalIncharge';
import ReportIssue from './pages/DeviceManagement/Inspection/IssueReportingForm';
import ViewIssue from './pages/DeviceManagement/Inspection/ViewIssues';
import ManageIssue from './pages/DeviceManagement/Inspection/ManageIssuesPage';
import IssuesInspect from './pages/DeviceManagement/Inspection/IssuesInspect';
import CompanyInspection from './pages/DeviceManagement/Inspection/CompanyInspectionForm';
import InspectionReportsPage from './pages/DeviceManagement/Reports/InspectionReport';

export const ColorModeContext = React.createContext({
  mode: 'light',
  toggleColorMode: () => { },
});

function App() {
  const [mode, setMode] = useState(localStorage.getItem('themeMode') || 'light');

  const colorMode = useMemo(
    () => ({
      mode,
      toggleColorMode: () => {
        setMode((prevMode) => {
          const newMode = prevMode === 'light' ? 'dark' : 'light';
          localStorage.setItem('themeMode', newMode);
          return newMode;
        });
      },
    }),
    [mode]
  );

  const theme = useMemo(
    () =>
      createTheme({
        ...baseTheme,  // Use the imported baseTheme
        palette: {
          ...baseTheme.palette,
          mode,
          background: {
            default: mode === 'light' ? '#f5f5f5' : '#121212',
            paper: mode === 'light' ? '#ffffff' : '#1e1e1e',
          },
        },
      }),
    [mode]
  );
  

  return (
    <ColorModeContext.Provider value={colorMode}>
      <ThemeProvider theme={theme}>
        <CssBaseline />
        <Routes>
          <Route path="/" element={<Home />} />
          
          {/* File Tracker Routes */}
          <Route path="/file-tracker">
            <Route path="login" element={<Login />} />
            <Route element={
              <PrivateRoute>
                <Frame />
              </PrivateRoute>
            }>
              <Route path="overview" element={<DashboardComponents />} />
              <Route path="profile" element={<Profile />} />
              
              {/* Admin only routes */}
              <Route path="create-user" element={
                <PrivateRoute requiredRole="ADMIN">
                  <UserManagement />
                </PrivateRoute>
              } />
              <Route path="manage-users" element={
                <PrivateRoute requiredRole="ADMIN">
                  <ManageUsers />
                </PrivateRoute>
              } />
              
              {/* Regular protected routes */}
              <Route path="reset-password" element={<div>Reset Password Component</div>} />
              <Route path="create-rack" element={<CreateRack />} />
              <Route path="manage-racks" element={<ManageRacks />} />
              <Route path="dispatched-files" element={<GetDispatchedFiles />} />
              <Route path="transfer-report" element={<FileTransferReport />} />
              <Route path="not-returned-report" element={<FileNotReturnedReport />} />
              <Route path="create-patient" element={<CreatePatient />} />
              <Route path="manage-patients" element={<ManagePatients />} />
              <Route path="create-file" element={<CreateFile />} />
              <Route path="manage-files" element={<ManageFiles />} />
              <Route path="dispatch-file" element={<DispatchFile />} />
              <Route path="file-tracking" element={<FileHistory />} />
              <Route path="return-file" element={<ReturnFile />} />
            </Route>
          </Route>

          {/* Device Portal Routes */}
          <Route path="/device-portal">
            <Route path="login" element={<LoginDevice />} />
            <Route element={
              <PrivateRoute>
                <FrameDevice />
              </PrivateRoute>
            }>
              <Route path="overview" element={<DashboardDevice />} />
              <Route path="profile" element={<Profile />} />
              
              {/* EOD Management */}
              <Route path="eod-dashboard" element={<EodDashboard />} />
              <Route path="create-eod" element={<CreateEod />} />
              <Route path="create-clinical-incharge" element={<ClinicalInchargeForm />} />
              <Route path="all-users" element={<AllUsers />} />
              
              {/* Device Management */}
              <Route path="add-device" element={<AddDevice />} />
              <Route path="device-manage" element={<ManageDevice />} />
              <Route path="all-device" element={<AllDevice />} />
              <Route path="add-accessories" element={<AddAccessory />} />
              <Route path="manage-accessories" element={<ManageAccessory />} />
              <Route path="all-accessories" element={<AllAccessory />} />
              <Route path="create-hod" element={<CreateHod />} />
              <Route path="manage-hod" element={<ManageHodPage />} />
              <Route path="manage-eod" element={<ManageEodPage />} />
              <Route path="manage-clinical-incharge" element={< ManageClinicalIncharge/>} />
              <Route path="daily-inspection" element={<DailyInspection />} />
              <Route path="report-issue" element={<ReportIssue />} />
              <Route path="view-issue" element={<ViewIssue />} />
              <Route path="manage-issue" element={<ManageIssue />} />
              <Route path="issues-inspect/:issueId" element={<IssuesInspect />} />
              <Route path="inspection-company/:issueId" element={<CompanyInspection />} />
              <Route path="reports-inspections" element={<InspectionReportsPage />} />
            </Route>
          </Route>

          <Route path="*" element={<Navigate to="/" replace />} />
        </Routes>
      </ThemeProvider>
    </ColorModeContext.Provider>
  );
}

export default App;