// components/Overview.jsx or features/components/Overview.jsx (adjust path)
import React, { useState, useEffect } from 'react';
import {
  Box,
  Grid,
  Card,
  CardContent,
  CardHeader,
  List,
  ListItem,
  ListItemText,
  ListItemIcon,
  Avatar,
  Typography,
  IconButton,
  Tooltip,
  useTheme,
  alpha,
  Chip,
  CircularProgress,
  Button,
} from '@mui/material';
import {
  MedicalServices,
  Build,
  Assignment,
  Warning,
  CheckCircle,
  Error as ErrorIcon,
  Timeline,
  CalendarMonth,
  MoreVert,
  Refresh,
  FilterList,
  NoteAdd,
  LocalHospital,
} from '@mui/icons-material';
import {
  AreaChart,
  Area,
  XAxis,
  YAxis,
  CartesianGrid,
  Tooltip as RechartsTooltip,
  ResponsiveContainer,
} from 'recharts';
import overviewService from '../../../features/services/overviewService'; // Adjust the import path
import { useNavigate } from 'react-router-dom';

const CustomChartTooltip = ({ active, payload, label }) => {
  if (active && payload && payload.length) {
    return (
      <Box
        sx={{
          bgcolor: 'background.paper',
          p: 2,
          boxShadow: 3,
          borderRadius: 1,
          border: '1px solid',
          borderColor: 'divider',
        }}
      >
        <Typography variant="subtitle2" sx={{ mb: 1 }}>{label}</Typography>
        {payload.map((entry, index) => (
          <Box key={index} sx={{ display: 'flex', alignItems: 'center', gap: 1, mb: 0.5 }}>
            <Box
              sx={{
                width: 12,
                height: 12,
                borderRadius: '50%',
                bgcolor: entry.color,
              }}
            />
            <Typography variant="body2">
              {entry.name}: {entry.value}%
            </Typography>
          </Box>
        ))}
      </Box>
    );
  }
  return null;
};

const Overview = () => {
  const theme = useTheme();
  const [stats, setStats] = useState({
    totalEquipment: 0,
    todaysInspections: 0,
    pendingMaintenance: 0,
    criticalAlerts: 0,
    totalIssues:0,
  });
  const [activityData, setActivityData] = useState([]);
  const [recentInspections, setRecentInspections] = useState([]);
  const [maintenanceAlerts, setMaintenanceAlerts] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);
  const navigate = useNavigate();

  useEffect(() => {
    const fetchData = async () => {
      try {
        setLoading(true);
        const [statsData, activityData, recentInspectionsData, maintenanceAlertsData] = await Promise.all([
          overviewService.getStats(),
          overviewService.getActivityData(),
          overviewService.getRecentInspections(),
          overviewService.getMaintenanceAlerts(),
        ]);

        setStats(statsData);
        setActivityData(activityData);
        setRecentInspections(recentInspectionsData);
        setMaintenanceAlerts(maintenanceAlertsData);
      } catch (err) {
        console.error('Error fetching overview data:', err);
        setError(err.message || 'Failed to load overview data. Please try again.');
      } finally {
        setLoading(false);
      }
    };

    fetchData();
  }, []);

  if (loading) {
    return (
      <Box sx={{ display: 'flex', justifyContent: 'center', alignItems: 'center', minHeight: '100vh' }}>
        <CircularProgress />
      </Box>
    );
  }

  if (error) {
    return (
      <Box sx={{ p: 3, display: 'flex', flexDirection: 'column', alignItems: 'center', gap: 2 }}>
        <Typography variant="body1" color="error">{error}</Typography>
        <Button variant="contained" onClick={() => window.location.reload()} color="primary">
          Retry
        </Button>
      </Box>
    );
  }

  const statsData = [
    {
      title: 'Total Equipment',
      value: stats.totalEquipment.toString(),
      icon: <MedicalServices />,
      color: theme.palette.primary.main,
      subtext: `${stats.totalIssues > 0 ? stats.totalIssues : 0} total issues reported.`,
    },
    {
      title: "Today's Inspections",
      value: stats.todaysInspections.toString(),
      icon: <Assignment />,
      color: theme.palette.info.main,
      subtext: `${stats.criticalAlerts > 0 ? stats.criticalAlerts : 0} high priority issues pending.`,
    },
    {
      title: 'Pending Maintenance',
      value: stats.pendingMaintenance.toString(),
      icon: <Build />,
      color: theme.palette.warning.main,
      subtext: 'Next 24 hours',
    },
    {
      title: 'Critical Alerts',
      value: stats.criticalAlerts.toString(),
      icon: <Warning />,
      color: theme.palette.error.main,
      subtext: 'Immediate attention',
    },
  ];

  return (
    <Box sx={{ p: 3 }}>
      {/* Header */}
      <Box sx={{
        display: 'flex',
        justifyContent: 'space-between',
        alignItems: 'center',
        mb: 3
      }}>
        <Box>
          <Typography variant="h5" sx={{ fontWeight: 600, mb: 1 }}>
            Equipment Management Dashboard
          </Typography>
          <Typography variant="body2" color="text.secondary">
            Overview of medical equipment status and maintenance
          </Typography>
        </Box>
        <Box sx={{ display: 'flex', gap: 1 }}>
          <Tooltip title="Add New Equipment">
            <IconButton size="small" color="primary"onClick={() => navigate('/device-portal/add-device')}>
              <NoteAdd />
            </IconButton>
          </Tooltip>
          <Tooltip title="Refresh">
            <IconButton size="small" onClick={() => window.location.reload()}>
              <Refresh />
            </IconButton>
          </Tooltip>
        </Box>
      </Box>

      {/* Stats Cards */}
      <Grid container spacing={3} sx={{ mb: 3 }}>
        {statsData.map((stat) => (
          <Grid item xs={12} sm={6} md={3} key={stat.title}>
            <Card
              elevation={0}
              sx={{
                borderRadius: 5,
                border: `1px solid ${alpha(stat.color, 0.2)}`,
                transition: 'transform 0.2s',
                '&:hover': {
                  transform: 'translateY(-4px)',
                },
              }}
            >
              <CardContent>
                <Box sx={{ display: 'flex', alignItems: 'center', mb: 2 }}>
                  <Box
                    sx={{
                      bgcolor: alpha(stat.color, 0.1),
                      borderRadius: 2,
                      p: 1,
                      display: 'flex',
                    }}
                  >
                    {React.cloneElement(stat.icon, {
                      sx: { fontSize: 24, color: stat.color }
                    })}
                  </Box>
                </Box>
                <Typography variant="h4" sx={{ fontWeight: 600, mb: 1 }}>
                  {stat.value}
                </Typography>
                <Typography variant="body2" color="text.secondary" sx={{ mb: 1 }}>
                  {stat.title}
                </Typography>
                <Typography variant="caption" sx={{ color: stat.color, fontWeight: "bold" }}>
                  {stat.subtext}
                </Typography>
              </CardContent>
            </Card>
          </Grid>
        ))}
      </Grid>

      <Grid container spacing={3}>
        {/* Recent Inspections */}
        <Grid item xs={12}>
          <Card elevation={0} sx={{ borderRadius: 5, border: '1px solid #e8e8e8' }}>
            <CardHeader
              title="Recent Inspections"
              action={
                <Box sx={{ display: 'flex', gap: 1 }}>
                  <Chip
                    icon={<CheckCircle sx={{ fontSize: 16 }} />}
                    label={`${
                      recentInspections.filter(inspection => inspection.status === 'Completed').length
                    } completed today`}
                    size="small"
                    color="success"
                  />
                  <IconButton size="small">
                    <MoreVert fontSize="small" />
                  </IconButton>
                </Box>
              }
            />
            <CardContent>
              <Grid container spacing={2}>
                {recentInspections.map((inspection, index) => (
                  <Grid item xs={12} md={4} key={index}>
                    <Box
                      sx={{
                        p: 2,
                        borderRadius: 2,
                        border: `1px solid ${alpha(theme.palette.primary.main, 0.1)}`,
                        '&:hover': {
                          bgcolor: alpha(theme.palette.primary.main, 0.02),
                        },
                      }}
                    >
                      <Box sx={{ display: 'flex', gap: 2 }}>
                        <Avatar sx={{ bgcolor: alpha(theme.palette.primary.main, 0.1) }}>
                          <LocalHospital color="primary" />
                        </Avatar>
                        <Box sx={{ flex: 1 }}>
                          <Box sx={{ display: 'flex', justifyContent: 'space-between', mb: 1 }}>
                            <Typography variant="subtitle2" fontWeight={600}>
                              {inspection.equipmentId}
                            </Typography>
                            <Chip
                              label={inspection.status}
                              size="small"
                              color={
                                inspection.status === 'Completed'
                                  ? 'success'
                                  : inspection.status === 'Pending'
                                    ? 'warning'
                                    : 'info'
                              }
                            />
                          </Box>
                          <Typography variant="body2" color="text.secondary">
                            {inspection.department}
                          </Typography>
                          <Box sx={{ display: 'flex', justifyContent: 'space-between', mt: 1 }}>
                            <Typography variant="caption" color="text.secondary">
                              {inspection.inspector}
                            </Typography>
                            <Typography variant="caption" color="text.secondary">
                              {new Date(inspection.date).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' }) + ' ' + new Date(inspection.date).toLocaleDateString()}
                            </Typography>
                          </Box>
                        </Box>
                      </Box>
                    </Box>
                  </Grid>
                ))}
              </Grid>
            </CardContent>
          </Card>
        </Grid>
        {/* Equipment Status Chart */}
        <Grid item xs={12} md={8}>
          <Card elevation={0} sx={{ borderRadius: 5, border: '1px solid #e8e8e8' }}>
            <CardHeader
              title="Equipment Operational Status"
              action={
                <Box sx={{ display: 'flex', gap: 1, alignItems: 'center' }}>
                  <Chip
                    label="Last 7 days"
                    size="small"
                    icon={<CalendarMonth sx={{ fontSize: 16 }} />}
                  />
                  <IconButton size="small">
                    <MoreVert fontSize="small" />
                  </IconButton>
                </Box>
              }
            />
            <CardContent sx={{ height: 300, p: 0 }}>
              <ResponsiveContainer width="100%" height="100%">
                <AreaChart data={activityData}>
                  <defs>
                    <linearGradient id="operationalGradient" x1="0" y1="0" x2="0" y2="1">
                      <stop offset="5%" stopColor={theme.palette.success.main} stopOpacity={0.8} />
                      <stop offset="95%" stopColor={theme.palette.success.main} stopOpacity={0} />
                    </linearGradient>
                    <linearGradient id="maintenanceGradient" x1="0" y1="0" x2="0" y2="1">
                      <stop offset="5%" stopColor={theme.palette.warning.main} stopOpacity={0.8} />
                      <stop offset="95%" stopColor={theme.palette.warning.main} stopOpacity={0} />
                    </linearGradient>
                  </defs>
                  <XAxis
                    dataKey="day"
                    axisLine={false}
                    tickLine={false}
                    padding={{ left: 10, right: 10 }}
                  />
                  <YAxis
                    axisLine={false}
                    tickLine={false}
                    tickFormatter={(value) => `${value}%`}
                  />
                  <CartesianGrid strokeDasharray="3 3" vertical={false} />
                  <RechartsTooltip content={<CustomChartTooltip />} />
                  <Area
                    type="monotone"
                    dataKey="operational"
                    stroke={theme.palette.success.main}
                    fillOpacity={1}
                    fill="url(#operationalGradient)"
                    name="Operational"
                  />
                  <Area
                    type="monotone"
                    dataKey="maintenance"
                    stroke={theme.palette.warning.main}
                    fillOpacity={1}
                    fill="url(#maintenanceGradient)"
                    name="Under Maintenance"
                  />
                </AreaChart>
              </ResponsiveContainer>
            </CardContent>
          </Card>
        </Grid>

        {/* Maintenance Alerts */}
        <Grid item xs={12} md={4}>
          <Card elevation={0} sx={{ height: '100%', borderRadius: 5, border: '1px solid #e8e8e8' }}>
            <CardHeader
              title="Maintenance Alerts"
              action={
                <Box sx={{ display: 'flex', gap: 1, alignItems: 'center' }}>
                  <Chip
                    label="Today"
                    size="small"
                    color="warning"
                    icon={<CalendarMonth sx={{ fontSize: 16 }} />}
                  />
                  <IconButton size="small">
                    <FilterList fontSize="small" />
                  </IconButton>
                </Box>
              }
            />
            <CardContent sx={{ p: '0 !important' }}>
              <List>
                {maintenanceAlerts.map((alert) => (
                  <ListItem
                    key={alert.id}
                    sx={{
                      px: 2,
                      py: 1.5,
                      mb: 1,
                      borderRadius: 1,
                      bgcolor: alpha(
                        alert.priority === 'critical'
                          ? theme.palette.error.main
                          : theme.palette.warning.main,
                        0.1
                      ),
                    }}
                  >
                    <ListItemIcon>
                      {alert.priority === 'critical' ? (
                        <ErrorIcon color="error" />
                      ) : (
                        <Warning color="warning" />
                      )}
                    </ListItemIcon>
                    <ListItemText
                      primary={
                        <Box sx={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
                          <Typography variant="subtitle2">{alert.equipment}</Typography>
                          <Chip
                            label={alert.status}
                            size="small"
                            color={alert.status === 'open' ? 'error' : 'info'}
                            sx={{ minWidth: 85 }}
                            onClick={() => navigate('/device-portal/manage-issue')}
                          />
                        </Box>
                      }
                      secondary={
                        <Typography variant="body2" color="text.secondary" sx={{ mt: 0.5 }}>
                          {alert.issue}
                        </Typography>
                      }
                    />
                  </ListItem>
                ))}
              </List>
            </CardContent>
          </Card>
        </Grid>
      </Grid>
    </Box>
  );
};

export default Overview;