import React, { useState, useEffect } from 'react';
import {
    Box,
    Card,
    CardContent,
    TextField,
    Button,
    Typography,
    Stack,
    Grid,
    IconButton,
    FormControl,
    InputLabel,
    Select,
    MenuItem,
    FormControlLabel,
    Switch,
    Divider,
    Paper,
    Alert,
    Snackbar,
    CircularProgress
} from '@mui/material';
import {
    ArrowBack,
    Upload,
    Save,
    AddCircleOutline
} from '@mui/icons-material';
import { useNavigate } from 'react-router-dom';
import { DatePicker } from '@mui/x-date-pickers/DatePicker';
import { LocalizationProvider } from '@mui/x-date-pickers';
import { AdapterDateFns } from '@mui/x-date-pickers/AdapterDateFns';
import deviceService from '../../../features/services/deviceService'; // Adjust path as needed

const AddAccessoryForm = () => {
    const navigate = useNavigate();

    // Device selection state
    const [selectedDevice, setSelectedDevice] = useState('');
    const [devices, setDevices] = useState([]);
    const [deviceDetails, setDeviceDetails] = useState(null);
    const [loading, setLoading] = useState(false);
    const [error, setError] = useState(null);

    // Accessory State
    const [accessoryData, setAccessoryData] = useState({
        itemName: '',
        supplier: '',
        purchaseDate: null,
        isRight: false,
        isLeft: false,
        status: 'active',
        photo: null
    });

    const [notification, setNotification] = useState({
        open: false,
        message: '',
        severity: 'success'
    });

    // Fetch devices from API
    useEffect(() => {
        const fetchDevices = async () => {
            setLoading(true);
            try {
                const response = await deviceService.getAllDevices();
                setDevices(response.data || []); // Assuming response.data contains the devices array
            } catch (err) {
                setError('Failed to fetch devices');
                setNotification({
                    open: true,
                    message: 'Failed to fetch devices',
                    severity: 'error'
                });
            } finally {
                setLoading(false);
            }
        };

        fetchDevices();
    }, []);

    // Handle device selection
    const handleDeviceChange = async (event) => {
        const deviceId = event.target.value;
        setSelectedDevice(deviceId);
        setLoading(true);
        try {
            const response = await deviceService.getDeviceById(deviceId);
            setDeviceDetails(response.data); // Assuming response.data contains device details
        } catch (err) {
            setNotification({
                open: true,
                message: 'Failed to fetch device details',
                severity: 'error'
            });
            setDeviceDetails(null);
        } finally {
            setLoading(false);
        }
    };

    const handleAccessoryChange = (event) => {
        const { name, value, checked, type } = event.target;
        setAccessoryData(prev => ({
            ...prev,
            [name]: type === 'checkbox' ? checked : value
        }));
    };

    const handlePhotoChange = (event) => {
        const file = event.target.files[0];
        if (file) {
            if (file.size > 5 * 1024 * 1024) {
                setNotification({
                    open: true,
                    message: 'File size should not exceed 5MB',
                    severity: 'error'
                });
                return;
            }
            setAccessoryData(prev => ({
                ...prev,
                photo: file
            }));
        }
    };

    const handleSubmit = async (e) => {
        e.preventDefault();
        if (!selectedDevice) {
            setNotification({
                open: true,
                message: 'Please select a device first',
                severity: 'error'
            });
            return;
        }
    
        setLoading(true);
        try {
            const formData = new FormData();
            formData.append('device', selectedDevice); // Changed from 'deviceId' to 'device'
            Object.keys(accessoryData).forEach(key => {
                if (key === 'photo') {
                    if (accessoryData[key]) {
                        formData.append('photo', accessoryData[key]);
                    }
                } else if (key === 'purchaseDate') {
                    if (accessoryData[key]) {
                        formData.append(key, accessoryData[key].toISOString());
                    }
                } else {
                    formData.append(key, accessoryData[key]);
                }
            });
    
            // Log FormData contents for debugging
            for (let [key, value] of formData.entries()) {
                console.log(`${key}: ${value}`);
            }
    
            const response = await deviceService.createAccessory(formData);
    
            setNotification({
                open: true,
                message: 'Accessory added successfully!',
                severity: 'success'
            });
    
            // Reset form
            setAccessoryData({
                itemName: '',
                supplier: '',
                purchaseDate: null,
                isRight: false,
                isLeft: false,
                status: 'active',
                photo: null
            });
    
        } catch (error) {
            console.error('Error adding accessory:', error);
            setNotification({
                open: true,
                message: error.response?.data?.message || 'Failed to add accessory',
                severity: 'error'
            });
        } finally {
            setLoading(false);
        }
    };

    return (
        <Box sx={{ p: 3, backgroundColor: '#f0f7ff', minHeight: '100vh' }}>
            <Card
                elevation={0}
                sx={{
                    borderRadius: 4,
                    background: 'linear-gradient(135deg, #ffffff 0%, #f8faff 100%)',
                    boxShadow: '0 8px 32px rgba(0, 0, 0, 0.1)'
                }}
            >
                <CardContent sx={{ p: 4 }}>
                    {/* Header */}
                    <Stack
                        direction="row"
                        alignItems="center"
                        spacing={2}
                        mb={4}
                    >
                        <IconButton
                            onClick={() => navigate(-1)}
                            sx={{
                                backgroundColor: '#e3f2fd',
                                '&:hover': { backgroundColor: '#bbdefb' }
                            }}
                            disabled={loading}
                        >
                            <ArrowBack />
                        </IconButton>
                        <Stack direction="column">
                            <Typography
                                variant="h5"
                                sx={{
                                    fontWeight: 600,
                                    color: '#1976d2'
                                }}
                            >
                                Add New Accessory
                            </Typography>
                            <Typography variant="body2" color="textSecondary">
                                Select a device and add its accessory details
                            </Typography>
                        </Stack>
                    </Stack>

                    <Divider sx={{ mb: 4 }} />

                    {loading && (
                        <Box sx={{ display: 'flex', justifyContent: 'center', mb: 4 }}>
                            <CircularProgress />
                        </Box>
                    )}

                    <form onSubmit={handleSubmit}>
                        {/* Device Selection Section */}
                        <Stack direction="row" alignItems="center" spacing={1} mb={3}>
                            <AddCircleOutline color="primary" />
                            <Typography variant="h6" color="primary">
                                Select Device
                            </Typography>
                        </Stack>

                        <Grid container spacing={3} mb={4}>
                            <Grid item xs={12}>
                                <FormControl fullWidth>
                                    <InputLabel>Device</InputLabel>
                                    <Select
                                        value={selectedDevice}
                                        onChange={handleDeviceChange}
                                        label="Device"
                                        required
                                        sx={{ borderRadius: 2 }}
                                        disabled={loading}
                                    >
                                        {devices.map((device) => (
                                            <MenuItem key={device._id} value={device._id}>
                                                {device.deviceName} - {device.serialNumber}
                                            </MenuItem>
                                        ))}
                                    </Select>
                                </FormControl>
                            </Grid>

                            {deviceDetails && (
                                <Grid item xs={12}>
                                    <Paper
                                        elevation={0}
                                        sx={{
                                            p: 2,
                                            borderRadius: 2,
                                            backgroundColor: '#e3f2fd',
                                            border: '1px solid #bbdefb'
                                        }}
                                    >
                                        <Typography variant="subtitle2" gutterBottom>
                                            Selected Device Details:
                                        </Typography>
                                        <Typography variant="body2">
                                            Device Name: {deviceDetails.deviceName}
                                        </Typography>
                                        <Typography variant="body2">
                                            Serial Number: {deviceDetails.serialNumber}
                                        </Typography>
                                    </Paper>
                                </Grid>
                            )}
                        </Grid>

                        {/* Accessory Details Section */}
                        {selectedDevice && (
                            <>
                                <Stack direction="row" alignItems="center" spacing={1} mb={3}>
                                    <AddCircleOutline color="primary" />
                                    <Typography variant="h6" color="primary">
                                        Accessory Details
                                    </Typography>
                                </Stack>

                                <Paper
                                    elevation={0}
                                    sx={{
                                        p: 3,
                                        borderRadius: 2,
                                        border: '1px solid #e0e0e0',
                                        mb: 4
                                    }}
                                >
                                    <Grid container spacing={3}>
                                        <Grid item xs={12} sm={6}>
                                            <TextField
                                                fullWidth
                                                label="Item Name"
                                                name="itemName"
                                                value={accessoryData.itemName}
                                                onChange={handleAccessoryChange}
                                                required
                                                disabled={loading}
                                                InputProps={{
                                                    sx: { borderRadius: 2 }
                                                }}
                                            />
                                        </Grid>
                                        <Grid item xs={12} sm={6}>
                                            <TextField
                                                fullWidth
                                                label="Supplier"
                                                name="supplier"
                                                value={accessoryData.supplier}
                                                onChange={handleAccessoryChange}
                                                required
                                                disabled={loading}
                                                InputProps={{
                                                    sx: { borderRadius: 2 }
                                                }}
                                            />
                                        </Grid>
                                        <Grid item xs={12} sm={6}>
                                            <LocalizationProvider dateAdapter={AdapterDateFns}>
                                                <DatePicker
                                                    label="Purchase Date"
                                                    value={accessoryData.purchaseDate}
                                                    onChange={(date) => handleAccessoryChange({
                                                        target: { name: 'purchaseDate', value: date }
                                                    })}
                                                    disabled={loading}
                                                    renderInput={(params) => (
                                                        <TextField
                                                            {...params}
                                                            fullWidth
                                                            required
                                                            InputProps={{
                                                                ...params.InputProps,
                                                                sx: { borderRadius: 2 }
                                                            }}
                                                        />
                                                    )}
                                                />
                                            </LocalizationProvider>
                                        </Grid>
                                        <Grid item xs={12} sm={6}>
                                            <FormControl fullWidth>
                                                <InputLabel>Status</InputLabel>
                                                <Select
                                                    name="status"
                                                    value={accessoryData.status}
                                                    onChange={handleAccessoryChange}
                                                    label="Status"
                                                    disabled={loading}
                                                    sx={{ borderRadius: 2 }}
                                                >
                                                    <MenuItem value="active">Active</MenuItem>
                                                    <MenuItem value="inactive">Inactive</MenuItem>
                                                    <MenuItem value="maintenance">Under Maintenance</MenuItem>
                                                </Select>
                                            </FormControl>
                                        </Grid>
                                        <Grid item xs={12} sm={6}>
                                            <Paper
                                                elevation={0}
                                                sx={{
                                                    p: 2,
                                                    borderRadius: 2,
                                                    backgroundColor: '#e3f2fd',
                                                    border: '1px solid #bbdefb'
                                                }}
                                            >
                                                <Stack direction="row" spacing={2}>
                                                    <FormControlLabel
                                                        control={
                                                            <Switch
                                                                checked={accessoryData.isRight}
                                                                onChange={handleAccessoryChange}
                                                                name="isRight"
                                                                disabled={loading}
                                                            />
                                                        }
                                                        label="Right"
                                                    />
                                                    <FormControlLabel
                                                        control={
                                                            <Switch
                                                                checked={accessoryData.isLeft}
                                                                onChange={handleAccessoryChange}
                                                                name="isLeft"
                                                                disabled={loading}
                                                            />
                                                        }
                                                        label="Left"
                                                    />
                                                </Stack>
                                            </Paper>
                                        </Grid>
                                        <Grid item xs={12}>
                                            <Button
                                                component="label"
                                                variant="outlined"
                                                startIcon={<Upload />}
                                                sx={{ borderRadius: 2 }}
                                                disabled={loading}
                                            >
                                                Upload Accessory Image
                                                <input
                                                    type="file"
                                                    hidden
                                                    accept="image/*"
                                                    onChange={handlePhotoChange}
                                                />
                                            </Button>
                                            {accessoryData.photo && (
                                                <Typography variant="body2" sx={{ mt: 1, color: 'success.main' }}>
                                                    Image uploaded: {accessoryData.photo.name}
                                                </Typography>
                                            )}
                                        </Grid>
                                    </Grid>
                                </Paper>
                            </>
                        )}

                        {/* Form Actions */}
                        <Stack direction="row" spacing={2} justifyContent="flex-end">
                            <Button
                                variant="outlined"
                                onClick={() => navigate(-1)}
                                sx={{ borderRadius: 2, px: 4 }}
                                disabled={loading}
                            >
                                Cancel
                            </Button>
                            <Button
                                type="submit"
                                variant="contained"
                                startIcon={<Save />}
                                sx={{
                                    borderRadius: 2,
                                    px: 4,
                                    backgroundColor: '#1976d2',
                                    '&:hover': {
                                        backgroundColor: '#1565c0',
                                        boxShadow: '0 4px 12px rgba(25, 118, 210, 0.3)',
                                    }
                                }}
                                disabled={loading}
                            >
                                {loading ? 'Saving...' : 'Save Accessory'}
                            </Button>
                        </Stack>
                    </form>
                </CardContent>
            </Card>

            {/* Notification */}
            <Snackbar
                open={notification.open}
                autoHideDuration={6000}
                onClose={() => setNotification(prev => ({ ...prev, open: false }))}
                anchorOrigin={{ vertical: 'top', horizontal: 'right' }}
            >
                <Alert
                    onClose={() => setNotification(prev => ({ ...prev, open: false }))}
                    severity={notification.severity}
                    variant="filled"
                    sx={{ width: '100%', borderRadius: 2 }}
                >
                    {notification.message}
                </Alert>
            </Snackbar>
        </Box>
    );
};

export default AddAccessoryForm;