import React, { useState, useEffect } from 'react';
import {
    Box,
    Card,
    CardContent,
    TextField,
    Button,
    Typography,
    Stack,
    Grid,
    IconButton,
    FormControl,
    InputLabel,
    Select,
    MenuItem,
    Paper,
    Chip,
    Tooltip,
    TableContainer,
    Table,
    TableHead,
    TableBody,
    TableRow,
    TableCell,
    TablePagination,
    InputAdornment,
    Dialog,
    DialogTitle,
    DialogContent,
    DialogActions,
    Alert,
    Snackbar,
    Collapse,
    CircularProgress
} from '@mui/material';
import {
    Add,
    Search,
    FilterList,
    Edit,
    Delete,
    Visibility,
    ClearAll,
    Download,
    ExpandMore,
    KeyboardArrowUp,
    KeyboardArrowDown,
    Engineering,
    Build,
    Image,
    Warning,
    PictureAsPdf
} from '@mui/icons-material';
import { useNavigate } from 'react-router-dom';
import deviceService from '../../../features/services/deviceService';
import exportToPDF from './exportPdf';
import * as XLSX from 'xlsx';

const ManageDevices = () => {
    const navigate = useNavigate();

    // States
    const [devices, setDevices] = useState([]);
    const [filteredDevices, setFilteredDevices] = useState([]);
    const [loading, setLoading] = useState(true);
    const [page, setPage] = useState(0);
    const [rowsPerPage, setRowsPerPage] = useState(10);
    const [totalDevices, setTotalDevices] = useState(0);
    const [searchQuery, setSearchQuery] = useState('');
    const [filters, setFilters] = useState({
        status: '',
        hasAMC: '',
        roomNo: ''
    });
    const [rooms, setRooms] = useState([]);
    const [expandedDevice, setExpandedDevice] = useState(null);
    const [deleteDialog, setDeleteDialog] = useState({ open: false, device: null });
    const [notification, setNotification] = useState({
        open: false,
        message: '',
        severity: 'success'
    });
    const [showFilters, setShowFilters] = useState(false);
    const [imagePreview, setImagePreview] = useState({ open: false, url: '' });

    // Fetch devices from API
    const fetchDevices = async () => {
        setLoading(true);
        try {
            // Prepare query parameters
            const params = {
                page: page + 1, // API uses 1-indexed pagination
                limit: rowsPerPage
            };

            // Add search and filters
            if (searchQuery) {
                params.search = searchQuery;
            }
            if (filters.status) {
                params.status = filters.status;
            }
            if (filters.hasAMC) {
                params.hasAMC = filters.hasAMC === 'yes';
            }
            if (filters.roomNo) {
                params.roomNo = filters.roomNo;
            }

            // Fetch data from API
            const response = await deviceService.getAllDevices(params);

            setDevices(response.data);
            setFilteredDevices(response.data);
            setTotalDevices(response.pagination.total);

            // Extract unique rooms for room filter
            const uniqueRooms = [...new Set(response.data.map(device => device.roomNo))].filter(Boolean);
            setRooms(uniqueRooms);
        } catch (error) {
            console.error('Error fetching devices:', error);
            showNotification('Failed to fetch devices', 'error');
        } finally {
            setLoading(false);
        }
    };

    // Initial fetch
    useEffect(() => {
        fetchDevices();
    }, []);

    // Refetch when pagination or filters change
    useEffect(() => {
        fetchDevices();
    }, [page, rowsPerPage, searchQuery, filters]);

    const handleChangePage = (event, newPage) => {
        setPage(newPage);
    };

    const handleChangeRowsPerPage = (event) => {
        setRowsPerPage(parseInt(event.target.value, 10));
        setPage(0);
    };

    const handleFilterChange = (event) => {
        const { name, value } = event.target;
        setFilters(prev => ({
            ...prev,
            [name]: value
        }));
    };

    const clearFilters = () => {
        setFilters({
            status: '',
            hasAMC: '',
            roomNo: ''
        });
        setSearchQuery('');
    };

    const handleDeleteClick = (device) => {
        setDeleteDialog({ open: true, device });
    };

    const handleDeleteConfirm = async () => {
        try {
            setLoading(true);
            await deviceService.deleteDevice(deleteDialog.device._id);

            setDeleteDialog({ open: false, device: null });
            setNotification({
                open: true,
                message: 'Device deleted successfully',
                severity: 'success'
            });

            // Refetch devices after deletion
            fetchDevices();
        } catch (error) {
            console.error('Error deleting device:', error);
            setNotification({
                open: true,
                message: 'Failed to delete device: ' + (error.response?.data?.message || error.message),
                severity: 'error'
            });
        } finally {
            setLoading(false);
        }
    };

    const handleInspection = (deviceId) => {
        navigate(`/devices/${deviceId}/inspection`);
    };

    const handleExportToPDF = async () => {
        try {
          setLoading(true);
          
          // Fetch all devices for export (without pagination)
          const params = {
            limit: totalDevices, // Get all devices
            page: 1
          };
          
          // Apply current filters
          if (searchQuery) params.search = searchQuery;
          if (filters.status) params.status = filters.status;
          if (filters.hasAMC) params.hasAMC = filters.hasAMC === 'yes';
          if (filters.roomNo) params.roomNo = filters.roomNo;
    
          const response = await deviceService.getAllDevices(params);
          const success = exportToPDF(response.data);
          
          if (success) {
            showNotification('PDF exported successfully', 'success');
          } else {
            showNotification('Failed to export PDF', 'error');
          }
        } catch (error) {
          console.error('Error exporting to PDF:', error);
          showNotification('Failed to export PDF', 'error');
        } finally {
          setLoading(false);
        }
      };
    
      const exportToExcel = async () => {
        try {
          setLoading(true);
          const params = { limit: totalDevices, page: 1, ...filters, search: searchQuery };
          const response = await deviceService.getAllDevices(params);
          
          const data = response.data.map(device => ({
            'Device Name': device.deviceName,
            'Make': device.make,
            'Model': device.model,
            'Serial No': device.serialNumber,
            'Room': device.roomNo,
            'Status': device.status,
            'AMC': device.hasAMC ? 'Yes' : 'No',
            'Calibration': device.calibrationDate ? new Date(device.calibrationDate).toLocaleDateString() : 'N/A'
          }));
          
          const ws = XLSX.utils.json_to_sheet(data);
          const wb = XLSX.utils.book_new();
          XLSX.utils.book_append_sheet(wb, ws, 'Devices');
          XLSX.writeFile(wb, `devices_export_${new Date().toISOString().split('T')[0]}.xlsx`);
          
          showNotification('Excel exported successfully', 'success');
        } catch (error) {
          console.error('Error exporting to Excel:', error);
          showNotification('Failed to export Excel', 'error');
        } finally {
          setLoading(false);
        }
      };

    const toggleDeviceExpansion = (deviceId) => {
        setExpandedDevice(expandedDevice === deviceId ? null : deviceId);
    };

    const showNotification = (message, severity) => {
        setNotification({
            open: true,
            message,
            severity
        });
    };

    // Open image preview
    const handleOpenImagePreview = (imagePath) => {
        if (!imagePath) return;

        const apiUrl = process.env.REACT_APP_API_URL || 'http://localhost:5000';
        const imageUrl = `${apiUrl}/uploads/${imagePath}`;

        setImagePreview({
            open: true,
            url: imageUrl
        });
    };
    // Add this function to your component
    const getDaysUntilCalibration = (dateString) => {
        if (!dateString) return -999; // Handle missing dates

        const today = new Date();
        const calibrationDate = new Date(dateString);
        const diffTime = calibrationDate - today;
        const diffDays = Math.ceil(diffTime / (1000 * 60 * 60 * 24));
        return diffDays;
    };
    return (
        <Box sx={{ p: 3, backgroundColor: '#f0f7ff', minHeight: '100vh' }}>
            <Card
                elevation={0}
                sx={{
                    borderRadius: 4,
                    background: 'linear-gradient(135deg, #ffffff 0%, #f8faff 100%)',
                    boxShadow: '0 8px 32px rgba(0, 0, 0, 0.1)'
                }}
            >
                <CardContent sx={{ p: 4 }}>
                    {/* Header */}
                    <Stack
                        direction={{ xs: 'column', sm: 'row' }}
                        justifyContent="space-between"
                        alignItems={{ xs: 'stretch', sm: 'center' }}
                        spacing={2}
                        mb={4}
                    >
                        <Typography
                            variant="h5"
                            sx={{
                                fontWeight: 600,
                                color: '#1976d2'
                            }}
                        >
                            Manage Devices
                        </Typography>
                       
                        <Stack
                            direction={{ xs: 'column', sm: 'row' }}
                            spacing={2}
                        >
<Button
                variant="outlined"
                startIcon={<Download />}
                onClick={exportToExcel}
                disabled={loading}
                sx={{ borderRadius: 2 }}
              >
                Export Excel
              </Button>
              <Button
                variant="outlined"
                startIcon={<PictureAsPdf />}
                onClick={handleExportToPDF}  // Updated handler
                disabled={loading}
                sx={{ borderRadius: 2 }}
              >
                Export PDF
              </Button>
                            <Button
                                variant="contained"
                                startIcon={<Add />}
                                onClick={() => navigate('/device-portal/add-device')}
                                sx={{
                                    borderRadius: 2,
                                    backgroundColor: '#1976d2',
                                    '&:hover': {
                                        backgroundColor: '#1565c0'
                                    }
                                }}
                            >
                                Add New Device
                            </Button>
                        </Stack>
                    </Stack>

                    {/* Search and Filters */}
                    <Grid container spacing={2} mb={4}>
                        <Grid item xs={12} sm={6} md={4}>
                            <TextField
                                fullWidth
                                placeholder="Search devices..."
                                value={searchQuery}
                                onChange={(e) => setSearchQuery(e.target.value)}
                                InputProps={{
                                    startAdornment: (
                                        <InputAdornment position="start">
                                            <Search />
                                        </InputAdornment>
                                    ),
                                    sx: { borderRadius: 2 }
                                }}
                            />
                        </Grid>
                        <Grid item xs={12} sm={6} md={8}>
                            <Stack
                                direction="row"
                                spacing={2}
                                alignItems="center"
                                justifyContent="flex-end"
                            >
                                <Button
                                    startIcon={<FilterList />}
                                    onClick={() => setShowFilters(!showFilters)}
                                    sx={{ borderRadius: 2 }}
                                >
                                    Filters
                                </Button>
                                {(filters.status || filters.hasAMC || filters.roomNo) && (
                                    <Button
                                        startIcon={<ClearAll />}
                                        onClick={clearFilters}
                                        sx={{ borderRadius: 2 }}
                                    >
                                        Clear Filters
                                    </Button>
                                )}
                            </Stack>
                        </Grid>
                    </Grid>

                    {/* Filter Panel */}
                    {showFilters && (
                        <Paper
                            elevation={0}
                            sx={{
                                p: 2,
                                mb: 3,
                                borderRadius: 2,
                                backgroundColor: '#f8faff',
                                border: '1px solid #e0e0e0'
                            }}
                        >
                            <Grid container spacing={2}>
                                <Grid item xs={12} sm={4}>
                                    <FormControl fullWidth>
                                        <InputLabel>Status</InputLabel>
                                        <Select
                                            name="status"
                                            value={filters.status}
                                            onChange={handleFilterChange}
                                            label="Status"
                                            sx={{ borderRadius: 2 }}
                                        >
                                            <MenuItem value="">All</MenuItem>
                                            <MenuItem value="active">Active</MenuItem>
                                            <MenuItem value="inactive">Inactive</MenuItem>
                                            <MenuItem value="maintenance">Under Maintenance</MenuItem>
                                        </Select>
                                    </FormControl>
                                </Grid>
                                <Grid item xs={12} sm={4}>
                                    <FormControl fullWidth>
                                        <InputLabel>AMC Status</InputLabel>
                                        <Select
                                            name="hasAMC"
                                            value={filters.hasAMC}
                                            onChange={handleFilterChange}
                                            label="AMC Status"
                                            sx={{ borderRadius: 2 }}
                                        >
                                            <MenuItem value="">All</MenuItem>
                                            <MenuItem value="yes">Active AMC</MenuItem>
                                            <MenuItem value="no">No AMC</MenuItem>
                                        </Select>
                                    </FormControl>
                                </Grid>
                                <Grid item xs={12} sm={4}>
                                    <FormControl fullWidth>
                                        <InputLabel>Room</InputLabel>
                                        <Select
                                            name="roomNo"
                                            value={filters.roomNo}
                                            onChange={handleFilterChange}
                                            label="Room"
                                            sx={{ borderRadius: 2 }}
                                        >
                                            <MenuItem value="">All</MenuItem>
                                            {rooms.map((room) => (
                                                <MenuItem key={room} value={room}>
                                                    {room}
                                                </MenuItem>
                                            ))}
                                        </Select>
                                    </FormControl>
                                </Grid>
                            </Grid>
                        </Paper>
                    )}

                    {/* Devices Table */}
                    <TableContainer component={Paper} sx={{ borderRadius: 2, mb: 3 }}>
                        <Table>
                            <TableHead>
                                <TableRow>
                                    <TableCell padding="checkbox" />
                                    <TableCell>Device Name</TableCell>
                                    <TableCell>Make/Model</TableCell>
                                    <TableCell>Room</TableCell>
                                    <TableCell>Status</TableCell>
                                    <TableCell>AMC</TableCell>
                                    <TableCell>Calibration</TableCell>
                                    <TableCell align="right">Actions</TableCell>
                                </TableRow>
                            </TableHead>
                            <TableBody>
                                {loading ? (
                                    <TableRow>
                                        <TableCell colSpan={7} align="center" sx={{ py: 3 }}>
                                            <CircularProgress />
                                        </TableCell>
                                    </TableRow>
                                ) : filteredDevices.length === 0 ? (
                                    <TableRow>
                                        <TableCell colSpan={7} align="center" sx={{ py: 3 }}>
                                            <Typography variant="body1" color="textSecondary">
                                                No devices found
                                            </Typography>
                                        </TableCell>
                                    </TableRow>
                                ) : (
                                    filteredDevices.map((device) => {
                                        const daysUntilCalibration = getDaysUntilCalibration(device.calibrationDate);
                                        return (

                                            <React.Fragment key={device._id}>
                                                <TableRow>
                                                    <TableCell padding="checkbox">
                                                        <IconButton
                                                            size="small"
                                                            onClick={() => toggleDeviceExpansion(device._id)}
                                                        >
                                                            {expandedDevice === device._id ?
                                                                <KeyboardArrowUp /> :
                                                                <KeyboardArrowDown />
                                                            }
                                                        </IconButton>
                                                    </TableCell>
                                                    <TableCell>
                                                        <Stack direction="row" alignItems="center" spacing={1}>
                                                            {device.deviceName}
                                                            {device.deviceImage && (
                                                                <Tooltip title="View device image">
                                                                    <IconButton
                                                                        size="small"
                                                                        onClick={() => handleOpenImagePreview(`devices/${device.deviceImage}`)}
                                                                    >
                                                                        <Image fontSize="small" />
                                                                    </IconButton>
                                                                </Tooltip>
                                                            )}
                                                        </Stack>
                                                        <Typography variant="caption" display="block" color="textSecondary">
                                                            SN: {device.serialNumber}
                                                        </Typography>
                                                    </TableCell>
                                                    <TableCell>
                                                        {device.make}
                                                        <Typography variant="caption" display="block" color="textSecondary">
                                                            {device.model}
                                                        </Typography>
                                                    </TableCell>
                                                    <TableCell>{device.roomNo}</TableCell>
                                                    <TableCell>
                                                        <Chip
                                                            label={device.status}
                                                            color={
                                                                device.status === 'active'
                                                                    ? 'success'
                                                                    : device.status === 'inactive'
                                                                        ? 'error'
                                                                        : 'warning'
                                                            }
                                                            size="small"
                                                        />
                                                    </TableCell>
                                                    <TableCell>
                                                        <Chip
                                                            label={device.hasAMC ? 'Active AMC' : 'No AMC'}
                                                            color={device.hasAMC ? 'success' : 'warning'}
                                                            size="small"
                                                        />
                                                    </TableCell>
                                                    <TableCell>
                                                        <Tooltip title={`Next Calibration: ${new Date(device.calibrationDate).toLocaleDateString()}`}>
                                                            <Chip
                                                                icon={daysUntilCalibration <= 30 ? <Warning sx={{ fontSize: 16 }} /> : null}
                                                                label={
                                                                    daysUntilCalibration <= 0
                                                                        ? 'Overdue'
                                                                        : daysUntilCalibration <= 30
                                                                            ? `Due in ${daysUntilCalibration} days`
                                                                            : 'Up to date'
                                                                }
                                                                color={
                                                                    daysUntilCalibration <= 0
                                                                        ? 'error'
                                                                        : daysUntilCalibration <= 30
                                                                            ? 'warning'
                                                                            : 'success'
                                                                }
                                                                size="small"
                                                            />
                                                        </Tooltip>
                                                    </TableCell>
                                                    <TableCell align="right">
                                                        <Stack
                                                            direction="row"
                                                            spacing={1}
                                                            justifyContent="flex-end"
                                                        >
                                                            <Tooltip title="View Details">
                                                                <IconButton
                                                                    size="small"
                                                                    onClick={() => navigate(`/devices/${device._id}`)}
                                                                    sx={{
                                                                        backgroundColor: '#e3f2fd',
                                                                        '&:hover': { backgroundColor: '#bbdefb' }
                                                                    }}
                                                                >
                                                                    <Visibility />
                                                                </IconButton>
                                                            </Tooltip>
                                                            <Tooltip title="Edit">
                                                                <IconButton
                                                                    size="small"
                                                                    onClick={() => navigate(`/devices/${device._id}/edit`)}
                                                                    sx={{
                                                                        backgroundColor: '#e8f5e9',
                                                                        '&:hover': { backgroundColor: '#c8e6c9' }
                                                                    }}
                                                                >
                                                                    <Edit />
                                                                </IconButton>
                                                            </Tooltip>
                                                            <Tooltip title="Start Inspection">
                                                                <IconButton
                                                                    size="small"
                                                                    onClick={() => handleInspection(device._id)}
                                                                    sx={{
                                                                        backgroundColor: '#e8eaf6',
                                                                        '&:hover': { backgroundColor: '#c5cae9' }
                                                                    }}
                                                                >
                                                                    <Engineering />
                                                                </IconButton>
                                                            </Tooltip>
                                                            <Tooltip title="Delete">
                                                                <IconButton
                                                                    size="small"
                                                                    onClick={() => handleDeleteClick(device)}
                                                                    sx={{
                                                                        backgroundColor: '#ffebee',
                                                                        '&:hover': { backgroundColor: '#ffcdd2' }
                                                                    }}
                                                                >
                                                                    <Delete />
                                                                </IconButton>
                                                            </Tooltip>
                                                        </Stack>
                                                    </TableCell>
                                                </TableRow>
                                                <TableRow>
                                                    <TableCell colSpan={7} sx={{ py: 0 }}>
                                                        <Collapse in={expandedDevice === device._id} timeout="auto" unmountOnExit>
                                                            <Box sx={{ p: 3 }}>
                                                                <Typography variant="subtitle2" gutterBottom component="div">
                                                                    Additional Details
                                                                </Typography>
                                                                <Grid container spacing={2}>
                                                                    <Grid item xs={12} sm={6}>
                                                                        <Stack spacing={1}>
                                                                            <Typography variant="body2" color="textSecondary">
                                                                                Purchased Year: {new Date(device.purchasedYear).getFullYear()}
                                                                            </Typography>
                                                                            <Typography variant="body2" color="textSecondary">
                                                                                Last Calibration: {new Date(device.calibrationDate).toLocaleDateString()}
                                                                            </Typography>
                                                                        </Stack>
                                                                    </Grid>
                                                                    <Grid item xs={12} sm={6}>
                                                                        {device.hasAMC ? (
                                                                            <Stack spacing={1}>
                                                                                <Typography variant="body2" color="textSecondary">
                                                                                    AMC Company: {device.amcCompany || 'N/A'}
                                                                                </Typography>
                                                                                {device.amcDetails && (
                                                                                    <Typography variant="body2" color="textSecondary">
                                                                                        AMC Details: {device.amcDetails}
                                                                                    </Typography>
                                                                                )}
                                                                            </Stack>
                                                                        ) : (
                                                                            <Typography variant="body2" color="textSecondary">
                                                                                No AMC Reason: {device.noAMCReason || 'N/A'}
                                                                            </Typography>
                                                                        )}
                                                                    </Grid>

                                                                    <Grid item xs={12}>
                                                                        <Typography variant="subtitle2" gutterBottom>
                                                                            Accessories ({(device.accessories || []).length})
                                                                        </Typography>
                                                                        {(device.accessories || []).length > 0 ? (
                                                                            <TableContainer component={Paper} variant="outlined" sx={{ mb: 2, borderRadius: 2 }}>
                                                                                <Table size="small">
                                                                                    <TableHead>
                                                                                        <TableRow>
                                                                                            <TableCell>Item Name</TableCell>
                                                                                            <TableCell>Supplier</TableCell>
                                                                                            <TableCell>Purchase Date</TableCell>
                                                                                            <TableCell>Position</TableCell>
                                                                                            <TableCell>Status</TableCell>
                                                                                        </TableRow>
                                                                                    </TableHead>
                                                                                    <TableBody>
                                                                                        {(device.accessories || []).map((acc, index) => (
                                                                                            <TableRow key={acc._id || index}>
                                                                                                <TableCell>
                                                                                                    <Stack direction="row" alignItems="center" spacing={1}>
                                                                                                        {acc.itemName}
                                                                                                        {acc.image && (
                                                                                                            <Tooltip title="View accessory image">
                                                                                                                <IconButton
                                                                                                                    size="small"
                                                                                                                    onClick={() => handleOpenImagePreview(`accessories/${acc.image}`)}
                                                                                                                >
                                                                                                                    <Image fontSize="small" />
                                                                                                                </IconButton>
                                                                                                            </Tooltip>
                                                                                                        )}
                                                                                                    </Stack>
                                                                                                </TableCell>
                                                                                                <TableCell>{acc.supplier || 'N/A'}</TableCell>
                                                                                                <TableCell>
                                                                                                    {acc.purchaseDate ? new Date(acc.purchaseDate).toLocaleDateString() : 'N/A'}
                                                                                                </TableCell>
                                                                                                <TableCell>
                                                                                                    {acc.isRight && acc.isLeft
                                                                                                        ? 'Right & Left'
                                                                                                        : acc.isRight
                                                                                                            ? 'Right'
                                                                                                            : acc.isLeft
                                                                                                                ? 'Left'
                                                                                                                : 'N/A'}
                                                                                                </TableCell>
                                                                                                <TableCell>
                                                                                                    <Chip
                                                                                                        label={acc.status}
                                                                                                        size="small"
                                                                                                        color={
                                                                                                            acc.status === 'active'
                                                                                                                ? 'success'
                                                                                                                : acc.status === 'inactive'
                                                                                                                    ? 'error'
                                                                                                                    : 'warning'
                                                                                                        }
                                                                                                    />
                                                                                                </TableCell>
                                                                                            </TableRow>
                                                                                        ))}
                                                                                    </TableBody>
                                                                                </Table>
                                                                            </TableContainer>
                                                                        ) : (
                                                                            <Typography variant="body2" color="textSecondary">
                                                                                No accessories found for this device
                                                                            </Typography>
                                                                        )}
                                                                    </Grid>
                                                                </Grid>
                                                            </Box>
                                                        </Collapse>
                                                    </TableCell>
                                                </TableRow>
                                            </React.Fragment>
                                        );
                                    })
                                )}
                            </TableBody>
                        </Table>
                    </TableContainer>

                    <TablePagination
                        component="div"
                        count={totalDevices}
                        page={page}
                        onPageChange={handleChangePage}
                        rowsPerPage={rowsPerPage}
                        onRowsPerPageChange={handleChangeRowsPerPage}
                        rowsPerPageOptions={[5, 10, 25, 50]}
                    />
                </CardContent>
            </Card>

            {/* Delete Confirmation Dialog */}
            <Dialog
                open={deleteDialog.open}
                onClose={() => !loading && setDeleteDialog({ open: false, device: null })}
                PaperProps={{
                    sx: { borderRadius: 3 }
                }}
            >
                <DialogTitle>Confirm Deletion</DialogTitle>
                <DialogContent>
                    {loading ? (
                        <Box sx={{ display: 'flex', justifyContent: 'center', p: 3 }}>
                            <CircularProgress />
                        </Box>
                    ) : (
                        <Typography>
                            Are you sure you want to delete the device "{deleteDialog.device?.deviceName}"?
                            This action cannot be undone.
                        </Typography>
                    )}
                </DialogContent>
                <DialogActions sx={{ p: 2 }}>
                    <Button
                        onClick={() => setDeleteDialog({ open: false, device: null })}
                        sx={{ borderRadius: 2 }}
                        disabled={loading}
                    >
                        Cancel
                    </Button>
                    <Button
                        onClick={handleDeleteConfirm}
                        variant="contained"
                        color="error"
                        sx={{ borderRadius: 2 }}
                        disabled={loading}
                    >
                        Delete
                    </Button>
                </DialogActions>
            </Dialog>

            {/* Image Preview Dialog */}
            <Dialog
                open={imagePreview.open}
                onClose={() => setImagePreview({ open: false, url: '' })}
                maxWidth="md"
                PaperProps={{
                    sx: { borderRadius: 3 }
                }}
            >
                <DialogContent sx={{ p: 0 }}>
                    <img
                        src={imagePreview.url}
                        alt="Preview"
                        style={{
                            width: '100%',
                            maxHeight: '80vh',
                            objectFit: 'contain'
                        }}
                    />
                </DialogContent>
                <DialogActions>
                    <Button
                        onClick={() => setImagePreview({ open: false, url: '' })}
                        sx={{ borderRadius: 2 }}
                    >
                        Close
                    </Button>
                    <Button
                        onClick={() => window.open(imagePreview.url, '_blank')}
                        variant="contained"
                        sx={{ borderRadius: 2 }}
                    >
                        Open Full Size
                    </Button>
                </DialogActions>
            </Dialog>

            {/* Notification */}
            <Snackbar
                open={notification.open}
                autoHideDuration={6000}
                onClose={() => setNotification(prev => ({ ...prev, open: false }))}
                anchorOrigin={{ vertical: 'top', horizontal: 'right' }}
            >
                <Alert
                    onClose={() => setNotification(prev => ({ ...prev, open: false }))}
                    severity={notification.severity}
                    variant="filled"
                    sx={{ width: '100%', borderRadius: 2 }}
                >
                    {notification.message}
                </Alert>
            </Snackbar>
        </Box>
    );
};

export default ManageDevices;