import React, { useState, useEffect } from 'react';
import {
  Box,
  Card,
  IconButton,
  Tooltip,
  Dialog,
  DialogTitle,
  DialogContent,
  DialogActions,
  Button,
  TextField,
  Typography,
  Stack,
  Alert,
  CircularProgress,
  InputAdornment,
  Divider,
} from '@mui/material';
import {
  DataGrid,
  GridToolbar,
} from '@mui/x-data-grid';
import {
  Edit as EditIcon,
  Search as SearchIcon,
  Phone as PhoneIcon,
} from '@mui/icons-material';
import { useSnackbar } from 'notistack';
import { debounce } from 'lodash';
import * as yup from 'yup';
import { useFormik } from 'formik';
import api from '../../../api/axios';
import { useSelector } from 'react-redux';
import { jwtDecode } from 'jwt-decode';

// Add validation schema at the beginning
const patientSchema = yup.object({
  patientName: yup.string()
    .required('Patient name is required')
    .min(3, 'Name must be at least 3 characters')
    .max(50, 'Name must be at most 50 characters'),
  email: yup.string()
    .email('Enter a valid email'),
  phoneNumber: yup.string()
    .required('Phone number is required')
    .matches(/^[0-9]{10}$/, 'Phone number must be 10 digits'),
  whatsApp: yup.string()
    .matches(/^[0-9]{10}$/, 'WhatsApp number must be 10 digits'),
  byStanderName: yup.string()
    .min(3, 'Bystander name must be at least 3 characters')
    .max(50, 'Bystander name must be at most 50 characters'),
  byStanderPhone: yup.string()
    .matches(/^[0-9]{10}$/, 'Phone number must be 10 digits'),
  address: yup.string()
    .min(5, 'Address must be at least 5 characters'),
  pincode: yup.string()
    .matches(/^[0-9]{6}$/, 'Pincode must be 6 digits')
});

const ManagePatients = () => {
  const [patients, setPatients] = useState([]);
  const [loading, setLoading] = useState(false);
  const [editDialog, setEditDialog] = useState(false);
  const [selectedPatient, setSelectedPatient] = useState(null);
  const [confirmDialog, setConfirmDialog] = useState(false);
  const [searchType, setSearchType] = useState('name');
  const [searchQuery, setSearchQuery] = useState('');
  const [pagination, setPagination] = useState({
    page: 0,
    pageSize: 10,
    total: 0,
  });

  const { enqueueSnackbar } = useSnackbar();
  
  // Get user ID from token
  const token = useSelector(state => state.auth.token);
  const userId = token ? jwtDecode(token).userId : null;

  const fetchPatients = async (page = 0, searchValue = searchQuery) => {
    setLoading(true);
    try {
      let response;
      if (searchValue) {
        if (searchType === 'phone') {
          response = await api.get(`/patients/search/phone?userId=${userId}&phoneNumber=${searchValue}`);
        } else {
          response = await api.get(`/patients/search/name?userId=${userId}&name=${searchValue}`);
        }
      } else {
        response = await api.get(`/patients?userId=${userId}&page=${page + 1}&limit=${pagination.pageSize}`);
      }

      setPatients(response.data.data);
      if (response.data.pagination) {
        setPagination(prev => ({
          ...prev,
          total: response.data.pagination.totalRecords,
        }));
      }
    } catch (error) {
      enqueueSnackbar(error.response?.data?.message || 'Error fetching patients', {
        variant: 'error'
      });
    } finally {
      setLoading(false);
    }
  };

  const formik = useFormik({
    initialValues: {
      patientName: '',
      email: '',
      phoneNumber: '',
      whatsApp: '',
      byStanderName: '',
      byStanderPhone: '',
      address: '',
      pincode: '',
    },
    validationSchema: patientSchema,
    onSubmit: () => {
      setConfirmDialog(true);
    }
  });

  const debouncedFetch = debounce(fetchPatients, 500);

  useEffect(() => {
    if (userId) {
      fetchPatients();
    }
  }, [pagination.pageSize, userId]);

  const handleEdit = (patient) => {
    setSelectedPatient(patient);
    formik.setValues({
      patientName: patient.patientName || '',
      email: patient.email || '',
      phoneNumber: patient.phoneNumber || '',
      whatsApp: patient.whatsApp || '',
      byStanderName: patient.byStanderName || '',
      byStanderPhone: patient.byStanderPhone || '',
      address: patient.address || '',
      pincode: patient.pincode || '',
    });
    setEditDialog(true);
  };

  const handleUpdate = async () => {
    if (!userId) {
      enqueueSnackbar('Authentication error', { variant: 'error' });
      return;
    }

    setLoading(true);
    try {
      const response = await api.put('/patients', {
        userId,
        patientId: selectedPatient._id,
        ...formik.values
      });

      if (response.data.success) {
        enqueueSnackbar('Patient updated successfully', { variant: 'success' });
        setEditDialog(false);
        setConfirmDialog(false);
        fetchPatients(pagination.page);
      }
    } catch (error) {
      enqueueSnackbar(error.response?.data?.message || 'Error updating patient', {
        variant: 'error'
      });
    } finally {
      setLoading(false);
    }
  };

  const handleSearch = (value) => {
    if (!userId) {
      enqueueSnackbar('Authentication error', { variant: 'error' });
      return;
    }
    setSearchQuery(value);
    if (searchType === 'phone') {
      // Direct search for phone numbers
      fetchPatients(0, value);
    } else {
      // Debounced search for names
      debouncedFetch(0, value);
    }
  };

  const columns = [
    {
      field: 'patientName',
      headerName: 'Patient Name',
      flex: 1,
      minWidth: 200,
    },
    {
      field: 'phoneNumber',
      headerName: 'Phone',
      width: 150,
    },
    {
      field: 'email',
      headerName: 'Email',
      width: 200,
      renderCell: (params) => params.value || '-',
    },
    {
      field: 'byStanderName',
      headerName: 'Bystander',
      width: 200,
      renderCell: (params) => params.value || '-',
    },
    {
      field: 'byStanderPhone',
      headerName: 'Bystander Phone',
      width: 150,
      renderCell: (params) => params.value || '-',
    },
    {
      field: 'actions',
      headerName: 'Actions',
      width: 100,
      sortable: false,
      renderCell: (params) => (
        <Tooltip title="Edit Patient">
          <IconButton
            onClick={() => handleEdit(params.row)}
            color="primary"
            size="small"
          >
            <EditIcon />
          </IconButton>
        </Tooltip>
      ),
    }
  ];

  if (!userId) {
    return (
      <Box sx={{ p: 3 }}>
        <Alert severity="error">Authentication error. Please log in again.</Alert>
      </Box>
    );
  }

  return (
    <Box sx={{ p: 3 }}>
      <Typography variant="h4" gutterBottom>
        Manage Patients
      </Typography>

      <Card sx={{ p: 3, mb: 3 }}>
        <Stack spacing={3}>
          <Stack
            direction={{ xs: 'column', sm: 'row' }}
            spacing={2}
            alignItems="center"
          >
            <TextField
              fullWidth
              placeholder={`Search by ${searchType === 'name' ? 'patient name' : 'phone number'}`}
              value={searchQuery}
              onChange={(e) => {
                // For phone number, only allow digits and max 10 digits
                if (searchType === 'phone') {
                  const value = e.target.value.replace(/\D/g, '').slice(0, 10);
                  setSearchQuery(value);
                } else {
                  setSearchQuery(e.target.value);
                  handleSearch(e.target.value);
                }
              }}
              InputProps={{
                startAdornment: (
                  <InputAdornment position="start">
                    {searchType === 'name' ? <SearchIcon /> : <PhoneIcon />}
                  </InputAdornment>
                ),
                endAdornment: searchType === 'phone' && (
                  <InputAdornment position="end">
                    <Button
                      variant="contained"
                      onClick={() => handleSearch(searchQuery)}
                      disabled={searchQuery.length !== 10}
                      size="small"
                    >
                      Search
                    </Button>
                  </InputAdornment>
                )
              }}
            />
            <Button
              variant="outlined"
              onClick={() => {
                setSearchType(prev => prev === 'name' ? 'phone' : 'name');
                setSearchQuery('');
              }}
            >
              Search by {searchType === 'name' ? 'Phone' : 'Name'}
            </Button>
          </Stack>
        </Stack>
      </Card>

      <Card>
        <DataGrid
          rows={patients}
          columns={columns}
          pagination
          paginationMode="server"
          rowCount={pagination.total}
          page={pagination.page}
          pageSize={pagination.pageSize}
          onPageChange={(newPage) => {
            setPagination(prev => ({ ...prev, page: newPage }));
            fetchPatients(newPage);
          }}
          onPageSizeChange={(newPageSize) =>
            setPagination(prev => ({ ...prev, pageSize: newPageSize, page: 0 }))
          }
          loading={loading}
          getRowId={(row) => row._id}
          autoHeight
          disableSelectionOnClick
          components={{
            Toolbar: GridToolbar,
          }}
          componentsProps={{
            toolbar: {
              showQuickFilter: true,
              quickFilterProps: { debounceMs: 500 },
            },
          }}
          sx={{
            '& .MuiDataGrid-toolbarContainer': {
              padding: 2,
              borderBottom: '1px solid',
              borderColor: 'divider',
            },
          }}
        />
      </Card>

      {/* Edit Dialog */}
      <Dialog
        open={editDialog}
        onClose={() => !loading && setEditDialog(false)}
        maxWidth="md"
        fullWidth
      >
        <form onSubmit={formik.handleSubmit}>
          <DialogTitle>Edit Patient</DialogTitle>
          <DialogContent>
            <Stack spacing={3} sx={{ mt: 2 }}>
              <Typography variant="h6">Patient Information</Typography>
              
              <Stack spacing={3} direction={{ xs: 'column', md: 'row' }}>
                <TextField
                  fullWidth
                  name="patientName"
                  label="Patient Name"
                  value={formik.values.patientName}
                  onChange={formik.handleChange}
                  error={formik.touched.patientName && Boolean(formik.errors.patientName)}
                  helperText={formik.touched.patientName && formik.errors.patientName}
                  disabled={loading}
                />
                <TextField
                  fullWidth
                  name="email"
                  label="Email"
                  value={formik.values.email}
                  onChange={formik.handleChange}
                  error={formik.touched.email && Boolean(formik.errors.email)}
                  helperText={formik.touched.email && formik.errors.email}
                  disabled={loading}
                />
              </Stack>

              <Stack spacing={3} direction={{ xs: 'column', md: 'row' }}>
                <TextField
                  fullWidth
                  name="phoneNumber"
                  label="Phone Number"
                  value={formik.values.phoneNumber}
                  onChange={formik.handleChange}
                  error={formik.touched.phoneNumber && Boolean(formik.errors.phoneNumber)}
                  helperText={formik.touched.phoneNumber && formik.errors.phoneNumber}
                  disabled={loading}
                />
                <TextField
                  fullWidth
                  name="whatsApp"
                  label="WhatsApp Number"
                  value={formik.values.whatsApp}
                  onChange={formik.handleChange}
                  error={formik.touched.whatsApp && Boolean(formik.errors.whatsApp)}
                  helperText={formik.touched.whatsApp && formik.errors.whatsApp}
                  disabled={loading}
                />
              </Stack>

              <Divider />
              
              <Typography variant="h6">Bystander Information</Typography>

              <Stack spacing={3} direction={{ xs: 'column', md: 'row' }}>
                <TextField
                  fullWidth
                  name="byStanderName"
                  label="Bystander Name"
                  value={formik.values.byStanderName}
                  onChange={formik.handleChange}
                  error={formik.touched.byStanderName && Boolean(formik.errors.byStanderName)}
                  helperText={formik.touched.byStanderName && formik.errors.byStanderName}
                  disabled={loading}
                />
                <TextField
                  fullWidth
                  name="byStanderPhone"
                  label="Bystander Phone"
                  value={formik.values.byStanderPhone}
                  onChange={formik.handleChange}
                  error={formik.touched.byStanderPhone && Boolean(formik.errors.byStanderPhone)}
                  helperText={formik.touched.byStanderPhone && formik.errors.byStanderPhone}
                  disabled={loading}
                />
              </Stack>

              <Divider />
              
              <Typography variant="h6">Address Information</Typography>

              <TextField
                fullWidth
                name="address"
                label="Address"
                multiline
                rows={3}
                value={formik.values.address}
             
onChange={formik.handleChange}
                error={formik.touched.address && Boolean(formik.errors.address)}
                helperText={formik.touched.address && formik.errors.address}
                disabled={loading}
              />

              <TextField
                fullWidth
                name="pincode"
                label="Pincode"
                value={formik.values.pincode}
                onChange={formik.handleChange}
                error={formik.touched.pincode && Boolean(formik.errors.pincode)}
                helperText={formik.touched.pincode && formik.errors.pincode}
                disabled={loading}
              />
            </Stack>
          </DialogContent>
          <DialogActions>
            <Button
              onClick={() => setEditDialog(false)}
              disabled={loading}
            >
              Cancel
            </Button>
            <Button
              type="submit"
              variant="contained"
              disabled={loading}
            >
              Update Patient
            </Button>
          </DialogActions>
        </form>
      </Dialog>

      {/* Confirmation Dialog */}
      <Dialog
        open={confirmDialog}
        onClose={() => !loading && setConfirmDialog(false)}
      >
        <DialogTitle>Confirm Update</DialogTitle>
        <DialogContent>
          <Stack spacing={2} sx={{ mt: 2 }}>
            <Typography>
              Please confirm the following changes:
            </Typography>
            <Alert severity="info">
              <Stack spacing={1}>
                <Typography variant="body2">
                  Name: {formik.values.patientName}
                </Typography>
                <Typography variant="body2">
                  Phone: {formik.values.phoneNumber}
                </Typography>
                {formik.values.email && (
                  <Typography variant="body2">
                    Email: {formik.values.email}
                  </Typography>
                )}
                {formik.values.byStanderName && (
                  <Typography variant="body2">
                    Bystander: {formik.values.byStanderName}
                  </Typography>
                )}
              </Stack>
            </Alert>
            <Alert severity="warning">
              This action will update the patient's information. Please make sure all details are correct.
            </Alert>
          </Stack>
        </DialogContent>
        <DialogActions>
          <Button
            onClick={() => setConfirmDialog(false)}
            disabled={loading}
          >
            Cancel
          </Button>
          <Button
            onClick={handleUpdate}
            variant="contained"
            disabled={loading}
          >
            {loading ? <CircularProgress size={24} /> : 'Confirm Update'}
          </Button>
        </DialogActions>
      </Dialog>

      {/* Loading Overlay */}
      {loading && (
        <Box
          sx={{
            position: 'fixed',
            top: 0,
            left: 0,
            right: 0,
            bottom: 0,
            display: 'flex',
            alignItems: 'center',
            justifyContent: 'center',
            backgroundColor: 'rgba(0, 0, 0, 0.5)',
            zIndex: 9999,
          }}
        >
          <CircularProgress />
        </Box>
      )}
    </Box>
  );
};

export default ManagePatients;