
import axios from 'axios';

const API_URL = process.env.REACT_APP_API_URL || 'http://localhost:5000';

// Create axios instance with default config
const api = axios.create({
  baseURL: `${API_URL}/device`,
  headers: {
    'Content-Type': 'application/json'
  }
});

// Add auth token to requests
api.interceptors.request.use(
  (config) => {
    const token = localStorage.getItem('token');
    if (token) {
      config.headers.Authorization = `Bearer ${token}`;
    }
    return config;
  },
  (error) => Promise.reject(error)
);

// Handle response errors
api.interceptors.response.use(
  (response) => response,
  (error) => {
    const errorMessage = error.response?.data?.message || 'Something went wrong';
    console.error('API Error:', errorMessage);
    return Promise.reject(error);
  }
);

const issueService = {
  // Issue operations
  createIssue: async (formData) => {
    const response = await api.post('/issue', formData, {
      headers: {
        'Content-Type': 'multipart/form-data'
      }
    });
    return response.data;
  },
  getAllIssues: async (deviceId) => {
    const response = await api.get(`/issue/get-all`);
    return response.data;
  },
  getIssuesByDevice: async (deviceId) => {
    const response = await api.get(`/issue/device/${deviceId}`);
    console.log("Fetching response:", JSON.stringify(response.data, null, 2));
    
    return response.data;
  },
  
    getIssueById: async (id) => {
        console.log(`Fetching issue with ID: ${id} from ${api.getUri()}/issue/${id}`); // Debug
        const response = await api.get(`/issue/${id}`);
        return response.data;
    },

  updateIssue: async (id, formData) => {
    console.log(`Updating issue with ID: ${id} with data_____________1:`, formData); // Debug
    
    const response = await api.put(`/issue/${id}`, formData, {
      headers: {
        'Content-Type': 'multipart/form-data'
      }
    });
    console.log(`Updating issue with ID: ${id} with data:___________2`, formData); // Debug
    
    return response.data;
  },
  getCompanyInspections: async (query = {}) => {
    console.log('Fetching company inspections with query:', query);
    const response = await api.get('/issues', {
        params: {
            ...query,
            status: 'pending_company_inspection', // Or adjust based on your company inspection status
            isCompanyInspection: true // Adjust based on your backend logic
        }
    });
    return response.data;
},

generateIssueReport: async (id = null) => {
  if (id) {
      const response = await api.get(`/issue/issue/${id}/report`, { responseType: 'blob' });
      return response.data;
  } 
},
generateCompanyReport: async (id = null) => {
  if (id) {
      const response = await api.get(`/issue/company/${id}/report`, { responseType: 'blob' });
      return response.data;
  } 
},
};

export default issueService;