import React, { useState, useEffect } from 'react';
import {
  Box,
  Typography,
  Button,
  Paper,
  TableContainer,
  Table,
  TableHead,
  TableBody,
  TableRow,
  TableCell,
  Dialog,
  DialogTitle,
  DialogContent,
  DialogActions,
  TextField,
  FormControl,
  InputLabel,
  Select,
  MenuItem,
  IconButton,
  Snackbar,
  Alert,
  CircularProgress,
  Chip,
  useMediaQuery,
  Stack,
  Grid,
  Card,
  CardContent,
  Switch,
  FormControlLabel,
  Divider,
  InputAdornment,
  Collapse,
  Tooltip
} from '@mui/material';
import { useTheme } from '@mui/material/styles';
import AddIcon from '@mui/icons-material/Add';
import EditIcon from '@mui/icons-material/Edit';
import DeleteIcon from '@mui/icons-material/Delete';
import SearchIcon from '@mui/icons-material/Search';
import FilterListIcon from '@mui/icons-material/FilterList';
import RefreshIcon from '@mui/icons-material/Refresh';
import CloseIcon from '@mui/icons-material/Close';
import TuneIcon from '@mui/icons-material/Tune';
import ClinicalInchargeService from '../../../features/services/clinicalInchargeService';
import { useNavigate } from 'react-router-dom';

const ClinicalInchargeManagement = () => {
  const theme = useTheme();
  const isMobile = useMediaQuery(theme.breakpoints.down('sm'));
  const navigate = useNavigate();

  // State variables for Clinical Incharge management
  const [clinicalIncharges, setClinicalIncharges] = useState([]);
  const [loading, setLoading] = useState(false);
  const [openDialog, setOpenDialog] = useState(false);
  const [isEditing, setIsEditing] = useState(false);
  const [selectedIncharge, setSelectedIncharge] = useState(null);
  const [searchTerm, setSearchTerm] = useState('');
  const [notification, setNotification] = useState({
    open: false,
    message: '',
    severity: 'success'
  });
  const [filterStatus, setFilterStatus] = useState('all');
  const [openDeleteDialog, setOpenDeleteDialog] = useState(false);
  const [deleteInchargeId, setDeleteInchargeId] = useState(null);
  
  // Advanced search states
  const [showAdvancedSearch, setShowAdvancedSearch] = useState(false);
  const [advancedSearchParams, setAdvancedSearchParams] = useState({
    name: '',
    email: '',
    phone: '',
    employeeId: '',
    department: '',
  });
  
  // Form state
  const [formData, setFormData] = useState({
    name: '',
    email: '',
    phone: '',
    employeeId: '',
    department: '',
    status: true
  });
  
  // Form validation state
  const [formErrors, setFormErrors] = useState({});
  
  // Fetch clinical incharges on component mount
  useEffect(() => {
    fetchClinicalIncharges();
  }, []);
  
  // Fetch all clinical incharges
  const fetchClinicalIncharges = async () => {
    setLoading(true);
    try {
      const data = await ClinicalInchargeService.getAllClinicalIncharges();
      setClinicalIncharges(data);
    } catch (error) {
      showNotification(error.message || 'Failed to fetch clinical incharges', 'error');
    } finally {
      setLoading(false);
    }
  };
  
  // Handle form input changes
  const handleInputChange = (e) => {
    const { name, value, checked, type } = e.target;
    setFormData((prevData) => ({
      ...prevData,
      [name]: type === 'checkbox' ? checked : value
    }));
    
    // Clear error when field is edited
    if (formErrors[name]) {
      setFormErrors((prev) => ({ ...prev, [name]: '' }));
    }
  };
  
  // Handle advanced search input changes
  const handleAdvancedSearchChange = (e) => {
    const { name, value } = e.target;
    setAdvancedSearchParams((prev) => ({
      ...prev,
      [name]: value
    }));
  };
  
  // Reset advanced search
  const resetAdvancedSearch = () => {
    setAdvancedSearchParams({
      name: '',
      email: '',
      phone: '',
      employeeId: '',
      department: '',
    });
  };
  
  // Toggle advanced search
  const toggleAdvancedSearch = () => {
    setShowAdvancedSearch(!showAdvancedSearch);
    if (!showAdvancedSearch) {
      // Reset basic search when opening advanced search
      setSearchTerm('');
    } else {
      // Reset advanced search when closing
      resetAdvancedSearch();
    }
  };
  
  // Validate form data
  const validateForm = () => {
    const errors = {};
    
    if (!formData.name.trim()) {
      errors.name = 'Name is required';
    }
    
    if (!formData.email.trim()) {
      errors.email = 'Email is required';
    } else if (!/\S+@\S+\.\S+/.test(formData.email)) {
      errors.email = 'Email is invalid';
    }
    
    if (!formData.phone.trim()) {
      errors.phone = 'Phone number is required';
    } else if (!/^\d{10}$/.test(formData.phone.replace(/\D/g, ''))) {
      errors.phone = 'Phone number should be 10 digits';
    }
    
    if (!formData.employeeId.trim()) {
      errors.employeeId = 'Employee ID is required';
    }
    
    if (!formData.department.trim()) {
      errors.department = 'Department is required';
    }
    
    setFormErrors(errors);
    return Object.keys(errors).length === 0;
  };
  
  // Open dialog for create/edit
  const handleOpenDialog = (incharge = null) => {
    if (incharge) {
      setIsEditing(true);
      setSelectedIncharge(incharge);
      setFormData({
        name: incharge.name,
        email: incharge.email,
        phone: incharge.phone,
        employeeId: incharge.employeeId,
        department: incharge.department,
        status: incharge.status
      });
    } else {
      setIsEditing(false);
      setSelectedIncharge(null);
      setFormData({
        name: '',
        email: '',
        phone: '',
        employeeId: '',
        department: '',
        status: true
      });
    }
    setOpenDialog(true);
  };
  
  // Close dialog
  const handleCloseDialog = () => {
    setOpenDialog(false);
    setFormErrors({});
  };
  
  // Submit form for create/edit
  const handleSubmit = async () => {
    if (!validateForm()) return;
    
    setLoading(true);
    try {
      if (isEditing && selectedIncharge) {
        // Update existing clinical incharge
        await ClinicalInchargeService.updateClinicalIncharge(selectedIncharge._id, formData);
        showNotification('Clinical Incharge updated successfully');
      } else {
        // Create new clinical incharge
        await ClinicalInchargeService.createClinicalIncharge(formData);
        showNotification('Clinical Incharge created successfully');
      }
      handleCloseDialog();
      fetchClinicalIncharges();
    } catch (error) {
      showNotification(error.message || 'Operation failed', 'error');
    } finally {
      setLoading(false);
    }
  };
  
  // Delete clinical incharge
  const handleDeleteIncharge = async () => {
    if (!deleteInchargeId) return;
    
    setLoading(true);
    try {
      await ClinicalInchargeService.deleteClinicalIncharge(deleteInchargeId);
      showNotification('Clinical Incharge deleted successfully');
      fetchClinicalIncharges();
    } catch (error) {
      showNotification(error.message || 'Failed to delete', 'error');
    } finally {
      setLoading(false);
      setOpenDeleteDialog(false);
      setDeleteInchargeId(null);
    }
  };
  
  // Handle delete confirmation dialog
  const openDeleteConfirmation = (id) => {
    setDeleteInchargeId(id);
    setOpenDeleteDialog(true);
  };
  
  // Update status
  const handleStatusChange = async (id, currentStatus) => {
    try {
      await ClinicalInchargeService.updateStatus(id, !currentStatus);
      showNotification('Status updated successfully');
      fetchClinicalIncharges();
    } catch (error) {
      showNotification(error.message || 'Failed to update status', 'error');
    }
  };
  
  // Show notification
  const showNotification = (message, severity = 'success') => {
    setNotification({
      open: true,
      message,
      severity
    });
  };
  
  // Close notification
  const handleCloseNotification = () => {
    setNotification({ ...notification, open: false });
  };
  
  // Filter clinical incharges based on search criteria
  const filteredIncharges = clinicalIncharges.filter((incharge) => {
    // Basic search filter
    const matchesBasicSearch = !searchTerm || 
      incharge.name.toLowerCase().includes(searchTerm.toLowerCase()) ||
      incharge.email.toLowerCase().includes(searchTerm.toLowerCase()) ||
      incharge.employeeId.toLowerCase().includes(searchTerm.toLowerCase()) ||
      incharge.phone.toLowerCase().includes(searchTerm.toLowerCase()) ||
      incharge.department.toLowerCase().includes(searchTerm.toLowerCase());
    
    // Advanced search filter
    const matchesAdvancedSearch = !showAdvancedSearch || (
      (!advancedSearchParams.name || incharge.name.toLowerCase().includes(advancedSearchParams.name.toLowerCase())) &&
      (!advancedSearchParams.email || incharge.email.toLowerCase().includes(advancedSearchParams.email.toLowerCase())) &&
      (!advancedSearchParams.phone || incharge.phone.includes(advancedSearchParams.phone)) &&
      (!advancedSearchParams.employeeId || incharge.employeeId.toLowerCase().includes(advancedSearchParams.employeeId.toLowerCase())) &&
      (!advancedSearchParams.department || incharge.department.toLowerCase().includes(advancedSearchParams.department.toLowerCase()))
    );
    
    // Status filter
    const matchesStatus = 
      filterStatus === 'all' || 
      (filterStatus === 'active' && incharge.status) || 
      (filterStatus === 'inactive' && !incharge.status);
    
    return matchesBasicSearch && matchesAdvancedSearch && matchesStatus;
  });
  
  // Clear search
  const clearSearch = () => {
    setSearchTerm('');
    resetAdvancedSearch();
    setFilterStatus('all');
  };
  
  return (
    <Box sx={{ p: { xs: 2, md: 3 } }}>
      <Paper sx={{ p: { xs: 2, md: 3 }, mb: 3 }}>
        <Box sx={{ display: 'flex', flexDirection: { xs: 'column', sm: 'row' }, justifyContent: 'space-between', alignItems: { xs: 'flex-start', sm: 'center' }, mb: 3, gap: 2 }}>
          <Typography variant="h5" component="h1">
            Clinical Incharge Management
          </Typography>
          
          <Button
            variant="contained"
            color="primary"
            startIcon={<AddIcon />}
            onClick={() => navigate('/device-portal/create-clinical-incharge')}
            >
            Add Clinical Incharge
          </Button>
        </Box>
        
        {/* Search and Filter Section */}
        <Box sx={{ mb: 3 }}>
          <Grid container spacing={2} sx={{ mb: 2 }}>
            <Grid item xs={12} sm={6} md={showAdvancedSearch ? 12 : 4}>
              <TextField
                fullWidth
                variant="outlined"
                placeholder="Search by name, email, ID..."
                value={searchTerm}
                onChange={(e) => setSearchTerm(e.target.value)}
                InputProps={{
                  startAdornment: <SearchIcon sx={{ mr: 1, color: 'text.secondary' }} />,
                  endAdornment: searchTerm && (
                    <InputAdornment position="end">
                      <IconButton
                        aria-label="clear search"
                        onClick={() => setSearchTerm('')}
                        edge="end"
                        size="small"
                      >
                        <CloseIcon />
                      </IconButton>
                    </InputAdornment>
                  )
                }}
                size="small"
                disabled={showAdvancedSearch}
              />
            </Grid>
            
            {!showAdvancedSearch && (
              <>
                <Grid item xs={12} sm={6} md={4}>
                  <FormControl fullWidth size="small">
                    <InputLabel id="status-filter-label">Filter by Status</InputLabel>
                    <Select
                      labelId="status-filter-label"
                      value={filterStatus}
                      onChange={(e) => setFilterStatus(e.target.value)}
                      label="Filter by Status"
                      startAdornment={<FilterListIcon sx={{ mr: 1, color: 'text.secondary' }} />}
                    >
                      <MenuItem value="all">All</MenuItem>
                      <MenuItem value="active">Active</MenuItem>
                      <MenuItem value="inactive">Inactive</MenuItem>
                    </Select>
                  </FormControl>
                </Grid>
                
                <Grid item xs={12} sm={6} md={4}>
                  <Box sx={{ display: 'flex', gap: 1 }}>
                    <Button
                      variant="outlined"
                      startIcon={<RefreshIcon />}
                      onClick={fetchClinicalIncharges}
                      sx={{ flex: 1 }}
                    >
                      Refresh
                    </Button>
                    
                    <Tooltip title="Advanced Search">
                      <Button
                        variant="outlined"
                        color="secondary"
                        onClick={toggleAdvancedSearch}
                        sx={{ minWidth: 'auto', width: '48px' }}
                      >
                        <TuneIcon />
                      </Button>
                    </Tooltip>
                  </Box>
                </Grid>
              </>
            )}
          </Grid>
          
          {/* Advanced Search Section */}
          <Collapse in={showAdvancedSearch}>
            <Paper variant="outlined" sx={{ p: 2, mb: 2 }}>
              <Box sx={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', mb: 2 }}>
                <Typography variant="subtitle1" fontWeight="medium">
                  Advanced Search
                </Typography>
                <Button 
                  size="small" 
                  startIcon={<CloseIcon />} 
                  onClick={toggleAdvancedSearch}
                >
                  Close
                </Button>
              </Box>
              
              <Grid container spacing={2}>
                <Grid item xs={12} sm={6} md={4}>
                  <TextField
                    fullWidth
                    label="Name"
                    name="name"
                    value={advancedSearchParams.name}
                    onChange={handleAdvancedSearchChange}
                    size="small"
                  />
                </Grid>
                
                <Grid item xs={12} sm={6} md={4}>
                  <TextField
                    fullWidth
                    label="Email"
                    name="email"
                    value={advancedSearchParams.email}
                    onChange={handleAdvancedSearchChange}
                    size="small"
                  />
                </Grid>
                
                <Grid item xs={12} sm={6} md={4}>
                  <TextField
                    fullWidth
                    label="Phone"
                    name="phone"
                    value={advancedSearchParams.phone}
                    onChange={handleAdvancedSearchChange}
                    size="small"
                  />
                </Grid>
                
                <Grid item xs={12} sm={6} md={4}>
                  <TextField
                    fullWidth
                    label="Employee ID"
                    name="employeeId"
                    value={advancedSearchParams.employeeId}
                    onChange={handleAdvancedSearchChange}
                    size="small"
                  />
                </Grid>
                
                <Grid item xs={12} sm={6} md={4}>
                  <FormControl fullWidth size="small">
                    <InputLabel id="department-search-label">Department</InputLabel>
                    <Select
                      labelId="department-search-label"
                      name="department"
                      value={advancedSearchParams.department}
                      onChange={handleAdvancedSearchChange}
                      label="Department"
                    >
                      <MenuItem value="">Any</MenuItem>
                      <MenuItem value="Cardiology">Cardiology</MenuItem>
                      <MenuItem value="Neurology">Neurology</MenuItem>
                      <MenuItem value="Orthopedics">Orthopedics</MenuItem>
                      <MenuItem value="Pediatrics">Pediatrics</MenuItem>
                      <MenuItem value="Radiology">Radiology</MenuItem>
                      <MenuItem value="General Medicine">General Medicine</MenuItem>
                      <MenuItem value="Surgery">Surgery</MenuItem>
                      <MenuItem value="ICU">ICU</MenuItem>
                      <MenuItem value="Emergency">Emergency</MenuItem>
                    </Select>
                  </FormControl>
                </Grid>
                
                <Grid item xs={12} sm={6} md={4}>
                  <FormControl fullWidth size="small">
                    <InputLabel id="status-filter-advanced-label">Status</InputLabel>
                    <Select
                      labelId="status-filter-advanced-label"
                      value={filterStatus}
                      onChange={(e) => setFilterStatus(e.target.value)}
                      label="Status"
                    >
                      <MenuItem value="all">All</MenuItem>
                      <MenuItem value="active">Active</MenuItem>
                      <MenuItem value="inactive">Inactive</MenuItem>
                    </Select>
                  </FormControl>
                </Grid>
              </Grid>
              
              <Box sx={{ display: 'flex', justifyContent: 'flex-end', mt: 2, gap: 1 }}>
                <Button 
                  variant="outlined" 
                  onClick={resetAdvancedSearch}
                  startIcon={<CloseIcon />}
                  size="small"
                >
                  Clear
                </Button>
                <Button 
                  variant="contained" 
                  color="secondary"
                  startIcon={<SearchIcon />}
                  size="small"
                  onClick={() => {}} // Already auto-filtered
                >
                  Search
                </Button>
              </Box>
            </Paper>
          </Collapse>
          
          {/* Search result summary */}
          {(searchTerm || showAdvancedSearch || filterStatus !== 'all') && (
            <Box sx={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', mb: 2 }}>
              <Typography variant="body2" color="text.secondary">
                Found {filteredIncharges.length} {filteredIncharges.length === 1 ? 'result' : 'results'}
              </Typography>
              
              <Button 
                size="small" 
                startIcon={<CloseIcon />}
                onClick={clearSearch}
              >
                Clear all filters
              </Button>
            </Box>
          )}
        </Box>
        
        {loading && <Box sx={{ display: 'flex', justifyContent: 'center', my: 4 }}><CircularProgress /></Box>}
        
        {!loading && filteredIncharges.length === 0 ? (
          <Box sx={{ textAlign: 'center', py: 4 }}>
            <Typography variant="body1" color="text.secondary">
              No clinical incharges found
            </Typography>
          </Box>
        ) : (
          isMobile ? (
            // Mobile view - card layout
            <Stack spacing={2}>
              {filteredIncharges.map((incharge) => (
                <Card key={incharge._id} variant="outlined">
                  <CardContent>
                    <Box sx={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', mb: 1 }}>
                      <Typography variant="h6" component="div">{incharge.name}</Typography>
                      <Chip 
                        label={incharge.status ? 'Active' : 'Inactive'} 
                        color={incharge.status ? 'success' : 'default'}
                        size="small"
                      />
                    </Box>
                    
                    <Typography variant="body2" color="text.secondary">ID: {incharge.employeeId}</Typography>
                    <Typography variant="body2" color="text.secondary">Email: {incharge.email}</Typography>
                    <Typography variant="body2" color="text.secondary">Phone: {incharge.phone}</Typography>
                    <Typography variant="body2" color="text.secondary">Department: {incharge.department}</Typography>
                    
                    <Box sx={{ display: 'flex', justifyContent: 'flex-end', mt: 2, gap: 1 }}>
                      <IconButton size="small" color="primary" onClick={() => handleOpenDialog(incharge)}>
                        <EditIcon fontSize="small" />
                      </IconButton>
                      <IconButton size="small" color="error" onClick={() => openDeleteConfirmation(incharge._id)}>
                        <DeleteIcon fontSize="small" />
                      </IconButton>
                      <Switch
                        size="small"
                        checked={incharge.status}
                        onChange={() => handleStatusChange(incharge._id, incharge.status)}
                      />
                    </Box>
                  </CardContent>
                </Card>
              ))}
            </Stack>
          ) : (
            // Desktop view - table layout
            <TableContainer component={Paper} variant="outlined">
              <Table>
                <TableHead>
                  <TableRow>
                    <TableCell>Name</TableCell>
                    <TableCell>Email</TableCell>
                    <TableCell>Phone</TableCell>
                    <TableCell>Employee ID</TableCell>
                    <TableCell>Department</TableCell>
                    <TableCell>Status</TableCell>
                    <TableCell align="center">Actions</TableCell>
                  </TableRow>
                </TableHead>
                <TableBody>
                  {filteredIncharges.map((incharge) => (
                    <TableRow key={incharge._id}>
                      <TableCell>{incharge.name}</TableCell>
                      <TableCell>{incharge.email}</TableCell>
                      <TableCell>{incharge.phone}</TableCell>
                      <TableCell>{incharge.employeeId}</TableCell>
                      <TableCell>{incharge.department}</TableCell>
                      <TableCell>
                        <Chip 
                          label={incharge.status ? 'Active' : 'Inactive'} 
                          color={incharge.status ? 'success' : 'default'}
                          size="small"
                        />
                      </TableCell>
                      <TableCell align="center">
                        <IconButton 
                          size="small" 
                          color="primary" 
                          onClick={() => handleOpenDialog(incharge)}
                          sx={{ mx: 0.5 }}
                        >
                          <EditIcon fontSize="small" />
                        </IconButton>
                        <IconButton 
                          size="small" 
                          color="error" 
                          onClick={() => openDeleteConfirmation(incharge._id)}
                          sx={{ mx: 0.5 }}
                        >
                          <DeleteIcon fontSize="small" />
                        </IconButton>
                        <Switch
                          size="small"
                          checked={incharge.status}
                          onChange={() => handleStatusChange(incharge._id, incharge.status)}
                        />
                      </TableCell>
                    </TableRow>
                  ))}
                </TableBody>
              </Table>
            </TableContainer>
          )
        )}
      </Paper>
      
      {/* Create/Edit Dialog */}
      <Dialog 
        open={openDialog} 
        onClose={handleCloseDialog} 
        maxWidth="sm"
        fullWidth
        fullScreen={isMobile}
      >
        <DialogTitle>
          {isEditing ? 'Edit Clinical Incharge' : 'Add Clinical Incharge'}
        </DialogTitle>
        <Divider />
        <DialogContent>
          <Grid container spacing={2} sx={{ mt: 0.5 }}>
            <Grid item xs={12}>
              <TextField
                fullWidth
                label="Name"
                name="name"
                value={formData.name}
                onChange={handleInputChange}
                error={!!formErrors.name}
                helperText={formErrors.name}
                required
              />
            </Grid>
            
            <Grid item xs={12} sm={6}>
              <TextField
                fullWidth
                label="Email"
                name="email"
                type="email"
                value={formData.email}
                onChange={handleInputChange}
                error={!!formErrors.email}
                helperText={formErrors.email}
                required
              />
            </Grid>
            
            <Grid item xs={12} sm={6}>
              <TextField
                fullWidth
                label="Phone"
                name="phone"
                value={formData.phone}
                onChange={handleInputChange}
                error={!!formErrors.phone}
                helperText={formErrors.phone}
                required
              />
            </Grid>
            
            <Grid item xs={12} sm={6}>
              <TextField
                fullWidth
                label="Employee ID"
                name="employeeId"
                value={formData.employeeId}
                onChange={handleInputChange}
                error={!!formErrors.employeeId}
                helperText={formErrors.employeeId}
                required
                disabled={isEditing} // Cannot change employee ID when editing
              />
            </Grid>
            
            <Grid item xs={12} sm={6}>
              <FormControl fullWidth required error={!!formErrors.department}>
                <InputLabel id="department-label">Department</InputLabel>
                <Select
                  labelId="department-label"
                  name="department"
                  value={formData.department}
                  onChange={handleInputChange}
                  label="Department"
                >
                  <MenuItem value="Cardiology">Cardiology</MenuItem>
                  <MenuItem value="Neurology">Neurology</MenuItem>
                  <MenuItem value="Orthopedics">Orthopedics</MenuItem>
                  <MenuItem value="Pediatrics">Pediatrics</MenuItem>
                  <MenuItem value="Radiology">Radiology</MenuItem>
                  <MenuItem value="General Medicine">General Medicine</MenuItem>
                  <MenuItem value="Surgery">Surgery</MenuItem>
                  <MenuItem value="ICU">ICU</MenuItem>
                  <MenuItem value="Emergency">Emergency</MenuItem>
                </Select>
                {formErrors.department && (
                  <Typography variant="caption" color="error">
                    {formErrors.department}
                  </Typography>
                )}
              </FormControl>
            </Grid>
            
            <Grid item xs={12}>
              <FormControlLabel
                control={
                  <Switch
                    checked={formData.status}
                    onChange={handleInputChange}
                    name="status"
                    color="primary"
                  />
                }
                label="Active Status"
              />
            </Grid>
          </Grid>
        </DialogContent>
        <DialogActions sx={{ px: 3, pb: 2 }}>
          <Button onClick={handleCloseDialog} disabled={loading}>
            Cancel
          </Button>
          <Button 
            onClick={handleSubmit} 
            variant="contained" 
            color="primary" 
            disabled={loading}
            startIcon={loading ? <CircularProgress size={20} /> : null}
          >
            {loading ? 'Processing' : isEditing ? 'Update' : 'Create'}
          </Button>
        </DialogActions>
      </Dialog>
      
      {/* Delete Confirmation Dialog */}
      <Dialog open={openDeleteDialog} onClose={() => setOpenDeleteDialog(false)}>
        <DialogTitle>Confirm Delete</DialogTitle>
        <DialogContent>
          <Typography>
            Are you sure you want to delete this clinical incharge? This action cannot be undone.
          </Typography>
        </DialogContent>
        <DialogActions>
          <Button onClick={() => setOpenDeleteDialog(false)} disabled={loading}>
            Cancel
          </Button>
          <Button 
            onClick={handleDeleteIncharge} 
            color="error" 
            variant="contained"
            disabled={loading}
            startIcon={loading ? <CircularProgress size={20} /> : null}
          >
            {loading ? 'Deleting...' : 'Delete'}
          </Button>
        </DialogActions>
      </Dialog>
      
      {/* Notification Snackbar */}
      <Snackbar
        open={notification.open}
        autoHideDuration={6000}
        onClose={handleCloseNotification}
        anchorOrigin={{ vertical: 'bottom', horizontal: 'right' }}
      >
        <Alert 
          onClose={handleCloseNotification} 
          severity={notification.severity} 
          variant="filled"
          sx={{ width: '100%' }}
        >
          {notification.message}
        </Alert>
      </Snackbar>
    </Box>
  );
};

export default ClinicalInchargeManagement;