import { Navigate, useLocation } from 'react-router-dom';

const PrivateRoute = ({ children }) => {
  const location = useLocation();
  const token = localStorage.getItem('token');
  const availableTypes = JSON.parse(localStorage.getItem('availableTypes') || '[]');
  
  // If not authenticated, redirect to login
  if (!token) {
    return <Navigate to="/login" state={{ from: location }} replace />;
  }

  // Check current route type
  const isDeviceRoute = location.pathname.includes('device-portal');
  const isFileRoute = location.pathname.includes('file-tracker');

  // Handle route access based on available types
  if (availableTypes.length === 0) {
    return <Navigate to="/login" replace />;
  }

  // If user only has file tracking access
  if (availableTypes.length === 1 && availableTypes[0] === 'file-tracking') {
    localStorage.setItem('type', 'file-tracking');
    if (isDeviceRoute) {
      return <Navigate to="/file-tracker/overview" replace />;
    }
  }

  // If user only has device inspection access
  if (availableTypes.length === 1 && availableTypes[0] === 'device-inspection') {
    localStorage.setItem('type', 'device-inspection');
    if (isFileRoute) {
      return <Navigate to="/device-portal/overview" replace />;
    }
  }

  // If user has both access types, allow access to both systems
  if (availableTypes.includes('file-tracking') && availableTypes.includes('device-inspection')) {
    return children;
  }

  return children;
};

export default PrivateRoute;