// pages/Users/UserManagement.jsx
import React, { useState, useEffect } from 'react';
import {
  Box,
  Card,
  IconButton,
  Tooltip,
  FormControl,
  InputLabel,
  Select,
  MenuItem,
  Dialog,
  DialogTitle,
  DialogContent,
  DialogActions,
  Button,
  TextField,
  CircularProgress,
  Typography,
  Stack,
} from '@mui/material';
import {
  DataGrid,
  GridToolbar,
} from '@mui/x-data-grid';
import { Add as AddIcon } from '@mui/icons-material';
import { useSnackbar } from 'notistack';
import * as yup from 'yup';
import { useFormik } from 'formik';
import api from '../../../api/axios';

// Validation schema for user creation
const userSchema = yup.object({
  name: yup.string().required('Name is required'),
  email: yup.string()
    .email('Enter a valid email')
    .required('Email is required'),
  phoneNumber: yup.string()
    .matches(/^[0-9]{10}$/, 'Phone number must be 10 digits')
    .required('Phone number is required'),
  whatsApp: yup.string()
    .matches(/^[0-9]{10}$/, 'WhatsApp number must be 10 digits'),
  nishStaffId: yup.string(),
  address: yup.string(),
  pincode: yup.string()
    .matches(/^[0-9]{6}$/, 'Pincode must be 6 digits'),
  level: yup.string().required('User level is required'),
});

const UserManagement = () => {
  const [users, setUsers] = useState([]);
  const [loading, setLoading] = useState(true);
  const [openDialog, setOpenDialog] = useState(false);
  const [filters, setFilters] = useState({
    level: 'all',
    status: 'all',
  });
  const [pagination, setPagination] = useState({
    page: 0,
    pageSize: 10,
    total: 0,
  });

  const { enqueueSnackbar } = useSnackbar();

  const formik = useFormik({
    initialValues: {
      name: '',
      email: '',
      phoneNumber: '',
      whatsApp: '',
      nishStaffId: '',
      address: '',
      pincode: '',
      level: '',
    },
    validationSchema: userSchema,
    onSubmit: async (values, { setSubmitting, resetForm }) => {
      try {
        await api.post('/users/register', values);
        enqueueSnackbar('User created successfully', { variant: 'success' });
        setOpenDialog(false);
        resetForm();
        fetchUsers();
      } catch (error) {
        enqueueSnackbar(error.response?.data?.message || 'Error creating user', { variant: 'error' });
      } finally {
        setSubmitting(false);
      }
    },
  });

  const columns = [
    { 
      field: 'name', 
      headerName: 'Name', 
      flex: 1,
      minWidth: 150,
    },
    { 
      field: 'email', 
      headerName: 'Email', 
      flex: 1,
      minWidth: 200,
    },
    { 
      field: 'phoneNumber', 
      headerName: 'Phone', 
      width: 130,
    },
    { 
      field: 'whatsApp', 
      headerName: 'WhatsApp', 
      width: 130,
    },
    { 
      field: 'nishStaffId', 
      headerName: 'Staff ID', 
      width: 130,
    },
    { 
      field: 'level', 
      headerName: 'Role', 
      width: 150,
      valueGetter: (params) => params.row.level === 'mrrs' ? 'Med.Room Staff' : 'Clinical Staff',
    },
    { 
      field: 'status', 
      headerName: 'Status', 
      width: 130,
      renderCell: (params) => (
        <Typography
          sx={{
            color: params.row.status === 'active' ? 'success.main' : 'error.main',
            fontWeight: 'medium',
          }}
        >
          {params.row.status.charAt(0).toUpperCase() + params.row.status.slice(1)}
        </Typography>
      ),
    },
  ];

  const fetchUsers = async () => {
    try {
      setLoading(true);
      const queryParams = new URLSearchParams({
        page: pagination.page + 1,
        limit: pagination.pageSize,
        ...(filters.level !== 'all' && { level: filters.level }),
        ...(filters.status !== 'all' && { status: filters.status }),
      });

      const response = await api.get(`/users?${queryParams}`);
      // Filter out superAdmin users in frontend
      const filteredUsers = response.data.data.filter(user => user.level !== 'superAdmin');
      setUsers(filteredUsers);
      setPagination(prev => ({
        ...prev,
        total: response.data.pagination.totalRecords,
      }));
    } catch (error) {
      enqueueSnackbar('Error fetching users', { variant: 'error' });
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchUsers();
  }, [pagination.page, pagination.pageSize, filters]);

  const handleFilterChange = (event) => {
    const { name, value } = event.target;
    setFilters(prev => ({ ...prev, [name]: value }));
    setPagination(prev => ({ ...prev, page: 0 }));
  };

  return (
    <Box sx={{ p: 3 }}>
      <Stack direction="row" justifyContent="space-between" alignItems="center" mb={3}>
        <Typography variant="h4">User Management</Typography>
        <Tooltip title="Create New User">
          <IconButton
            color="primary"
            onClick={() => setOpenDialog(true)}
            sx={{
              bgcolor: 'primary.main',
              color: 'white',
              '&:hover': {
                bgcolor: 'primary.dark',
              },
            }}
          >
            <AddIcon />
          </IconButton>
        </Tooltip>
      </Stack>

      <Card sx={{ mb: 3 }}>
        <Stack direction="row" spacing={2} p={2}>
          <FormControl sx={{ minWidth: 200 }}>
            <InputLabel>Role</InputLabel>
            <Select
              name="level"
              value={filters.level}
              label="Role"
              onChange={handleFilterChange}
            >
              <MenuItem value="all">All Roles</MenuItem>
              <MenuItem value="mrrs">Med.Room Staff</MenuItem>
              <MenuItem value="cs">Clinical Staff</MenuItem>
            </Select>
          </FormControl>

          <FormControl sx={{ minWidth: 200 }}>
            <InputLabel>Status</InputLabel>
            <Select
              name="status"
              value={filters.status}
              label="Status"
              onChange={handleFilterChange}
            >
              <MenuItem value="all">All Status</MenuItem>
              <MenuItem value="active">Active</MenuItem>
              <MenuItem value="blocked">Blocked</MenuItem>
            </Select>
          </FormControl>
        </Stack>
      </Card>

      <Card>
        <DataGrid
          rows={users}
          columns={columns}
          pagination
          paginationMode="server"
          rowCount={pagination.total}
          page={pagination.page}
          pageSize={pagination.pageSize}
          onPageChange={(newPage) => setPagination(prev => ({ ...prev, page: newPage }))}
          onPageSizeChange={(newPageSize) => 
            setPagination(prev => ({ ...prev, pageSize: newPageSize, page: 0 }))
          }
          loading={loading}
          getRowId={(row) => row._id}
          autoHeight
          disableSelectionOnClick
          components={{
            Toolbar: GridToolbar,
          }}
          componentsProps={{
            toolbar: {
              showQuickFilter: true,
              quickFilterProps: { 
                debounceMs: 500,
                sx: { 
                  '& .MuiInputBase-input': {
                    fontSize: '1rem',
                    fontWeight: 900,
                  }
                }
              },
              sx: {
                '& .MuiButton-root': {
                  fontSize: '0.875rem',
                  fontWeight: 600,
                },
                '& .MuiFormControl-root': {
                  '& .MuiInputBase-input': {
                    fontSize: '0.900rem',
                    fontWeight: 500,
                  }
                }
              }
            },
          }}
          sx={{
            '& .MuiDataGrid-toolbarContainer': {
              padding: 2,
              borderBottom: '1px solid',
              borderColor: 'divider',
            },
          }}
        />
      </Card>

      <Dialog 
        open={openDialog} 
        onClose={() => setOpenDialog(false)}
        maxWidth="sm"
        fullWidth
      >
        <form onSubmit={formik.handleSubmit}>
          <DialogTitle>Create New User</DialogTitle>
          <DialogContent>
            <Stack spacing={2} sx={{ mt: 2 }}>
              <TextField
                fullWidth
                name="name"
                label="Name"
                value={formik.values.name}
                onChange={formik.handleChange}
                error={formik.touched.name && Boolean(formik.errors.name)}
                helperText={formik.touched.name && formik.errors.name}
              />

              <TextField
                fullWidth
                name="email"
                label="Email"
                value={formik.values.email}
                onChange={formik.handleChange}
                error={formik.touched.email && Boolean(formik.errors.email)}
                helperText={formik.touched.email && formik.errors.email}
              />

              <TextField
                fullWidth
                name="phoneNumber"
                label="Phone Number"
                value={formik.values.phoneNumber}
                onChange={formik.handleChange}
                error={formik.touched.phoneNumber && Boolean(formik.errors.phoneNumber)}
                helperText={formik.touched.phoneNumber && formik.errors.phoneNumber}
              />

              <TextField
                fullWidth
                name="whatsApp"
                label="WhatsApp Number"
                value={formik.values.whatsApp}
                onChange={formik.handleChange}
                error={formik.touched.whatsApp && Boolean(formik.errors.whatsApp)}
                helperText={formik.touched.whatsApp && formik.errors.whatsApp}
              />

              <TextField
                fullWidth
                name="nishStaffId"
                label="NISH Staff ID"
                value={formik.values.nishStaffId}
                onChange={formik.handleChange}
              />

              <TextField
                fullWidth
                name="address"
                label="Address"
                multiline
                rows={3}
                value={formik.values.address}
                onChange={formik.handleChange}
              />

              <TextField
                fullWidth
                name="pincode"
                label="Pincode"
                value={formik.values.pincode}
                onChange={formik.handleChange}
                error={formik.touched.pincode && Boolean(formik.errors.pincode)}
                helperText={formik.touched.pincode && formik.errors.pincode}
              />

              <FormControl fullWidth>
                <InputLabel>Role</InputLabel>
                <Select
                  name="level"
                  value={formik.values.level}
                  label="Role"
                  onChange={formik.handleChange}
                  error={formik.touched.level && Boolean(formik.errors.level)}
                >
                  <MenuItem value="mrrs">Med.Room Staff</MenuItem>
                  <MenuItem value="cs">Clinical Staff</MenuItem>
                </Select>
              </FormControl>
            </Stack>
          </DialogContent>
          <DialogActions>
            <Button 
              onClick={() => setOpenDialog(false)}
              disabled={formik.isSubmitting}
            >
              Cancel
            </Button>
            <Button 
              type="submit"
              variant="contained"
              disabled={formik.isSubmitting}
            >
              {formik.isSubmitting ? <CircularProgress size={24} /> : 'Create'}
            </Button>
          </DialogActions>
        </form>
      </Dialog>
    </Box>
  );
};

export default UserManagement;