import axios from 'axios';

const API_URL = process.env.REACT_APP_API_URL || 'http://localhost:5000';

// Create axios instance with default config
const api = axios.create({
  baseURL: `${API_URL}/device`,
  headers: {
    'Content-Type': 'application/json'
  }
});

// Add auth token to requests
api.interceptors.request.use(
  (config) => {
    const token = localStorage.getItem('token');
    if (token) {
      config.headers.Authorization = `Bearer ${token}`;
    }
    return config;
  },
  (error) => Promise.reject(error)
);

// Handle response errors
api.interceptors.response.use(
  (response) => response,
  (error) => {
    const errorMessage = error.response?.data?.message || 'Something went wrong';
    console.error('API Error:', errorMessage);
    return Promise.reject(error);
  }
);

const notificationService = {
  getNotifications: async (token) => {
    try {
      const response = await api.get('/notifications', {
        headers: {
          'Authorization': `Bearer ${token}`,
        },
      });
      return response.data;
    } catch (error) {
      throw error.response?.data?.message || 'Failed to fetch notifications';
    }
  },

  markNotificationAsRead: async (notificationId, token) => {
    try {
      const response = await api.patch(`/notifications/${notificationId}/read`, {}, {
        headers: {
          'Authorization': `Bearer ${token}`,
        },
      });
      return response.data;
    } catch (error) {
      throw error.response?.data?.message || 'Failed to mark notification as read';
    }
  },

  markNotificationAsUnread: async (notificationId, token) => {
    try {
      const response = await api.patch(`/notifications/${notificationId}/unread`, {}, {
        headers: {
          'Authorization': `Bearer ${token}`,
        },
      });
      return response.data;
    } catch (error) {
      throw error.response?.data?.message || 'Failed to mark notification as unread';
    }
  },
  
  toggleNotificationReadStatus: async (notification, token) => {
    try {
      if (notification.read) {
        return await notificationService.markNotificationAsUnread(notification._id, token);
      } else {
        return await notificationService.markNotificationAsRead(notification._id, token);
      }
    } catch (error) {
      throw error.response?.data?.message || 'Failed to toggle notification status';
    }
  },
  
  markAllNotificationsAsRead: async (token) => {
    try {
      const response = await api.patch('/notifications/read-all', {}, {
        headers: {
          'Authorization': `Bearer ${token}`,
        },
      });
      return response.data;
    } catch (error) {
      throw error.response?.data?.message || 'Failed to mark all notifications as read';
    }
  }
};

export default notificationService;